function sketch(p) {
  let figure;
  let lantern;
  let footprints = [];
  let pathParticles = [];
  let timeFlow = 0;
  let breathe = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize figure position
    figure = {
      x: 200,
      y: 400,
      sway: 0
    };

    // Initialize lantern
    lantern = {
      x: 180,
      y: 350,
      glow: 0
    };

    // Create footprints behind the figure
    for(let i = 0; i < 8; i++) {
      footprints.push({
        x: 200 + p.random(-20, 20),
        y: 450 + i * 15,
        alpha: p.map(i, 0, 7, 0, 150),
        size: p.random(3, 6)
      });
    }

    // Create path particles for the road ahead
    for(let i = 0; i < 30; i++) {
      pathParticles.push({
        x: p.random(150, 250),
        y: p.random(100, 350),
        drift: p.random(-0.5, 0.5),
        alpha: p.random(30, 80),
        size: p.random(1, 3)
      });
    }
  };

  p.draw = function() {
    // Time flows
    timeFlow += 0.02;
    breathe += 0.03;

    // Ambiguous dawn/dusk gradient
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let skyColor = p.lerpColor(
        p.color(120, 140, 160, 200), // blue-tinted top
        p.color(180, 120, 80, 180),  // orange horizon
        inter
      );
      p.stroke(skyColor);
      p.line(0, y, p.width, y);
    }

    // Draw the path ahead - fading into distance
    p.stroke(90, 110, 130, 60);
    p.strokeWeight(2);
    let pathY = 350;
    for(let i = 0; i < 10; i++) {
      let alpha = p.map(i, 0, 10, 100, 0);
      p.stroke(90, 110, 130, alpha);
      let pathWidth = p.map(i, 0, 10, 40, 10);
      let y = pathY - i * 25;
      p.line(200 - pathWidth/2, y, 200 + pathWidth/2, y);
    }

    // Draw footprints behind (the past)
    p.noStroke();
    footprints.forEach(print => {
      p.fill(80, 90, 100, print.alpha);
      p.ellipse(print.x - 5, print.y, print.size, print.size * 1.5);
      p.ellipse(print.x + 5, print.y, print.size, print.size * 1.5);
    });

    // Draw path particles (time as medium)
    pathParticles.forEach(particle => {
      particle.x += particle.drift * p.sin(timeFlow);
      particle.alpha += p.random(-2, 2);
      particle.alpha = p.constrain(particle.alpha, 20, 100);

      p.fill(140, 160, 180, particle.alpha);
      p.ellipse(particle.x, particle.y, particle.size);
    });

    // Figure sway with breath of time
    figure.sway = p.sin(breathe) * 3;

    // Draw figure silhouette
    p.fill(60, 70, 90, 180);
    p.noStroke();

    // Body
    p.ellipse(figure.x + figure.sway, figure.y, 25, 60);

    // Head
    p.ellipse(figure.x + figure.sway, figure.y - 40, 20, 25);

    // Arms
    p.ellipse(figure.x - 15 + figure.sway, figure.y - 10, 8, 30);
    p.ellipse(figure.x + 15 + figure.sway, figure.y - 10, 8, 30);

    // Legs in walking pose
    let legSway = p.sin(timeFlow * 2) * 2;
    p.ellipse(figure.x - 8 + figure.sway, figure.y + 25, 8, 35);
    p.ellipse(figure.x + 8 + figure.sway + legSway, figure.y + 20, 8, 35);

    // Lantern glow
    lantern.glow = 100 + p.sin(timeFlow * 3) * 30;
    lantern.x = figure.x - 20 + figure.sway;
    lantern.y = figure.y - 20;

    // Lantern light
    for(let r = 40; r > 0; r -= 5) {
      let alpha = p.map(r, 0, 40, lantern.glow, 0);
      p.fill(220, 180, 120, alpha);
      p.ellipse(lantern.x, lantern.y, r);
    }

    // Lantern object
    p.fill(100, 80, 60);
    p.rect(lantern.x - 4, lantern.y - 8, 8, 16, 2);
    p.fill(240, 200, 140, 200);
    p.ellipse(lantern.x, lantern.y, 6, 10);

    // Interactive: mouse movement affects the path ahead
    let mouseInfluence = p.map(p.mouseX, 0, p.width, -1, 1);
    p.stroke(120, 140, 160, 50);
    p.strokeWeight(1);
    p.noFill();

    // Draw the convergence of past and future
    p.beginShape();
    p.curveVertex(200, 500); // past
    p.curveVertex(200, 450);
    p.curveVertex(figure.x + figure.sway, figure.y); // present moment
    p.curveVertex(200 + mouseInfluence * 20, 300);
    p.curveVertex(200 + mouseInfluence * 10, 100); // future
    p.endShape();

    // Threshold markers
    p.stroke(100, 120, 140, 100);
    p.strokeWeight(3);
    p.line(150, figure.y + 50, 250, figure.y + 50);

    // Time compression effect on click
    if(p.mouseIsPressed) {
      p.stroke(200, 150, 100, 150);
      p.strokeWeight(1);
      for(let i = 0; i < 8; i++) {
        let radius = 50 + i * 15;
        p.noFill();
        p.ellipse(figure.x, figure.y, radius + p.sin(timeFlow * 4) * 10);
      }
    }
  };
}

function sketch(p) {
  let paths = [];
  let footprints = [];
  let noiseOffset = 0;
  let skyOffset = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Create multiple overlapping paths
    for (let i = 0; i < 8; i++) {
      paths.push({
        points: [],
        worn: p.random(0.2, 1.0),
        overgrown: p.random(0.1, 0.8),
        visible: p.random(0.3, 1.0),
        y: p.random(100, 500)
      });

      // Generate path points
      for (let x = -50; x < 450; x += 15) {
        let baseY = paths[i].y;
        let wavyY = baseY + p.sin(x * 0.01 + i) * 20;
        let noiseY = wavyY + p.noise(x * 0.005, i * 0.1) * 40 - 20;
        paths[i].points.push({x: x, y: noiseY});
      }
    }

    // Create footprint clusters
    for (let i = 0; i < 80; i++) {
      footprints.push({
        x: p.random(-20, 420),
        y: p.random(80, 520),
        age: p.random(0, 1),
        size: p.random(3, 8),
        angle: p.random(-p.PI/6, p.PI/6)
      });
    }
  };

  p.draw = function() {
    // Muted blue-tinted background with orange sky breakthrough
    let skyIntensity = p.sin(skyOffset * 0.005) * 0.3 + 0.7;
    p.background(200, 20, 15);

    // Orange sky breakthrough in upper portion
    p.push();
    p.fill(25, 80, 70, skyIntensity * 30);
    p.noStroke();
    p.ellipse(p.width/2, -50, 300, 200);
    p.pop();

    // Ground texture with subtle noise
    for (let y = 100; y < p.height; y += 3) {
      let alpha = p.map(y, 100, p.height, 10, 30);
      p.stroke(40, 30, 25, alpha);
      p.line(0, y, p.width, y + p.noise(y * 0.01, noiseOffset) * 4 - 2);
    }

    // Draw paths in order of visibility
    let sortedPaths = [...paths].sort((a, b) => b.visible - a.visible);

    for (let path of sortedPaths) {
      p.push();

      // Path color based on how worn/overgrown it is
      let pathHue = 200 + path.worn * 20;
      let pathSat = 40 - path.overgrown * 20;
      let pathBright = 30 + path.worn * 20;
      let pathAlpha = path.visible * 60;

      p.stroke(pathHue, pathSat, pathBright, pathAlpha);
      p.strokeWeight(path.worn * 4 + 1);
      p.noFill();

      // Draw the path with languid brush strokes
      p.beginShape();
      p.noFill();
      for (let i = 0; i < path.points.length - 1; i++) {
        let pt = path.points[i];
        let nextPt = path.points[i + 1];

        // Add some organic variation to the stroke
        let waveX = pt.x + p.sin(p.frameCount * 0.01 + i * 0.1) * 0.5;
        let waveY = pt.y + p.noise(pt.x * 0.003, pt.y * 0.003, p.frameCount * 0.002) * 2;

        if (i === 0) {
          p.vertex(waveX, waveY);
        } else {
          p.vertex(waveX, waveY);
        }
      }
      p.endShape();

      // Draw overgrowth on more abandoned paths
      if (path.overgrown > 0.5) {
        for (let i = 0; i < path.points.length; i += 3) {
          if (p.random() < 0.3) {
            let pt = path.points[i];
            p.stroke(80, 60, 40, 20);
            p.strokeWeight(1);
            p.line(pt.x, pt.y - 5, pt.x + p.random(-3, 3), pt.y - p.random(8, 15));
          }
        }
      }

      p.pop();
    }

    // Draw footprints with varying ages
    for (let fp of footprints) {
      p.push();
      p.translate(fp.x, fp.y);
      p.rotate(fp.angle);

      let fpAlpha = (1 - fp.age) * 30 + 10;
      p.fill(180, 30, 20, fpAlpha);
      p.noStroke();

      // Simple footprint shape
      p.ellipse(0, 0, fp.size * 0.6, fp.size);
      p.ellipse(0, -fp.size * 0.3, fp.size * 0.4, fp.size * 0.4);

      p.pop();
    }

    // Interactive element: paths glow slightly toward mouse
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, p.width/2, p.height/2) / (p.width/2);
    mouseInfluence = 1 - mouseInfluence;

    if (mouseInfluence > 0.3) {
      p.push();
      p.stroke(200, 60, 80, mouseInfluence * 20);
      p.strokeWeight(1);
      p.noFill();

      // Highlight the path closest to mouse
      for (let path of paths) {
        for (let i = 0; i < path.points.length - 1; i++) {
          let pt = path.points[i];
          let dist = p.dist(p.mouseX, p.mouseY, pt.x, pt.y);
          if (dist < 50) {
            let alpha = p.map(dist, 0, 50, 30, 0);
            p.stroke(200, 60, 80, alpha);
            p.line(pt.x, pt.y, path.points[i + 1].x, path.points[i + 1].y);
          }
        }
      }
      p.pop();
    }

    noiseOffset += 0.01;
    skyOffset += 1;
  };

  p.mousePressed = function() {
    // Add new footprint at mouse location
    if (p.mouseY > 80 && p.mouseY < p.height - 20) {
      footprints.push({
        x: p.mouseX + p.random(-5, 5),
        y: p.mouseY + p.random(-5, 5),
        age: 0,
        size: p.random(4, 7),
        angle: p.random(-p.PI/4, p.PI/4)
      });

      // Age existing footprints slightly
      for (let fp of footprints) {
        fp.age = p.min(fp.age + 0.05, 1);
      }
    }
  };
}

function sketch(p) {
  let particles = [];
  let treePoints = [];
  let skyGradient = [];
  let lightRays = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create tree silhouette points
    for (let i = 0; i < 15; i++) {
      treePoints.push({
        x: 50 + i * 8,
        y: 200 + p.sin(i * 0.3) * 30,
        baseY: 200 + p.sin(i * 0.3) * 30
      });
    }

    // Create floating particles for atmosphere
    for (let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        size: p.random(1, 3),
        speed: p.random(0.2, 0.8),
        alpha: p.random(20, 60)
      });
    }

    // Create light rays
    for (let i = 0; i < 5; i++) {
      lightRays.push({
        x: 250 + i * 30,
        angle: p.random(-0.2, 0.2),
        intensity: p.random(0.3, 0.8)
      });
    }
  };

  p.draw = function() {
    // Sky gradient - muted blues with orange breakthrough
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let skyBlue = p.color(85, 115, 140);
      let horizonOrange = p.color(180, 120, 80);
      let c = p.lerpColor(skyBlue, horizonOrange, inter * inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Ground
    p.fill(70, 85, 75);
    p.noStroke();
    p.rect(0, 450, 400, 150);

    // Subtle light rays in background
    p.stroke(255, 180, 120, 15);
    p.strokeWeight(8);
    for (let ray of lightRays) {
      let mouseInfluence = p.map(p.mouseX, 0, 400, -0.1, 0.1);
      p.line(ray.x, 0, 
             ray.x + p.sin(p.frameCount * 0.01 + ray.angle + mouseInfluence) * 150, 
             400);
    }

    // Tree trunk and branches
    p.stroke(40, 50, 45);
    p.strokeWeight(12);
    p.line(80, 450, 80, 200);

    p.strokeWeight(6);
    p.line(80, 220, 120, 180);
    p.line(80, 240, 60, 190);

    // Tree canopy - languid, organic shapes
    p.fill(45, 60, 50);
    p.noStroke();
    p.beginShape();
    for (let i = 0; i < treePoints.length; i++) {
      let point = treePoints[i];
      let sway = p.sin(p.frameCount * 0.02 + i * 0.5) * 3;
      p.curveVertex(point.x, point.baseY + sway);
    }
    p.endShape();

    // Figure in shadow - deliberately spare and simple
    let figureX = 110;
    let figureY = 400;
    let mouseInfluenceX = p.map(p.mouseX, 0, 400, -5, 5);
    let mouseInfluenceY = p.map(p.mouseY, 0, 600, -3, 3);

    // Figure body
    p.fill(35, 45, 50, 180);
    p.ellipse(figureX + mouseInfluenceX, figureY + mouseInfluenceY, 15, 35);

    // Figure head
    p.ellipse(figureX + mouseInfluenceX, figureY - 15 + mouseInfluenceY, 12, 12);

    // Contemplative posture - one hand visible
    p.stroke(35, 45, 50, 150);
    p.strokeWeight(2);
    p.line(figureX + mouseInfluenceX - 5, figureY - 5 + mouseInfluenceY, 
           figureX + mouseInfluenceX - 8, figureY + 5 + mouseInfluenceY);

    // Shadow cast by tree - dynamic with mouse
    let shadowOpacity = p.map(p.mouseX, 0, 400, 80, 120);
    p.fill(20, 30, 35, shadowOpacity);
    p.noStroke();
    p.beginShape();
    p.vertex(80, 450);
    p.vertex(160, 450);
    p.vertex(180, 400);
    p.vertex(100, 380);
    p.endShape(p.CLOSE);

    // Illuminated area beyond shadow
    let lightX = 250;
    let lightArea = p.map(p.mouseY, 0, 600, 30, 80);
    p.fill(255, 200, 150, 25);
    p.ellipse(lightX, 420, lightArea * 2, lightArea);

    // Atmospheric particles
    for (let particle of particles) {
      p.fill(200, 220, 240, particle.alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size, particle.size);

      particle.y += particle.speed;
      particle.x += p.sin(p.frameCount * 0.01 + particle.y * 0.01) * 0.5;

      if (particle.y > 600) {
        particle.y = -10;
        particle.x = p.random(400);
      }
    }

    // Subtle interaction - when clicked, brief moment of connection
    if (p.mouseIsPressed) {
      p.stroke(255, 180, 120, 100);
      p.strokeWeight(1);
      p.line(figureX, figureY - 10, p.mouseX, p.mouseY);

      p.fill(255, 180, 120, 50);
      p.noStroke();
      p.ellipse(p.mouseX, p.mouseY, 20, 20);
    }
  };
}

function sketch(p) {
  let figure;
  let particles = [];
  let time = 0;
  let questionTime = 0;
  let handWave = 0;
  let skyBreakthrough = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create questioning particles that drift around
    for (let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.5, 0.5),
        size: p.random(2, 6),
        alpha: p.random(50, 150)
      });
    }

    figure = {
      x: p.width / 2,
      y: p.height * 0.6,
      leftHandY: p.height * 0.45,
      rightHandY: p.height * 0.45
    };
  };

  p.draw = function() {
    time += 0.01;
    questionTime += 0.008;

    // Background - ambiguous time of day
    let topColor = p.color(45, 55, 75, 255); // deep blue-grey
    let midColor = p.color(85, 95, 120, 200); // lighter blue-grey
    let bottomColor = p.color(120, 130, 140, 255); // pale blue-grey

    // Gradient background with subtle movement
    for (let y = 0; y < p.height; y++) {
      let inter1 = p.map(y, 0, p.height * 0.7, 0, 1);
      let inter2 = p.map(y, p.height * 0.3, p.height, 0, 1);

      if (y < p.height * 0.7) {
        let c = p.lerpColor(topColor, midColor, inter1);
        p.stroke(c);
        p.line(0, y, p.width, y);
      } else {
        let c = p.lerpColor(midColor, bottomColor, inter2);
        p.stroke(c);
        p.line(0, y, p.width, y);
      }
    }

    // Orange sky breakthrough - responds to mouse proximity
    let mouseInfluence = p.map(p.mouseY, 0, p.height * 0.4, 1, 0);
    mouseInfluence = p.constrain(mouseInfluence, 0, 1);
    skyBreakthrough = p.lerp(skyBreakthrough, mouseInfluence, 0.05);

    if (skyBreakthrough > 0.1) {
      p.fill(255, 140, 60, skyBreakthrough * 120);
      p.noStroke();
      p.ellipse(p.width * 0.3, p.height * 0.2, 150 * skyBreakthrough, 80 * skyBreakthrough);

      // Warm light rays
      p.stroke(255, 160, 80, skyBreakthrough * 60);
      p.strokeWeight(2);
      for (let i = 0; i < 5; i++) {
        let angle = p.map(i, 0, 5, -0.5, 0.5) + p.sin(time * 2) * 0.1;
        let x1 = p.width * 0.3;
        let y1 = p.height * 0.2;
        let x2 = x1 + p.cos(angle) * 100;
        let y2 = y1 + p.sin(angle) * 100;
        p.line(x1, y1, x2, y2);
      }
    }

    // Unfamiliar landscape - abstract, shifting forms
    p.noStroke();
    p.fill(60, 80, 100, 100);

    // Distant uncertain shapes
    for (let i = 0; i < 4; i++) {
      let x = p.width * (0.2 + i * 0.2);
      let y = p.height * 0.8 + p.sin(time + i) * 10;
      let w = 40 + p.sin(time * 1.5 + i) * 15;
      let h = 60 + p.cos(time + i * 0.5) * 20;
      p.ellipse(x, y, w, h);
    }

    // Drifting question particles
    p.strokeWeight(1);
    for (let particle of particles) {
      particle.x += particle.vx + p.sin(time + particle.y * 0.01) * 0.1;
      particle.y += particle.vy + p.cos(time + particle.x * 0.01) * 0.1;

      // Wrap around edges
      if (particle.x < 0) particle.x = p.width;
      if (particle.x > p.width) particle.x = 0;
      if (particle.y < 0) particle.y = p.height;
      if (particle.y > p.height) particle.y = 0;

      // Mouse interaction - particles are drawn to question
      let mouseDistance = p.dist(particle.x, particle.y, p.mouseX, p.mouseY);
      if (mouseDistance < 50) {
        particle.alpha = p.lerp(particle.alpha, 255, 0.1);
      } else {
        particle.alpha = p.lerp(particle.alpha, 80, 0.05);
      }

      p.stroke(180, 190, 220, particle.alpha);
      p.noFill();
      p.ellipse(particle.x, particle.y, particle.size, particle.size);
    }

    // The questioning figure
    handWave = p.sin(questionTime) * 15;

    // Body - simple, spare
    p.stroke(90, 110, 140, 200);
    p.strokeWeight(8);
    p.line(figure.x, figure.y, figure.x, figure.y + 80); // torso

    // Head - turned slightly upward in question
    p.fill(110, 120, 150, 180);
    p.noStroke();
    p.ellipse(figure.x, figure.y - 40, 35, 40);

    // Raised hands - the gesture of questioning
    p.stroke(90, 110, 140, 200);
    p.strokeWeight(6);

    // Left hand raised, open
    let leftHandX = figure.x - 40 + p.sin(time * 1.2) * 5;
    let leftHandY = figure.leftHandY + handWave;
    p.line(figure.x - 10, figure.y - 10, leftHandX, leftHandY);

    // Right hand raised, open
    let rightHandX = figure.x + 40 + p.cos(time * 0.8) * 5;
    let rightHandY = figure.rightHandY - handWave;
    p.line(figure.x + 10, figure.y - 10, rightHandX, rightHandY);

    // Open palms
    p.fill(120, 130, 160, 150);
    p.noStroke();
    p.ellipse(leftHandX, leftHandY, 12, 8);
    p.ellipse(rightHandX, rightHandY, 12, 8);

    // Mouse interaction - figure responds to presence
    let mouseProximity = p.dist(p.mouseX, p.mouseY, figure.x, figure.y);
    if (mouseProximity < 100) {
      // Subtle glow when mouse approaches - moment of connection
      p.fill(200, 210, 240, 30);
      p.noStroke();
      p.ellipse(figure.x, figure.y - 20, 80, 120);
    }

    // Subtle animation of confusion - gentle sway
    figure.x = p.width / 2 + p.sin(time * 0.5) * 3;

    // On click - moment of intensified questioning
    if (p.mouseIsPressed) {
      // Ripples of uncertainty
      p.noFill();
      p.stroke(180, 200, 240, 100);
      p.strokeWeight(2);
      for (let i = 0; i < 3; i++) {
        let radius = 30 + i * 20 + p.sin(time * 3) * 10;
        p.ellipse(figure.x, figure.y - 20, radius, radius);
      }
    }
  };
}

function sketch(p) {
  let figure;
  let emptySpaces = [];
  let time = 0;
  let breathingOffset = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Central solitary figure
    figure = {
      x: 200,
      y: 350,
      size: 60
    };

    // Create empty spaces where others might stand
    for (let i = 0; i < 8; i++) {
      emptySpaces.push({
        x: p.random(50, 350),
        y: p.random(200, 500),
        alpha: p.random(20, 60),
        size: p.random(40, 80),
        fadeSpeed: p.random(0.5, 2)
      });
    }
  };

  p.draw = function() {
    time += 0.02;
    breathingOffset = p.sin(time) * 3;

    // Background - muted sky with hint of orange breakthrough
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(120, 140, 160, 220), // muted blue-gray
        p.color(140, 120, 100, 180), // earthy brown with orange hint
        inter
      );
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Sparse landscape elements
    p.noStroke();
    p.fill(80, 90, 120, 100);
    p.ellipse(100, 480, 200, 40); // distant shadow/ground
    p.ellipse(300, 520, 150, 30);

    // Draw empty spaces - faint outlines where others might be
    for (let space of emptySpaces) {
      space.alpha += p.sin(time + space.x * 0.01) * space.fadeSpeed;
      space.alpha = p.constrain(space.alpha, 10, 80);

      p.stroke(100, 120, 150, space.alpha);
      p.strokeWeight(2);
      p.noFill();

      // Languid, loose circles suggesting absent presence
      let offsetX = p.sin(time + space.x * 0.005) * 2;
      let offsetY = p.cos(time + space.y * 0.005) * 1;

      p.circle(space.x + offsetX, space.y + offsetY, space.size);

      // Faint suggestion of where feet might be
      p.stroke(100, 120, 150, space.alpha * 0.5);
      p.strokeWeight(1);
      p.line(space.x - 10 + offsetX, space.y + space.size/2 + offsetY, 
             space.x + 10 + offsetX, space.y + space.size/2 + offsetY);
    }

    // The solitary figure - simple, intimate
    p.stroke(60, 80, 110);
    p.strokeWeight(3);
    p.noFill();

    // Body with subtle breathing motion
    let bodySize = figure.size + breathingOffset;
    p.circle(figure.x, figure.y, bodySize);

    // Head
    p.circle(figure.x, figure.y - 40, 30 + breathingOffset * 0.5);

    // Arms hanging at sides
    p.strokeWeight(2);
    p.line(figure.x - bodySize/3, figure.y - 10, 
           figure.x - bodySize/2, figure.y + 20);
    p.line(figure.x + bodySize/3, figure.y - 10, 
           figure.x + bodySize/2, figure.y + 20);

    // Legs
    p.line(figure.x - 10, figure.y + bodySize/3, 
           figure.x - 15, figure.y + 60);
    p.line(figure.x + 10, figure.y + bodySize/3, 
           figure.x + 15, figure.y + 60);

    // Interactive element - mouse proximity affects figure's posture
    let mouseDistance = p.dist(p.mouseX, p.mouseY, figure.x, figure.y);
    if (mouseDistance < 100) {
      // Figure seems to notice, slight head turn toward mouse
      let headTurn = p.map(mouseDistance, 0, 100, 5, 0);
      let turnDirection = p.mouseX > figure.x ? headTurn : -headTurn;

      p.stroke(80, 100, 130);
      p.strokeWeight(2);
      p.circle(figure.x + turnDirection, figure.y - 40, 30 + breathingOffset * 0.5);
    }

    // Subtle light rays breaking through - the orange breakthrough
    if (p.sin(time * 0.3) > 0.7) {
      p.stroke(180, 120, 60, 30);
      p.strokeWeight(1);
      for (let i = 0; i < 3; i++) {
        let rayX = p.width * 0.8 + p.sin(time + i) * 20;
        p.line(rayX, 0, rayX - 50, p.height);
      }
    }
  };

  p.mousePressed = function() {
    // On click, empty spaces briefly become more visible, then fade
    for (let space of emptySpaces) {
      space.alpha = 120;
    }
  };
}

function sketch(p) {
  let lightIntensity = 0;
  let lightPulse = 0;
  let handOffset = 0;
  let particles = [];
  let overwhelmLevel = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create light particles
    for(let i = 0; i < 50; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height * 0.4),
        size: p.random(2, 8),
        speed: p.random(0.5, 2),
        brightness: p.random(50, 255)
      });
    }
  };

  p.draw = function() {
    // Muted earthy background with blue tint
    p.background(45, 52, 65);

    // Calculate overwhelm based on mouse proximity to top
    overwhelmLevel = p.map(p.mouseY, 0, p.height * 0.5, 1, 0);
    overwhelmLevel = p.constrain(overwhelmLevel, 0, 1);

    // Pulsing light source
    lightPulse = p.sin(p.millis() * 0.003) * 0.3 + 0.7;
    lightIntensity = lightPulse * overwhelmLevel;

    // Draw overwhelming light rays
    p.push();
    p.translate(p.width * 0.5, p.height * 0.15);
    p.rotate(p.sin(p.millis() * 0.001) * 0.1);

    for(let i = 0; i < 12; i++) {
      p.push();
      p.rotate((p.TWO_PI / 12) * i);

      let rayAlpha = lightIntensity * 255 * p.random(0.3, 0.8);
      p.stroke(255, 180, 80, rayAlpha);
      p.strokeWeight(p.random(2, 8) * lightIntensity);
      p.line(0, 0, 0, p.random(100, 300) * lightIntensity);
      p.pop();
    }
    p.pop();

    // Update and draw light particles
    p.noStroke();
    for(let particle of particles) {
      particle.y += particle.speed;
      if(particle.y > p.height) {
        particle.y = -10;
        particle.x = p.random(p.width);
      }

      let alpha = particle.brightness * lightIntensity * 0.6;
      p.fill(255, 220, 120, alpha);
      p.circle(particle.x, particle.y, particle.size * lightIntensity);
    }

    // Figure silhouette - hunched, turning away
    let figureY = p.height * 0.45;
    handOffset = p.sin(p.millis() * 0.002) * 5;

    // Body
    p.fill(25, 35, 50);
    p.noStroke();
    p.ellipse(p.width * 0.5, figureY + 80, 60, 120);

    // Head (turned away from light)
    let headTurn = overwhelmLevel * 15;
    p.push();
    p.translate(p.width * 0.5 + headTurn, figureY);
    p.ellipse(0, 0, 50, 55);

    // Suggestion of face - just enough to show distress
    p.fill(15, 25, 40);
    p.ellipse(-8, -5, 3, 8); // Squinted eye
    p.pop();

    // Shielding hand/arm
    p.push();
    p.translate(p.width * 0.5 - 15, figureY - 10);
    p.rotate(-0.3 - overwhelmLevel * 0.2);

    // Arm
    p.fill(30, 40, 55);
    p.rect(-5, 0, 10, 40);

    // Hand shielding
    p.push();
    p.translate(0, 35 + handOffset);
    p.rotate(overwhelmLevel * 0.3);
    p.fill(35, 45, 60);
    p.ellipse(0, 0, 25, 15);

    // Fingers spread in defensive gesture
    for(let i = 0; i < 4; i++) {
      p.push();
      p.rotate((i - 1.5) * 0.2);
      p.rect(-1, -8, 2, 12);
      p.pop();
    }
    p.pop();
    p.pop();

    // Ground/landscape suggestion
    p.fill(40, 50, 65);
    p.noStroke();
    for(let x = 0; x < p.width; x += 20) {
      let groundHeight = p.noise(x * 0.01, p.millis() * 0.0001) * 30 + 20;
      p.rect(x, p.height - groundHeight, 20, groundHeight);
    }

    // Orange sky breakthrough (muted)
    if(lightIntensity > 0.3) {
      p.fill(180, 100, 60, 30 * lightIntensity);
      p.rect(0, 0, p.width, p.height * 0.3);
    }

    // Visual noise overlay when overwhelmed
    if(overwhelmLevel > 0.7) {
      for(let i = 0; i < 20; i++) {
        p.fill(255, 255, 255, p.random(10, 40));
        p.circle(p.random(p.width), p.random(p.height), p.random(1, 3));
      }
    }
  };

  p.mousePressed = function() {
    // Reset particles on click
    for(let particle of particles) {
      particle.x = p.random(p.width);
      particle.y = p.random(-50, 0);
    }
  };
}

function sketch(p) {
  let hands = [];
  let breathe = 0;
  let hideIntensity = 0;
  let particles = [];
  let timeOffset = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create hand vertices for two hands covering face
    hands = [
      // Left hand
      {
        palm: [
          {x: 140, y: 280},
          {x: 160, y: 300},
          {x: 180, y: 320},
          {x: 170, y: 350},
          {x: 150, y: 340}
        ],
        fingers: [
          [{x: 135, y: 280}, {x: 130, y: 260}, {x: 132, y: 240}], // thumb
          [{x: 150, y: 270}, {x: 145, y: 230}, {x: 148, y: 210}], // index
          [{x: 165, y: 265}, {x: 162, y: 220}, {x: 164, y: 200}], // middle
          [{x: 178, y: 275}, {x: 175, y: 235}, {x: 177, y: 215}], // ring
          [{x: 188, y: 290}, {x: 185, y: 250}, {x: 187, y: 235}]  // pinky
        ]
      },
      // Right hand
      {
        palm: [
          {x: 260, y: 280},
          {x: 240, y: 300},
          {x: 220, y: 320},
          {x: 230, y: 350},
          {x: 250, y: 340}
        ],
        fingers: [
          [{x: 265, y: 280}, {x: 270, y: 260}, {x: 268, y: 240}], // thumb
          [{x: 250, y: 270}, {x: 255, y: 230}, {x: 252, y: 210}], // index
          [{x: 235, y: 265}, {x: 238, y: 220}, {x: 236, y: 200}], // middle
          [{x: 222, y: 275}, {x: 225, y: 235}, {x: 223, y: 215}], // ring
          [{x: 212, y: 290}, {x: 215, y: 250}, {x: 213, y: 235}]  // pinky
        ]
      }
    ];

    // Initialize particles for emotional atmosphere
    for(let i = 0; i < 15; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.3, 0.1),
        size: p.random(2, 8),
        alpha: p.random(20, 60)
      });
    }
  };

  p.draw = function() {
    // Background with subtle gradient
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(45, 55, 75), p.color(65, 75, 95), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    timeOffset += 0.01;
    breathe = p.sin(timeOffset * 2) * 0.3 + 1;

    // Mouse interaction affects hiding intensity
    let mouseDistFromCenter = p.dist(p.mouseX, p.mouseY, p.width/2, p.height/2);
    hideIntensity = p.map(mouseDistFromCenter, 0, p.width/2, 1, 0.3);
    hideIntensity = p.constrain(hideIntensity, 0.3, 1);

    // Draw subtle face outline behind hands
    p.push();
    p.translate(p.width/2, 320);
    p.scale(breathe * 0.95);
    p.noFill();
    p.stroke(80, 90, 120, 40);
    p.strokeWeight(2);
    p.ellipse(0, -20, 120, 140);
    p.pop();

    // Draw atmospheric particles
    for(let particle of particles) {
      p.fill(120, 140, 180, particle.alpha * hideIntensity);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);

      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.alpha += p.sin(timeOffset * 3 + particle.x * 0.01) * 0.5;

      if(particle.x < 0 || particle.x > p.width) particle.vx *= -1;
      if(particle.y < 0 || particle.y > p.height) particle.vy *= -1;
    }

    // Draw hands with organic, languid brush strokes
    p.push();
    p.translate(p.width/2, 320);
    p.scale(breathe);

    for(let hand of hands) {
      // Draw palm
      p.fill(95, 85, 75, 180 * hideIntensity);
      p.stroke(75, 65, 55, 200 * hideIntensity);
      p.strokeWeight(2);

      p.beginShape();
      for(let point of hand.palm) {
        let wobble = p.sin(timeOffset * 1.5 + point.x * 0.02) * 2;
        p.curveVertex(point.x - p.width/2 + wobble, point.y - 320);
      }
      p.endShape(p.CLOSE);

      // Draw fingers with subtle movement
      for(let finger of hand.fingers) {
        p.strokeWeight(p.random(3, 5));
        p.stroke(85, 75, 65, 160 * hideIntensity);

        for(let i = 0; i < finger.length - 1; i++) {
          let current = finger[i];
          let next = finger[i + 1];
          let wobble1 = p.sin(timeOffset * 2 + current.x * 0.01) * 1.5;
          let wobble2 = p.sin(timeOffset * 2 + next.x * 0.01) * 1.5;

          p.line(
            current.x - p.width/2 + wobble1, current.y - 320,
            next.x - p.width/2 + wobble2, next.y - 320
          );
        }
      }
    }

    // Add subtle glow between fingers
    p.fill(110, 120, 140, 30 * hideIntensity);
    p.noStroke();
    for(let i = 0; i < 8; i++) {
      let angle = i * p.PI / 4;
      let x = p.sin(angle + timeOffset) * 15;
      let y = p.cos(angle + timeOffset) * 10 - 40;
      p.ellipse(x, y, 20, 30);
    }

    p.pop();

    // Gentle light rays suggesting witness
    if(hideIntensity < 0.7) {
      p.stroke(140, 160, 200, (0.7 - hideIntensity) * 100);
      p.strokeWeight(1);
      for(let i = 0; i < 5; i++) {
        let angle = i * p.PI / 3 + timeOffset * 0.5;
        let x1 = p.width/2 + p.cos(angle) * 150;
        let y1 = 250 + p.sin(angle) * 80;
        let x2 = p.width/2 + p.cos(angle) * 200;
        let y2 = 250 + p.sin(angle) * 120;
        p.line(x1, y1, x2, y2);
      }
    }
  };

  p.mousePressed = function() {
    // Create ripple effect when clicked
    particles.push({
      x: p.mouseX,
      y: p.mouseY,
      vx: p.random(-2, 2),
      vy: p.random(-2, 2),
      size: p.random(10, 20),
      alpha: 80
    });
  };
}

function sketch(p) {
  let fallTimer = 0;
  let particles = [];
  let wallBricks = [];
  let childY = 100;
  let groundY = 500;
  let fallSpeed = 0;
  let hasHitGround = false;
  let impactRipples = [];
  let bloodDrops = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize wall bricks
    for(let x = 50; x < 200; x += 30) {
      for(let y = 80; y < 200; y += 20) {
        wallBricks.push({
          x: x + (y % 40 == 0 ? 15 : 0),
          y: y,
          w: 28,
          h: 18
        });
      }
    }

    // Initialize atmospheric particles
    for(let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        vx: p.random(-0.5, 0.5),
        vy: p.random(0.2, 0.8),
        alpha: p.random(30, 80)
      });
    }
  };

  p.draw = function() {
    // Blue-tinted sky with orange breakthrough
    let skyTop = p.color(45, 55, 85);
    let skyBottom = p.color(85, 70, 55);

    for(let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(skyTop, skyBottom, inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Orange sky breakthrough near horizon
    p.fill(180, 95, 45, 60);
    p.noStroke();
    p.ellipse(p.width * 0.7, p.height * 0.3, 120, 40);

    // Ground
    p.fill(65, 55, 45);
    p.rect(0, groundY, p.width, p.height - groundY);

    // Wall
    p.stroke(75, 75, 85, 150);
    p.strokeWeight(1);
    for(let brick of wallBricks) {
      p.fill(85, 85, 95, 180);
      p.rect(brick.x, brick.y, brick.w, brick.h);
    }

    // Atmospheric particles
    p.noStroke();
    for(let particle of particles) {
      p.fill(120, 130, 150, particle.alpha);
      p.ellipse(particle.x, particle.y, 2);

      particle.x += particle.vx;
      particle.y += particle.vy;

      if(particle.y > p.height) {
        particle.y = -10;
        particle.x = p.random(400);
      }
    }

    // Child figure falling
    fallTimer += 0.02;

    if(!hasHitGround) {
      fallSpeed += 0.3;
      childY += fallSpeed;

      if(childY >= groundY - 40) {
        childY = groundY - 40;
        hasHitGround = true;

        // Create impact ripples
        for(let i = 0; i < 5; i++) {
          impactRipples.push({
            x: 120,
            y: groundY,
            radius: 0,
            maxRadius: 30 + i * 15,
            alpha: 255 - i * 40
          });
        }

        // Create blood drops
        for(let i = 0; i < 8; i++) {
          bloodDrops.push({
            x: 120 + p.random(-10, 10),
            y: childY + 30,
            vx: p.random(-2, 2),
            vy: p.random(-3, -1),
            life: 255
          });
        }
      }
    }

    // Draw impact ripples
    p.strokeWeight(2);
    for(let i = impactRipples.length - 1; i >= 0; i--) {
      let ripple = impactRipples[i];
      p.stroke(120, 130, 150, ripple.alpha);
      p.noFill();
      p.ellipse(ripple.x, ripple.y, ripple.radius * 2);

      ripple.radius += 2;
      ripple.alpha -= 4;

      if(ripple.alpha <= 0) {
        impactRipples.splice(i, 1);
      }
    }

    // Draw blood drops
    p.noStroke();
    for(let i = bloodDrops.length - 1; i >= 0; i--) {
      let drop = bloodDrops[i];
      p.fill(140, 45, 45, drop.life);
      p.ellipse(drop.x, drop.y, 3);

      drop.x += drop.vx;
      drop.y += drop.vy;
      drop.vy += 0.1;
      drop.life -= 3;

      if(drop.life <= 0) {
        bloodDrops.splice(i, 1);
      }
    }

    // Child figure
    p.strokeWeight(2);
    p.stroke(95, 85, 75);

    // Body
    p.fill(110, 100, 90);
    p.ellipse(120, childY + 20, 25, 35);

    // Head
    p.fill(125, 115, 105);
    p.ellipse(120, childY, 20, 22);

    // Arms - flailing if falling
    if(!hasHitGround) {
      let armOffset = p.sin(fallTimer * 15) * 8;
      p.line(108, childY + 10, 95 + armOffset, childY + 5);
      p.line(132, childY + 10, 145 - armOffset, childY + 5);
    } else {
      // Arms on ground after fall
      p.line(108, childY + 15, 100, childY + 25);
      p.line(132, childY + 15, 140, childY + 25);
    }

    // Legs
    if(!hasHitGround) {
      p.line(115, childY + 35, 110, childY + 50);
      p.line(125, childY + 35, 130, childY + 50);
    } else {
      p.line(115, childY + 35, 115, childY + 45);
      p.line(125, childY + 35, 125, childY + 45);
    }

    // Interactive element - mouse proximity creates tremor effect
    let mouseDistance = p.dist(p.mouseX, p.mouseY, 120, childY);
    if(mouseDistance < 80) {
      let tremor = p.map(mouseDistance, 0, 80, 3, 0);
      p.translate(p.random(-tremor, tremor), p.random(-tremor, tremor));

      // Add more particles when mouse is near
      if(p.frameCount % 3 == 0) {
        particles.push({
          x: p.mouseX + p.random(-20, 20),
          y: p.mouseY + p.random(-20, 20),
          vx: p.random(-1, 1),
          vy: p.random(0.5, 1.5),
          alpha: p.random(40, 100)
        });

        // Remove excess particles
        if(particles.length > 60) {
          particles.splice(0, 10);
        }
      }
    }

    // Reset fall after some time
    if(hasHitGround && p.frameCount % 300 == 0) {
      childY = 100;
      fallSpeed = 0;
      hasHitGround = false;
      impactRipples = [];
      bloodDrops = [];
    }
  };
}

function sketch(p) {
  let breathParticles = [];
  let waterLevel;
  let figure;
  let breathIntensity = 0;
  let breathCycle = 0;
  let lungAlpha = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    waterLevel = p.height * 0.75;
    figure = {
      x: p.width / 2,
      y: waterLevel - 120,
      headRadius: 35
    };

    // Initialize breath particles
    for (let i = 0; i < 50; i++) {
      breathParticles.push(createBreathParticle());
    }
  };

  function createBreathParticle() {
    return {
      x: figure.x + p.random(-5, 5),
      y: figure.y - figure.headRadius + p.random(-5, 5),
      vx: p.random(-0.3, 0.3),
      vy: p.random(-1.5, -0.8),
      size: p.random(2, 6),
      life: p.random(100, 200),
      maxLife: p.random(100, 200),
      active: false
    };
  }

  p.draw = function() {
    // Muted blue-tinted background with hint of orange
    let skyR = p.lerp(45, 85, p.sin(p.millis() * 0.0003) * 0.5 + 0.5);
    let skyG = p.lerp(55, 95, p.sin(p.millis() * 0.0003) * 0.5 + 0.5);
    let skyB = p.lerp(75, 120, p.sin(p.millis() * 0.0003) * 0.5 + 0.5);

    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let r = p.lerp(skyR, 35, inter);
      let g = p.lerp(skyG, 45, inter);
      let b = p.lerp(skyB, 65, inter);
      p.stroke(r, g, b);
      p.line(0, y, p.width, y);
    }

    // Mouse influence for breathing intensity
    let mouseDistance = p.dist(p.mouseX, p.mouseY, figure.x, figure.y);
    mouseInfluence = p.map(p.constrain(mouseDistance, 0, 150), 0, 150, 1.5, 0.3);

    // Breathing cycle
    breathCycle += 0.02 * mouseInfluence;
    breathIntensity = p.sin(breathCycle) * 0.5 + 0.5;

    // Suggested lungs - translucent overlay
    lungAlpha = breathIntensity * 80 + 20;
    p.push();
    p.translate(figure.x, figure.y + 10);
    p.fill(100, 120, 150, lungAlpha);
    p.noStroke();
    let lungSize = 25 + breathIntensity * 8;
    p.ellipse(-12, 0, lungSize, lungSize * 1.2);
    p.ellipse(12, 0, lungSize, lungSize * 1.2);
    p.pop();

    // Water surface
    p.stroke(60, 80, 110, 150);
    p.strokeWeight(2);
    for (let x = 0; x < p.width; x += 3) {
      let waveHeight = p.sin(x * 0.05 + p.millis() * 0.003) * 3;
      let y = waterLevel + waveHeight;
      p.point(x, y);
    }

    // Figure's head - keeping above water
    p.fill(80, 90, 110, 200);
    p.noStroke();
    let headBob = p.sin(p.millis() * 0.004) * 2;
    p.ellipse(figure.x, figure.y + headBob, figure.headRadius * 2, figure.headRadius * 2);

    // Subtle facial features
    p.fill(60, 70, 90, 150);
    p.ellipse(figure.x - 8, figure.y - 5 + headBob, 3, 4); // eye
    p.ellipse(figure.x + 8, figure.y - 5 + headBob, 3, 4); // eye

    // Mouth - breathing
    let mouthOpen = breathIntensity * 3 + 1;
    p.ellipse(figure.x, figure.y + 8 + headBob, 4, mouthOpen);

    // Manage breath particles
    for (let i = breathParticles.length - 1; i >= 0; i--) {
      let particle = breathParticles[i];

      if (!particle.active && breathIntensity > 0.3 && p.random() < 0.1) {
        particle.active = true;
        particle.x = figure.x + p.random(-8, 8);
        particle.y = figure.y + 8 + headBob;
        particle.life = particle.maxLife;
      }

      if (particle.active) {
        // Update particle
        particle.x += particle.vx;
        particle.y += particle.vy;
        particle.vy -= 0.01; // slight upward drift
        particle.life--;

        // Draw particle as breath mist
        let alpha = p.map(particle.life, 0, particle.maxLife, 0, 100);
        p.fill(150, 180, 200, alpha);
        p.noStroke();
        let size = p.map(particle.life, particle.maxLife, 0, particle.size, particle.size * 2);
        p.ellipse(particle.x, particle.y, size, size);

        // Reset particle when it dies
        if (particle.life <= 0) {
          particle.active = false;
        }
      }
    }

    // Ripples around figure suggesting gentle movement in water
    p.noFill();
    p.stroke(80, 100, 130, 60);
    p.strokeWeight(1);
    for (let r = 20; r < 100; r += 20) {
      let rippleAlpha = p.map(r, 20, 100, 60, 10);
      p.stroke(80, 100, 130, rippleAlpha);
      let rippleOffset = p.sin(p.millis() * 0.005 + r * 0.1) * 2;
      p.ellipse(figure.x, waterLevel + rippleOffset, r, r * 0.3);
    }
  };

  p.mousePressed = function() {
    // Create burst of breath particles on click
    for (let i = 0; i < 10; i++) {
      let particle = createBreathParticle();
      particle.active = true;
      particle.x = figure.x + p.random(-15, 15);
      particle.y = figure.y + p.random(-10, 10);
      particle.vy = p.random(-2.5, -1.2);
      breathParticles.push(particle);
    }
  };
}

function sketch(p) {
  let figure;
  let walls = [];
  let shadowFigures = [];
  let particles = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Main isolated figure
    figure = {
      x: p.width * 0.5,
      y: p.height * 0.6,
      opacity: 255
    };

    // Create walls/barriers
    for(let i = 0; i < 6; i++) {
      walls.push({
        x: p.random(50, p.width - 50),
        y: p.random(100, p.height - 100),
        w: p.random(40, 80),
        h: p.random(60, 120),
        opacity: p.random(60, 120)
      });
    }

    // Shadow figures in parallel worlds
    for(let i = 0; i < 8; i++) {
      shadowFigures.push({
        x: p.random(60, p.width - 60),
        y: p.random(150, p.height - 50),
        size: p.random(15, 25),
        phase: p.random(p.TWO_PI),
        opacity: p.random(30, 80)
      });
    }

    // Floating isolation particles
    for(let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.3, 0.3),
        size: p.random(2, 6),
        opacity: p.random(20, 60)
      });
    }
  };

  p.draw = function() {
    time += 0.02;

    // Muted blue-tinted background with subtle orange breakthrough
    let bgBlue = p.color(45, 55, 75);
    let orangeGlow = p.color(180, 120, 60, 30);

    p.background(bgBlue);

    // Subtle orange glow in upper portion
    p.fill(orangeGlow);
    p.noStroke();
    p.ellipse(p.width * 0.7, p.height * 0.2, 200, 100);

    // Draw floating isolation particles
    for(let particle of particles) {
      particle.x += particle.vx;
      particle.y += particle.vy;

      if(particle.x < 0) particle.x = p.width;
      if(particle.x > p.width) particle.x = 0;
      if(particle.y < 0) particle.y = p.height;
      if(particle.y > p.height) particle.y = 0;

      p.fill(120, 140, 160, particle.opacity);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);
    }

    // Draw walls/barriers with languid brush strokes
    p.strokeWeight(3);
    for(let wall of walls) {
      p.stroke(80, 100, 130, wall.opacity);
      p.fill(60, 80, 110, wall.opacity * 0.5);

      // Languid, imperfect rectangles
      p.beginShape();
      p.vertex(wall.x, wall.y);
      p.vertex(wall.x + wall.w + p.sin(time + wall.x) * 3, wall.y);
      p.vertex(wall.x + wall.w + p.sin(time + wall.x) * 3, wall.y + wall.h);
      p.vertex(wall.x, wall.y + wall.h + p.cos(time + wall.y) * 2);
      p.endShape(p.CLOSE);
    }

    // Draw shadow figures in parallel worlds
    for(let shadow of shadowFigures) {
      let pulse = p.sin(time + shadow.phase) * 0.3 + 0.7;
      p.fill(100, 120, 150, shadow.opacity * pulse);
      p.noStroke();

      // Simple figure representation
      p.ellipse(shadow.x, shadow.y - shadow.size, shadow.size * 0.6); // head
      p.ellipse(shadow.x, shadow.y, shadow.size); // body
    }

    // Main figure - isolated and more prominent
    let figureGlow = p.sin(time * 0.5) * 20 + 235;
    let mouseDistance = p.dist(p.mouseX, p.mouseY, figure.x, figure.y);
    let isolation = p.map(mouseDistance, 0, 200, 0.5, 1.0);

    // Head with subtle breathing
    p.fill(140, 160, 190, figureGlow);
    p.noStroke();
    let headSize = 25 + p.sin(time * 2) * 2;
    p.ellipse(figure.x, figure.y - 40, headSize);

    // Body
    p.fill(120, 140, 170, figureGlow);
    let bodySize = 35 + p.sin(time * 1.5) * 3;
    p.ellipse(figure.x, figure.y, bodySize);

    // Arms reaching out slightly, responding to mouse
    p.stroke(120, 140, 170, figureGlow);
    p.strokeWeight(4);

    let leftArm = p.lerp(-30, -50, isolation);
    let rightArm = p.lerp(30, 50, isolation);

    p.line(figure.x, figure.y, 
           figure.x + leftArm + p.sin(time) * 5, 
           figure.y + 10 + p.cos(time * 0.8) * 3);
    p.line(figure.x, figure.y, 
           figure.x + rightArm + p.sin(time + 1) * 5, 
           figure.y + 10 + p.cos(time * 0.9) * 3);

    // Isolation field that responds to mouse
    if(mouseDistance > 100) {
      p.stroke(80, 100, 130, 60);
      p.strokeWeight(2);
      p.noFill();
      let fieldSize = 80 + p.sin(time) * 10;
      p.ellipse(figure.x, figure.y, fieldSize);
    }

    // Connection lines that fade based on proximity
    if(mouseDistance < 150) {
      let connectionOpacity = p.map(mouseDistance, 50, 150, 100, 0);
      p.stroke(160, 130, 80, connectionOpacity);
      p.strokeWeight(1);

      for(let shadow of shadowFigures) {
        if(p.random() < 0.3) {
          p.line(figure.x, figure.y, shadow.x, shadow.y);
        }
      }
    }
  };

  p.mousePressed = function() {
    // Momentary breakthrough - walls become more transparent
    for(let wall of walls) {
      wall.opacity *= 0.6;
    }

    // Shadow figures become slightly more visible
    for(let shadow of shadowFigures) {
      shadow.opacity = p.min(shadow.opacity * 1.2, 120);
    }
  };
}

function sketch(p) {
  let figures = [];
  let particles = [];
  let mouseInfluence = 0;
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create two figures that move together
    figures.push({
      x: 150,
      y: 300,
      baseY: 300,
      offsetX: 0,
      offsetY: 0,
      alpha: 180
    });

    figures.push({
      x: 250,
      y: 300,
      baseY: 300,
      offsetX: 0,
      offsetY: 0,
      alpha: 160
    });

    // Initialize floating particles for atmosphere
    for(let i = 0; i < 20; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.3, 0.3),
        size: p.random(1, 3),
        alpha: p.random(30, 80)
      });
    }
  };

  p.draw = function() {
    // Muted background with subtle orange breakthrough
    let bgColor = p.lerpColor(
      p.color(45, 52, 68), 
      p.color(88, 62, 45), 
      0.1 + 0.05 * p.sin(time * 0.01)
    );
    p.background(bgColor);

    time++;
    mouseInfluence = p.map(p.mouseX, 0, p.width, 0, 1);

    // Draw atmospheric particles
    p.noFill();
    for(let particle of particles) {
      p.stroke(120, 140, 160, particle.alpha);
      p.strokeWeight(particle.size);
      p.point(particle.x, particle.y);

      particle.x += particle.vx;
      particle.y += particle.vy;

      if(particle.x < 0) particle.x = p.width;
      if(particle.x > p.width) particle.x = 0;
      if(particle.y < 0) particle.y = p.height;
      if(particle.y > p.height) particle.y = 0;
    }

    // Calculate synchronized movement
    let baseWave = p.sin(time * 0.02) * 15;
    let mouseWave = p.sin(time * 0.03 + mouseInfluence * p.PI) * 8;

    // Update figure positions with mutual movement
    for(let i = 0; i < figures.length; i++) {
      let figure = figures[i];
      let phase = i * p.PI * 0.3; // Slight phase offset for natural variation

      figure.offsetY = baseWave + mouseWave * p.sin(time * 0.025 + phase);
      figure.y = figure.baseY + figure.offsetY;

      // Subtle horizontal drift that responds to mouse
      figure.offsetX = p.sin(time * 0.015 + phase) * 3 + mouseInfluence * 10;
      figure.x = (i === 0 ? 150 : 250) + figure.offsetX;
    }

    // Draw connecting energy between figures
    let distance = p.dist(figures[0].x, figures[0].y, figures[1].x, figures[1].y);
    let connectionAlpha = p.map(distance, 80, 120, 100, 20);

    p.stroke(140, 160, 200, connectionAlpha);
    p.strokeWeight(1);

    // Draw flowing connection
    let steps = 12;
    for(let i = 0; i < steps; i++) {
      let t = i / (steps - 1);
      let x = p.lerp(figures[0].x, figures[1].x, t);
      let y = p.lerp(figures[0].y, figures[1].y, t);

      // Add organic curve to connection
      let curve = p.sin(t * p.PI + time * 0.03) * 8;
      y += curve;

      if(i > 0) {
        let prevT = (i-1) / (steps - 1);
        let prevX = p.lerp(figures[0].x, figures[1].x, prevT);
        let prevY = p.lerp(figures[0].y, figures[1].y, prevT);
        let prevCurve = p.sin(prevT * p.PI + time * 0.03) * 8;
        prevY += prevCurve;

        p.line(prevX, prevY, x, y);
      }
    }

    // Draw the figures as flowing, organic forms
    for(let i = 0; i < figures.length; i++) {
      let figure = figures[i];

      p.push();
      p.translate(figure.x, figure.y);

      // Body - elongated organic shape
      p.fill(100, 120, 150, figure.alpha);
      p.noStroke();

      p.beginShape();
      for(let angle = 0; angle < p.TWO_PI; angle += 0.1) {
        let radius = 25 + p.sin(angle * 3 + time * 0.02) * 3;
        let x = p.cos(angle) * radius;
        let y = p.sin(angle) * radius * 1.8; // Elongated
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);

      // Suggestion of movement - trailing elements
      for(let j = 1; j <= 3; j++) {
        let trailAlpha = figure.alpha * (0.3 - j * 0.08);
        p.fill(120, 140, 180, trailAlpha);

        let trailX = -j * 8 - figure.offsetX * 0.3;
        let trailY = j * 2;

        p.ellipse(trailX, trailY, 15 - j * 2, 25 - j * 3);
      }

      // Subtle face indication
      p.fill(140, 160, 200, figure.alpha * 0.8);
      p.ellipse(0, -15, 12, 15);

      // Arms/hands reaching
      p.stroke(120, 140, 170, figure.alpha * 0.6);
      p.strokeWeight(2);
      p.noFill();

      let armReach = 15 + mouseInfluence * 8;
      let armAngle = p.sin(time * 0.025 + i * p.PI) * 0.3;

      // Reaching toward the other figure
      let reachDirection = i === 0 ? 1 : -1;
      p.line(0, 0, armReach * reachDirection * p.cos(armAngle), -5 + armReach * p.sin(armAngle));

      p.pop();
    }

    // Gentle color wash overlay for atmosphere
    p.fill(80, 100, 140, 15);
    p.noStroke();
    p.rect(0, 0, p.width, p.height);

    // Subtle orange breakthrough at horizon
    let horizonY = p.height * 0.7;
    for(let i = 0; i < 5; i++) {
      let alpha = 20 - i * 3;
      p.fill(200, 120, 60, alpha);
      p.rect(0, horizonY - i * 3, p.width, 6 + i * 2);
    }
  };

  p.mousePressed = function() {
    // Add a gentle ripple effect when clicked
    for(let i = 0; i < 5; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        size: p.random(1, 2),
        alpha: 60
      });
    }
  };
}

function sketch(p) {
  let particles = [];
  let houseOpacity = 0;
  let embraceStrength = 0;
  let breathePhase = 0;
  let lightParticles = [];
  let homeReached = false;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.RGB, 255);

    // Create warm light particles
    for(let i = 0; i < 15; i++) {
      lightParticles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(2, 8),
        alpha: p.random(30, 80),
        drift: p.random(-0.3, 0.3)
      });
    }
  };

  p.draw = function() {
    // Deep blue-tinted background with gradient
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(25, 35, 55), p.color(45, 55, 75), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    breathePhase += 0.02;
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, p.width/2, p.height/2) / (p.width/2);
    mouseInfluence = 1 - mouseInfluence;

    // Responding to proximity - the closer to center, the more "home" emerges
    houseOpacity = p.lerp(houseOpacity, mouseInfluence * 180 + 75, 0.03);
    embraceStrength = p.lerp(embraceStrength, mouseInfluence, 0.02);

    // Warm light particles floating
    p.noStroke();
    for(let particle of lightParticles) {
      particle.x += particle.drift + p.sin(p.frameCount * 0.01 + particle.y * 0.01) * 0.2;
      particle.y += p.sin(p.frameCount * 0.008 + particle.x * 0.01) * 0.15;

      if(particle.x > p.width + 10) particle.x = -10;
      if(particle.x < -10) particle.x = p.width + 10;
      if(particle.y > p.height + 10) particle.y = -10;
      if(particle.y < -10) particle.y = p.height + 10;

      p.fill(255, 200, 150, particle.alpha * mouseInfluence);
      p.circle(particle.x, particle.y, particle.size);
    }

    p.push();
    p.translate(p.width/2, p.height/2 + 50);

    // Archetypal house shape - emerging from abstract to concrete
    p.stroke(180, 190, 220, houseOpacity);
    p.strokeWeight(2 + embraceStrength * 2);
    p.noFill();

    let houseSize = 120 + p.sin(breathePhase) * 8 + embraceStrength * 30;
    let roofHeight = 40 + embraceStrength * 15;

    // House base
    let baseAlpha = houseOpacity * (0.3 + embraceStrength * 0.7);
    p.stroke(160, 180, 210, baseAlpha);
    p.rect(-houseSize/2, -roofHeight, houseSize, houseSize * 0.8);

    // Roof
    p.stroke(180, 190, 220, baseAlpha);
    p.line(-houseSize/2, -roofHeight, 0, -roofHeight - roofHeight, 0);
    p.line(houseSize/2, -roofHeight, 0, -roofHeight - roofHeight, 0);

    // Door - the entrance home
    let doorAlpha = baseAlpha * (0.5 + embraceStrength * 0.5);
    p.stroke(200, 180, 160, doorAlpha);
    p.strokeWeight(3);
    let doorWidth = 25 + embraceStrength * 10;
    let doorHeight = 45 + embraceStrength * 15;
    p.rect(-doorWidth/2, -roofHeight + houseSize * 0.8 - doorHeight, doorWidth, doorHeight);

    // Window - light within
    if(embraceStrength > 0.3) {
      p.fill(255, 220, 180, (embraceStrength - 0.3) * 200);
      p.noStroke();
      p.rect(-15, -roofHeight + 20, 30, 25);
    }

    p.pop();

    // Embracing figures - hands forming shelter
    p.push();
    p.translate(p.width/2, p.height/2 - 80);

    let embraceAlpha = embraceStrength * 120 + 50;
    p.stroke(190, 200, 230, embraceAlpha);
    p.strokeWeight(3 + embraceStrength * 2);
    p.noFill();

    // Two figures embracing, forming shelter
    let embrace1X = -60 + p.sin(breathePhase) * 5;
    let embrace2X = 60 + p.sin(breathePhase + p.PI) * 5;

    // Left figure's arm reaching around
    p.beginShape();
    p.noFill();
    p.vertex(embrace1X, 40);
    p.bezierVertex(embrace1X - 20, 0, embrace2X + 40, -10, embrace2X + 20, 20);
    p.endShape();

    // Right figure's arm reaching around
    p.beginShape();
    p.vertex(embrace2X, 40);
    p.bezierVertex(embrace2X + 20, 0, embrace1X - 40, -10, embrace1X - 20, 20);
    p.endShape();

    // Hands meeting - the shelter
    if(embraceStrength > 0.5) {
      p.stroke(220, 200, 180, (embraceStrength - 0.5) * 300);
      p.strokeWeight(2);
      p.circle(0, -15, 8);
      p.circle(-5, -12, 6);
      p.circle(5, -12, 6);
    }

    p.pop();

    // Orange sky breakthrough when home is recognized
    if(embraceStrength > 0.7) {
      p.push();
      let skyAlpha = (embraceStrength - 0.7) * 600;

      // Orange glow on horizon
      for(let i = 0; i < 30; i++) {
        let alpha = skyAlpha * (1 - i/30) * 0.3;
        p.stroke(255, 180 - i*2, 80 - i, alpha);
        p.strokeWeight(4);
        p.line(0, 150 + i*3, p.width, 150 + i*3);
      }
      p.pop();

      homeReached = true;
    }

    // Gentle particle system - the feeling of arriving
    if(p.frameCount % 30 === 0 && embraceStrength > 0.4) {
      particles.push({
        x: p.width/2 + p.random(-50, 50),
        y: p.height/2 + p.random(-50, 50),
        life: 255,
        size: p.random(3, 8)
      });
    }

    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.y -= 0.5;
      particle.life -= 2;

      p.noStroke();
      p.fill(255, 220, 190, particle.life * 0.5);
      p.circle(particle.x, particle.y, particle.size);

      if(particle.life <= 0) {
        particles.splice(i, 1);
      }
    }

    // Subtle title positioning
    if(homeReached) {
      p.fill(220, 210, 190, 180);
      p.textAlign(p.CENTER);
      p.textSize(16);
      p.text("XI", p.width/2, 50);
    }
  };

  p.mousePressed = function() {
    // Create a moment of recognition
    for(let i = 0; i < 8; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        life: 255,
        size: p.random(4, 12)
      });
    }
  };
}

function sketch(p) {
  let boat;
  let stream = [];
  let ripples = [];
  let time = 0;
  let boatX, boatY;
  let oars = [];
  let currentFlow = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize boat position
    boatX = p.width * 0.5;
    boatY = p.height * 0.4;

    // Create stream flow lines
    for(let i = 0; i < 20; i++) {
      stream.push({
        x: p.random(p.width),
        y: p.random(p.height),
        length: p.random(30, 80),
        speed: p.random(0.5, 1.5),
        opacity: p.random(0.2, 0.6)
      });
    }

    // Initialize oars
    oars = [
      { angle: 0, side: -1 },
      { angle: p.PI, side: 1 }
    ];
  };

  p.draw = function() {
    // Muted blue-tinted background with subtle gradient
    for(let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(135, 160, 180), p.color(95, 120, 145), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    time += 0.02;
    currentFlow = p.sin(time * 0.3) * 0.5;

    // Draw flowing stream lines
    p.strokeWeight(1);
    for(let flow of stream) {
      let alpha = flow.opacity * 255;
      p.stroke(180, 200, 220, alpha);

      let startX = flow.x + p.sin(time + flow.y * 0.01) * 20;
      let startY = flow.y + time * flow.speed * 10;

      // Wrap around screen
      if(startY > p.height + 50) {
        flow.y = -50;
      }

      let endX = startX + p.cos(time * 0.5 + flow.y * 0.02) * flow.length;
      let endY = startY + flow.length * 0.3;

      p.line(startX, startY, endX, endY);
    }

    // Update boat position with gentle drift
    boatX += currentFlow * 0.3;
    boatY += p.sin(time * 0.8) * 0.2;

    // Mouse interaction - gentle influence
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, boatX, boatY) < 100 ? 0.02 : 0;
    boatX = p.lerp(boatX, boatX + (p.mouseX - boatX) * mouseInfluence, 0.1);

    // Keep boat roughly centered
    if(boatX < 100 || boatX > p.width - 100) {
      boatX = p.lerp(boatX, p.width * 0.5, 0.02);
    }

    // Draw ripples when mouse is clicked
    if(p.mouseIsPressed && p.frameCount % 10 === 0) {
      ripples.push({
        x: p.mouseX,
        y: p.mouseY,
        radius: 0,
        life: 1.0
      });
    }

    // Update and draw ripples
    for(let i = ripples.length - 1; i >= 0; i--) {
      let ripple = ripples[i];
      ripple.radius += 2;
      ripple.life -= 0.02;

      if(ripple.life <= 0) {
        ripples.splice(i, 1);
        continue;
      }

      p.stroke(180, 200, 220, ripple.life * 100);
      p.strokeWeight(2);
      p.noFill();
      p.ellipse(ripple.x, ripple.y, ripple.radius * 2);
    }

    // Draw the boat
    p.push();
    p.translate(boatX, boatY);
    p.rotate(p.sin(time * 0.6) * 0.05); // Gentle rocking

    // Boat hull - earthy brown
    p.fill(85, 70, 55);
    p.stroke(65, 50, 35);
    p.strokeWeight(2);
    p.ellipse(0, 0, 80, 25);

    // Boat interior
    p.fill(95, 80, 65);
    p.ellipse(0, -2, 65, 18);

    // Draw oars with gentle rowing motion
    for(let oar of oars) {
      p.push();
      let oarAngle = oar.angle + p.sin(time * 2) * 0.3;
      p.rotate(oarAngle);

      // Oar handle
      p.stroke(70, 50, 30);
      p.strokeWeight(3);
      p.line(0, 0, oar.side * 40, 0);

      // Oar blade
      p.fill(60, 45, 30);
      p.stroke(50, 35, 20);
      p.strokeWeight(1);
      p.ellipse(oar.side * 45, 0, 15, 8);
      p.pop();
    }

    p.pop();

    // Subtle figure suggestion in boat (very minimal)
    p.fill(120, 100, 85, 150);
    p.noStroke();
    let figureY = boatY - 5 + p.sin(time * 0.6) * 0.05;
    p.ellipse(boatX, figureY, 8, 12);

    // Occasional orange sky breakthrough
    if(p.sin(time * 0.1) > 0.7) {
      p.fill(220, 140, 60, 30);
      p.noStroke();
      p.ellipse(p.width * 0.8, 80, 60 + p.sin(time) * 10, 40);
    }

    // Dreamlike particles
    for(let i = 0; i < 3; i++) {
      let px = p.width * 0.2 + p.sin(time + i) * 50;
      let py = 100 + i * 50 + p.cos(time * 0.7 + i) * 20;
      p.fill(200, 220, 240, 80);
      p.noStroke();
      p.ellipse(px, py, 3, 3);
    }
  };
}

function sketch(p) {
  let particles = [];
  let numParticles = 150;
  let figure = { x: 200, y: 300, sway: 0 };
  let depthOffset = 0;
  let breathe = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Initialize floating particles
    for (let i = 0; i < numParticles; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(2, 8),
        drift: p.random(0.3, 1.2),
        alpha: p.random(20, 60),
        hue: p.random(200, 240)
      });
    }
  };

  p.draw = function() {
    // Create gradient background - deep blue to lighter blue
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(220, 80, 15), // Deep blue
        p.color(200, 60, 40), // Lighter blue
        inter
      );
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    depthOffset += 0.005;
    breathe += 0.02;

    // Draw floating particles - creating sense of depth and drift
    for (let particle of particles) {
      let mouseInfluence = p.dist(p.mouseX, p.mouseY, particle.x, particle.y);
      let influence = p.map(mouseInfluence, 0, 200, 2, 0);

      particle.x += p.sin(depthOffset + particle.y * 0.01) * particle.drift + influence * 0.5;
      particle.y += p.cos(depthOffset + particle.x * 0.008) * 0.3;

      // Wrap particles
      if (particle.x > p.width + 20) particle.x = -20;
      if (particle.x < -20) particle.x = p.width + 20;
      if (particle.y > p.height + 20) particle.y = -20;
      if (particle.y < -20) particle.y = p.height + 20;

      p.fill(particle.hue, 70, 80, particle.alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);
    }

    // Figure floating/submerged
    figure.sway = p.sin(breathe) * 15;
    let figureAlpha = p.map(p.mouseY, 0, p.height, 80, 30);

    p.fill(210, 40, 70, figureAlpha);
    p.noStroke();

    // Body - elongated, floating
    p.push();
    p.translate(figure.x + figure.sway, figure.y);
    p.rotate(p.sin(breathe * 0.7) * 0.1);
    p.ellipse(0, 0, 60, 140);
    p.pop();

    // Head - slightly separate, dreamy
    p.push();
    p.translate(figure.x + figure.sway * 0.8, figure.y - 80);
    p.rotate(p.sin(breathe * 0.5) * 0.08);
    p.ellipse(0, 0, 45, 50);
    p.pop();

    // Arms - languid, drifting
    p.push();
    p.translate(figure.x + figure.sway, figure.y - 20);
    p.rotate(p.sin(breathe * 0.6) * 0.15);
    p.ellipse(-35, 0, 15, 80);
    p.ellipse(35, 0, 15, 80);
    p.pop();

    // Water/depth ripples around figure
    let rippleDistance = p.dist(p.mouseX, p.mouseY, figure.x, figure.y);
    if (rippleDistance < 100) {
      for (let r = 20; r < 120; r += 20) {
        p.noFill();
        p.stroke(200, 60, 60, 20);
        p.strokeWeight(2);
        p.ellipse(figure.x + figure.sway, figure.y, r + p.sin(breathe * 2) * 5, r + p.sin(breathe * 2) * 5);
      }
    }

    // Subtle light rays from above - suggesting surface
    p.stroke(45, 30, 90, 15);
    p.strokeWeight(3);
    for (let i = 0; i < 5; i++) {
      let x = p.width * 0.2 + i * p.width * 0.15;
      let waver = p.sin(depthOffset + i) * 20;
      p.line(x + waver, 0, x + waver * 2, p.height * 0.4);
    }

    // Mouse interaction creates gentle disturbance
    if (p.mouseIsPressed) {
      p.fill(200, 50, 80, 30);
      p.noStroke();
      for (let r = 10; r < 60; r += 15) {
        p.ellipse(p.mouseX, p.mouseY, r + p.sin(breathe * 3) * 8, r + p.sin(breathe * 3) * 8);
      }
    }

    // Depth layers - creating sense of blue mind consciousness
    p.fill(220, 70, 20, 10);
    p.noStroke();
    p.rect(0, 0, p.width, p.height);

    // Breathing blue overlay
    let breatheAlpha = p.map(p.sin(breathe), -1, 1, 5, 15);
    p.fill(210, 60, 40, breatheAlpha);
    p.rect(0, 0, p.width, p.height);
  };
}

function sketch(p) {
  let figure1, figure2;
  let particles = [];
  let timeParticles = [];
  let breathe = 0;
  let reachIntensity = 0;
  let skyColor, groundColor, figureColor;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize figures
    figure1 = { x: 120, y: 400, reaching: false };
    figure2 = { x: 280, y: 420, waiting: true };

    // Colors - muted and earthy with blue tint
    skyColor = p.color(140, 150, 180, 200);
    groundColor = p.color(80, 90, 110);
    figureColor = p.color(60, 70, 90);

    // Create time particles (floating moments)
    for (let i = 0; i < 12; i++) {
      timeParticles.push({
        x: p.random(50, 350),
        y: p.random(50, 200),
        size: p.random(2, 6),
        drift: p.random(-0.5, 0.5),
        bob: p.random(0.01, 0.03),
        phase: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    // Gradient sky with subtle orange breakthrough
    for (let y = 0; y < 300; y++) {
      let inter = p.map(y, 0, 300, 0, 1);
      let c = p.lerpColor(p.color(180, 140, 120, 150), skyColor, inter);
      p.stroke(c);
      p.line(0, y, 400, y);
    }

    // Ground
    p.fill(groundColor);
    p.noStroke();
    p.rect(0, 300, 400, 300);

    breathe += 0.02;

    // Mouse interaction - intensifies reaching
    let mouseDistance = p.dist(p.mouseX, p.mouseY, figure1.x, figure1.y);
    reachIntensity = p.map(p.constrain(mouseDistance, 50, 200), 200, 50, 0, 1);

    // Draw connection line (fading with distance)
    let distance = p.dist(figure1.x, figure1.y, figure2.x, figure2.y);
    p.stroke(100, 110, 130, p.map(distance, 100, 300, 150, 20));
    p.strokeWeight(1);
    p.line(figure1.x + 20, figure1.y - 30, figure2.x - 20, figure2.y - 25);

    // Draw figures with languid brush-like strokes
    drawFigure1(); // The asker
    drawFigure2(); // The waited-for

    // Time particles floating
    drawTimeParticles();

    // Subtle breath particles around figures
    if (p.frameCount % 60 === 0) {
      particles.push({
        x: figure1.x + p.random(-30, 30),
        y: figure1.y - 50,
        life: 255,
        drift: p.random(-1, 1)
      });
    }

    // Draw and update breath particles
    for (let i = particles.length - 1; i >= 0; i--) {
      let part = particles[i];
      p.fill(120, 140, 160, part.life);
      p.noStroke();
      p.ellipse(part.x, part.y, 3);

      part.y -= 1;
      part.x += part.drift * 0.5;
      part.life -= 3;

      if (part.life <= 0) {
        particles.splice(i, 1);
      }
    }
  };

  function drawFigure1() {
    p.push();
    p.translate(figure1.x, figure1.y);

    // Body with languid strokes
    p.stroke(figureColor);
    p.strokeWeight(8);
    p.noFill();

    // Torso - curved, reaching forward
    let lean = p.sin(breathe) * 2 + reachIntensity * 10;
    p.beginShape();
    p.vertex(0, 0);
    p.bezierVertex(lean, -20, lean + 5, -40, lean, -60);
    p.endShape();

    // Reaching arm
    let armReach = reachIntensity * 20 + p.sin(breathe) * 3;
    p.strokeWeight(6);
    p.line(lean, -40, lean + 30 + armReach, -35 + p.sin(breathe * 2) * 2);

    // Hand reaching
    p.strokeWeight(3);
    p.ellipse(lean + 30 + armReach, -35 + p.sin(breathe * 2) * 2, 8 + reachIntensity * 3);

    // Head - turned toward figure2
    p.strokeWeight(6);
    p.ellipse(lean, -70, 15);

    p.pop();
  }

  function drawFigure2() {
    p.push();
    p.translate(figure2.x, figure2.y);

    // Body - more still, waiting posture
    p.stroke(figureColor);
    p.strokeWeight(8);
    p.noFill();

    // Torso - straighter, patient
    let sway = p.sin(breathe * 0.7) * 1;
    p.beginShape();
    p.vertex(0, 0);
    p.bezierVertex(sway, -25, sway, -45, sway, -65);
    p.endShape();

    // Arms at sides, one slightly extended
    p.strokeWeight(6);
    p.line(sway - 5, -45, sway - 15, -25);
    p.line(sway + 5, -45, sway + 20, -30 + p.sin(breathe) * 2);

    // Head - facing away or toward, ambiguous
    p.strokeWeight(6);
    p.ellipse(sway, -75, 15);

    p.pop();
  }

  function drawTimeParticles() {
    for (let tp of timeParticles) {
      tp.y += p.sin(p.frameCount * tp.bob + tp.phase) * 0.3;
      tp.x += tp.drift;

      // Wrap around
      if (tp.x > 400) tp.x = -10;
      if (tp.x < -10) tp.x = 400;

      // Draw as soft glowing dots
      p.fill(140, 160, 200, 100);
      p.noStroke();
      p.ellipse(tp.x, tp.y, tp.size);

      // Inner glow
      p.fill(180, 200, 220, 60);
      p.ellipse(tp.x, tp.y, tp.size * 0.5);
    }
  }

  p.mousePressed = function() {
    // Create ripple of waiting energy
    for (let i = 0; i < 8; i++) {
      particles.push({
        x: figure2.x + p.random(-20, 20),
        y: figure2.y - 40 + p.random(-10, 10),
        life: 200,
        drift: p.random(-2, 2)
      });
    }
  };
}

function sketch(p) {
  let figure;
  let particles = [];
  let noise_offset = 0;
  let breathing_phase = 0;
  let transparency_base = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 1);

    // Initialize figure center
    figure = {
      x: 200,
      y: 280,
      size: 120
    };

    // Create particle system for spirit essence
    for(let i = 0; i < 40; i++) {
      particles.push({
        x: p.random(150, 250),
        y: p.random(200, 360),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.8, -0.2),
        alpha: p.random(0.3, 0.8),
        size: p.random(2, 6),
        phase: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    // Muted blue-tinted gradient background
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(210, 35, 85), p.color(215, 45, 25), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Orange sky breakthrough at top
    let orange_height = p.map(p.sin(p.frameCount * 0.008), -1, 1, 40, 80);
    for(let y = 0; y < orange_height; y++) {
      let inter = p.map(y, 0, orange_height, 0, 1);
      let c = p.lerpColor(p.color(35, 70, 90), p.color(210, 35, 85), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    breathing_phase += 0.02;
    noise_offset += 0.005;

    // Mouse interaction affects transparency and form stability
    let mouse_influence = p.map(p.dist(p.mouseX, p.mouseY, figure.x, figure.y), 0, 200, 1, 0);
    transparency_base = p.map(mouse_influence, 0, 1, 0.2, 0.8);

    // Draw ethereal particles
    p.noStroke();
    for(let particle of particles) {
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.phase += 0.05;

      let breathing_scale = 1 + 0.3 * p.sin(breathing_phase + particle.phase);
      let particle_alpha = particle.alpha * (0.3 + 0.4 * p.sin(particle.phase)) * transparency_base;

      p.fill(200, 60, 90, particle_alpha);
      p.ellipse(particle.x, particle.y, particle.size * breathing_scale);

      // Reset particles when they float away
      if(particle.y < -10 || particle.x < -10 || particle.x > 410) {
        particle.x = p.random(150, 250);
        particle.y = p.random(300, 400);
      }
    }

    // Draw the figure - both solid and ethereal
    p.push();
    p.translate(figure.x, figure.y);

    // Body breathing effect
    let breath_scale = 1 + 0.1 * p.sin(breathing_phase);
    p.scale(breath_scale);

    // Solid aspect - human form
    let solid_alpha = 0.4 + 0.3 * (1 - transparency_base);
    p.fill(210, 30, 60, solid_alpha);
    p.noStroke();

    // Torso
    p.ellipse(0, 20, 60, 90);

    // Head
    p.ellipse(0, -40, 45, 55);

    // Arms - languid, expressive
    p.push();
    let arm_sway = 10 * p.sin(breathing_phase * 0.7);
    p.rotate(p.radians(arm_sway));
    p.ellipse(-25, 10, 15, 50);
    p.ellipse(25, 10, 15, 50);
    p.pop();

    // Ethereal aspect - spirit trying to hold form
    let ethereal_alpha = transparency_base * 0.6;
    p.stroke(190, 80, 95, ethereal_alpha);
    p.strokeWeight(2);
    p.noFill();

    // Wavering outline
    p.beginShape();
    for(let angle = 0; angle < p.TWO_PI; angle += 0.1) {
      let r = 40 + 15 * p.noise(angle * 3 + noise_offset, p.frameCount * 0.01);
      let x = r * p.cos(angle);
      let y = r * p.sin(angle) - 10;
      p.vertex(x, y);
    }
    p.endShape(p.CLOSE);

    // Face - suggestion of features
    p.noStroke();
    p.fill(200, 40, 80, solid_alpha * 1.2);
    p.ellipse(-8, -45, 4, 6); // eyes
    p.ellipse(8, -45, 4, 6);
    p.ellipse(0, -35, 3, 2); // mouth suggestion

    // Hands - emphasis on hands as connection point
    p.fill(210, 25, 70, solid_alpha * 1.1);
    let hand_reach = 5 * p.sin(breathing_phase * 0.5);
    p.ellipse(-25 + hand_reach, 35, 12, 18);
    p.ellipse(25 - hand_reach, 35, 12, 18);

    p.pop();

    // Interactive shimmer on click
    if(p.mouseIsPressed && p.dist(p.mouseX, p.mouseY, figure.x, figure.y) < 100) {
      p.noStroke();
      for(let i = 0; i < 10; i++) {
        let shimmer_alpha = 0.3 * p.random(0.5, 1);
        p.fill(180, 70, 95, shimmer_alpha);
        let shimmer_x = figure.x + p.random(-80, 80);
        let shimmer_y = figure.y + p.random(-80, 80);
        p.ellipse(shimmer_x, shimmer_y, p.random(3, 8));
      }
    }
  };
}

function sketch(p) {
  let lightSource;
  let figure;
  let particles = [];
  let lightIntensity = 0;
  let fearLevel = 1;
  let handShield = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    lightSource = { x: 320, y: 150, radius: 80 };
    figure = { x: 120, y: 350, bodyHeight: 180 };

    for(let i = 0; i < 30; i++) {
      particles.push({
        x: lightSource.x + p.random(-40, 40),
        y: lightSource.y + p.random(-40, 40),
        vx: p.random(-0.5, 0.5),
        vy: p.random(0.2, 0.8),
        life: p.random(100, 255),
        maxLife: p.random(100, 255)
      });
    }
  };

  p.draw = function() {
    // Muted blue-tinted gradient background
    for(let i = 0; i < p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(45, 55, 75), p.color(25, 35, 55), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Calculate mouse influence
    let mouseDistance = p.dist(p.mouseX, p.mouseY, lightSource.x, lightSource.y);
    lightIntensity = p.map(p.constrain(mouseDistance, 50, 200), 200, 50, 0.2, 1.2);

    let figureDistance = p.dist(p.mouseX, p.mouseY, figure.x, figure.y - 60);
    fearLevel = p.map(p.constrain(figureDistance, 0, 150), 0, 150, 1.5, 0.3);
    handShield = p.map(p.constrain(figureDistance, 0, 100), 0, 100, 1, 0);

    // Draw light rays emanating from source
    p.push();
    p.translate(lightSource.x, lightSource.y);
    for(let angle = 0; angle < p.TWO_PI; angle += p.PI/8) {
      let rayLength = 150 * lightIntensity + p.sin(p.frameCount * 0.05 + angle) * 20;
      let alpha = 40 * lightIntensity;

      p.stroke(255, 200, 100, alpha);
      p.strokeWeight(3);
      let endX = p.cos(angle) * rayLength;
      let endY = p.sin(angle) * rayLength;
      p.line(0, 0, endX, endY);

      // Softer outer rays
      p.stroke(255, 220, 150, alpha * 0.5);
      p.strokeWeight(1);
      p.line(0, 0, endX * 1.3, endY * 1.3);
    }
    p.pop();

    // Main light source with orange breakthrough
    let lightAlpha = 150 * lightIntensity;
    p.fill(255, 180, 80, lightAlpha);
    p.noStroke();
    p.ellipse(lightSource.x, lightSource.y, lightSource.radius * lightIntensity, lightSource.radius * lightIntensity);

    // Inner core
    p.fill(255, 220, 120, lightAlpha * 0.8);
    p.ellipse(lightSource.x, lightSource.y, lightSource.radius * 0.6 * lightIntensity, lightSource.radius * 0.6 * lightIntensity);

    // Update and draw light particles
    for(let i = particles.length - 1; i >= 0; i--) {
      let part = particles[i];
      part.x += part.vx;
      part.y += part.vy;
      part.life -= 1;

      if(part.life <= 0) {
        particles[i] = {
          x: lightSource.x + p.random(-40, 40),
          y: lightSource.y + p.random(-40, 40),
          vx: p.random(-0.5, 0.5),
          vy: p.random(0.2, 0.8),
          life: p.random(100, 255),
          maxLife: p.random(100, 255)
        };
      }

      let alpha = p.map(part.life, 0, part.maxLife, 0, 100) * lightIntensity;
      p.fill(255, 200, 100, alpha);
      p.noStroke();
      p.ellipse(part.x, part.y, 3, 3);
    }

    // Draw figure body - simple, intimate silhouette
    p.fill(30, 40, 60);
    p.noStroke();

    // Body
    p.ellipse(figure.x, figure.y, 40, figure.bodyHeight);

    // Head position influenced by fear
    let headY = figure.y - figure.bodyHeight/2 - 30;
    let headTilt = fearLevel * 15;

    p.push();
    p.translate(figure.x, headY);
    p.rotate(-headTilt * p.PI/180);

    // Head
    p.fill(35, 45, 65);
    p.ellipse(0, 0, 50, 55);
    p.pop();

    // Shielding hands - the central gesture
    let handX = figure.x + 15 + handShield * 20;
    let handY = headY - 5;

    // Right hand shielding eyes
    p.push();
    p.translate(handX, handY);
    p.rotate(-0.3 - handShield * 0.5);
    p.fill(40, 50, 70);
    p.ellipse(0, 0, 35, 15);

    // Fingers slightly spread
    for(let i = 0; i < 4; i++) {
      let fingerX = -12 + i * 8;
      let fingerY = -2 + p.sin(fingerX * 0.3) * 3;
      p.ellipse(fingerX, fingerY, 6, 20);
    }
    p.pop();

    // Left hand supporting/reinforcing the shield
    p.push();
    p.translate(figure.x - 5, handY + 10);
    p.rotate(0.2 + handShield * 0.3);
    p.fill(40, 50, 70);
    p.ellipse(0, 0, 30, 12);
    p.pop();

    // Subtle ground/landscape line
    p.stroke(60, 70, 90);
    p.strokeWeight(2);
    let groundY = figure.y + figure.bodyHeight/2 + 20;
    p.line(0, groundY, p.width, groundY);

    // Environmental response to light
    if(lightIntensity > 0.8) {
      p.fill(255, 200, 100, 20);
      p.noStroke();
      p.rect(0, 0, p.width, p.height/3);
    }

    // Breathing animation for the figure
    let breathe = p.sin(p.frameCount * 0.03) * 2;
    figure.bodyHeight = 180 + breathe;
  };

  p.mousePressed = function() {
    // On click, create a moment of decision - brief light surge
    lightIntensity = 1.5;
    for(let i = 0; i < 10; i++) {
      particles.push({
        x: lightSource.x + p.random(-60, 60),
        y: lightSource.y + p.random(-60, 60),
        vx: p.random(-1, 1),
        vy: p.random(0.5, 1.5),
        life: p.random(150, 200),
        maxLife: p.random(150, 200)
      });
    }
  };
}

