    time += 0.01;

    // Calculate emergence based on time and mouse proximity
    let mouseProx = p.dist(p.mouseX, p.mouseY, figure.x, figure.y);
    mouseInfluence = p.map(mouseProx, 0, 200, 1.0, 0.3);
    mouseInfluence = p.constrain(mouseInfluence, 0.3, 1.0);

    emergenceAmount = (p.sin(time * 0.8) * 0.3 + 0.7) * mouseInfluence;

    // Update figure properties based on emergence
    figure.armSpread = p.lerp(figure.armSpread, emergenceAmount * 80, 0.03);
    figure.openness = p.lerp(figure.openness, emergenceAmount, 0.02);

    // Update and draw light particles
    p.blendMode(p.ADD);

    for(let i = lightParticles.length - 1; i >= 0; i--) {
      let particle = lightParticles[i];

      // Move particles
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.vy += 0.001; // slight gravity

      // Add floating motion
      particle.x += p.sin(time + particle.angle) * 0.1;
      particle.y += p.cos(time * 0.7 + particle.angle) * 0.05;

      // Fade life
      particle.life -= 0.005;

      // Draw particle with warm orange glow
      let alpha = p.map(particle.life, 0, particle.maxLife, 0, 180);
      p.fill(255, 180, 80, alpha * emergenceAmount);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size * particle.life);

      // Add subtle outer glow
      p.fill(255, 200, 120, alpha * 0.3 * emergenceAmount);
      p.ellipse(particle.x, particle.y, particle.size * particle.life * 2);

      // Reset particle if dead
      if(particle.life <= 0) {
        particle.x = figure.x + p.random(-30, 30);
        particle.y = figure.y + p.random(-40, 20);
        particle.vx = p.random(-0.3, 0.3);
        particle.vy = p.random(-1, -0.2);
        particle.life = p.random(0.8, 1.2);
        particle.angle = p.random(p.TWO_PI);
      }
    }

    p.blendMode(p.BLEND);

    // Draw the figure
    p.pushMatrix();
    p.translate(figure.x, figure.y);

    // Body with languid brush stroke style
    p.strokeWeight(3);
    p.stroke(180, 190, 220, 200);
    p.fill(120, 140, 170, 100 + figure.openness * 50);

    // Torso - elongated and graceful
    p.ellipse(0, 0, 40, 80);

    // Head with gentle glow
    p.fill(160, 170, 200, 150 + figure.openness * 80);
    p.ellipse(0, -50, 35, 35);

    // Arms opening outward - the key gesture of emergence
    p.strokeWeight(4);
    p.stroke(200, 210, 240, 180 + figure.openness * 75);

    // Left arm
    let leftArmX = -figure.armSpread;
    let leftArmY = -15 - p.sin(figure.armSpread * 0.02) * 10;
    p.line(0, -10, leftArmX, leftArmY);
    p.line(leftArmX, leftArmY, leftArmX - 20, leftArmY + 10);

    // Right arm
    let rightArmX = figure.armSpread;
    let rightArmY = -15 - p.sin(figure.armSpread * 0.02) * 10;
    p.line(0, -10, rightArmX, rightArmY);
    p.line(rightArmX, rightArmY, rightArmX + 20, rightArmY + 10);

    // Central radiant glow emanating from figure
    p.blendMode(p.ADD);
    for(let r = 80; r > 0; r -= 10) {
      let alpha = p.map(r, 0, 80, 100, 0) * emergenceAmount;
      p.fill(255, 190, 100, alpha * 0.3);
      p.noStroke();
      p.ellipse(0, -20, r * 2, r * 1.5);
    }

    p.blendMode(p.BLEND);
    p.popMatrix();

    // Subtle horizon line suggesting landscape
    p.stroke(100, 120, 150, 60);
    p.strokeWeight(2);
    p.line(0, p.height * 0.8, p.width, p.height * 0.8 + p.sin(time) * 3);
  };

  p.mousePressed = function() {
    // Add burst of particles on click
    for(let i = 0; i < 15; i++) {
      lightParticles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-1, 1),
        vy: p.random(-2, -0.5),
        life: p.random(0.8, 1.5),
        maxLife: p.random(1.0, 1.5),
        size: p.random(3, 10),
        angle: p.random(p.TWO_PI)
      });
    }
  };
}

function sketch(p) {
  let figure = {};
  let breathPhase = 0;
  let innerGlow = 0;
  let particles = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize figure
    figure.x = 200;
    figure.y = 380;
    figure.handX = 200;
    figure.handY = 320;

    // Create subtle particles for inner knowing
    for (let i = 0; i < 12; i++) {
      particles.push({
        x: figure.x + p.random(-30, 30),
        y: figure.y + p.random(-40, 0),
        alpha: p.random(50, 150),
        size: p.random(2, 6),
        drift: p.random(-0.3, 0.3)
      });
    }
  };

  p.draw = function() {
    time += 0.01;
    breathPhase = p.sin(time * 2) * 0.3;
    innerGlow = p.map(p.sin(time * 1.5), -1, 1, 30, 80);

    // Sky gradient with orange breakthrough
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let skyColor = p.lerpColor(
        p.color(180 + innerGlow/2, 120 + innerGlow/3, 80 + innerGlow/4),
        p.color(60, 80, 120),
        inter
      );
      p.stroke(skyColor);
      p.line(0, y, p.width, y);
    }

    // Ground - muted earth tones
    p.fill(95, 85, 75, 180);
    p.noStroke();
    p.ellipse(200, 520, 300, 120);

    // Subtle landscape elements
    drawDistantHills();

    // Internal knowing particles
    drawKnowingParticles();

    // Main figure
    drawFigure();

    // Interactive glow around hand on heart
    let mouseDistance = p.dist(p.mouseX, p.mouseY, figure.handX, figure.handY);
    if (mouseDistance < 60) {
      let glowIntensity = p.map(mouseDistance, 0, 60, 100, 0);
      p.fill(255, 200, 100, glowIntensity * 0.3);
      p.noStroke();
      p.ellipse(figure.handX, figure.handY, 40 + glowIntensity * 0.2);
    }
  };

  function drawDistantHills() {
    p.fill(80, 90, 110, 100);
    p.noStroke();
    p.beginShape();
    p.vertex(0, 450);
    for (let x = 0; x <= p.width; x += 20) {
      let hillHeight = 420 + p.noise(x * 0.01, time * 0.2) * 40;
      p.vertex(x, hillHeight);
    }
    p.vertex(p.width, p.height);
    p.vertex(0, p.height);
    p.endShape(p.CLOSE);
  }

  function drawKnowingParticles() {
    for (let particle of particles) {
      particle.y += particle.drift;
      particle.x += p.sin(time + particle.x * 0.01) * 0.2;
      particle.alpha = 80 + p.sin(time * 2 + particle.x * 0.05) * 30;

      if (particle.y < figure.y - 60) {
        particle.y = figure.y + p.random(-10, 10);
        particle.x = figure.x + p.random(-30, 30);
      }

      p.fill(150, 180, 220, particle.alpha * 0.6);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);
    }
  }

  function drawFigure() {
    // Figure silhouette with gentle breathing
    p.push();
    p.translate(figure.x, figure.y + breathPhase);

    // Body - simple, grounded form
    p.fill(60, 70, 90, 200);
    p.noStroke();
    p.ellipse(0, 0, 80, 160);

    // Shoulders
    p.ellipse(-25, -50, 35, 45);
    p.ellipse(25, -50, 35, 45);

    // Head - slightly upward gaze
    p.ellipse(0, -90, 55, 65);

    // Hand on heart - the gesture of knowing
    figure.handX = figure.x - 15 + p.sin(time * 3) * 2;
    figure.handY = figure.y - 30 + breathPhase;

    p.fill(80, 90, 110, 220);
    p.ellipse(-15, -30, 18, 25);

    // Inner light at heart center
    p.fill(255, 180, 80, innerGlow);
    p.ellipse(-10, -25, 12 + breathPhase * 3);

    // Subtle aura of certainty
    p.stroke(120, 140, 180, 40);
    p.strokeWeight(2);
    p.noFill();
    p.ellipse(0, -20, 100 + innerGlow * 0.5);

    p.pop();
  }

  p.mousePressed = function() {
    // Pulse of recognition when clicked
    innerGlow = 120;
    for (let particle of particles) {
      particle.alpha = 200;
      particle.drift = p.random(-1, -0.2);
    }
  };
}

function sketch(p) {
  let figure1, figure2;
  let recognitionMoment = 0;
  let particles = [];
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize figures
    figure1 = {
      x: p.width * 0.3,
      y: p.height * 0.6,
      angle: 0,
      recognition: 0
    };

    figure2 = {
      x: p.width * 0.7,
      y: p.height * 0.5,
      angle: p.PI,
      recognition: 0
    };

    // Create recognition particles
    for(let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(2, 6),
        alpha: p.random(0.3, 0.8),
        drift: p.random(-0.5, 0.5)
      });
    }
  };

  p.draw = function() {
    // Muted blue-tinted sky gradient
    for(let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(180, 160, 140, 50), // warm muted top
        p.color(120, 140, 160, 80), // blue-tinted bottom
        inter
      );
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Orange sky breakthrough near horizon
    let orangeY = p.height * 0.3;
    p.fill(220, 140, 80, 60);
    p.noStroke();
    p.ellipse(p.width/2, orangeY, p.width * 1.5, 80);

    // Mouse influence
    mouseInfluence = p.map(p.mouseX, 0, p.width, 0, 1);

    // Recognition moment builds over time
    recognitionMoment += 0.005;
    let recognition = p.map(p.sin(recognitionMoment), -1, 1, 0.2, 1);

    // Update figure angles based on recognition and mouse
    figure1.angle = p.lerp(0, p.PI * 0.3, recognition * mouseInfluence);
    figure2.angle = p.lerp(p.PI, p.PI * 0.7, recognition * mouseInfluence);

    figure1.recognition = recognition * mouseInfluence;
    figure2.recognition = recognition * mouseInfluence;

    // Draw recognition particles
    p.fill(255, 220, 180, 40);
    p.noStroke();
    for(let particle of particles) {
      let particleAlpha = particle.alpha * recognition * mouseInfluence;
      p.fill(255, 220, 180, particleAlpha * 100);

      let connectionForce = p.dist(particle.x, particle.y, p.width/2, p.height * 0.55) / 200;
      particle.x += particle.drift * (1 - connectionForce);
      particle.y += p.sin(p.millis() * 0.001 + particle.x * 0.01) * 0.3;

      p.ellipse(particle.x, particle.y, particle.size * (1 + recognition * 0.5));

      // Wrap particles
      if(particle.x < 0) particle.x = p.width;
      if(particle.x > p.width) particle.x = 0;
    }

    // Draw figures
    drawFigure(figure1, true);
    drawFigure(figure2, false);

    // Draw connection light between figures
    if(figure1.recognition > 0.3) {
      p.stroke(255, 200, 150, figure1.recognition * 80);
      p.strokeWeight(2);
      let midX = (figure1.x + figure2.x) / 2;
      let midY = (figure1.y + figure2.y) / 2;

      // Soft connecting arc
      p.noFill();
      p.bezier(
        figure1.x, figure1.y - 20,
        midX, midY - 40,
        midX, midY - 40,
        figure2.x, figure2.y - 20
      );
    }
  };

  function drawFigure(fig, isLeft) {
    p.push();
    p.translate(fig.x, fig.y);
    p.rotate(fig.angle);

    // Body - simple, gestural
    p.stroke(100, 120, 140, 150);
    p.strokeWeight(3);
    p.noFill();

    // Torso
    p.line(0, -20, 0, 20);

    // Arms reaching/gesturing
    let armReach = fig.recognition * 15;
    if(isLeft) {
      p.line(0, -10, 20 + armReach, -5);
      p.line(0, 5, 15 + armReach, 15);
    } else {
      p.line(0, -10, -20 - armReach, -5);
      p.line(0, 5, -15 - armReach, 15);
    }

    // Head - subtle
    p.fill(160, 140, 120, 120 + fig.recognition * 100);
    p.noStroke();
    p.ellipse(0, -35, 15, 18);

    // Eyes - the light of recognition
    if(fig.recognition > 0.2) {
      p.fill(255, 220, 180, fig.recognition * 200);
      let eyeOffset = isLeft ? 2 : -2;
      p.ellipse(eyeOffset, -37, 2 + fig.recognition * 2, 2);
      p.ellipse(-eyeOffset, -37, 2 + fig.recognition * 2, 2);
    }

    p.pop();
  }

  p.mousePressed = function() {
    // Reset recognition moment on click
    recognitionMoment = 0;

    // Add particle burst at mouse
    for(let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        size: p.random(3, 8),
        alpha: 0.8,
        drift: p.random(-1, 1)
      });
    }

    // Remove excess particles
    if(particles.length > 50) {
      particles.splice(0, 10);
    }
  };
}

function sketch(p) {
  let figures = [];
  let skyParticles = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create three figures with slight variations
    figures.push({
      x: 120,
      y: 400,
      baseY: 400,
      sway: 0.5,
      phase: 0
    });
    figures.push({
      x: 200,
      y: 390,
      baseY: 390,
      sway: 0.3,
      phase: p.PI / 3
    });
    figures.push({
      x: 280,
      y: 405,
      baseY: 405,
      sway: 0.4,
      phase: p.PI / 2
    });

    // Create sky particles for subtle movement
    for (let i = 0; i < 20; i++) {
      skyParticles.push({
        x: p.random(0, 400),
        y: p.random(0, 200),
        vx: p.random(-0.2, 0.2),
        vy: p.random(-0.1, 0.1),
        alpha: p.random(10, 30)
      });
    }
  };

  p.draw = function() {
    time += 0.01;

    // Create gradient sky - orange to muted blue
    for (let y = 0; y < 300; y++) {
      let inter = p.map(y, 0, 300, 0, 1);
      let c = p.lerpColor(
        p.color(255, 150, 80, 200), // Orange sky
        p.color(120, 140, 180, 100), // Blue-tinted horizon
        inter
      );
      p.stroke(c);
      p.line(0, y, 400, y);
    }

    // Ground with blue tint
    p.fill(80, 90, 120);
    p.noStroke();
    p.rect(0, 300, 400, 300);

    // Sky particles for atmosphere
    p.fill(255, 200, 120, 50);
    p.noStroke();
    for (let particle of skyParticles) {
      p.ellipse(particle.x, particle.y, 3, 3);
      particle.x += particle.vx;
      particle.y += particle.vy;

      if (particle.x < 0) particle.x = 400;
      if (particle.x > 400) particle.x = 0;
      if (particle.y < 0) particle.y = 200;
      if (particle.y > 200) particle.y = 0;
    }

    // Mouse interaction - figures lean slightly toward cursor
    let mouseInfluence = p.map(p.mouseX, 0, 400, -10, 10);

    // Draw figures
    for (let i = 0; i < figures.length; i++) {
      let fig = figures[i];

      // Gentle swaying motion
      let sway = p.sin(time + fig.phase) * fig.sway;
      fig.y = fig.baseY + sway;

      // Mouse influence
      let lean = mouseInfluence * 0.3;

      p.push();
      p.translate(fig.x + lean, fig.y);

      // Body - simple elongated shape
      p.fill(60, 70, 90, 180);
      p.noStroke();
      p.ellipse(0, 0, 25, 80);

      // Head
      p.fill(100, 110, 130, 200);
      p.ellipse(0, -50, 20, 25);

      // Arms extending toward each other
      p.stroke(80, 90, 110, 150);
      p.strokeWeight(3);
      if (i === 0) { // Left figure reaches right
        p.line(12, -20, 25, -15);
      } else if (i === 2) { // Right figure reaches left
        p.line(-12, -20, -25, -15);
      } else { // Center figure has both arms out
        p.line(-15, -20, -25, -15);
        p.line(15, -20, 25, -15);
      }

      p.pop();
    }

    // Connecting lines between figures (bonds of standing by)
    p.stroke(120, 100, 80, 100);
    p.strokeWeight(1);
    for (let i = 0; i < figures.length - 1; i++) {
      let alpha = p.map(p.sin(time * 2), -1, 1, 30, 80);
      p.stroke(120, 100, 80, alpha);
      p.line(figures[i].x, figures[i].y - 30, 
             figures[i + 1].x, figures[i + 1].y - 30);
    }

    // Orange sky glow intensifies with mouse proximity to top
    if (p.mouseY < 200) {
      let intensity = p.map(p.mouseY, 200, 0, 0, 1);
      p.fill(255, 180, 100, intensity * 60);
      p.noStroke();
      p.rect(0, 0, 400, 250);
    }

    // Subtle breathing light around figures
    let breathe = p.sin(time * 3) * 0.5 + 0.5;
    p.fill(200, 180, 140, breathe * 20);
    p.noStroke();
    for (let fig of figures) {
      p.ellipse(fig.x, fig.y, 80, 120);
    }
  };

  p.mousePressed = function() {
    // On click, create a brief orange sky bloom
    for (let i = 0; i < 5; i++) {
      skyParticles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        alpha: 100
      });
    }
  };
}

function sketch(p) {
  let figures = [];
  let pathParticles = [];
  let breathingPhase = 0;
  let embraceStrength = 0;
  let skyBurst = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create two figures for the embrace
    figures.push({
      x: 180,
      y: 320,
      targetX: 180,
      targetY: 320,
      angle: 0.2
    });

    figures.push({
      x: 220,
      y: 320,
      targetX: 220,
      targetY: 320,
      angle: -0.2
    });

    // Initialize path particles representing the journey
    for(let i = 0; i < 30; i++) {
      pathParticles.push({
        x: p.random(50, 350),
        y: p.random(500, 580),
        targetX: 200,
        targetY: 340,
        alpha: p.random(50, 150),
        size: p.random(2, 5),
        speed: p.random(0.005, 0.02)
      });
    }
  };

  p.draw = function() {
    // Background - muted earth tones with blue tint
    let bgColor = p.color(45, 52, 68);
    p.background(bgColor);

    // Sky burst - orange breaking through
    skyBurst += (p.mouseY < 200 ? 0.03 : -0.02);
    skyBurst = p.constrain(skyBurst, 0, 1);

    if(skyBurst > 0.1) {
      p.fill(255, 140, 60, skyBurst * 100);
      p.noStroke();
      for(let i = 0; i < 8; i++) {
        let burst = p.sin(p.millis() * 0.001 + i) * skyBurst * 20;
        p.ellipse(200, 100 + burst, 300 - i * 20, 60);
      }
    }

    // Ground plane - earthy, muted
    p.fill(65, 68, 58);
    p.noStroke();
    p.rect(0, 400, 400, 200);

    // Breathing animation
    breathingPhase += 0.02;
    let breathe = p.sin(breathingPhase) * 0.5 + 0.5;

    // Mouse interaction affects embrace strength
    let mouseDistance = p.dist(p.mouseX, p.mouseY, 200, 320);
    embraceStrength = p.map(mouseDistance, 0, 200, 1, 0);
    embraceStrength = p.constrain(embraceStrength, 0, 1);

    // Draw path particles - the journey converging
    for(let particle of pathParticles) {
      let progress = p.sin(p.millis() * particle.speed) * 0.5 + 0.5;
      particle.x = p.lerp(particle.x, particle.targetX, progress * 0.01);
      particle.y = p.lerp(particle.y, particle.targetY, progress * 0.01);

      p.fill(120, 135, 150, particle.alpha * embraceStrength);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);

      // Trail effect
      if(p.frameCount % 3 === 0) {
        p.fill(120, 135, 150, particle.alpha * 0.3);
        p.ellipse(particle.x + p.random(-5, 5), particle.y + p.random(-5, 5), particle.size * 0.5);
      }
    }

    // Draw figures in embrace
    p.push();
    p.translate(200, 320);

    // Figure 1 - left
    p.push();
    p.rotate(figures[0].angle * embraceStrength + breathe * 0.1);
    p.translate(-20 * embraceStrength, 0);

    // Body
    p.stroke(140, 150, 180);
    p.strokeWeight(8);
    p.noFill();
    p.beginShape();
    p.curveVertex(-10, -40);
    p.curveVertex(-15, -20);
    p.curveVertex(-10, 0);
    p.curveVertex(-5, 30);
    p.curveVertex(0, 50);
    p.endShape();

    // Arms reaching
    p.strokeWeight(5);
    p.line(-10, -10, 15 * embraceStrength, -5);
    p.line(-8, 10, 20 * embraceStrength, 15);

    // Head
    p.fill(160, 170, 200, 200);
    p.noStroke();
    p.ellipse(-8, -45, 15, 18);
    p.pop();

    // Figure 2 - right  
    p.push();
    p.rotate(-figures[1].angle * embraceStrength - breathe * 0.1);
    p.translate(20 * embraceStrength, 0);

    // Body
    p.stroke(140, 150, 180);
    p.strokeWeight(8);
    p.noFill();
    p.beginShape();
    p.curveVertex(10, -40);
    p.curveVertex(15, -20);
    p.curveVertex(10, 0);
    p.curveVertex(5, 30);
    p.curveVertex(0, 50);
    p.endShape();

    // Arms reaching
    p.strokeWeight(5);
    p.line(10, -10, -15 * embraceStrength, -5);
    p.line(8, 10, -20 * embraceStrength, 15);

    // Head
    p.fill(160, 170, 200, 200);
    p.noStroke();
    p.ellipse(8, -45, 15, 18);
    p.pop();

    p.pop();

    // Connection energy between figures
    if(embraceStrength > 0.3) {
      p.stroke(200, 180, 120, embraceStrength * 100);
      p.strokeWeight(2);
      for(let i = 0; i < 5; i++) {
        let wave = p.sin(p.millis() * 0.005 + i) * 10;
        p.line(180 + wave, 315 + i * 2, 220 - wave, 315 + i * 2);
      }
    }

    // Subtle light emanation from the center
    p.fill(255, 220, 180, 30 * embraceStrength);
    p.noStroke();
    let lightRadius = 100 + breathe * 20;
    p.ellipse(200, 320, lightRadius, lightRadius);

    // Ground shadows - suggesting presence
    p.fill(40, 45, 55, 100);
    p.ellipse(200, 420, 80 + embraceStrength * 20, 20);
  };
}

function sketch(p) {
  let particles = [];
  let lantern = {};
  let roads = [];
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize lantern
    lantern = {
      x: p.width * 0.5,
      y: p.height * 0.4,
      glow: 0,
      pulsePhase: 0
    };

    // Create road paths
    for(let i = 0; i < 3; i++) {
      roads.push({
        points: [],
        offset: i * 0.3
      });

      // Generate curved road points
      for(let j = 0; j <= 20; j++) {
        let progress = j / 20;
        let x = p.width * 0.5 + (progress - 0.5) * p.width * 1.2 + p.sin(progress * p.PI * 2 + i) * 30;
        let y = p.height * 0.7 + progress * p.height * 0.8;
        roads[i].points.push({x: x, y: y});
      }
    }

    // Initialize floating particles
    for(let i = 0; i < 40; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.3, 0.1),
        size: p.random(1, 3),
        alpha: p.random(0.3, 0.8),
        phase: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    // Create twilight gradient background
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(25, 25, 60), // Deep blue night
        p.color(80, 60, 120), // Purple twilight
        inter
      );
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    mouseInfluence = p.map(p.mouseX, 0, p.width, 0.5, 1.5);

    // Draw distant roads with perspective
    p.noFill();
    for(let road of roads) {
      p.strokeWeight(1);
      p.stroke(60, 80, 140, 60);

      p.beginShape();
      p.noFill();
      for(let point of road.points) {
        let influence = p.dist(p.mouseX, p.mouseY, point.x, point.y) / 200;
        let offsetX = point.x + p.sin(p.millis() * 0.001 + road.offset) * 5 * influence;
        p.vertex(offsetX, point.y);
      }
      p.endShape();

      // Road markers - distant lights
      for(let i = 2; i < road.points.length; i += 4) {
        let point = road.points[i];
        p.fill(120, 150, 200, 80 + p.sin(p.millis() * 0.003 + i) * 40);
        p.noStroke();
        p.ellipse(point.x, point.y, 3, 3);
      }
    }

    // Draw floating particles (stars/dust)
    for(let particle of particles) {
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.phase += 0.02;

      // Wrap around edges
      if(particle.x < 0) particle.x = p.width;
      if(particle.x > p.width) particle.x = 0;
      if(particle.y < 0) particle.y = p.height;
      if(particle.y > p.height) particle.y = 0;

      // Mouse interaction - particles drawn to cursor
      let distToMouse = p.dist(particle.x, particle.y, p.mouseX, p.mouseY);
      if(distToMouse < 100) {
        let force = p.map(distToMouse, 0, 100, 0.02, 0);
        particle.vx += (p.mouseX - particle.x) * force * 0.001;
        particle.vy += (p.mouseY - particle.y) * force * 0.001;
      }

      p.fill(150, 180, 255, particle.alpha * 255 * (0.5 + 0.5 * p.sin(particle.phase)));
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size, particle.size);
    }

    // Central lantern/compass - the seeking symbol
    lantern.pulsePhase += 0.03;
    lantern.glow = 0.7 + 0.3 * p.sin(lantern.pulsePhase);

    let lanternSize = 60 * mouseInfluence;
    let glowSize = lanternSize * 2 * lantern.glow;

    // Outer glow
    p.noFill();
    for(let r = glowSize; r > 0; r -= 5) {
      let alpha = p.map(r, 0, glowSize, 200, 0);
      p.stroke(100, 150, 255, alpha * 0.3);
      p.strokeWeight(2);
      p.ellipse(lantern.x, lantern.y, r, r);
    }

    // Lantern body
    p.fill(40, 60, 120);
    p.stroke(80, 120, 180);
    p.strokeWeight(2);
    p.ellipse(lantern.x, lantern.y, lanternSize, lanternSize);

    // Inner light
    p.fill(150, 200, 255, 150 + 100 * lantern.glow);
    p.noStroke();
    p.ellipse(lantern.x, lantern.y, lanternSize * 0.6, lanternSize * 0.6);

    // Compass points/directional markers
    p.pushMatrix();
    p.translate(lantern.x, lantern.y);
    p.rotate(p.millis() * 0.0005);

    for(let i = 0; i < 8; i++) {
      p.pushMatrix();
      p.rotate(i * p.PI / 4);

      p.stroke(120, 160, 220, 150);
      p.strokeWeight(2);
      p.line(0, -lanternSize * 0.4, 0, -lanternSize * 0.6);

      // Needle pointing toward mouse
      if(i === 0) {
        p.stroke(200, 220, 255);
        p.strokeWeight(3);
        let angle = p.atan2(p.mouseY - lantern.y, p.mouseX - lantern.x);
        p.rotate(angle);
        p.line(0, 0, lanternSize * 0.4, 0);

        // Arrowhead
        p.line(lanternSize * 0.4, 0, lanternSize * 0.3, -5);
        p.line(lanternSize * 0.4, 0, lanternSize * 0.3, 5);
      }

      p.popMatrix();
    }
    p.popMatrix();

    // Horizon line with distant glow
    p.stroke(60, 100, 160, 100);
    p.strokeWeight(1);
    p.line(0, p.height * 0.75, p.width, p.height * 0.75);

    // Distant light on horizon
    let horizonGlow = 50 + 20 * p.sin(p.millis() * 0.002);
    p.fill(100, 140, 200, horizonGlow);
    p.noStroke();
    p.ellipse(p.width * 0.8, p.height * 0.75, 30, 15);
  };

  p.mousePressed = function() {
    // Create burst of particles when clicked
    for(let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX,
        y: p.mouseY,
        vx: p.random(-2, 2),
        vy: p.random(-2, 2),
        size: p.random(2, 4),
        alpha: p.random(0.7, 1),
        phase: p.random(p.TWO_PI)
      });
    }

    // Keep particle count manageable
    if(particles.length > 60) {
      particles.splice(0, particles.length - 50);
    }
  };
}

function sketch(p) {
  let roadPoints = [];
  let leftRoadPoints = [];
  let rightRoadPoints = [];
  let distantLights = [];
  let shadowParticles = [];
  let time = 0;
  let choicePoint = { x: 200, y: 450 };
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize road points for converging paths
    for (let i = 0; i < 30; i++) {
      let progress = i / 29;
      // Left road curves in from left edge
      leftRoadPoints.push({
        x: p.lerp(50, choicePoint.x - 20, progress),
        y: p.lerp(550, choicePoint.y, progress),
        width: p.lerp(80, 40, progress)
      });
      // Right road curves in from right edge
      rightRoadPoints.push({
        x: p.lerp(350, choicePoint.x + 20, progress),
        y: p.lerp(550, choicePoint.y, progress),
        width: p.lerp(80, 40, progress)
      });
    }

    // Continuing road that diverges upward
    for (let i = 0; i < 25; i++) {
      let progress = i / 24;
      roadPoints.push({
        x: p.lerp(choicePoint.x, 200, progress),
        y: p.lerp(choicePoint.y, 50, progress),
        width: p.lerp(40, 60, progress)
      });
    }

    // Distant lights along the horizon
    for (let i = 0; i < 8; i++) {
      distantLights.push({
        x: p.random(50, 350),
        y: p.random(60, 120),
        brightness: p.random(0.3, 1),
        flicker: p.random(0.02, 0.05)
      });
    }

    // Shadow particles
    for (let i = 0; i < 50; i++) {
      shadowParticles.push({
        x: p.random(0, 400),
        y: p.random(200, 600),
        size: p.random(2, 8),
        alpha: p.random(0.1, 0.3),
        drift: p.random(-0.5, 0.5)
      });
    }
  };

  p.draw = function() {
    time += 0.01;

    // Golden hour twilight gradient
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c1 = p.color(135, 206, 235); // Sky blue
      let c2 = p.color(25, 25, 112);   // Midnight blue
      let c3 = p.color(255, 215, 0, 50); // Golden overlay

      let skyColor = p.lerpColor(c1, c2, inter);
      p.stroke(p.red(skyColor) + p.sin(time) * 10, 
               p.green(skyColor) + p.cos(time) * 5, 
               p.blue(skyColor) + 20);
      p.line(0, y, 400, y);
    }

    // Mouse influence for interactive seeking
    mouseInfluence = p.map(p.mouseX, 0, 400, -1, 1);
    let mouseY_influence = p.map(p.mouseY, 0, 600, 0, 1);

    // Draw distant lights with flickering
    p.noStroke();
    for (let light of distantLights) {
      let flicker = p.sin(time * 60 + light.x * 0.1) * light.flicker + 1;
      let brightness = light.brightness * flicker * (1 + mouseY_influence * 0.3);

      // Glow effect
      for (let r = 20; r > 0; r--) {
        let alpha = p.map(r, 0, 20, brightness * 0.8, 0);
        p.fill(255, 235, 150, alpha * 255);
        p.ellipse(light.x, light.y, r * 2);
      }

      p.fill(255, 255, 200, brightness * 255);
      p.ellipse(light.x, light.y, 3);
    }

    // Draw shadow particles drifting
    for (let particle of shadowParticles) {
      particle.x += particle.drift + p.sin(time + particle.y * 0.01) * 0.2;
      if (particle.x > 410) particle.x = -10;
      if (particle.x < -10) particle.x = 410;

      let influenced_alpha = particle.alpha * (1 + Math.abs(mouseInfluence) * 0.5);
      p.fill(30, 50, 80, influenced_alpha * 255);
      p.ellipse(particle.x, particle.y, particle.size);
    }

    // Draw the roads with languid brush strokes
    p.strokeWeight(3);
    p.stroke(80, 120, 160, 180);
    p.fill(60, 90, 140, 100);

    // Left road
    p.beginShape();
    for (let point of leftRoadPoints) {
      let wobble = p.sin(time * 2 + point.y * 0.01) * 2;
      p.vertex(point.x + wobble + mouseInfluence * 5, point.y);
    }
    for (let i = leftRoadPoints.length - 1; i >= 0; i--) {
      let point = leftRoadPoints[i];
      let wobble = p.sin(time * 2 + point.y * 0.01) * 2;
      p.vertex(point.x + point.width + wobble + mouseInfluence * 5, point.y);
    }
    p.endShape(p.CLOSE);

    // Right road
    p.beginShape();
    for (let point of rightRoadPoints) {
      let wobble = p.sin(time * 2.5 + point.y * 0.01) * 2;
      p.vertex(point.x + wobble - mouseInfluence * 5, point.y);
    }
    for (let i = rightRoadPoints.length - 1; i >= 0; i--) {
      let point = rightRoadPoints[i];
      let wobble = p.sin(time * 2.5 + point.y * 0.01) * 2;
      p.vertex(point.x + point.width + wobble - mouseInfluence * 5, point.y);
    }
    p.endShape(p.CLOSE);

    // Central continuing road
    p.beginShape();
    for (let point of roadPoints) {
      let wobble = p.sin(time * 1.5 + point.y * 0.02) * 1.5;
      p.vertex(point.x - point.width/2 + wobble, point.y);
    }
    for (let i = roadPoints.length - 1; i >= 0; i--) {
      let point = roadPoints[i];
      let wobble = p.sin(time * 1.5 + point.y * 0.02) * 1.5;
      p.vertex(point.x + point.width/2 + wobble, point.y);
    }
    p.endShape(p.CLOSE);

    // Choice point - two seeking symbols in dialogue
    p.push();
    p.translate(choicePoint.x, choicePoint.y);

    // Left seeking symbol (compass-like)
    p.push();
    p.translate(-30 + mouseInfluence * 10, 0);
    p.rotate(time + mouseInfluence * 0.2);
    p.stroke(120, 180, 220, 200);
    p.strokeWeight(2);
    p.noFill();
    p.ellipse(0, 0, 25);
    for (let i = 0; i < 8; i++) {
      let angle = (i / 8) * p.TWO_PI;
      let x1 = p.cos(angle) * 8;
      let y1 = p.sin(angle) * 8;
      let x2 = p.cos(angle) * 15;
      let y2 = p.sin(angle) * 15;
      p.line(x1, y1, x2, y2);
    }
    p.pop();

    // Right seeking symbol (compass-like, mirrored)
    p.push();
    p.translate(30 - mouseInfluence * 10, 0);
    p.rotate(-time - mouseInfluence * 0.2);
    p.stroke(120, 180, 220, 200);
    p.strokeWeight(2);
    p.noFill();
    p.ellipse(0, 0, 25);
    for (let i = 0; i < 8; i++) {
      let angle = (i / 8) * p.TWO_PI;
      let x1 = p.cos(angle) * 8;
      let y1 = p.sin(angle) * 8;
      let x2 = p.cos(angle) * 15;
      let y2 = p.sin(angle) * 15;
      p.line(x1, y1, x2, y2);
    }
    p.pop();

    // Energy between the symbols
    let tension = p.sin(time * 3) * 0.3 + 0.7;
    p.stroke(150, 200, 255, 100 * tension);
    p.strokeWeight(1);
    for (let i = 0; i < 5; i++) {
      let y_offset = p.sin(time * 4 + i) * 3;
      p.line(-25, y_offset, 25, y_offset);
    }

    p.pop();

    // Subtle atmospheric effects
    p.fill(70, 130, 180, 20);
    p.noStroke();
    for (let i = 0; i < 3; i++) {
      let x = p.sin(time * 0.5 + i * 2) * 50 + 200;
      let y = p.cos(time * 0.3 + i * 1.5) * 30 + 150;
      p.ellipse(x, y, 60 + i * 20, 40 + i * 10);
    }
  };

  p.mousePressed = function() {
    // Create ripple effect at choice point when clicked
    if (p.dist(p.mouseX, p.mouseY, choicePoint.x, choicePoint.y) < 100) {
      for (let i = 0; i < 10; i++) {
        shadowParticles.push({
          x: choicePoint.x + p.random(-20, 20),
          y: choicePoint.y + p.random(-20, 20),
          size: p.random(3, 12),
          alpha: p.random(0.2, 0.6),
          drift: p.random(-2, 2)
        });
      }
    }
  };
}

function sketch(p) {
  let roads = [];
  let particles = [];
  let symbols = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create three converging roads
    roads.push({
      start: {x: 50, y: 500},
      control1: {x: 100, y: 350},
      control2: {x: 150, y: 250},
      end: {x: 200, y: 150}
    });
    roads.push({
      start: {x: 350, y: 500},
      control1: {x: 300, y: 350},
      control2: {x: 250, y: 250},
      end: {x: 200, y: 150}
    });
    roads.push({
      start: {x: 200, y: 550},
      control1: {x: 200, y: 400},
      control2: {x: 200, y: 300},
      end: {x: 200, y: 150}
    });

    // Create three symbols in triangular arrangement
    symbols.push({x: 200, y: 120, phase: 0});
    symbols.push({x: 150, y: 180, phase: p.TWO_PI/3});
    symbols.push({x: 250, y: 180, phase: 4*p.TWO_PI/3});

    // Initialize particles
    for(let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        size: p.random(2, 6),
        speed: p.random(0.5, 2),
        alpha: p.random(50, 150),
        direction: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    // Twilight gradient background
    for(let i = 0; i < p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(25, 25, 60), // Deep blue night
        p.color(80, 60, 120), // Purple twilight
        inter
      );
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    time += 0.01;

    // Draw languid brush stroke roads
    p.noFill();
    p.strokeWeight(8);

    roads.forEach((road, index) => {
      // Road glow
      p.stroke(100, 150, 255, 40);
      p.strokeWeight(20);
      p.bezier(road.start.x, road.start.y, road.control1.x, road.control1.y, road.control2.x, road.control2.y, road.end.x, road.end.y);

      // Road surface
      p.stroke(120, 160, 255, 180);
      p.strokeWeight(6);
      p.bezier(road.start.x, road.start.y, road.control1.x, road.control1.y, road.control2.x, road.control2.y, road.end.x, road.end.y);

      // Road highlights
      p.stroke(150, 180, 255, 100);
      p.strokeWeight(2);
      p.bezier(road.start.x - 2, road.start.y, road.control1.x - 2, road.control1.y, road.control2.x - 2, road.control2.y, road.end.x - 2, road.end.y);
    });

    // Distant horizon light
    p.fill(200, 180, 120, 60);
    p.noStroke();
    p.ellipse(200, 80, 150, 40);

    // Draw floating particles (signs/clues)
    particles.forEach(particle => {
      particle.x += p.cos(particle.direction) * particle.speed;
      particle.y += p.sin(particle.direction) * particle.speed;

      // Wrap around canvas
      if(particle.x < 0) particle.x = 400;
      if(particle.x > 400) particle.x = 0;
      if(particle.y < 0) particle.y = 600;
      if(particle.y > 600) particle.y = 0;

      // Mouse interaction - particles are drawn toward mouse
      let mouseDistance = p.dist(particle.x, particle.y, p.mouseX, p.mouseY);
      if(mouseDistance < 100) {
        let angle = p.atan2(p.mouseY - particle.y, p.mouseX - particle.x);
        particle.direction = p.lerp(particle.direction, angle, 0.05);
      }

      p.fill(150, 200, 255, particle.alpha);
      p.noStroke();
      p.push();
      p.translate(particle.x, particle.y);
      p.rotate(time + particle.direction);
      p.ellipse(0, 0, particle.size, particle.size * 0.5);
      p.pop();
    });

    // Draw the three symbols in triangular arrangement
    symbols.forEach((symbol, index) => {
      let pulse = p.sin(time * 2 + symbol.phase) * 0.3 + 1;
      let glow = p.sin(time + symbol.phase) * 20 + 80;

      // Symbol glow
      p.fill(120, 180, 255, glow * 0.5);
      p.noStroke();
      p.ellipse(symbol.x, symbol.y, 30 * pulse, 30 * pulse);

      // Symbol core
      p.fill(200, 220, 255, glow);
      p.ellipse(symbol.x, symbol.y, 15 * pulse, 15 * pulse);

      // Connecting lines between symbols (showing the triangle)
      if(index < symbols.length - 1) {
        let nextSymbol = symbols[index + 1];
        p.stroke(150, 180, 255, 60);
        p.strokeWeight(2);
        p.line(symbol.x, symbol.y, nextSymbol.x, nextSymbol.y);
      }
    });

    // Complete the triangle
    p.stroke(150, 180, 255, 60);
    p.strokeWeight(2);
    p.line(symbols[2].x, symbols[2].y, symbols[0].x, symbols[0].y);

    // Interactive shadows that stretch from mouse position
    if(p.mouseX > 0 && p.mouseY > 0) {
      p.stroke(40, 40, 80, 100);
      p.strokeWeight(3);
      symbols.forEach(symbol => {
        let shadowX = symbol.x + (symbol.x - p.mouseX) * 0.3;
        let shadowY = symbol.y + (symbol.y - p.mouseY) * 0.3;
        p.line(symbol.x, symbol.y, shadowX, shadowY);
      });
    }

    // Growth/manifestation effect at convergence point
    let convergenceGlow = p.sin(time * 3) * 30 + 50;
    p.fill(255, 220, 150, convergenceGlow);
    p.noStroke();
    p.ellipse(200, 150, convergenceGlow * 0.5, convergenceGlow * 0.5);
  };
}

function sketch(p) {
  let roads = [];
  let stars = [];
  let searchSymbols = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create four seeking symbols in square arrangement
    searchSymbols = [
      {x: 120, y: 150, angle: 0},
      {x: 280, y: 150, angle: p.PI/2},
      {x: 280, y: 300, angle: p.PI},
      {x: 120, y: 300, angle: 3*p.PI/2}
    ];

    // Create background stars
    for(let i = 0; i < 30; i++) {
      stars.push({
        x: p.random(p.width),
        y: p.random(p.height * 0.3),
        brightness: p.random(0.3, 1),
        twinkle: p.random(p.TWO_PI)
      });
    }

    // Create converging roads
    for(let i = 0; i < 4; i++) {
      roads.push({
        startX: [80, 320, 320, 80][i],
        startY: [480, 480, 120, 120][i],
        endX: 200,
        endY: 225,
        segments: [],
        traveled: 0
      });

      // Create road segments
      for(let j = 0; j < 20; j++) {
        let progress = j / 19;
        let x = p.lerp(roads[i].startX, roads[i].endX, progress);
        let y = p.lerp(roads[i].startY, roads[i].endY, progress);
        roads[i].segments.push({x: x, y: y, alpha: 0});
      }
    }
  };

  p.draw = function() {
    time += 0.02;

    // Gradient twilight sky
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c1 = p.color(20, 30, 80); // Deep blue
      let c2 = p.color(60, 80, 120); // Lighter blue
      let c3 = p.color(100, 120, 160); // Even lighter

      let skyColor;
      if(inter < 0.4) {
        skyColor = p.lerpColor(c1, c2, inter / 0.4);
      } else {
        skyColor = p.lerpColor(c2, c3, (inter - 0.4) / 0.6);
      }

      p.stroke(skyColor);
      p.line(0, y, p.width, y);
    }

    // Draw twinkling stars
    for(let star of stars) {
      let twinkle = p.sin(time * 2 + star.twinkle) * 0.3 + 0.7;
      p.fill(200, 220, 255, star.brightness * twinkle * 150);
      p.noStroke();
      p.ellipse(star.x, star.y, 2, 2);
    }

    // Draw roads with traveling light
    for(let road of roads) {
      road.traveled = (p.sin(time * 0.5) + 1) * 0.5;

      for(let i = 0; i < road.segments.length; i++) {
        let segment = road.segments[i];
        let progress = i / (road.segments.length - 1);

        // Road base
        p.stroke(80, 100, 140, 100);
        p.strokeWeight(3);
        if(i < road.segments.length - 1) {
          let next = road.segments[i + 1];
          p.line(segment.x, segment.y, next.x, next.y);
        }

        // Traveling light along road
        if(p.abs(progress - road.traveled) < 0.1) {
          let lightIntensity = 1 - p.abs(progress - road.traveled) * 10;
          p.fill(255, 255, 200, lightIntensity * 200);
          p.noStroke();
          p.ellipse(segment.x, segment.y, 8, 8);
        }
      }
    }

    // Draw four seeking symbols (compass-like)
    for(let i = 0; i < searchSymbols.length; i++) {
      let symbol = searchSymbols[i];
      let pulse = p.sin(time * 1.5 + i * p.PI/2) * 0.3 + 0.7;
      let mouseDistance = p.dist(p.mouseX, p.mouseY, symbol.x, symbol.y);
      let hover = p.map(p.constrain(mouseDistance, 0, 100), 0, 100, 1.5, 1);

      p.push();
      p.translate(symbol.x, symbol.y);
      p.rotate(symbol.angle + time * 0.3);
      p.scale(hover);

      // Outer ring
      p.noFill();
      p.stroke(150, 170, 220, pulse * 200);
      p.strokeWeight(2);
      p.ellipse(0, 0, 40, 40);

      // Inner compass needle
      p.stroke(200, 220, 255, pulse * 255);
      p.strokeWeight(3);
      p.line(0, -15, 0, 15);
      p.line(-10, 0, 10, 0);

      // Direction indicator
      p.fill(255, 255, 200, pulse * 200);
      p.noStroke();
      p.triangle(0, -15, -5, -8, 5, -8);

      p.pop();
    }

    // Central convergence point - the foundation
    let centerPulse = p.sin(time * 2) * 0.2 + 0.8;
    p.fill(180, 200, 255, centerPulse * 150);
    p.noStroke();
    p.ellipse(200, 225, 20, 20);

    // Boundary lines connecting the four symbols (foundation structure)
    p.stroke(120, 140, 180, 100);
    p.strokeWeight(1);
    for(let i = 0; i < 4; i++) {
      let current = searchSymbols[i];
      let next = searchSymbols[(i + 1) % 4];
      p.line(current.x, current.y, next.x, next.y);
    }

    // Horizon line
    p.stroke(140, 160, 200, 150);
    p.strokeWeight(2);
    p.line(0, 100, p.width, 100);

    // Interactive element - mouse creates ripples in the foundation
    if(p.mouseIsPressed) {
      let ripple = p.sin(time * 8) * 20;
      p.noFill();
      p.stroke(255, 255, 255, 100);
      p.strokeWeight(1);
      p.ellipse(p.mouseX, p.mouseY, ripple, ripple);
      p.ellipse(p.mouseX, p.mouseY, ripple * 1.5, ripple * 1.5);
    }
  };
}

function sketch(p) {
  let paths = [];
  let distantLights = [];
  let mouseInfluence = 0;
  let timeOffset = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create five seeking paths - the symbols of this suit
    for (let i = 0; i < 5; i++) {
      paths.push({
        startX: p.random(50, 350),
        startY: p.random(400, 550),
        endX: p.random(100, 300),
        endY: p.random(50, 200),
        offset: p.random(0, p.TWO_PI),
        instability: p.random(0.5, 2.0),
        broken: i === 2 // middle path is disrupted
      });
    }

    // Distant lights on horizons
    for (let i = 0; i < 8; i++) {
      distantLights.push({
        x: p.random(0, 400),
        y: p.random(50, 150),
        brightness: p.random(0.3, 0.8),
        flicker: p.random(0.02, 0.05)
      });
    }
  };

  p.draw = function() {
    // Twilight gradient sky
    for (let y = 0; y < 300; y++) {
      let inter = p.map(y, 0, 300, 0, 1);
      let c = p.lerpColor(p.color(25, 25, 45), p.color(45, 55, 85), inter);
      p.stroke(c);
      p.line(0, y, 400, y);
    }

    // Ground with blue tint
    for (let y = 300; y < 600; y++) {
      let inter = p.map(y, 300, 600, 0, 1);
      let c = p.lerpColor(p.color(45, 55, 85), p.color(20, 30, 50), inter);
      p.stroke(c);
      p.line(0, y, 400, y);
    }

    timeOffset += 0.01;
    mouseInfluence = p.map(p.mouseX + p.mouseY, 0, 1000, 0.5, 2.0);

    // Distant lights flickering
    p.strokeWeight(1);
    for (let light of distantLights) {
      let flicker = 0.7 + 0.3 * p.sin(p.millis() * light.flicker + light.x);
      p.fill(220, 200, 150, light.brightness * flicker * 255);
      p.noStroke();
      p.ellipse(light.x, light.y, 3 + flicker * 2, 3 + flicker * 2);

      // Light rays
      p.stroke(220, 200, 150, light.brightness * flicker * 60);
      p.strokeWeight(0.5);
      for (let j = 0; j < 3; j++) {
        let rayLength = p.random(20, 40) * flicker;
        let angle = p.random(0, p.TWO_PI);
        p.line(light.x, light.y, 
               light.x + p.cos(angle) * rayLength,
               light.y + p.sin(angle) * rayLength);
      }
    }

    // Draw the five seeking paths with instability
    p.strokeWeight(3);
    for (let i = 0; i < paths.length; i++) {
      let path = paths[i];

      // Calculate instability - more chaotic for disrupted paths
      let chaos = path.instability * mouseInfluence;
      let wobble = p.sin(timeOffset * 2 + path.offset) * chaos;

      if (path.broken) {
        // Broken path - fragments and false leads
        p.stroke(80, 120, 160, 150);

        // Draw fragmented segments
        let segments = 4;
        for (let seg = 0; seg < segments; seg++) {
          let t1 = seg / segments;
          let t2 = (seg + 0.6) / segments; // gaps between segments

          if (seg === 2) continue; // missing middle segment

          let x1 = p.lerp(path.startX, path.endX, t1) + wobble * 2;
          let y1 = p.lerp(path.startY, path.endY, t1);
          let x2 = p.lerp(path.startX, path.endX, t2) + wobble * 2;
          let y2 = p.lerp(path.startY, path.endY, t2);

          // Add random deviation to broken path
          x2 += p.sin(timeOffset * 3 + seg) * 15;

          p.line(x1, y1, x2, y2);
        }
      } else {
        // Intact but unstable paths
        p.stroke(100, 140, 180, 180);

        let startX = path.startX + wobble;
        let startY = path.startY;
        let endX = path.endX + wobble * 1.5;
        let endY = path.endY;

        // Draw path with languid curves
        p.noFill();
        p.beginShape();
        let steps = 20;
        for (let j = 0; j <= steps; j++) {
          let t = j / steps;
          let x = p.lerp(startX, endX, t);
          let y = p.lerp(startY, endY, t);

          // Add organic curve
          x += p.sin(t * p.PI + timeOffset + path.offset) * (10 + wobble);
          y += p.sin(t * p.PI * 2 + timeOffset * 0.7) * 5;

          p.curveVertex(x, y);
        }
        p.endShape();
      }

      // Path markers/signs that shift and become unclear
      let markerX = p.lerp(path.startX, path.endX, 0.7) + wobble;
      let markerY = p.lerp(path.startY, path.endY, 0.7);

      p.fill(120, 160, 200, 100 + p.sin(timeOffset + i) * 50);
      p.noStroke();
      p.push();
      p.translate(markerX, markerY);
      p.rotate(p.sin(timeOffset + i * 0.5) * 0.2);
      p.rect(-3, -8, 6, 16);
      p.pop();
    }

    // Searching figures/shadows in distance
    p.fill(40, 60, 90, 120);
    p.noStroke();
    for (let i = 0; i < 3; i++) {
      let x = 50 + i * 120 + p.sin(timeOffset * 0.5 + i) * 30;
      let y = 200 + p.sin(timeOffset * 0.3 + i * 2) * 20;
      p.ellipse(x, y, 8, 12);
    }

    // Interactive disruption on click
    if (p.mouseIsPressed) {
      p.stroke(150, 180, 220, 100);
      p.strokeWeight(1);
      for (let i = 0; i < 5; i++) {
        let angle = (i / 5) * p.TWO_PI + timeOffset * 2;
        let x = p.mouseX + p.cos(angle) * 30;
        let y = p.mouseY + p.sin(angle) * 30;
        p.line(p.mouseX, p.mouseY, x, y);
      }
    }

    // Lengthening shadows
    p.fill(20, 30, 45, 80);
    p.noStroke();
    for (let i = 0; i < paths.length; i++) {
      let path = paths[i];
      let shadowLength = 40 + p.sin(timeOffset + i) * 15;
      p.push();
      p.translate(path.startX, path.startY);
      p.shear(0.3, 0);
      p.ellipse(0, 0, 20, shadowLength);
      p.pop();
    }
  };
}

function sketch(p) {
  let roads = [];
  let lights = [];
  let symbols = [];
  let mouseInfluence = 0;
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create six winding roads stretching to horizon
    for (let i = 0; i < 6; i++) {
      let angle = (i / 6) * p.TWO_PI - p.PI/2;
      roads.push({
        startX: 200 + p.cos(angle) * 80,
        startY: 300 + p.sin(angle) * 50,
        angle: angle + p.PI,
        curves: []
      });

      // Generate curve points for each road
      for (let j = 0; j < 15; j++) {
        roads[i].curves.push({
          x: p.random(-30, 30),
          y: j * 25,
          offset: p.random(p.TWO_PI)
        });
      }
    }

    // Create distant lights
    for (let i = 0; i < 12; i++) {
      lights.push({
        x: p.random(50, 350),
        y: p.random(50, 200),
        brightness: p.random(0.3, 1),
        flicker: p.random(0.01, 0.03),
        size: p.random(2, 8)
      });
    }

    // Create six seeking symbols in hexagonal arrangement
    for (let i = 0; i < 6; i++) {
      let angle = (i / 6) * p.TWO_PI - p.PI/2;
      symbols.push({
        x: 200 + p.cos(angle) * 120,
        y: 300 + p.sin(angle) * 80,
        rotation: 0,
        size: 25,
        pulseOffset: i * p.PI / 3
      });
    }
  };

  p.draw = function() {
    time += 0.02;
    mouseInfluence = p.map(p.mouseX, 0, 400, 0, 1);

    // Twilight gradient background
    for (let y = 0; y < 600; y++) {
      let inter = p.map(y, 0, 600, 0, 1);
      let c1 = p.color(25, 45, 85);  // Deep blue
      let c2 = p.color(85, 65, 95);  // Purple dusk
      let c3 = p.color(120, 95, 75); // Golden horizon

      let col;
      if (inter < 0.6) {
        col = p.lerpColor(c1, c2, inter / 0.6);
      } else {
        col = p.lerpColor(c2, c3, (inter - 0.6) / 0.4);
      }

      p.stroke(col);
      p.line(0, y, 400, y);
    }

    // Draw distant lights with flicker
    for (let light of lights) {
      let flicker = 1 + p.sin(time * light.flicker * 60) * 0.3;
      let alpha = light.brightness * flicker * 255;

      p.fill(255, 220, 180, alpha * 0.6);
      p.noStroke();
      p.ellipse(light.x, light.y, light.size * flicker);

      // Light glow
      p.fill(255, 220, 180, alpha * 0.2);
      p.ellipse(light.x, light.y, light.size * flicker * 3);
    }

    // Draw the six roads with languid brush strokes
    p.strokeWeight(3);
    for (let i = 0; i < roads.length; i++) {
      let road = roads[i];
      let roadAlpha = 150 + p.sin(time + i) * 50;

      p.stroke(180, 160, 200, roadAlpha);
      p.noFill();

      p.push();
      p.translate(road.startX, road.startY);
      p.rotate(road.angle);

      p.beginShape();
      p.noFill();

      for (let j = 0; j < road.curves.length; j++) {
        let curve = road.curves[j];
        let waveX = p.sin(time + curve.offset + j * 0.3) * 15 * mouseInfluence;
        let x = curve.x + waveX;
        let y = curve.y;

        if (j === 0) {
          p.vertex(x, y);
        } else {
          p.curveVertex(x, y);
        }
      }
      p.endShape();
      p.pop();
    }

    // Draw seeking symbols in harmonious flow
    for (let i = 0; i < symbols.length; i++) {
      let symbol = symbols[i];
      let pulse = p.sin(time * 2 + symbol.pulseOffset) * 0.3 + 1;
      let drift = p.sin(time * 0.5 + i) * 10;

      p.push();
      p.translate(symbol.x + drift, symbol.y);
      p.rotate(time * 0.3 + i * p.PI/6);

      // Symbol as compass-like seeking icon
      p.stroke(150, 180, 220, 200);
      p.strokeWeight(2);
      p.noFill();

      let size = symbol.size * pulse;

      // Outer circle
      p.ellipse(0, 0, size);

      // Inner directional lines
      p.line(-size/3, 0, size/3, 0);
      p.line(0, -size/3, 0, size/3);

      // Seeking arrow pointing toward center of hexagon
      let angleToCenter = p.atan2(300 - symbol.y, 200 - symbol.x);
      p.push();
      p.rotate(angleToCenter);
      p.line(0, 0, size/2, 0);
      p.line(size/2-5, -3, size/2, 0);
      p.line(size/2-5, 3, size/2, 0);
      p.pop();

      p.pop();
    }

    // Draw connecting energy between symbols
    p.stroke(120, 150, 200, 100 + mouseInfluence * 100);
    p.strokeWeight(1);

    for (let i = 0; i < symbols.length; i++) {
      let next = (i + 1) % symbols.length;
      let flowOffset = p.sin(time * 3 + i) * 20;

      p.line(
        symbols[i].x + flowOffset,
        symbols[i].y,
        symbols[next].x - flowOffset,
        symbols[next].y
      );
    }

    // Central convergence point with gentle glow
    let centralGlow = 50 + p.sin(time * 2) * 20;
    p.fill(180, 200, 255, centralGlow);
    p.noStroke();
    p.ellipse(200, 300, 15);

    p.fill(180, 200, 255, centralGlow * 0.3);
    p.ellipse(200, 300, 40);
  };
}

function sketch(p) {
  let stars = [];
  let paths = [];
  let crossroadsCenter;
  let symbols = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    crossroadsCenter = p.createVector(200, 400);

    // Create seven symbols arranged around evaluation points
    for (let i = 0; i < 7; i++) {
      let angle = (i / 7) * p.TWO_PI - p.PI/2;
      let radius = 80 + (i % 2) * 30; // Varying distances for evaluation
      let x = crossroadsCenter.x + p.cos(angle) * radius;
      let y = crossroadsCenter.y + p.sin(angle) * radius;
      symbols.push({
        x: x,
        y: y,
        originalX: x,
        originalY: y,
        size: 12 + (i % 3) * 4,
        glow: p.random(0.5, 1.0),
        evaluated: false,
        pulse: p.random(p.TWO_PI)
      });
    }

    // Create multiple paths radiating from crossroads
    for (let i = 0; i < 5; i++) {
      let angle = (i / 5) * p.TWO_PI;
      let path = [];
      for (let j = 0; j < 15; j++) {
        let distance = j * 25 + 50;
        let x = crossroadsCenter.x + p.cos(angle) * distance;
        let y = crossroadsCenter.y + p.sin(angle) * distance;
        // Add some wandering to the paths
        x += p.noise(i * 100, j * 0.1) * 40 - 20;
        y += p.noise(i * 100 + 50, j * 0.1) * 40 - 20;
        path.push({x: x, y: y, opacity: 1 - (j / 15) * 0.8});
      }
      paths.push(path);
    }

    // Create distant stars/lights
    for (let i = 0; i < 30; i++) {
      stars.push({
        x: p.random(400),
        y: p.random(200),
        brightness: p.random(0.3, 1.0),
        twinkle: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    time += 0.01;

    // Create gradient twilight sky
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(20, 30, 80, 255), // Deep blue
        p.color(60, 80, 140, 255), // Lighter blue
        inter
      );
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Draw distant stars with twinkling
    p.fill(200, 220, 255);
    p.noStroke();
    for (let star of stars) {
      let brightness = star.brightness * (0.7 + 0.3 * p.sin(time * 2 + star.twinkle));
      p.fill(200, 220, 255, brightness * 150);
      p.circle(star.x, star.y, 3 * brightness);
    }

    // Draw paths with languid brush strokes
    p.strokeWeight(2);
    for (let i = 0; i < paths.length; i++) {
      let path = paths[i];
      p.stroke(100, 150, 200, 120);

      for (let j = 1; j < path.length; j++) {
        let opacity = path[j].opacity * (0.6 + 0.4 * p.sin(time + i));
        p.stroke(100, 150, 200, opacity * 120);

        // Languid, flowing lines
        let prevPoint = path[j-1];
        let currPoint = path[j];
        let controlX = (prevPoint.x + currPoint.x) / 2 + p.sin(time + j) * 5;
        let controlY = (prevPoint.y + currPoint.y) / 2 + p.cos(time + j) * 5;

        p.noFill();
        p.beginShape();
        p.vertex(prevPoint.x, prevPoint.y);
        p.quadraticVertex(controlX, controlY, currPoint.x, currPoint.y);
        p.endShape();
      }
    }

    // Draw crossroads center with gentle pulsing
    let centerPulse = 1 + 0.2 * p.sin(time * 1.5);
    p.fill(120, 160, 220, 100);
    p.noStroke();
    p.circle(crossroadsCenter.x, crossroadsCenter.y, 40 * centerPulse);

    // Draw the seven symbols with evaluation states
    for (let i = 0; i < symbols.length; i++) {
      let symbol = symbols[i];

      // Gentle floating movement
      symbol.x = symbol.originalX + p.sin(time + symbol.pulse) * 3;
      symbol.y = symbol.originalY + p.cos(time * 0.7 + symbol.pulse) * 2;

      // Check if mouse is near for interaction
      let distance = p.dist(p.mouseX, p.mouseY, symbol.x, symbol.y);
      if (distance < 30) {
        symbol.evaluated = true;
        symbol.glow = p.min(symbol.glow + 0.05, 2.0);
      } else {
        symbol.glow = p.max(symbol.glow - 0.02, 0.5);
      }

      // Draw symbol with glow
      let glowSize = symbol.size * symbol.glow;

      // Outer glow
      p.fill(150, 180, 255, 30);
      p.noStroke();
      p.circle(symbol.x, symbol.y, glowSize * 2);

      // Inner symbol - star-like shape for seeking
      p.fill(180, 200, 255, 200);
      p.stroke(220, 230, 255, 150);
      p.strokeWeight(1);

      p.push();
      p.translate(symbol.x, symbol.y);
      p.rotate(time * 0.3 + symbol.pulse);

      // Draw seven-pointed star for seeking
      p.beginShape();
      for (let j = 0; j < 7; j++) {
        let angle = (j / 7) * p.TWO_PI;
        let outerRadius = symbol.size;
        let innerRadius = symbol.size * 0.4;

        // Outer point
        let x1 = p.cos(angle) * outerRadius;
        let y1 = p.sin(angle) * outerRadius;
        p.vertex(x1, y1);

        // Inner point
        let innerAngle = angle + p.PI / 7;
        let x2 = p.cos(innerAngle) * innerRadius;
        let y2 = p.sin(innerAngle) * innerRadius;
        p.vertex(x2, y2);
      }
      p.endShape(p.CLOSE);
      p.pop();

      // Draw connection lines for evaluated symbols
      if (symbol.evaluated) {
        p.stroke(120, 160, 220, 100);
        p.strokeWeight(1);
        p.line(symbol.x, symbol.y, crossroadsCenter.x, crossroadsCenter.y);
      }
    }

    // Draw assessment lines - connecting evaluated symbols
    p.stroke(140, 180, 240, 80);
    p.strokeWeight(1);
    let evaluatedSymbols = symbols.filter(s => s.evaluated);
    for (let i = 0; i < evaluatedSymbols.length; i++) {
      for (let j = i + 1; j < evaluatedSymbols.length; j++) {
        let alpha = 50 * p.sin(time * 2 + i + j);
        p.stroke(140, 180, 240, p.abs(alpha));
        p.line(evaluatedSymbols[i].x, evaluatedSymbols[i].y, 
               evaluatedSymbols[j].x, evaluatedSymbols[j].y);
      }
    }

    // Add title at bottom with Roman numeral
    p.fill(160, 190, 230, 180);
    p.noStroke();
    p.textAlign(p.CENTER);
    p.textSize(16);
    p.text("VII", 200, 560);
  };

  p.mousePressed = function() {
    // Reset evaluation on click
    for (let symbol of symbols) {
      symbol.evaluated = false;
      symbol.glow = p.random(0.5, 1.0);
    }
  };
}

function sketch(p) {
