        angle: p.random(p.TWO_PI),
        speed: p.random(0.01, 0.03),
        size: p.random(15, 25),
        phase: p.random(p.TWO_PI)
      });
    }

    // Create winding paths
    for(let i = 0; i < 5; i++) {
      let path = [];
      let startX = p.random(-50, 450);
