        path.push({
          x: x,
          y: y + p.noise(x * 0.01, i * 0.5) * 60
        });
      }
      paths.push(path);
    }
  };

  p.draw = function() {
    time += 0.015;
    mouseInfluence = p.map(p.mouseX, 0, p.width, 0.5, 2.0);

