      let skyColor;
      if(inter < 0.7) {
        skyColor = p.lerpColor(c1, c2, inter / 0.7);
      } else {
        skyColor = p.lerpColor(c2, c3, (inter - 0.7) / 0.3);
      }
      p.stroke(skyColor);
      p.line(0, y, p.width, y);
    }

    // Ground gradient
    for(let y = horizon; y < p.height; y++) {
      let inter = p.map(y, horizon, p.height, 0, 1);
      let groundColor = p.lerpColor(p.color(60, 80, 120), p.color(20, 30, 60), inter);
      p.stroke(groundColor);
      p.line(0, y, p.width, y);
    }

    // Distant lights on horizon
    p.noStroke();
    for(let i = 0; i < 6; i++) {
