      p.fill(255, 200, 150, 120 * flicker);
      p.ellipse(lightX, horizon - 10, 8, 12);
      p.fill(255, 230, 180, 60 * flicker);
      p.ellipse(lightX, horizon - 10, 16, 20);
    }

    // Draw winding paths
    p.noFill();
    for(let i = 0; i < paths.length; i++) {
      let path = paths[i];
      let alpha = p.map(i, 0, paths.length - 1, 100, 30);
      p.stroke(150, 170, 200, alpha);
      p.strokeWeight(2 - i * 0.3);

      p.beginShape();
      for(let j = 0; j < path.length - 1; j++) {
        let point = path[j];
        let offsetY = p.sin(time + point.x * 0.02) * 3;
        p.curveVertex(point.x - time * 20, point.y + offsetY);
      }
      p.endShape();
    }

    // Draw the 8 seeking symbols in dynamic spiral
    p.push();
    p.translate(p.width/2, p.height * 0.65);

    for(let i = 0; i < 8; i++) {
      let symbol = symbols[i];

      // Spiral arrangement with mouse influence
      let spiralRadius = 80 + i * 12;
      let spiralAngle = time * 0.5 + i * p.PI/4;
      let x = p.cos(spiralAngle) * spiralRadius * mouseInfluence;
      let y = p.sin(spiralAngle) * spiralRadius * 0.7;

      p.push();
      p.translate(x, y);
      p.rotate(symbol.angle + time * symbol.speed);

      // Draw compass-like seeking symbol
      p.stroke(180, 200, 255, 200);
      p.strokeWeight(2);
      p.noFill();

      // Outer ring
      p.ellipse(0, 0, symbol.size, symbol.size);

      // Cross with extending lines (seeking directions)
      p.line(-symbol.size/3, 0, symbol.size/3, 0);
      p.line(0, -symbol.size/3, 0, symbol.size/3);

      // Directional markers
      for(let dir = 0; dir < 4; dir++) {
        p.push();
        p.rotate(dir * p.PI/2);
        p.stroke(220, 240, 255, 150);
        p.strokeWeight(1);
        p.line(symbol.size/2, 0, symbol.size/2 + 8, 0);
        p.pop();
      }

      p.pop();
    }
    p.pop();

    // Subtle particle system for atmosphere
    for(let i = 0; i < 20; i++) {
      let px = p.noise(time * 0.5, i * 0.1) * p.width;
      let py = p.noise(time * 0.3, i * 0.2, 100) * (p.height - horizon) + horizon;
      let alpha = p.noise(time, i) * 80 + 40;

      p.noStroke();
      p.fill(200, 220, 255, alpha);
      p.ellipse(px, py, 2, 2);
    }

    // Motion trails for mouse interaction
    if(p.mouseX > 0 && p.mouseX < p.width && p.mouseY > 0 && p.mouseY < p.height) {
      p.stroke(255, 255, 255, 30);
      p.strokeWeight(1);
      p.noFill();
      for(let i = 0; i < 5; i++) {
        let trailX = p.mouseX + p.cos(time * 2 + i) * 20;
        let trailY = p.mouseY + p.sin(time * 2 + i) * 20;
        p.ellipse(trailX, trailY, 10 + i * 3, 10 + i * 3);
      }
    }
  };

  p.mousePressed = function() {
    // Ripple effect when clicked
    for(let i = 0; i < symbols.length; i++) {
      symbols[i].speed *= 1.5;
      symbols[i].angle += p.random(-0.5, 0.5);
    }
  };
}

function sketch(p) {
  let roads = [];
  let stars = [];
  let signs = [];
  let mouseInfluence = 0;
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create nine winding roads at different depths
    for(let i = 0; i < 9; i++) {
      roads.push({
        points: [],
        depth: i * 0.1 + 0.1,
        width: p.map(i, 0, 8, 15, 3),
        alpha: p.map(i, 0, 8, 180, 60),
        completed: i < 8 ? 1.0 : 0.85 // ninth road is almost complete
      });

      // Generate road path points
      let roadPoints = [];
      for(let j = 0; j <= 50; j++) {
        let progress = j / 50;
        let x = 200 + p.sin(progress * p.PI * 2 + i * 0.3) * (80 - i * 8);
        let y = p.map(progress, 0, 1, 600, 50 + i * 15);
        roadPoints.push({x: x, y: y});
      }
      roads[i].points = roadPoints;
    }

    // Create distant lights/stars
    for(let i = 0; i < 20; i++) {
      stars.push({
        x: p.random(50, 350),
        y: p.random(50, 200),
        brightness: p.random(0.3, 1),
        twinkle: p.random(0.02, 0.05),
        size: p.random(1, 3)
      });
    }

    // Create waypoint signs along roads
    for(let i = 0; i < 9; i++) {
      if(i < 8) {
        let roadIdx = i;
        let pointIdx = Math.floor(roads[roadIdx].points.length * 0.7);
        if(roads[roadIdx].points[pointIdx]) {
          signs.push({
            x: roads[roadIdx].points[pointIdx].x,
            y: roads[roadIdx].points[pointIdx].y,
            rotation: p.random(-0.2, 0.2),
            sway: p.random(0.01, 0.03)
          });
        }
      }
    }
  };

  p.draw = function() {
    time += 0.01;
    mouseInfluence = p.map(p.mouseX, 0, 400, 0, 1);

    // Create twilight gradient background
    for(let i = 0; i <= 600; i++) {
      let inter = p.map(i, 0, 600, 0, 1);
      let c = p.lerpColor(
        p.color(25, 35, 70), // deep blue night
        p.color(180, 120, 60, 150), // golden horizon
        p.pow(inter, 2.5)
      );
      p.stroke(c);
      p.line(0, i, 400, i);
    }

    // Draw distant stars with twinkling
    p.noStroke();
    for(let star of stars) {
      let brightness = star.brightness + p.sin(time * star.twinkle * 60) * 0.3;
      brightness = p.constrain(brightness, 0.1, 1);

      p.fill(255, 240, 200, brightness * 255);
      p.ellipse(star.x, star.y, star.size * brightness, star.size * brightness);

      // Star glow
      p.fill(200, 220, 255, brightness * 30);
      p.ellipse(star.x, star.y, star.size * 3, star.size * 3);
    }

    // Draw the nine roads with languid, flowing strokes
    for(let i = roads.length - 1; i >= 0; i--) {
      let road = roads[i];

      p.strokeWeight(road.width);
      p.noFill();

      // Road surface with blue tint
      p.stroke(60, 80, 120, road.alpha);

      p.beginShape();
      for(let j = 0; j < road.points.length * road.completed; j++) {
        let point = road.points[j];
        let progress = j / road.points.length;

        // Add subtle wandering motion influenced by mouse
        let wander = p.sin(time + i * 0.5 + progress * 2) * 3 * mouseInfluence;
        let x = point.x + wander;
        let y = point.y;

        if(j === 0) {
          p.vertex(x, y);
        } else {
          let prev = road.points[j-1];
          p.bezierVertex(
            prev.x + wander * 0.5, prev.y - 10,
            x - wander * 0.5, y + 10,
            x, y
          );
        }
      }
      p.endShape();

      // Road highlights
      p.strokeWeight(road.width * 0.3);
      p.stroke(120, 140, 180, road.alpha * 0.6);

      p.beginShape();
      for(let j = 0; j < road.points.length * road.completed; j++) {
        let point = road.points[j];
        let progress = j / road.points.length;
        let wander = p.sin(time + i * 0.5 + progress * 2) * 3 * mouseInfluence;
        let x = point.x + wander;
        let y = point.y;

        if(j === 0) {
          p.vertex(x, y);
        } else {
          let prev = road.points[j-1];
          p.bezierVertex(
            prev.x + wander * 0.5, prev.y - 5,
            x - wander * 0.5, y + 5,
            x, y
          );
        }
      }
      p.endShape();
    }

    // Draw waypoint signs swaying in twilight wind
    for(let i = 0; i < signs.length; i++) {
      let sign = signs[i];

      p.push();
      p.translate(sign.x, sign.y);
      p.rotate(sign.rotation + p.sin(time * sign.sway * 60) * 0.1);

      // Sign post
      p.stroke(40, 30, 20);
      p.strokeWeight(3);
      p.line(0, 0, 0, 25);

      // Sign board with blue tint
      p.fill(80, 100, 140, 200);
      p.stroke(50, 60, 90);
      p.strokeWeight(1);
      p.rect(-8, -5, 16, 10, 2);

      // Subtle glow around signs
      p.fill(120, 140, 180, 30);
      p.noStroke();
      p.ellipse(0, 0, 25, 25);

      p.pop();
    }

    // Add atmospheric particles floating upward
    p.noStroke();
    for(let i = 0; i < 15; i++) {
      let x = p.noise(time * 0.1 + i * 0.5) * 400;
      let y = (time * 20 + i * 40) % 650 - 50;
      let alpha = p.sin(y * 0.01) * 60;

      if(alpha > 0) {
        p.fill(150, 170, 200, alpha);
        p.ellipse(x, y, 2, 2);
      }
    }

    // Final road termination effect - the ninth path fading into mystery
    let finalRoad = roads[8];
    if(finalRoad && finalRoad.points.length > 0) {
      let lastPoint = finalRoad.points[Math.floor(finalRoad.points.length * finalRoad.completed) - 1];
      if(lastPoint) {
        p.noStroke();
        for(let i = 0; i < 10; i++) {
          p.fill(100, 120, 160, 150 - i * 15);
          p.ellipse(lastPoint.x, lastPoint.y - i * 3, 20 - i, 20 - i);
        }
      }
    }
  };

  p.mousePressed = function() {
    // Subtle interaction: mouse clicks create ripples of light along roads
    for(let road of roads) {
      for(let point of road.points) {
        let distance = p.dist(p.mouseX, p.mouseY, point.x, point.y);
        if(distance < 50) {
          // Create temporary light ripple effect
          setTimeout(() => {
            // Effect handled in main draw loop through time variations
          }, 100);
        }
      }
    }
  };
}

function sketch(p) {
  let roads = [];
  let stars = [];
  let symbols = [];
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create ten winding roads
    for (let i = 0; i < 10; i++) {
      let road = {
        startX: p.random(50, 350),
        startY: p.height - 50,
        controlX1: p.random(100, 300),
        controlY1: p.random(300, 450),
        controlX2: p.random(100, 300),
        controlY2: p.random(150, 300),
        endX: p.random(150, 250) + p.random(-30, 30),
        endY: 80 + i * 5,
        brightness: p.random(0.3, 0.8),
        width: p.random(2, 8)
      };
      roads.push(road);
    }

    // Create distant stars/lights
    for (let i = 0; i < 15; i++) {
      stars.push({
        x: p.random(50, 350),
        y: p.random(50, 200),
        size: p.random(1, 3),
        twinkle: p.random(0, p.TWO_PI),
        speed: p.random(0.02, 0.05)
      });
    }

    // Create ten seeking symbols arranged in completion
    let centerX = 200;
    let centerY = 120;
    let radius = 40;

    for (let i = 0; i < 10; i++) {
      let angle = (i / 10) * p.TWO_PI - p.PI / 2;
      symbols.push({
        x: centerX + p.cos(angle) * radius,
        y: centerY + p.sin(angle) * radius,
        baseX: centerX + p.cos(angle) * radius,
        baseY: centerY + p.sin(angle) * radius,
        angle: angle,
        size: 8,
        glow: p.random(0, p.TWO_PI),
        completed: false
      });
    }
  };

  p.draw = function() {
    time += 0.01;
    mouseInfluence = p.map(p.mouseY, 0, p.height, 0.2, 1.0);

    // Create gradient background - twilight blues
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(25, 25, 60), // dark blue top
        p.color(60, 40, 80), // purple middle
        inter
      );
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Add atmospheric haze
    p.fill(40, 50, 90, 20);
    p.noStroke();
    p.ellipse(200, 150, 300, 200);

    // Draw roads with languid, searching quality
    for (let road of roads) {
      let roadAlpha = road.brightness * mouseInfluence * 255;

      // Road glow
      p.strokeWeight(road.width + 4);
      p.stroke(100, 120, 160, roadAlpha * 0.3);
      p.noFill();

      p.bezier(
        road.startX, road.startY,
        road.controlX1 + p.sin(time + road.startX * 0.01) * 5,
        road.controlY1 + p.cos(time + road.startY * 0.01) * 3,
        road.controlX2 + p.sin(time + road.endX * 0.01) * 3,
        road.controlY2 + p.cos(time + road.endY * 0.01) * 2,
        road.endX, road.endY
      );

      // Road itself
      p.strokeWeight(road.width);
      p.stroke(140, 160, 200, roadAlpha);

      p.bezier(
        road.startX, road.startY,
        road.controlX1 + p.sin(time + road.startX * 0.01) * 5,
        road.controlY1 + p.cos(time + road.startY * 0.01) * 3,
        road.controlX2 + p.sin(time + road.endX * 0.01) * 3,
        road.controlY2 + p.cos(time + road.endY * 0.01) * 2,
        road.endX, road.endY
      );
    }

    // Draw twinkling stars/distant lights
    for (let star of stars) {
      let twinkle = p.sin(time * star.speed + star.twinkle);
      let brightness = p.map(twinkle, -1, 1, 100, 255);

      p.fill(180, 190, 220, brightness);
      p.noStroke();
      p.ellipse(star.x, star.y, star.size + twinkle, star.size + twinkle);

      // Subtle cross sparkle
      p.stroke(180, 190, 220, brightness * 0.6);
      p.strokeWeight(0.5);
      let sparkle = (star.size + twinkle) * 2;
      p.line(star.x - sparkle, star.y, star.x + sparkle, star.y);
      p.line(star.x, star.y - sparkle, star.x, star.y + sparkle);
    }

    // Draw the ten symbols of completion
    let completionProgress = p.sin(time * 0.5) * 0.5 + 0.5;

    for (let i = 0; i < symbols.length; i++) {
      let symbol = symbols[i];

      // Mouse interaction - symbols respond to presence
      let mouseDistance = p.dist(p.mouseX, p.mouseY, symbol.x, symbol.y);
      let mouseFactor = p.map(mouseDistance, 0, 100, 1.5, 1.0);
      mouseFactor = p.constrain(mouseFactor, 1.0, 1.5);

      // Completion effect - symbols gradually activate
      let activationTime = (time * 0.3 + i * 0.3) % (p.TWO_PI * 2);
      symbol.completed = activationTime > p.PI;

      // Symbol position with gentle drift
      symbol.x = symbol.baseX + p.sin(time * 0.2 + i) * 2;
      symbol.y = symbol.baseY + p.cos(time * 0.15 + i) * 1.5;

      // Symbol appearance
      let alpha = symbol.completed ? 255 : 150;
      let size = symbol.size * mouseFactor;

      if (symbol.completed) {
        // Glow for completed symbols
        p.fill(160, 180, 220, 80);
        p.noStroke();
        p.ellipse(symbol.x, symbol.y, size * 3, size * 3);
      }

      // The symbol itself - a stylized compass/star
      p.push();
      p.translate(symbol.x, symbol.y);
      p.rotate(symbol.angle + time * 0.1);

      p.stroke(180, 190, 240, alpha);
      p.strokeWeight(1.5);
      p.noFill();

      // Outer ring
      p.ellipse(0, 0, size * 2, size * 2);

      // Inner star/compass points
      p.strokeWeight(2);
      for (let j = 0; j < 4; j++) {
        let pointAngle = (j / 4) * p.TWO_PI;
        let x1 = p.cos(pointAngle) * size * 0.5;
        let y1 = p.sin(pointAngle) * size * 0.5;
        let x2 = p.cos(pointAngle) * size * 1.2;
        let y2 = p.sin(pointAngle) * size * 1.2;
        p.line(x1, y1, x2, y2);
      }

      p.pop();
    }

    // Completion overflow effect
    let allCompleted = symbols.every(s => s.completed);
    if (allCompleted || completionProgress > 0.8) {
      // Gentle particle overflow suggesting transformation
      let overflowAlpha = p.map(p.sin(time), -1, 1, 20, 60);

      for (let i = 0; i < 20; i++) {
        let angle = time + i * 0.3;
        let radius = 60 + p.sin(time * 0.3 + i) * 20;
        let x = 200 + p.cos(angle) * radius;
        let y = 120 + p.sin(angle) * radius;

        p.fill(200, 210, 255, overflowAlpha);
        p.noStroke();
        p.ellipse(x, y, 2, 2);
      }
    }

    // Subtle vignette to focus the composition
    let vignette = p.createGraphics(p.width, p.height);
    vignette.fill(20, 25, 50);
    vignette.noStroke();
    vignette.ellipse(p.width/2, p.height/2, p.width * 2, p.height * 1.5);

    p.blendMode(p.MULTIPLY);
    p.tint(255, 30);
    p.image(vignette, 0, 0);
    p.blendMode(p.BLEND);
    p.noTint();
  };

  p.mousePressed = function() {
    // Clicking advances the completion cycle
    time += p.PI * 0.25;
  };
}

function sketch(p) {
  let wandererX, wandererY;
  let roadPoints = [];
  let stars = [];
  let mapSymbols = [];
  let time = 0;
  let questItems = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize wanderer position
    wandererX = 120;
    wandererY = 450;

    // Create road points for the winding path
    for (let i = 0; i < 15; i++) {
      roadPoints.push({
        x: 50 + i * 25 + p.random(-15, 15),
        y: 500 - i * 20 + p.random(-10, 10),
        width: 80 - i * 3
      });
    }

    // Create distant stars/lights
    for (let i = 0; i < 25; i++) {
      stars.push({
        x: p.random(p.width),
        y: p.random(150),
        brightness: p.random(0.3, 1),
        twinkleSpeed: p.random(0.02, 0.05)
      });
    }

    // Create map symbols scattered along the path
    for (let i = 0; i < 8; i++) {
      mapSymbols.push({
        x: p.random(50, 350),
        y: p.random(350, 550),
        type: p.random(['compass', 'marker', 'sign']),
        opacity: p.random(0.2, 0.6),
        size: p.random(8, 15)
      });
    }

    // Create floating quest items
    for (let i = 0; i < 6; i++) {
      questItems.push({
        x: p.random(p.width),
        y: p.random(200, 400),
        floatOffset: p.random(p.TWO_PI),
        type: p.random(['scroll', 'compass', 'light'])
      });
    }
  };

  p.draw = function() {
    time += 0.01;

    // Gradient sky - twilight blues
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(25, 35, 80),     // Deep blue at top
        p.color(60, 80, 120)     // Lighter blue at horizon
      );
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Draw distant mountains/horizon
    p.fill(40, 50, 90, 150);
    p.noStroke();
    p.beginShape();
    p.vertex(0, 200);
    for (let x = 0; x <= p.width; x += 20) {
      let y = 180 + p.noise(x * 0.01, time * 0.5) * 40;
      p.vertex(x, y);
    }
    p.vertex(p.width, 200);
    p.vertex(p.width, p.height);
    p.vertex(0, p.height);
    p.endShape(p.CLOSE);

    // Draw the winding road
    p.strokeWeight(3);
    for (let i = 0; i < roadPoints.length - 1; i++) {
      let opacity = p.map(i, 0, roadPoints.length, 255, 50);
      p.stroke(80, 100, 140, opacity);
      p.strokeWeight(roadPoints[i].width * 0.1);

      // Road surface
      p.fill(70, 85, 120, opacity * 0.7);
      p.noStroke();
      p.ellipse(roadPoints[i].x, roadPoints[i].y, roadPoints[i].width, 15);

      // Road edges
      p.stroke(50, 70, 100, opacity);
      p.strokeWeight(2);
      p.line(
        roadPoints[i].x - roadPoints[i].width/2, roadPoints[i].y,
        roadPoints[i+1].x - roadPoints[i+1].width/2, roadPoints[i+1].y
      );
      p.line(
        roadPoints[i].x + roadPoints[i].width/2, roadPoints[i].y,
        roadPoints[i+1].x + roadPoints[i+1].width/2, roadPoints[i+1].y
      );
    }

    // Draw stars and distant lights
    p.noStroke();
    for (let star of stars) {
      let brightness = star.brightness * (0.7 + 0.3 * p.sin(time * star.twinkleSpeed));
      p.fill(200, 220, 255, brightness * 200);
      p.circle(star.x, star.y, 3 * brightness);

      // Larger glow for brighter stars
      if (brightness > 0.8) {
        p.fill(180, 200, 255, 30);
        p.circle(star.x, star.y, 12);
      }
    }

    // Draw map symbols
    for (let symbol of mapSymbols) {
      p.push();
      p.translate(symbol.x, symbol.y);
      p.fill(120, 140, 180, symbol.opacity * 255);
      p.noStroke();

      if (symbol.type === 'compass') {
        p.circle(0, 0, symbol.size);
        p.stroke(80, 100, 140, symbol.opacity * 200);
        p.strokeWeight(1);
        p.line(0, -symbol.size/2, 0, symbol.size/2);
        p.line(-symbol.size/2, 0, symbol.size/2, 0);
      } else if (symbol.type === 'marker') {
        p.triangle(0, -symbol.size/2, -symbol.size/3, symbol.size/2, symbol.size/3, symbol.size/2);
      } else {
        p.rect(-symbol.size/2, -symbol.size/3, symbol.size, symbol.size/1.5);
      }
      p.pop();
    }

    // Draw floating quest items
    for (let item of questItems) {
      let floatY = item.y + p.sin(time * 2 + item.floatOffset) * 8;
      let mouseDistance = p.dist(p.mouseX, p.mouseY, item.x, floatY);
      let attraction = p.map(mouseDistance, 0, 200, 1.5, 0.8);

      p.push();
      p.translate(item.x, floatY);
      p.scale(attraction);
      p.fill(150, 170, 220, 150);
      p.noStroke();

      if (item.type === 'scroll') {
        p.rect(-8, -12, 16, 24, 2);
        p.fill(100, 120, 160, 100);
        for (let i = 0; i < 3; i++) {
          p.rect(-6, -8 + i * 4, 12, 1);
        }
      } else if (item.type === 'compass') {
        p.circle(0, 0, 16);
        p.stroke(100, 120, 160, 150);
        p.line(0, -6, 0, 6);
        p.line(-6, 0, 6, 0);
      } else {
        p.circle(0, 0, 12);
        p.fill(200, 220, 255, 200);
        p.circle(0, 0, 6);
      }
      p.pop();
    }

    // Calculate wanderer position with mouse influence
    let targetX = 120 + (p.mouseX - p.width/2) * 0.1;
    let targetY = 450 + p.sin(time * 1.5) * 10;
    wandererX = p.lerp(wandererX, targetX, 0.03);
    wandererY = p.lerp(wandererY, targetY, 0.05);

    // Draw wanderer's shadow
    p.fill(30, 40, 70, 100);
    p.noStroke();
    p.ellipse(wandererX + 5, wandererY + 35, 25, 8);

    // Draw the wanderer figure
    p.push();
    p.translate(wandererX, wandererY);

    // Body with languid brush stroke effect
    p.strokeWeight(8);
    p.stroke(90, 110, 150);
    p.noFill();
    p.beginShape();
    p.vertex(0, 10);
    p.vertex(2 + p.sin(time * 2) * 2, 25);
    p.vertex(-1, 35);
    p.endShape();

    // Head
    p.fill(120, 140, 180);
    p.noStroke();
    p.circle(0, 0, 16);

    // Arms - one reaching toward the horizon
    p.stroke(90, 110, 150);
    p.strokeWeight(4);
    let armReach = 15 + p.sin(time * 3) * 3;
    p.line(0, 15, armReach, 8); // Reaching arm
    p.line(0, 15, -8, 20); // Other arm

    // Legs
    p.line(0, 35, -5, 45);
    p.line(0, 35, 5, 45);

    // Quest item in hand (compass/map)
    p.push();
    p.translate(armReach, 8);
    p.rotate(p.sin(time * 2) * 0.2);
    p.fill(140, 160, 200, 200);
    p.noStroke();
    p.rect(-4, -3, 8, 6, 1);
    p.fill(100, 120, 160);
    p.circle(0, 0, 3);
    p.pop();

    p.pop();

    // Interactive golden hour light
    if (p.mouseIsPressed) {
      let lightX = p.mouseX;
      let lightY = p.mouseY;

      // Golden light rays
      for (let i = 0; i < 8; i++) {
        let angle = (p.TWO_PI / 8) * i + time;
        let rayLength = 100 + p.sin(time * 2 + i) * 30;
        let endX = lightX + p.cos(angle) * rayLength;
        let endY = lightY + p.sin(angle) * rayLength;

        p.stroke(255, 200, 100, 60);
        p.strokeWeight(3);
        p.line(lightX, lightY, endX, endY);
      }

      // Central light
      p.fill(255, 220, 150, 150);
      p.noStroke();
      p.circle(lightX, lightY, 40);
      p.fill(255, 240, 200, 200);
      p.circle(lightX, lightY, 20);
    }

    // Subtle movement in road points
    for (let i = 0; i < roadPoints.length; i++) {
      roadPoints[i].x += p.sin(time + i) * 0.1;
    }
  };
}

function sketch(p) {
  let road = [];
  let stars = [];
  let observerX, observerY;
  let roadOffset = 0;
  let twilightTime = 0;
  let eyeGlow = 0;
  let recognitionPulse = 0;
  let pathParticles = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create winding road points
    for(let i = 0; i < 15; i++) {
      road.push({
        x: 200 + p.sin(i * 0.3) * 60,
        y: 600 - i * 35,
        width: 80 - i * 3
      });
    }

    // Create distant stars/lights
    for(let i = 0; i < 25; i++) {
      stars.push({
        x: p.random(400),
        y: p.random(200),
        brightness: p.random(0.3, 1),
        twinkle: p.random(0.01, 0.03)
      });
    }

    observerX = 200;
    observerY = 480;

    // Initialize path particles
    for(let i = 0; i < 8; i++) {
      pathParticles.push({
        x: p.random(50, 350),
        y: p.random(300, 550),
        life: p.random(1),
        speed: p.random(0.5, 1.5)
      });
    }
  };

  p.draw = function() {
    // Dynamic twilight gradient
    twilightTime += 0.008;
    let skyColor1 = p.color(20 + p.sin(twilightTime) * 15, 25 + p.sin(twilightTime) * 20, 60 + p.sin(twilightTime) * 25);
    let skyColor2 = p.color(80 + p.sin(twilightTime * 0.7) * 30, 40 + p.sin(twilightTime * 0.7) * 25, 120 + p.sin(twilightTime * 0.7) * 35);

    for(let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(skyColor1, skyColor2, inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Animate road offset for sense of movement
    roadOffset += 0.3;

    // Draw distant horizon glow
    p.noStroke();
    for(let i = 0; i < 50; i++) {
      p.fill(120, 140, 180, 30 - i * 0.6);
      p.ellipse(200, 50, 300 + i * 8, 60 + i * 2);
    }

    // Draw twinkling stars/distant lights
    for(let star of stars) {
      star.brightness += star.twinkle * p.sin(p.millis() * 0.01 + star.x);
      star.brightness = p.constrain(star.brightness, 0.2, 1.2);
      p.fill(150 + star.brightness * 50, 160 + star.brightness * 40, 200 + star.brightness * 55, star.brightness * 180);
      p.ellipse(star.x, star.y, star.brightness * 4);

      // Distant light rays
      if(star.brightness > 0.8) {
        p.stroke(150, 160, 200, 30);
        p.strokeWeight(1);
        p.line(star.x, star.y - 10, star.x, star.y + 10);
        p.line(star.x - 10, star.y, star.x + 10, star.y);
      }
    }

    // Draw the road with perspective and movement
    p.noStroke();
    for(let i = road.length - 1; i >= 0; i--) {
      let segment = road[i];
      let roadAlpha = p.map(i, 0, road.length - 1, 180, 60);
      p.fill(60, 80, 120, roadAlpha);

      let waveOffset = p.sin(roadOffset + i * 0.2) * 3;
      p.ellipse(segment.x + waveOffset, segment.y, segment.width, 25);
    }

    // Draw path particles (signs and clues)
    p.stroke(120, 140, 180, 100);
    p.strokeWeight(1);
    for(let particle of pathParticles) {
      particle.life += particle.speed * 0.01;
      particle.y -= particle.speed * 0.3;

      if(particle.y < 100) {
        particle.y = 550;
        particle.x = p.random(50, 350);
        particle.life = 0;
      }

      let alpha = p.sin(particle.life) * 100 + 50;
      p.stroke(140, 160, 200, alpha);
      p.point(particle.x + p.sin(particle.life * 2) * 5, particle.y);

      // Subtle trail effect
      p.stroke(140, 160, 200, alpha * 0.3);
      p.point(particle.x + p.sin(particle.life * 2) * 5, particle.y + 3);
    }

    // Interactive recognition - eyes follow mouse with constraint
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, observerX, observerY) < 100 ? 1 : 0;
    eyeGlow = p.lerp(eyeGlow, mouseInfluence, 0.05);
    recognitionPulse += 0.1;

    let eyeOffsetX = p.constrain((p.mouseX - observerX) * 0.1, -8, 8);
    let eyeOffsetY = p.constrain((p.mouseY - observerY) * 0.1, -5, 5);

    // Draw observer figure - active and present
    p.stroke(80, 100, 140, 150);
    p.strokeWeight(3);
    p.noFill();

    // Body in contemplative pose
    p.beginShape();
    p.vertex(observerX, observerY + 40);
    p.bezierVertex(observerX - 15, observerY + 20, observerX - 10, observerY, observerX, observerY - 20);
    p.bezierVertex(observerX + 10, observerY, observerX + 15, observerY + 20, observerX, observerY + 40);
    p.endShape();

    // Head
    p.ellipse(observerX, observerY - 35, 25, 30);

    // Eyes that see and are seen
    p.strokeWeight(2);
    p.stroke(150 + eyeGlow * 50, 170 + eyeGlow * 30, 220 + eyeGlow * 35);
    p.fill(180 + eyeGlow * 40, 190 + eyeGlow * 30, 240 + eyeGlow * 15, 150 + eyeGlow * 100);
    p.ellipse(observerX - 6 + eyeOffsetX, observerY - 35 + eyeOffsetY, 6 + eyeGlow * 3);
    p.ellipse(observerX + 6 + eyeOffsetX, observerY - 35 + eyeOffsetY, 6 + eyeGlow * 3);

    // Recognition aura when mouse is near
    if(eyeGlow > 0.3) {
      p.noStroke();
      for(let i = 0; i < 5; i++) {
        p.fill(140, 160, 200, (eyeGlow * 50) - i * 10);
        p.ellipse(observerX, observerY - 15, 60 + i * 15 + p.sin(recognitionPulse) * 8);
      }
    }

    // Arm gesturing toward the path
    p.stroke(80, 100, 140, 120);
    p.strokeWeight(2);
    p.noFill();
    p.beginShape();
    p.vertex(observerX + 8, observerY - 10);
    p.bezierVertex(observerX + 25, observerY - 5, observerX + 35, observerY + 10, observerX + 40, observerY + 25);
    p.endShape();

    // Shadow extending toward horizon
    p.noStroke();
    p.fill(30, 40, 80, 60);
    p.beginShape();
    p.vertex(observerX - 12, observerY + 40);
    p.vertex(observerX + 12, observerY + 40);
    p.vertex(220, 200);
    p.vertex(180, 200);
    p.endShape();
  };
}

function sketch(p) {
  let figure = {};
  let lantern = {};
  let roads = [];
  let stars = [];
  let particles = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize figure
    figure.x = 200;
    figure.y = 350;
    figure.sway = 0;

    // Initialize lantern
    lantern.x = figure.x + 40;
    lantern.y = figure.y - 60;
    lantern.glow = 0;

    // Create winding roads
    for (let i = 0; i < 3; i++) {
      roads.push({
        points: [],
        alpha: 0.3 - i * 0.1,
        width: 80 - i * 15
      });

      // Generate road points
      for (let j = 0; j < 50; j++) {
        let x = 200 + p.sin(j * 0.3 + i * 2) * (30 + i * 10);
        let y = 600 - j * 15 + i * 50;
        roads[i].points.push({x: x, y: y});
      }
    }

    // Create distant stars/lights
    for (let i = 0; i < 15; i++) {
      stars.push({
        x: p.random(400),
        y: p.random(200),
        brightness: p.random(0.5, 1),
        pulse: p.random(0.02, 0.05),
        phase: p.random(p.TWO_PI)
      });
    }

    // Initialize search particles
    for (let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.8, -0.2),
        life: p.random(1),
        maxLife: p.random(200, 400)
      });
    }
  };

  p.draw = function() {
    time += 0.01;

    // Twilight gradient background
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c1 = p.color(20, 30, 60);      // Deep blue night
      let c2 = p.color(80, 60, 100);     // Purple twilight
      let c3 = p.color(120, 100, 140);   // Lighter purple

      let col;
      if (inter < 0.3) {
        col = p.lerpColor(c1, c2, inter / 0.3);
      } else {
        col = p.lerpColor(c2, c3, (inter - 0.3) / 0.7);
      }

      p.stroke(col);
      p.line(0, y, 400, y);
    }

    // Draw distant mountains/horizon
    p.noStroke();
    p.fill(40, 50, 80, 150);
    p.beginShape();
    p.vertex(0, 200);
    for (let x = 0; x <= 400; x += 20) {
      let y = 200 + p.sin(x * 0.02 + time) * 20 + p.sin(x * 0.008) * 40;
      p.vertex(x, y);
    }
    p.vertex(400, 600);
    p.vertex(0, 600);
    p.endShape();

    // Draw roads with languid strokes
    for (let road of roads) {
      p.strokeWeight(road.width);
      p.stroke(60, 70, 120, road.alpha * 255);
      p.noFill();

      p.beginShape();
      for (let i = 0; i < road.points.length - 1; i++) {
        let pt = road.points[i];
        let nextPt = road.points[i + 1];
        if (pt.y > 0 && pt.y < 600) {
          // Add subtle movement to road
          let offsetX = p.sin(time + i * 0.1) * 2;
          p.curveVertex(pt.x + offsetX, pt.y);
        }
      }
      p.endShape();
    }

    // Draw distant lights/stars
    for (let star of stars) {
      let brightness = star.brightness + p.sin(time * star.pulse + star.phase) * 0.3;
      brightness = p.constrain(brightness, 0.2, 1);

      p.fill(200, 180, 255, brightness * 255);
      p.noStroke();
      p.ellipse(star.x, star.y, 3, 3);

      // Subtle glow
      p.fill(150, 130, 200, brightness * 50);
      p.ellipse(star.x, star.y, 8, 8);
    }

    // Update and draw search particles
    for (let particle of particles) {
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life++;

      if (particle.life > particle.maxLife) {
        particle.x = p.random(400);
        particle.y = 600 + p.random(50);
        particle.vx = p.random(-0.5, 0.5);
        particle.vy = p.random(-0.8, -0.2);
        particle.life = 0;
      }

      let alpha = p.map(particle.life, 0, particle.maxLife, 255, 0);
      p.fill(180, 160, 220, alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, 2, 2);
    }

    // Interactive response to mouse
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, figure.x, figure.y) / 200;
    figure.sway = p.sin(time * 2) * 3 + (p.mouseX - 200) * 0.02;
    lantern.glow = 1 - mouseInfluence + p.sin(time * 3) * 0.2;

    // Draw figure's shadow first
    p.fill(20, 25, 40, 100);
    p.noStroke();
    p.ellipse(figure.x + 10, figure.y + 80, 60, 20);

    // Draw figure holding the lantern
    p.strokeWeight(3);
    p.stroke(80, 90, 140);

    // Body
    p.fill(60, 70, 120);
    p.rect(figure.x - 15 + figure.sway, figure.y, 30, 60, 5);

    // Arms - one reaching toward lantern
    p.line(figure.x - 15 + figure.sway, figure.y + 20, lantern.x - 20, lantern.y + 10);
    p.line(figure.x + 15 + figure.sway, figure.y + 20, lantern.x - 10, lantern.y + 15);

    // Head
    p.fill(80, 90, 140);
    p.ellipse(figure.x + figure.sway, figure.y - 15, 25, 25);

    // Draw the lantern with dynamic glow
    let glowIntensity = p.constrain(lantern.glow, 0.3, 1.2);

    // Lantern glow layers
    p.noStroke();
    for (let i = 40; i > 0; i -= 5) {
      let alpha = p.map(i, 0, 40, glowIntensity * 60, 0);
      p.fill(255, 200, 100, alpha);
      p.ellipse(lantern.x, lantern.y, i, i * 1.2);
    }

    // Lantern frame
    p.stroke(120, 100, 80);
    p.strokeWeight(2);
    p.fill(40, 50, 80, 150);
    p.rect(lantern.x - 10, lantern.y - 15, 20, 30, 3);

    // Light emanating from lantern
    p.stroke(255, 220, 150, glowIntensity * 100);
    p.strokeWeight(1);
    for (let angle = 0; angle < p.TWO_PI; angle += p.PI / 6) {
      let rayLength = 30 + p.sin(time * 2 + angle) * 10;
      let x2 = lantern.x + p.cos(angle) * rayLength;
      let y2 = lantern.y + p.sin(angle) * rayLength;
      p.line(lantern.x, lantern.y, x2, y2);
    }

    // Path markers/signs scattered along roads
    for (let i = 0; i < 3; i++) {
      let signX = 100 + i * 100 + p.sin(time + i) * 20;
      let signY = 450 + i * 30;

      p.stroke(100, 110, 160);
      p.strokeWeight(2);
      p.line(signX, signY, signX, signY - 40);

      p.fill(80, 90, 140, 200);
      p.rect(signX - 15, signY - 50, 30, 15, 2);
    }

    // Subtle map elements in the sky
    p.stroke(120, 130, 180, 100);
    p.strokeWeight(1);
    p.noFill();
    for (let i = 0; i < 2; i++) {
      let mapX = 50 + i * 300;
      let mapY = 80 + i * 40;
      p.beginShape();
      for (let j = 0; j < 5; j++) {
        let x = mapX + j * 20 + p.sin(time + j) * 5;
        let y = mapY + p.sin(j * 0.5 + time) * 10;
        p.vertex(x, y);
      }
      p.endShape();
    }
  };
}

function sketch(p) {
  let figure;
  let roads = [];
  let stars = [];
  let signs = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize figure at rest in center-bottom
    figure = {
      x: 200,
      y: 450,
      sway: 0
    };

    // Create multiple roads stretching to horizons
    for(let i = 0; i < 5; i++) {
      roads.push({
        startX: 50 + i * 75,
        startY: 600,
        endX: 150 + i * 25,
        endY: 100,
        offset: i * 0.3
      });
    }

    // Create distant stars/lights
    for(let i = 0; i < 20; i++) {
      stars.push({
        x: p.random(400),
        y: p.random(150),
        brightness: p.random(100, 255),
        twinkle: p.random(0.02, 0.05)
      });
    }

    // Create signs and markers
    for(let i = 0; i < 8; i++) {
      signs.push({
        x: p.random(50, 350),
        y: p.random(200, 500),
        size: p.random(15, 35),
        rotation: p.random(p.TWO_PI),
        drift: p.random(0.01, 0.03)
      });
    }
  };

  p.draw = function() {
    time += 0.01;

    // Golden hour sky gradient
    for(let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(255, 200, 100), p.color(20, 40, 80), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Twinkling stars
    for(let star of stars) {
      let brightness = star.brightness + p.sin(time * star.twinkle) * 30;
      p.fill(brightness, brightness, 255, 180);
      p.noStroke();
      p.circle(star.x, star.y, 3);
    }

    // Draw roads with perspective
    p.strokeWeight(2);
    for(let road of roads) {
      let alpha = 100 + p.sin(time + road.offset) * 30;
      p.stroke(100, 120, 200, alpha);

      // Road lines
      p.line(road.startX - 10, road.startY, road.endX - 5, road.endY);
      p.line(road.startX + 10, road.startY, road.endX + 5, road.endY);

      // Dashed center line
      for(let t = 0; t < 1; t += 0.1) {
        if(t % 0.2 < 0.1) {
          let x = p.lerp(road.startX, road.endX, t);
          let y = p.lerp(road.startY, road.endY, t);
          p.strokeWeight(1);
          p.point(x, y);
        }
      }
    }

    // Floating signs and markers
    p.strokeWeight(2);
    for(let sign of signs) {
      p.push();
      p.translate(sign.x, sign.y + p.sin(time + sign.drift * 10) * 5);
      p.rotate(sign.rotation + p.sin(time * sign.drift) * 0.2);

      p.fill(120, 150, 255, 150);
      p.stroke(80, 100, 180);

      // Diamond shape for signs
      p.beginShape();
      p.vertex(0, -sign.size/2);
      p.vertex(sign.size/2, 0);
      p.vertex(0, sign.size/2);
      p.vertex(-sign.size/2, 0);
      p.endShape(p.CLOSE);

      p.pop();
    }

    // Main figure at rest - dweller in seeking
    figure.sway = p.sin(time * 0.5) * 3;

    p.push();
    p.translate(figure.x + figure.sway, figure.y);

    // Figure's shadow lengthening
    p.fill(30, 50, 100, 100);
    p.noStroke();
    p.ellipse(20, 30, 60, 20);

    // Figure body - at complete ease
    p.fill(80, 120, 200, 200);
    p.stroke(60, 100, 180);
    p.strokeWeight(2);

    // Sitting posture
    p.ellipse(0, 0, 40, 50); // torso
    p.ellipse(0, -25, 25, 25); // head

    // Arms relaxed
    p.line(-15, -5, -25, 10);
    p.line(15, -5, 25, 10);

    // Legs in meditation pose
    p.ellipse(-12, 25, 20, 35);
    p.ellipse(12, 25, 20, 35);

    p.pop();

    // Paths radiating from figure - dwelling in the journey
    p.strokeWeight(1);
    for(let angle = 0; angle < p.TWO_PI; angle += p.PI/6) {
      let alpha = 50 + p.sin(time + angle) * 30;
      p.stroke(150, 170, 255, alpha);

      let endX = figure.x + p.cos(angle) * 150;
      let endY = figure.y + p.sin(angle) * 100;

      // Curved paths
      p.noFill();
      p.beginShape();
      for(let t = 0; t <= 1; t += 0.1) {
        let x = p.lerp(figure.x, endX, t);
        let y = p.lerp(figure.y, endY, t);
        let curve = p.sin(t * p.PI) * 20;
        p.vertex(x + curve, y);
      }
      p.endShape();
    }

    // Interactive mouse response - paths lean toward cursor
    if(p.mouseX > 0 && p.mouseX < p.width && p.mouseY > 0 && p.mouseY < p.height) {
      let mouseInfluence = p.createVector(p.mouseX - figure.x, p.mouseY - figure.y);
      mouseInfluence.normalize();
      mouseInfluence.mult(20);

      p.strokeWeight(3);
      p.stroke(200, 220, 255, 150);
      p.line(figure.x, figure.y, 
             figure.x + mouseInfluence.x, 
             figure.y + mouseInfluence.y);
    }

    // Ambient particles drifting
    p.fill(180, 200, 255, 100);
    p.noStroke();
    for(let i = 0; i < 15; i++) {
      let x = p.noise(time + i) * p.width;
      let y = p.noise(time + i + 100) * p.height;
      p.circle(x, y, 2);
    }
  };
}

