    // Draw the Ace symbol - a simple doorway/threshold symbol
    drawAceSymbol();

    // Draw stopped clock
    drawClock();

    // Draw empty chair in corner
    drawChair();

    // Update animations
    clockAngle += 0.002;
    aceSymbol.glow = p.sin(p.millis() * 0.001) * 0.3 + 0.7;
    aceSymbol.y = 300 + p.sin(p.millis() * 0.0008) * 3;
  };

  function drawRoom() {
    // Room walls with blue tint
    p.fill(25, 35, 60, 150);
    p.noStroke();

    // Left wall
    p.quad(0, 0, 80, 100, 80, 500, 0, 600);

    // Right wall
    p.quad(320, 100, 400, 0, 400, 600, 320, 500);

    // Back wall
    p.fill(20, 30, 50);
    p.rect(80, 100, 240, 400);

    // Doorway threshold
    p.fill(10, 15, 30, doorOpacity);
    p.rect(160, 100, 80, 180);

    // Door frame
    p.stroke(40, 60, 100);
    p.strokeWeight(2);
    p.noFill();
    p.rect(160, 100, 80, 180);
  }

  function drawLightShaft() {
    // Window light shaft
    p.push();
    p.translate(lightBeam.x, lightBeam.y);

    // Main light beam
    for (let i = 0; i < 5; i++) {
      let alpha = 15 - i * 3;
      p.fill(180, 200, 255, alpha);
      p.noStroke();
      let w = lightBeam.width + i * 10;
      p.rect(-w/2, 0, w, 250);
    }

    // Light beam particles
    for (let particle of lightBeam.particles) {
      p.fill(220, 240, 255, particle.opacity);
      p.circle(particle.x - lightBeam.x, particle.y - lightBeam.y, 2);

      particle.y += 0.3;
      particle.x += particle.drift;
      particle.opacity += p.random(-2, 2);

      if (particle.y > lightBeam.y + 250) {
        particle.y = lightBeam.y;
        particle.opacity = p.random(20, 60);
      }
    }
    p.pop();
  }

  function drawDustParticles() {
    for (let dust of dustParticles) {
      p.fill(120, 140, 180, dust.opacity);
      p.noStroke();
      p.circle(dust.x, dust.y, dust.size);

      dust.y += dust.speed;
      dust.x += dust.driftX;
      dust.opacity += p.random(-1, 1);

      if (dust.y > p.height) {
        dust.y = -10;
        dust.x = p.random(p.width);
      }

      if (dust.x < 0 || dust.x > p.width) {
        dust.driftX *= -1;
      }

      dust.opacity = p.constrain(dust.opacity, 20, 100);
    }
  }

  function drawAceSymbol() {
    p.push();
    p.translate(200, aceSymbol.y);
    p.scale(aceSymbol.scale);

    // Glowing effect
    for (let i = 3; i > 0; i--) {
      p.stroke(100, 150, 255, aceSymbol.glow * 30 / i);
      p.strokeWeight(i * 3);
      p.noFill();

      // Simple threshold/doorway symbol
      p.rect(-25, -30, 50, 60);
      p.line(-25, -10, 25, -10); // Threshold line
    }

    // Core symbol
    p.stroke(150, 180, 255);
    p.strokeWeight(2);
    p.fill(20, 40, 80, 100);
    p.rect(-25, -30, 50, 60);
    p.line(-25, -10, 25, -10);

    // Small emanating lines
    p.stroke(120, 160, 255, aceSymbol.glow * 100);
    p.strokeWeight(1);
    for (let i = 0; i < 8; i++) {
      let angle = (i / 8) * p.TWO_PI;
      let x1 = p.cos(angle) * 35;
      let y1 = p.sin(angle) * 35;
      let x2 = p.cos(angle) * 45;
      let y2 = p.sin(angle) * 45;
      p.line(x1, y1, x2, y2);
    }

    p.pop();

    // Mouse interaction - symbol follows mouse slightly
    let targetScale = p.map(p.mouseY, 0, p.height, 0.8, 1.2);
    aceSymbol.scale = p.lerp(aceSymbol.scale, targetScale, 0.05);
  }

  function drawClock() {
    p.push();
    p.translate(320, 180);

    // Clock face
    p.fill(30, 40, 65);
    p.stroke(60, 80, 120);
    p.strokeWeight(2);
    p.circle(0, 0, 60);

    // Clock numbers (faded)
    p.fill(80, 100, 140, 100);
    p.noStroke();
    p.textAlign(p.CENTER, p.CENTER);
    p.textSize(8);
    for (let i = 1; i <= 12; i++) {
      let angle = (i / 12) * p.TWO_PI - p.PI/2;
      let x = p.cos(angle) * 22;
      let y = p.sin(angle) * 22;
      p.text(i, x, y);
    }

    // No hands - just the center dot
    p.fill(100, 120, 160);
    p.circle(0, 0, 4);

    p.pop();
  }

  function drawChair() {
    p.push();
    p.translate(100, 450);

    p.stroke(40, 60, 100);
    p.strokeWeight(3);
    p.noFill();

    // Chair back
    p.line(-15, -50, -15, -10);
    p.line(15, -50, 15, -10);
    p.line(-15, -50, 15, -50);
    p.line(-15, -30, 15, -30);

    // Chair seat
    p.line(-15, -10, 15, -10);
    p.line(-15, -10, -20, 0);
    p.line(15, -10, 20, 0);
    p.line(-20, 0, 20, 0);

    // Chair legs
    p.line(-15, -10, -15, 20);
    p.line(15, -10, 15, 20);
    p.line(-20, 0, -20, 30);
    p.line(20, 0, 20, 30);

    p.pop();
  }
}

function sketch(p) {
  let doorway1, doorway2;
  let dustParticles = [];
  let lightShaft = {
    x: 200,
    width: 120,
    opacity: 0.3,
    oscillation: 0
  };
  let chair1, chair2;
  let clockTime = 0;
  let waitingTension = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize doorways
    doorway1 = { x: 80, y: 150, width: 60, height: 120, openness: 0.3 };
    doorway2 = { x: 260, y: 150, width: 60, height: 120, openness: 0.7 };

    // Initialize chairs
    chair1 = { x: 120, y: 350, angle: 0.1, presence: 0.8 };
    chair2 = { x: 280, y: 350, angle: -0.1, presence: 0.6 };

    // Create dust particles
    for (let i = 0; i < 25; i++) {
      dustParticles.push({
        x: p.random(lightShaft.x - lightShaft.width/2, lightShaft.x + lightShaft.width/2),
        y: p.random(50, 550),
        size: p.random(1, 3),
        speed: p.random(0.2, 0.8),
        drift: p.random(-0.3, 0.3),
        opacity: p.random(0.3, 0.8)
      });
    }
  };

  p.draw = function() {
    // Blue-tinted gradient background
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(135, 165, 195, 40), p.color(85, 115, 145, 80), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Mouse influence for tension
    mouseInfluence = p.map(p.mouseX, 0, p.width, -1, 1);
    waitingTension = p.sin(p.frameCount * 0.02) * 0.5 + mouseInfluence * 0.3;

    // Light shaft with subtle animation
    lightShaft.oscillation = p.sin(p.frameCount * 0.01) * 10;
    drawLightShaft();

    // Animated dust particles
    updateDustParticles();

    // Draw doorways with languid brush strokes
    drawDoorways();

    // Draw chairs facing each other
    drawChairs();

    // Clock without hands
    drawClock();

    // Window frames
    drawWindows();

    // Subtle interaction feedback
    if (p.mouseIsPressed) {
      drawTensionField();
    }
  };

  function drawLightShaft() {
    p.push();
    p.noStroke();

    // Main light shaft
    for (let i = 0; i < 3; i++) {
      let alpha = p.map(i, 0, 2, 0.15, 0.05);
      let width = lightShaft.width + i * 20;
      p.fill(220, 235, 255, alpha * 255);
      p.rect(lightShaft.x - width/2 + lightShaft.oscillation, 0, width, p.height);
    }
    p.pop();
  }

  function updateDustParticles() {
    for (let dust of dustParticles) {
      dust.y += dust.speed;
      dust.x += dust.drift + waitingTension * 0.5;

      // Keep particles in light shaft area
      if (dust.x < lightShaft.x - lightShaft.width/2 || dust.x > lightShaft.x + lightShaft.width/2) {
        dust.x = p.random(lightShaft.x - lightShaft.width/2, lightShaft.x + lightShaft.width/2);
      }

      if (dust.y > p.height) {
        dust.y = -10;
      }

      // Draw dust particle
      p.push();
      p.noStroke();
      p.fill(255, 255, 240, dust.opacity * 200);
      p.circle(dust.x, dust.y, dust.size);
      p.pop();
    }
  }

  function drawDoorways() {
    p.push();

    // Doorway 1 - slightly open
    p.stroke(95, 125, 155, 180);
    p.strokeWeight(3);
    p.fill(75, 100, 130, 100);

    // Frame
    p.rect(doorway1.x, doorway1.y, doorway1.width, doorway1.height);

    // Door slightly ajar
    let door1Open = doorway1.openness + waitingTension * 0.1;
    p.fill(65, 90, 120, 150);
    p.rect(doorway1.x + doorway1.width * door1Open, doorway1.y, 
           doorway1.width * (1 - door1Open), doorway1.height);

    // Doorway 2 - more open
    p.fill(75, 100, 130, 100);
    p.rect(doorway2.x, doorway2.y, doorway2.width, doorway2.height);

    let door2Open = doorway2.openness - waitingTension * 0.1;
    p.fill(65, 90, 120, 150);
    p.rect(doorway2.x + doorway2.width * door2Open, doorway2.y, 
           doorway2.width * (1 - door2Open), doorway2.height);

    p.pop();
  }

  function drawChairs() {
    p.push();
    p.strokeWeight(2);
    p.stroke(85, 115, 145, 200);

    // Chair 1
    p.push();
    p.translate(chair1.x, chair1.y);
    p.rotate(chair1.angle + waitingTension * 0.05);
    p.fill(105, 135, 165, chair1.presence * 150);

    // Seat
    p.rect(-15, 0, 30, 25);
    // Back
    p.rect(-15, -25, 30, 25);
    // Legs
    p.line(-10, 25, -10, 45);
    p.line(10, 25, 10, 45);
    p.line(-10, -25, -10, -5);
    p.line(10, -25, 10, -5);
    p.pop();

    // Chair 2
    p.push();
    p.translate(chair2.x, chair2.y);
    p.rotate(chair2.angle - waitingTension * 0.05);
    p.fill(105, 135, 165, chair2.presence * 150);

    // Seat
    p.rect(-15, 0, 30, 25);
    // Back
    p.rect(-15, -25, 30, 25);
    // Legs
    p.line(-10, 25, -10, 45);
    p.line(10, 25, 10, 45);
    p.line(-10, -25, -10, -5);
    p.line(10, -25, 10, -5);
    p.pop();

    p.pop();
  }

  function drawClock() {
    p.push();
    p.translate(200, 100);

    // Clock face
    p.stroke(115, 145, 175, 180);
    p.strokeWeight(2);
    p.fill(125, 155, 185, 100);
    p.circle(0, 0, 60);

    // Hour markers (no hands)
    p.strokeWeight(1);
    for (let i = 0; i < 12; i++) {
      let angle = i * p.TWO_PI / 12;
      let x1 = p.cos(angle) * 25;
      let y1 = p.sin(angle) * 25;
      let x2 = p.cos(angle) * 22;
      let y2 = p.sin(angle) * 22;
      p.line(x1, y1, x2, y2);
    }

    // Center dot where hands would be
    p.fill(95, 125, 155, 200);
    p.noStroke();
    p.circle(0, 0, 4);

    p.pop();
  }

  function drawWindows() {
    p.push();
    p.stroke(95, 125, 155, 120);
    p.strokeWeight(2);
    p.noFill();

    // Window 1
    p.rect(50, 80, 40, 60);
    p.line(70, 80, 70, 140);
    p.line(50, 110, 90, 110);

    // Window 2
    p.rect(310, 80, 40, 60);
    p.line(330, 80, 330, 140);
    p.line(310, 110, 350, 110);

    p.pop();
  }

  function drawTensionField() {
    p.push();
    p.noFill();
    p.stroke(155, 185, 215, 50);
    p.strokeWeight(1);

    // Draw tension lines between chairs
    let tension = p.map(p.mouseY, 0, p.height, 0.5, 2);
    for (let i = 0; i < 5; i++) {
      let offset = p.sin(p.frameCount * 0.1 + i) * 10;
      p.line(chair1.x, chair1.y + offset, chair2.x, chair2.y - offset);
    }

    p.pop();
  }
}

function sketch(p) {
  let dustParticles = [];
  let clockAngles = [0, 0, 0];
  let doorOpacity = 200;
  let lightShafts = [];
  let timeOffset = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize dust particles
    for (let i = 0; i < 80; i++) {
      dustParticles.push({
        x: p.random(400),
        y: p.random(600),
        size: p.random(1, 3),
        driftX: p.random(-0.2, 0.2),
        driftY: p.random(-0.1, 0.1),
        alpha: p.random(30, 80)
      });
    }

    // Initialize light shafts
    for (let i = 0; i < 3; i++) {
      lightShafts.push({
        x: 80 + i * 120,
        y: 120,
        width: p.random(40, 80),
        intensity: p.random(0.3, 0.6)
      });
    }
  };

  p.draw = function() {
    // Deep blue gradient background
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 45), p.color(35, 45, 75), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    timeOffset += 0.005;

    // Draw room structure with three doorways
    p.strokeWeight(3);
    p.stroke(80, 90, 120);
    p.fill(25, 35, 55, 150);

    // Three doorway frames in triangular arrangement
    let doorWidth = 60;
    let doorHeight = 120;

    // Top doorway
    let door1X = 200 - doorWidth/2;
    let door1Y = 100;

    // Bottom left doorway
    let door2X = 120 - doorWidth/2;
    let door2Y = 350;

    // Bottom right doorway
    let door3X = 280 - doorWidth/2;
    let door3Y = 350;

    // Draw doorway frames
    p.noFill();
    p.rect(door1X, door1Y, doorWidth, doorHeight);
    p.rect(door2X, door2Y, doorWidth, doorHeight);
    p.rect(door3X, door3Y, doorWidth, doorHeight);

    // Draw light shafts through doorways
    p.blendMode(p.SCREEN);
    for (let i = 0; i < 3; i++) {
      let shaft = lightShafts[i];
      let doorCenterX = [200, 120, 280][i];
      let doorCenterY = [160, 410, 410][i];

      p.fill(120, 140, 180, shaft.intensity * 40);
      p.noStroke();

      // Animated light shaft
      let shaftSway = p.sin(timeOffset * 2 + i) * 5;
      p.quad(
        doorCenterX - shaft.width/4 + shaftSway, doorCenterY,
        doorCenterX + shaft.width/4 + shaftSway, doorCenterY,
        doorCenterX + shaft.width/2, doorCenterY + 200,
        doorCenterX - shaft.width/2, doorCenterY + 200
      );
    }
    p.blendMode(p.BLEND);

    // Draw three clocks without hands in triangular arrangement
    let mouseInfluence = p.map(p.mouseX, 0, p.width, 0.5, 1.5);

    for (let i = 0; i < 3; i++) {
      let clockX = [200, 120, 280][i];
      let clockY = [60, 320, 320][i];
      let clockSize = 35;

      // Clock face
      p.fill(45, 55, 85, 180);
      p.stroke(90, 100, 140);
      p.strokeWeight(2);
      p.circle(clockX, clockY, clockSize);

      // Hour marks
      p.strokeWeight(1);
      for (let j = 0; j < 12; j++) {
        let angle = j * p.TWO_PI / 12;
        let x1 = clockX + p.cos(angle) * (clockSize/2 - 3);
        let y1 = clockY + p.sin(angle) * (clockSize/2 - 3);
        let x2 = clockX + p.cos(angle) * (clockSize/2 - 1);
        let y2 = clockY + p.sin(angle) * (clockSize/2 - 1);
        p.line(x1, y1, x2, y2);
      }

      // Stopped hands (barely visible, like time suspended)
      clockAngles[i] += 0.001 * mouseInfluence;
      p.strokeWeight(1);
      p.stroke(70, 80, 110, 100);
      let handX = clockX + p.cos(clockAngles[i]) * (clockSize/3);
      let handY = clockY + p.sin(clockAngles[i]) * (clockSize/3);
      p.line(clockX, clockY, handX, handY);
    }

    // Empty chair suggesting waiting presence
    p.strokeWeight(2);
    p.stroke(70, 80, 110);
    p.fill(35, 45, 65, 120);
    let chairX = 200;
    let chairY = 480;

    // Chair seat
    p.rect(chairX - 20, chairY, 40, 25);
    // Chair back
    p.rect(chairX - 18, chairY - 30, 36, 35);
    // Chair legs
    p.line(chairX - 15, chairY + 25, chairX - 15, chairY + 40);
    p.line(chairX + 15, chairY + 25, chairX + 15, chairY + 40);

    // Dust particles floating in light
    p.noStroke();
    for (let particle of dustParticles) {
      // Particles more visible in light shafts
      let inLight = false;
      for (let shaft of lightShafts) {
        if (p.dist(particle.x, particle.y, shaft.x, shaft.y + 100) < shaft.width) {
          inLight = true;
          break;
        }
      }

      let alpha = inLight ? particle.alpha * 2 : particle.alpha;
      p.fill(150, 160, 200, alpha);
      p.circle(particle.x, particle.y, particle.size);

      // Languid drift motion
      particle.x += particle.driftX + p.sin(timeOffset + particle.x * 0.01) * 0.1;
      particle.y += particle.driftY + p.cos(timeOffset + particle.y * 0.01) * 0.05;

      // Mouse interaction - particles gently respond
      let mouseDistance = p.dist(p.mouseX, p.mouseY, particle.x, particle.y);
      if (mouseDistance < 50) {
        let pushX = (particle.x - p.mouseX) * 0.002;
        let pushY = (particle.y - p.mouseY) * 0.002;
        particle.x += pushX;
        particle.y += pushY;
      }

      // Wrap around edges
      if (particle.x < 0) particle.x = p.width;
      if (particle.x > p.width) particle.x = 0;
      if (particle.y < 0) particle.y = p.height;
      if (particle.y > p.height) particle.y = 0;
    }

    // Subtle growth/manifestation energy connecting the three points
    p.stroke(80, 120, 160, 60);
    p.strokeWeight(1);
    p.noFill();

    let pulse = p.sin(timeOffset * 3) * 10 + 20;
    // Triangle connecting the three focal points
    p.beginShape();
    p.vertex(200, 160 + pulse * 0.1);
    p.vertex(120, 410 + pulse * 0.1);
    p.vertex(280, 410 + pulse * 0.1);
    p.vertex(200, 160 + pulse * 0.1);
    p.endShape();

    // Breathing effect on doorway opacity with mouse
    let breathe = p.sin(timeOffset * 2) * 20 + 100;
    doorOpacity = p.lerp(doorOpacity, breathe + p.map(p.mouseY, 0, p.height, 50, 150), 0.1);
  };

  p.mousePressed = function() {
    // Click creates a gentle ripple in the dust
    for (let particle of dustParticles) {
      let distance = p.dist(p.mouseX, p.mouseY, particle.x, particle.y);
      if (distance < 100) {
        particle.driftX += p.random(-0.5, 0.5);
        particle.driftY += p.random(-0.5, 0.5);
      }
    }
  };
}

function sketch(p) {
