    doorways.push({x: 240, y: 150, width: 60, height: 90});
    doorways.push({x: 100, y: 360, width: 60, height: 90});
    doorways.push({x: 240, y: 360, width: 60, height: 90});

    // Four stopped clocks
    clockCenters.push({x: 130, y: 120});
    clockCenters.push({x: 270, y: 120});
    clockCenters.push({x: 130, y: 480});
    clockCenters.push({x: 270, y: 480});

    // Initialize dust particles
    for(let i = 0; i < 150; i++) {
      dustParticles.push({
        x: p.random(400),
        y: p.random(600),
        size: p.random(1, 3),
        speed: p.random(0.1, 0.3),
        alpha: p.random(30, 80)
      });
    }

    // Light shaft positions
    for(let i = 0; i < 4; i++) {
      lightShafts.push({
        x: doorways[i].x + doorways[i].width/2,
