      let col = p.lerpColor(p.color(15, 25, 45), p.color(25, 35, 65), inter);
      p.stroke(col);
      p.line(0, y, 400, y);
    }

    // Draw light shafts from windows
    p.blendMode(p.OVERLAY);
    for(let shaft of lightShafts) {
      let mouseInfluence = p.dist(p.mouseX, p.mouseY, shaft.x, shaft.y) / 200;
      let intensity = shaft.intensity + p.sin(p.frameCount * 0.01) * 0.1;
      intensity *= (1 - mouseInfluence * 0.3);

      p.fill(120, 140, 200, intensity * 40);
      p.noStroke();
      p.beginShape();
      p.vertex(shaft.x - 15, shaft.y);
      p.vertex(shaft.x + 15, shaft.y);
      p.vertex(shaft.x + 60, shaft.y + 200);
      p.vertex(shaft.x - 60, shaft.y + 200);
      p.endShape(p.CLOSE);
    }
    p.blendMode(p.BLEND);

    // Draw doorways with depth
    for(let door of doorways) {
      // Doorframe shadow
      p.fill(8, 15, 28);
      p.noStroke();
      p.rect(door.x - 5, door.y - 5, door.width + 10, door.height + 10);

      // Doorframe
      p.fill(35, 50, 85);
      p.rect(door.x - 3, door.y - 3, door.width + 6, door.height + 6);

      // Door opening (darker blue suggesting depth)
      p.fill(5, 10, 20);
      p.rect(door.x, door.y, door.width, door.height);

      // Window in door
      let windowAlpha = 80 + p.sin(p.frameCount * 0.005 + door.x) * 20;
      p.fill(60, 80, 140, windowAlpha);
      p.rect(door.x + 10, door.y + 15, door.width - 20, 35);
    }

    // Draw stopped clocks without hands
    for(let clock of clockCenters) {
      let hover = p.dist(p.mouseX, p.mouseY, clock.x, clock.y) < 30;
      let clockSize = hover ? 25 : 20;

      // Clock face
      p.fill(45, 65, 95);
      p.stroke(80, 100, 140);
      p.strokeWeight(2);
      p.ellipse(clock.x, clock.y, clockSize * 2, clockSize * 2);

      // Hour markers
      p.strokeWeight(1);
      for(let i = 0; i < 12; i++) {
        let angle = i * p.PI / 6;
        let x1 = clock.x + p.cos(angle) * (clockSize - 3);
        let y1 = clock.y + p.sin(angle) * (clockSize - 3);
        let x2 = clock.x + p.cos(angle) * (clockSize - 7);
        let y2 = clock.y + p.sin(angle) * (clockSize - 7);
        p.line(x1, y1, x2, y2);
      }
    }

    // Draw empty chair in center
    let centerX = 200;
    let centerY = 300;
    chairAlpha += chairFade;
    if(chairAlpha > 200 || chairAlpha < 100) chairFade *= -1;

    p.fill(50, 70, 110, chairAlpha);
    p.noStroke();

    // Chair back
    p.rect(centerX - 15, centerY - 30, 30, 40, 5);
    // Chair seat
    p.rect(centerX - 20, centerY, 40, 25, 3);
    // Chair legs
    p.rect(centerX - 18, centerY + 25, 4, 20);
    p.rect(centerX + 14, centerY + 25, 4, 20);
    p.rect(centerX - 18, centerY - 5, 4, 15);
    p.rect(centerX + 14, centerY - 5, 4, 15);

    // Animated dust particles in light shafts
    p.blendMode(p.OVERLAY);
    for(let dust of dustParticles) {
      dust.y += dust.speed;
      dust.x += p.sin(dust.y * 0.01) * 0.2;

      if(dust.y > 600) {
        dust.y = -10;
        dust.x = p.random(400);
      }

      // Check if in light shaft
      let inLight = false;
      for(let shaft of lightShafts) {
        if(dust.x > shaft.x - 60 && dust.x < shaft.x + 60 && 
           dust.y > shaft.y && dust.y < shaft.y + 200) {
          inLight = true;
          break;
        }
      }

      let alpha = inLight ? dust.alpha * 2 : dust.alpha * 0.3;
      p.fill(200, 220, 255, alpha);
      p.noStroke();
      p.ellipse(dust.x, dust.y, dust.size, dust.size);
    }
    p.blendMode(p.BLEND);

    // Subtle boundary lines suggesting the four corners/structure
    p.stroke(70, 90, 130, 100);
    p.strokeWeight(1);
    p.line(200, 100, 200, 500);
    p.line(50, 300, 350, 300);

    // Corner markers
    p.fill(80, 100, 140, 120);
    p.noStroke();
    p.rect(45, 95, 10, 10);
    p.rect(345, 95, 10, 10);
    p.rect(45, 495, 10, 10);
    p.rect(345, 495, 10, 10);
  };
}

function sketch(p) {
  let clocks = [];
  let dustParticles = [];
  let doorRect;
  let windowRect;
  let chairRect;
  let timeDistortion = 0;
  let waitingTension = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 1);

    // Initialize five clocks in unstable arrangement
    clocks.push({x: 80, y: 120, size: 45, angle: 0, wobble: 0.02, broken: true});
    clocks.push({x: 320, y: 140, size: 38, angle: p.PI/3, wobble: 0.015, broken: false});
    clocks.push({x: 200, y: 200, size: 52, angle: p.PI/2, wobble: 0.025, broken: true});
    clocks.push({x: 120, y: 320, size: 41, angle: p.PI, wobble: 0.018, broken: false});
    clocks.push({x: 300, y: 380, size: 48, angle: p.PI*1.5, wobble: 0.012, broken: true});

    // Door threshold
    doorRect = {x: 50, y: 450, w: 80, h: 140};

    // Window
    windowRect = {x: 280, y: 480, w: 100, h: 80};

    // Empty chair
    chairRect = {x: 180, y: 420, w: 40, h: 60};

    // Initialize dust particles
    for(let i = 0; i < 150; i++) {
      dustParticles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.3, 0.3),
        vy: p.random(-0.2, 0.2),
        size: p.random(1, 3),
        opacity: p.random(0.1, 0.4),
        driftX: p.random(-1, 1),
        driftY: p.random(-1, 1)
      });
    }
  };

  p.draw = function() {
    // Blue-tinted background with subtle gradient
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(220, 30, 85, 0.9),
        p.color(230, 45, 25, 0.8),
        inter
      );
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    timeDistortion += 0.01;
    waitingTension = p.sin(timeDistortion * 0.7) * 0.5 + 0.5;

    // Mouse influence on tension
    let mouseInfluence = p.map(p.mouseX + p.mouseY, 0, p.width + p.height, 0, 1);
    waitingTension = p.lerp(waitingTension, mouseInfluence, 0.1);

    // Draw shaft of light from window
    p.push();
    p.translate(windowRect.x + windowRect.w/2, windowRect.y);
    p.rotate(p.PI/6);
    let lightAlpha = 0.15 + waitingTension * 0.1;
    p.fill(45, 20, 90, lightAlpha);
    p.noStroke();
    p.triangle(0, 0, -60, 200, 60, 200);
    p.pop();

    // Draw dust particles in light shaft
    p.noStroke();
    for(let dust of dustParticles) {
      // Check if in light shaft area
      let inLight = dust.x > 200 && dust.x < 380 && dust.y > 480;
      let dustColor = inLight ? 
        p.color(45, 15, 95, dust.opacity + waitingTension * 0.2) :
        p.color(220, 20, 70, dust.opacity);

      p.fill(dustColor);
      p.circle(dust.x, dust.y, dust.size);

      // Languid movement
      dust.x += dust.vx + p.sin(timeDistortion + dust.driftX) * 0.1;
      dust.y += dust.vy + p.cos(timeDistortion + dust.driftY) * 0.08;

      // Wrap around edges
      if(dust.x < 0) dust.x = p.width;
      if(dust.x > p.width) dust.x = 0;
      if(dust.y < 0) dust.y = p.height;
      if(dust.y > p.height) dust.y = 0;
    }

    // Draw doorway threshold
    p.stroke(220, 40, 40, 0.8);
    p.strokeWeight(3);
    p.fill(220, 60, 15, 0.3);
    p.rect(doorRect.x, doorRect.y, doorRect.w, doorRect.h);

    // Doorframe details
    p.stroke(220, 50, 30, 0.9);
    p.strokeWeight(2);
    p.line(doorRect.x, doorRect.y, doorRect.x, doorRect.y + doorRect.h);
    p.line(doorRect.x + doorRect.w, doorRect.y, doorRect.x + doorRect.w, doorRect.y + doorRect.h);

    // Draw window
    p.stroke(220, 35, 50, 0.7);
    p.strokeWeight(2);
    p.fill(45, 25, 85, 0.2);
    p.rect(windowRect.x, windowRect.y, windowRect.w, windowRect.h);

    // Window crossbars
    p.line(windowRect.x + windowRect.w/2, windowRect.y, windowRect.x + windowRect.w/2, windowRect.y + windowRect.h);
    p.line(windowRect.x, windowRect.y + windowRect.h/2, windowRect.x + windowRect.w, windowRect.y + windowRect.h/2);

    // Draw empty chair
    p.stroke(220, 45, 35, 0.8);
    p.strokeWeight(3);
    p.noFill();

    // Chair back
    p.rect(chairRect.x, chairRect.y, chairRect.w, chairRect.h * 0.6);
    // Chair seat
    p.rect(chairRect.x, chairRect.y + chairRect.h * 0.6, chairRect.w, chairRect.h * 0.4);

    // Chair legs with subtle wobble from tension
    let wobble = waitingTension * 2;
    p.line(chairRect.x + wobble, chairRect.y + chairRect.h, chairRect.x + wobble, chairRect.y + chairRect.h + 20);
    p.line(chairRect.x + chairRect.w - wobble, chairRect.y + chairRect.h, chairRect.x + chairRect.w - wobble, chairRect.y + chairRect.h + 20);

    // Draw five clocks in unstable arrangement
    for(let i = 0; i < clocks.length; i++) {
      let clock = clocks[i];

      p.push();
      p.translate(clock.x, clock.y);

      // Unstable rotation based on waiting tension
      let instability = waitingTension * clock.wobble * 10;
      p.rotate(clock.angle + p.sin(timeDistortion * 2 + i) * instability);

      // Clock face
      let clockAlpha = clock.broken ? 0.4 + waitingTension * 0.3 : 0.7;
      p.stroke(220, 50, 60, clockAlpha);
      p.strokeWeight(2);
      p.fill(220, 30, 90, clockAlpha * 0.3);
      p.circle(0, 0, clock.size);

      // Clock markings (only for working clocks)
      if(!clock.broken) {
        p.stroke(220, 60, 50, clockAlpha);
        p.strokeWeight(1);
        for(let j = 0; j < 12; j++) {
          p.push();
          p.rotate(j * p.TWO_PI / 12);
          p.line(0, -clock.size/2 + 3, 0, -clock.size/2 + 8);
          p.pop();
        }
      }

      // Hands (or lack thereof for broken clocks)
      if(clock.broken) {
        // Broken/missing hands - just fragments
        p.stroke(220, 70, 40, clockAlpha);
        p.strokeWeight(2);
        p.line(0, 0, clock.size/4, -clock.size/6);
        // Second hand fragment
        p.strokeWeight(1);
        p.line(0, 0, -clock.size/6, clock.size/8);
      } else {
        // Working clock with moving hands
        p.stroke(220, 65, 45, clockAlpha);
        p.strokeWeight(3);
        // Hour hand
        p.line(0, 0, 0, -clock.size/4);
        p.strokeWeight(2);
        // Minute hand
        p.line(0, 0, clock.size/3, 0);
      }

      p.pop();

      // Add subtle drift to create instability
      clock.x += p.sin(timeDistortion + i) * 0.3;
      clock.y += p.cos(timeDistortion * 1.2 + i) * 0.2;
    }

    // Interactive response to mouse clicks
    if(p.mouseIsPressed) {
      // Create ripple effect of disrupted time
      let rippleSize = p.sin(timeDistortion * 5) * 20 + 30;
      p.noFill();
      p.stroke(45, 40, 95, 0.6);
      p.strokeWeight(2);
      p.circle(p.mouseX, p.mouseY, rippleSize);
      p.stroke(45, 30, 85, 0.4);
      p.strokeWeight(1);
      p.circle(p.mouseX, p.mouseY, rippleSize * 1.5);
    }
  };
}

function sketch(p) {
  let doorways = [];
  let dustParticles = [];
  let clockPositions = [];
  let windowLight;
  let harmonicFlow = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create six doorway/threshold positions in hexagonal arrangement
    let centerX = 200;
    let centerY = 300;
    let radius = 120;

    for (let i = 0; i < 6; i++) {
      let angle = (i * p.TWO_PI) / 6;
      doorways.push({
        x: centerX + p.cos(angle) * radius,
        y: centerY + p.sin(angle) * radius,
        angle: angle,
        openness: 0.3 + i * 0.1,
        breathe: p.random(0.01, 0.03)
      });
    }

    // Create dust particles for light shafts
    for (let i = 0; i < 150; i++) {
      dustParticles.push({
        x: p.random(400),
        y: p.random(600),
        size: p.random(1, 3),
        speed: p.random(0.2, 0.8),
        alpha: p.random(30, 80),
        drift: p.random(-0.5, 0.5)
      });
    }

    // Clock positions - six clocks without hands
    for (let i = 0; i < 6; i++) {
      let angle = (i * p.TWO_PI) / 6;
      clockPositions.push({
        x: 200 + p.cos(angle) * 80,
        y: 300 + p.sin(angle) * 80,
        phase: i * 0.5
      });
    }

    windowLight = {
      x: 350,
      y: 100,
      width: 60,
      height: 120
    };
  };

  p.draw = function() {
    // Blue-tinted atmospheric background
    p.background(15, 25, 45);

    harmonicFlow += 0.02;
    mouseInfluence = p.map(p.mouseX, 0, 400, 0.8, 1.2);

    // Window light shaft
    p.push();
    p.noStroke();
    let lightAlpha = 25 + 10 * p.sin(harmonicFlow * 0.7);
    p.fill(220, 230, 255, lightAlpha);

    // Languid light shaft from window
    p.beginShape();
    p.vertex(windowLight.x, windowLight.y);
    p.vertex(windowLight.x + windowLight.width, windowLight.y);
    p.vertex(200 + 100 * mouseInfluence, 500);
    p.vertex(100 * mouseInfluence, 500);
    p.endShape(p.CLOSE);
    p.pop();

    // Dust particles in light shaft
    for (let dust of dustParticles) {
      dust.y += dust.speed;
      dust.x += dust.drift * p.sin(harmonicFlow + dust.y * 0.01);

      if (dust.y > 600) {
        dust.y = -10;
        dust.x = p.random(400);
      }

      // Check if in light shaft roughly
      let inLight = dust.x > 50 && dust.x < 350 && dust.y > 100;
      let alpha = inLight ? dust.alpha * 1.5 : dust.alpha * 0.3;

      p.push();
      p.noStroke();
      p.fill(200, 220, 255, alpha);
      p.circle(dust.x, dust.y, dust.size);
      p.pop();
    }

    // Six doorways/thresholds in hexagonal harmony
    for (let i = 0; i < doorways.length; i++) {
      let door = doorways[i];
      let breathing = p.sin(harmonicFlow * door.breathe + door.angle) * 5;

      p.push();
      p.translate(door.x, door.y);
      p.rotate(door.angle + p.PI/2);

      // Doorway frame
      p.stroke(80, 120, 180);
      p.strokeWeight(3);
      p.noFill();

      let doorWidth = 30 + breathing;
      let doorHeight = 50 + breathing * 0.5;

      // Languid brush stroke style
      for (let j = 0; j < 3; j++) {
        p.stroke(80 + j*10, 120 + j*10, 180 + j*15, 150 - j*30);
        p.rect(-doorWidth/2 + j, -doorHeight/2 + j, doorWidth - j*2, doorHeight - j*2, 5);
      }

      // Threshold glow
      p.noStroke();
      p.fill(120, 150, 220, 30 + door.openness * 50);
      p.rect(-doorWidth/2, -doorHeight/2, doorWidth, doorHeight, 5);

      p.pop();
    }

    // Six clocks without hands - stopped time
    for (let i = 0; i < clockPositions.length; i++) {
      let clock = clockPositions[i];
      let pulse = p.sin(harmonicFlow * 0.5 + clock.phase) * 0.1 + 1;

      p.push();
      p.translate(clock.x, clock.y);
      p.scale(pulse);

      // Clock face
      p.stroke(60, 90, 140);
      p.strokeWeight(2);
      p.noFill();
      p.circle(0, 0, 25);

      // Hour marks but no hands
      p.strokeWeight(1);
      for (let h = 0; h < 12; h++) {
        let angle = (h * p.TWO_PI) / 12 - p.PI/2;
        let x1 = p.cos(angle) * 10;
        let y1 = p.sin(angle) * 10;
        let x2 = p.cos(angle) * 8;
        let y2 = p.sin(angle) * 8;
        p.line(x1, y1, x2, y2);
      }

      p.pop();
    }

    // Central harmony visualization - flowing communication
    p.push();
    p.translate(200, 300);
    p.noFill();
    p.strokeWeight(1);

    // Six-fold flowing pattern
    for (let layer = 0; layer < 3; layer++) {
      let radius = 40 + layer * 15;
      let alpha = 100 - layer * 20;

      p.stroke(100 + layer*20, 140 + layer*15, 200 + layer*10, alpha);

      p.beginShape();
      p.noFill();
      for (let a = 0; a <= p.TWO_PI + 0.1; a += 0.1) {
        let r = radius + p.sin(a * 6 + harmonicFlow + layer * 0.5) * 8 * mouseInfluence;
        let x = p.cos(a) * r;
        let y = p.sin(a) * r;
        p.vertex(x, y);
      }
      p.endShape();
    }
    p.pop();

    // Empty chair suggestion - waiting presence
    p.push();
    p.translate(80, 480);
    p.stroke(70, 110, 160);
    p.strokeWeight(2);
    p.noFill();

    // Simple chair outline with languid strokes
    let chairSway = p.sin(harmonicFlow * 0.3) * 2;
    p.line(0 + chairSway, 0, 0 + chairSway, -40); // back
    p.line(-15 + chairSway, -20, 15 + chairSway, -20); // seat
    p.line(-15 + chairSway, -20, -15 + chairSway, 20); // leg
    p.line(15 + chairSway, -20, 15 + chairSway, 20); // leg

    // Subtle presence glow
    p.noStroke();
    p.fill(120, 150, 200, 20);
    p.ellipse(0, -10, 40, 60);
    p.pop();

    // Subtle interaction - mouse creates ripples in the harmony
    if (p.mouseIsPressed) {
      let dist = p.dist(p.mouseX, p.mouseY, 200, 300);
      if (dist < 150) {
        p.push();
        p.translate(p.mouseX, p.mouseY);
        p.noFill();
        p.stroke(150, 180, 220, 100);
        p.strokeWeight(1);

        for (let r = 0; r < 60; r += 15) {
          let alpha = 100 - r * 1.5;
          p.stroke(150, 180, 220, alpha);
          p.circle(0, 0, r + harmonicFlow * 5);
        }
        p.pop();
      }
    }
  };
}

function sketch(p) {
  let doorways = [];
  let dustParticles = [];
  let waitingSymbols = [];
  let clockHands = [];
  let evaluationClock = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create seven doorway/threshold rectangles
    for(let i = 0; i < 7; i++) {
      doorways.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        w: p.random(40, 80),
        h: p.random(60, 120),
        alpha: p.random(0.3, 0.8),
        drift: p.random(-0.5, 0.5)
      });
    }

    // Create dust particles for light shafts
    for(let i = 0; i < 150; i++) {
      dustParticles.push({
        x: p.random(0, 400),
        y: p.random(0, 600),
        size: p.random(1, 3),
        speed: p.random(0.1, 0.5),
        alpha: p.random(0.1, 0.4),
        drift: p.random(-0.2, 0.2)
      });
    }

    // Create seven waiting symbols arranged in assessment pattern
    let centerX = 200;
    let centerY = 300;
    for(let i = 0; i < 7; i++) {
      if(i < 3) {
        // Three symbols on left - the past
        waitingSymbols.push({
          x: centerX - 120 + (i * 30),
          y: centerY - 50 + (i * 20),
          phase: i * 0.5,
          evaluated: false,
          type: 'past'
        });
      } else if(i < 6) {
        // Two symbols on right - the future options
        waitingSymbols.push({
          x: centerX + 60 + ((i-3) * 40),
          y: centerY - 30 + ((i-3) * 30),
          phase: i * 0.5,
          evaluated: false,
          type: 'future'
        });
      } else {
        // One symbol at center - the decision point
        waitingSymbols.push({
          x: centerX,
          y: centerY + 40,
          phase: i * 0.5,
          evaluated: false,
          type: 'present'
        });
      }
    }

    // Create clock hands that float without purpose
    for(let i = 0; i < 3; i++) {
      clockHands.push({
        x: p.random(100, 300),
        y: p.random(150, 450),
        angle: p.random(0, p.TWO_PI),
        length: p.random(20, 40),
        speed: p.random(0.005, 0.02)
      });
    }
  };

  p.draw = function() {
    // Blue-tinted background with subtle gradient
    for(let i = 0; i < p.height; i++) {
      let alpha = p.map(i, 0, p.height, 0.1, 0.3);
      p.stroke(100, 120, 160, alpha * 255);
      p.line(0, i, p.width, i);
    }

    evaluationClock += 0.01;
    mouseInfluence = p.lerp(mouseInfluence, p.dist(p.mouseX, p.mouseY, 200, 300) / 200, 0.05);

    // Draw light shafts with suspended dust
    p.noFill();
    for(let i = 0; i < 4; i++) {
      let shaftX = 80 + (i * 80);
      p.stroke(130, 150, 200, 30);
      p.strokeWeight(60);
      p.line(shaftX, 0, shaftX + 20, p.height);
    }

    // Animate dust particles in light
    for(let particle of dustParticles) {
      particle.y += particle.speed;
      particle.x += particle.drift + p.sin(evaluationClock + particle.x * 0.01) * 0.1;

      if(particle.y > p.height) particle.y = -10;
      if(particle.x < 0 || particle.x > p.width) particle.x = p.random(0, p.width);

      p.fill(150, 170, 220, particle.alpha * 255);
      p.noStroke();
      p.circle(particle.x, particle.y, particle.size);
    }

    // Draw threshold doorways with languid movement
    for(let i = 0; i < doorways.length; i++) {
      let door = doorways[i];
      door.x += door.drift * 0.1;
      door.y += p.sin(evaluationClock + i) * 0.2;

      p.stroke(80, 100, 140, door.alpha * 255);
      p.strokeWeight(3);
      p.noFill();

      // Doorframe
      p.rect(door.x, door.y, door.w, door.h);

      // Door opening - darkness within
      p.fill(20, 30, 60, 100);
      p.rect(door.x + 5, door.y + 5, door.w - 10, door.h - 10);
    }

    // Draw the seven waiting symbols in evaluation arrangement
    for(let i = 0; i < waitingSymbols.length; i++) {
      let symbol = waitingSymbols[i];
      let pulse = p.sin(evaluationClock + symbol.phase) * 0.3 + 0.7;

      // Mouse proximity affects evaluation state
      let dist = p.dist(p.mouseX, p.mouseY, symbol.x, symbol.y);
      if(dist < 50) {
        symbol.evaluated = true;
      }

      p.pushMatrix();
      p.translate(symbol.x, symbol.y);

      if(symbol.type === 'past') {
        // Faded, already evaluated symbols
        p.stroke(60, 80, 120, 150);
        p.fill(70, 90, 130, 100);
        p.strokeWeight(2);
        p.circle(0, 0, 15 * pulse);

        // Small marks indicating time passed
        for(let j = 0; j < 4; j++) {
          let angle = (j * p.PI / 2) + evaluationClock * 0.5;
          let x = p.cos(angle) * 8;
          let y = p.sin(angle) * 8;
          p.line(0, 0, x, y);
        }
      } else if(symbol.type === 'future') {
        // Bright, uncertain symbols
        let brightness = symbol.evaluated ? 200 : 120;
        p.stroke(brightness, brightness + 20, brightness + 40, 200);
        p.fill(brightness - 50, brightness - 30, brightness, 80);
        p.strokeWeight(symbol.evaluated ? 3 : 1);

        // Question mark shape suggesting uncertainty
        p.arc(0, -5, 20 * pulse, 20 * pulse, 0, p.PI + p.HALF_PI);
        p.circle(0, 8, 3);
      } else {
        // Central decision symbol - most prominent
        let intensity = 100 + mouseInfluence * 100;
        p.stroke(intensity, intensity + 30, intensity + 60, 255);
        p.strokeWeight(4);
        p.noFill();

        // Crossroads symbol
        p.line(-15, 0, 15, 0);
        p.line(0, -15, 0, 15);

        // Rotating assessment circle
        p.stroke(intensity - 20, intensity + 10, intensity + 40, 150);
        p.strokeWeight(2);
        p.circle(0, 0, 25 + p.sin(evaluationClock * 2) * 5);
      }

      p.popMatrix();
    }

    // Draw floating clock hands without faces
    for(let hand of clockHands) {
      hand.angle += hand.speed;
      hand.x += p.sin(evaluationClock + hand.x * 0.01) * 0.2;
      hand.y += p.cos(evaluationClock + hand.y * 0.01) * 0.1;

      p.stroke(90, 110, 150, 180);
      p.strokeWeight(3);

      let endX = hand.x + p.cos(hand.angle) * hand.length;
      let endY = hand.y + p.sin(hand.angle) * hand.length;

      p.line(hand.x, hand.y, endX, endY);

      // Small circle at center
      p.fill(100, 120, 160, 150);
      p.noStroke();
      p.circle(hand.x, hand.y, 4);
    }

    // Empty chair suggestion in lower right
    p.stroke(70, 90, 130, 120);
    p.strokeWeight(2);
    p.noFill();
    p.rect(320, 480, 30, 40);  // Chair back
    p.rect(320, 520, 30, 15);  // Seat

    // Tension lines - the weight of decision
    if(mouseInfluence > 0.5) {
      p.stroke(150, 170, 220, 100);
      p.strokeWeight(1);
      for(let i = 0; i < 5; i++) {
        let startY = 100 + (i * 100);
        p.line(0, startY, 400, startY + p.sin(evaluationClock + i) * 20);
      }
    }
  };

  p.mousePressed = function() {
    // Reset evaluation state - the moment of choosing to reassess
    for(let symbol of waitingSymbols) {
      symbol.evaluated = false;
    }

    // Disturb the dust
    for(let particle of dustParticles) {
      particle.speed += p.random(-0.2, 0.5);
      particle.drift += p.random(-0.3, 0.3);
    }
  };
}

function sketch(p) {
  let doorframes = [];
  let dustParticles = [];
  let waitingSymbols = [];
  let clockHands = [];
  let lightShafts = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create doorframes at different depths
    for(let i = 0; i < 3; i++) {
      doorframes.push({
        x: 50 + i * 20,
        y: 100 + i * 30,
        width: 300 - i * 40,
        height: 400 - i * 60,
        depth: i,
        alpha: 255 - i * 60
      });
    }

    // Create dust particles
    for(let i = 0; i < 120; i++) {
      dustParticles.push({
        x: p.random(400),
        y: p.random(600),
        size: p.random(1, 3),
        speed: p.random(0.2, 0.8),
        angle: p.random(p.TWO_PI),
        brightness: p.random(100, 255)
      });
    }

    // Create eight waiting symbols in spiral arrangement
    for(let i = 0; i < 8; i++) {
      let angle = (i / 8) * p.TWO_PI;
      let radius = 80 + p.sin(i * 0.5) * 20;
      waitingSymbols.push({
        baseX: 200 + p.cos(angle) * radius,
        baseY: 300 + p.sin(angle) * radius,
        x: 0,
        y: 0,
        angle: angle,
        rotSpeed: 0.01 + i * 0.002,
        size: 12 + i * 2,
        phase: i * p.PI / 4
      });
    }

    // Create clock elements without hands
    for(let i = 0; i < 3; i++) {
      clockHands.push({
        x: 100 + i * 150,
        y: 150 + i * 100,
        radius: 25 + i * 5,
        frozen: true,
        tickMarks: 12
      });
    }

    // Create light shafts
    for(let i = 0; i < 4; i++) {
      lightShafts.push({
        x: 100 + i * 80,
        y: 0,
        width: 40 + i * 10,
        height: 600,
        intensity: 0.3 + i * 0.1
      });
    }
  };

  p.draw = function() {
    // Blue-tinted background with gradient
    for(let i = 0; i < p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(45, 55, 85), p.color(25, 35, 65), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Draw light shafts with dust
    p.blendMode(p.ADD);
    for(let shaft of lightShafts) {
      p.fill(100, 120, 160, shaft.intensity * 30);
      p.noStroke();
      p.rect(shaft.x, shaft.y, shaft.width, shaft.height);
    }
    p.blendMode(p.BLEND);

    // Draw doorframes creating depth
    for(let door of doorframes) {
      p.stroke(120, 140, 180, door.alpha);
      p.strokeWeight(2 + door.depth);
      p.noFill();

      // Draw door frame
      p.rect(door.x, door.y, door.width, door.height);

      // Draw threshold
      p.fill(80, 100, 140, door.alpha * 0.3);
      p.rect(door.x, door.y + door.height - 10, door.width, 10);
    }

    // Animate and draw waiting symbols in spiral motion
    p.push();
    p.translate(200, 300);
    p.rotate(p.frameCount * 0.005);

    for(let i = 0; i < waitingSymbols.length; i++) {
      let symbol = waitingSymbols[i];

      // Update spiral position
      let spiralRadius = 60 + p.sin(p.frameCount * 0.02 + symbol.phase) * 25;
      let spiralAngle = symbol.angle + p.frameCount * symbol.rotSpeed;

      symbol.x = p.cos(spiralAngle) * spiralRadius;
      symbol.y = p.sin(spiralAngle) * spiralRadius;

      // Draw symbol with languid brush stroke effect
      p.push();
      p.translate(symbol.x, symbol.y);
      p.rotate(spiralAngle);

      // Waiting symbol - abstract hourglass/doorway shape
      p.stroke(150, 170, 220, 200);
      p.strokeWeight(3);
      p.fill(100, 120, 180, 100);

      // Hourglass/doorway shape
      p.beginShape();
      p.vertex(-symbol.size/2, -symbol.size);
      p.vertex(symbol.size/2, -symbol.size);
      p.vertex(symbol.size/4, 0);
      p.vertex(symbol.size/2, symbol.size);
      p.vertex(-symbol.size/2, symbol.size);
      p.vertex(-symbol.size/4, 0);
      p.endShape(p.CLOSE);

      p.pop();
    }
    p.pop();

    // Draw clocks without hands
    for(let clock of clockHands) {
      p.stroke(130, 150, 190, 180);
      p.strokeWeight(2);
      p.noFill();
      p.circle(clock.x, clock.y, clock.radius * 2);

      // Draw tick marks but no hands
      for(let i = 0; i < clock.tickMarks; i++) {
        let angle = (i / clock.tickMarks) * p.TWO_PI - p.PI/2;
        let x1 = clock.x + p.cos(angle) * (clock.radius - 5);
        let y1 = clock.y + p.sin(angle) * (clock.radius - 5);
        let x2 = clock.x + p.cos(angle) * (clock.radius - 2);
        let y2 = clock.y + p.sin(angle) * (clock.radius - 2);
        p.line(x1, y1, x2, y2);
      }
    }

    // Animate and draw dust particles
    for(let dust of dustParticles) {
      dust.x += p.cos(dust.angle) * dust.speed;
      dust.y += p.sin(dust.angle) * dust.speed + 0.1;

      // Drift with mouse influence
      let mouseInfluence = p.dist(dust.x, dust.y, p.mouseX, p.mouseY);
      if(mouseInfluence < 50) {
        dust.x += (dust.x - p.mouseX) * 0.01;
        dust.y += (dust.y - p.mouseY) * 0.01;
      }

      // Wrap around edges
      if(dust.x < 0 || dust.x > 400) dust.x = p.random(400);
      if(dust.y > 600) dust.y = 0;

      // Draw dust mote
      p.fill(dust.brightness, dust.brightness + 20, dust.brightness + 40, 150);
      p.noStroke();
      p.circle(dust.x, dust.y, dust.size);
    }

    // Draw empty chair silhouette
    p.stroke(90, 110, 150, 180);
    p.strokeWeight(3);
    p.noFill();

    // Chair back
    p.line(320, 450, 320, 380);
    p.line(360, 450, 360, 380);
    p.line(320, 380, 360, 380);

    // Chair seat
    p.line(315, 450, 365, 450);
    p.line(315, 470, 365, 470);
    p.line(315, 450, 315, 470);
    p.line(365, 450, 365, 470);

    // Chair legs
    p.line(315, 470, 315, 500);
    p.line(365, 470, 365, 500);

    // Interactive element - mouse movement affects the spiral speed
    let mouseInfluence = p.map(p.mouseX, 0, p.width, 0.5, 2.0);
    for(let symbol of waitingSymbols) {
      symbol.rotSpeed = (0.01 + symbol.phase * 0.002) * mouseInfluence;
    }
  };

  p.mousePressed = function() {
    // On click, create ripple effect in dust
    for(let dust of dustParticles) {
      let distance = p.dist(dust.x, dust.y, p.mouseX, p.mouseY);
      if(distance < 100) {
        let angle = p.atan2(dust.y - p.mouseY, dust.x - p.mouseX);
        dust.x += p.cos(angle) * 10;
        dust.y += p.sin(angle) * 10;
        dust.speed *= 1.5;
      }
    }
  };
}

function sketch(p) {
  let doorways = [];
  let dustParticles = [];
  let clockAngle = 0;
  let waitingSymbols = [];
  let lightShaft = { x: 200, y: 100, intensity: 0.3 };
  let breathingPhase = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create nine doorway/threshold symbols
    for (let i = 0; i < 9; i++) {
      let row = Math.floor(i / 3);
      let col = i % 3;
      waitingSymbols.push({
        x: 80 + col * 120,
        y: 150 + row * 120,
        type: i % 3, // 0: door, 1: window, 2: chair
        opacity: 0.7 + (i * 0.03), // Increasing richness
        scale: 0.8 + (i * 0.025)
      });
    }

    // Create dust particles in light shaft
    for (let i = 0; i < 60; i++) {
      dustParticles.push({
        x: p.random(150, 250),
        y: p.random(50, 550),
        size: p.random(1, 3),
        drift: p.random(-0.5, 0.5),
        fall: p.random(0.2, 0.8),
        opacity: p.random(0.3, 0.8)
      });
    }
  };

  p.draw = function() {
    // Deep blue background with subtle gradient
    for (let y = 0; y < 600; y++) {
      let alpha = p.map(y, 0, 600, 0.9, 0.4);
      p.stroke(20, 30, 80, alpha * 255);
      p.line(0, y, 400, y);
    }

    breathingPhase += 0.02;
    let breathe = p.sin(breathingPhase) * 0.1 + 1;

    // Light shaft - golden blue beam
    p.push();
    p.translate(lightShaft.x, lightShaft.y);
    let mouseInfluence = p.map(p.mouseX, 0, 400, 0.8, 1.2);
    lightShaft.intensity = p.lerp(lightShaft.intensity, 0.2 + mouseInfluence * 0.3, 0.05);

    p.fill(120, 140, 200, lightShaft.intensity * 60 * breathe);
    p.noStroke();
    p.beginShape();
    p.vertex(-30, 0);
    p.vertex(30, 0);
    p.vertex(80, 500);
    p.vertex(-80, 500);
    p.endShape(p.CLOSE);
    p.pop();

    // Dust particles floating in light shaft
    for (let particle of dustParticles) {
      particle.x += particle.drift * breathe;
      particle.y += particle.fall;

      if (particle.y > 600) particle.y = -10;
      if (particle.x < 100) particle.x = 300;
      if (particle.x > 300) particle.x = 100;

      let distToLight = p.dist(particle.x, particle.y, lightShaft.x, lightShaft.y + 200);
      let lightInfluence = p.map(distToLight, 0, 150, 1, 0.3);

      p.fill(180, 200, 240, particle.opacity * lightInfluence * 150 * breathe);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);
    }

    // Draw nine waiting symbols with languid brush strokes
    for (let i = 0; i < waitingSymbols.length; i++) {
      let symbol = waitingSymbols[i];
      let mouseDistance = p.dist(p.mouseX, p.mouseY, symbol.x, symbol.y);
      let hover = p.map(mouseDistance, 0, 100, 1.3, 1);
      hover = p.constrain(hover, 1, 1.3);

      p.push();
      p.translate(symbol.x, symbol.y);
      p.scale(symbol.scale * hover * breathe);

      let baseOpacity = symbol.opacity;
      if (i === 8) baseOpacity *= 1.5; // Ninth symbol brighter - almost complete

      p.strokeWeight(2);
      p.stroke(80, 120, 180, baseOpacity * 200);
      p.fill(60, 90, 150, baseOpacity * 100);

      if (symbol.type === 0) { // Door/threshold
        p.rect(-20, -30, 40, 60);
        p.rect(-15, -25, 30, 50);
        p.fill(40, 70, 120, baseOpacity * 80);
        p.ellipse(12, 0, 3, 3); // Door handle
      } else if (symbol.type === 1) { // Window
        p.rect(-25, -20, 50, 40);
        p.line(-25, 0, 25, 0);
        p.line(0, -20, 0, 20);
        p.fill(100, 130, 200, baseOpacity * 60);
        p.rect(-23, -18, 46, 36);
      } else { // Empty chair
        p.line(-15, 20, -15, -10);
        p.line(15, 20, 15, -10);
        p.line(-15, -10, 15, -10);
        p.line(-15, 5, 15, 5);
        p.line(-15, -25, 15, -25);
        p.line(-15, -25, -15, -10);
        p.line(15, -25, 15, -10);
      }
      p.pop();
    }

    // Clock without hands - suspended time at top
    p.push();
    p.translate(200, 80);
    p.rotate(clockAngle);
    clockAngle += 0.003;

    p.strokeWeight(3);
    p.stroke(90, 130, 190, 180);
    p.noFill();
    p.ellipse(0, 0, 60);

    // Clock marks but no hands
    for (let i = 0; i < 12; i++) {
      p.push();
      p.rotate(i * p.PI / 6);
      p.line(0, -25, 0, -20);
      p.pop();
    }
    p.pop();

    // Subtle interactive glow on mouse movement
    if (p.mouseIsPressed) {
      p.fill(120, 150, 220, 30);
      p.noStroke();
      p.ellipse(p.mouseX, p.mouseY, 100);
    }

    // Almost-complete energy - nine symbols with one position slightly emphasized
    p.push();
    p.translate(waitingSymbols[8].x, waitingSymbols[8].y - 10);
    let pulse = p.sin(p.millis() * 0.005) * 0.3 + 0.7;
    p.fill(140, 170, 240, pulse * 80);
    p.noStroke();
    p.ellipse(0, 0, 80 * pulse);
    p.pop();
  };
}

function sketch(p) {
  let doorways = [];
  let dustParticles = [];
  let clock;
  let waitingChairs = [];
  let completionCircles = [];
  let timeFlow = 0;
  let doorOpenness = 0;
  let vigil = { x: 200, y: 300, intensity: 0 };

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create 10 doorways in circular arrangement (Ten of Waiting)
    for(let i = 0; i < 10; i++) {
      let angle = (i / 10) * p.TWO_PI;
      let radius = 120;
      doorways.push({
        x: 200 + p.cos(angle) * radius,
        y: 300 + p.sin(angle) * radius,
        angle: angle,
        openness: 0,
        light: 0,
        complete: false
      });
    }

    // Dust particles suspended in light
    for(let i = 0; i < 80; i++) {
      dustParticles.push({
        x: p.random(400),
        y: p.random(600),
        size: p.random(1, 3),
        drift: p.random(-0.2, 0.2),
        float: p.random(-0.3, 0.3),
        alpha: p.random(20, 60)
      });
    }

    // Clock without hands at center
    clock = {
      x: 200,
      y: 150,
      radius: 40,
      stopped: true
    };

    // Empty chairs waiting
    for(let i = 0; i < 3; i++) {
      waitingChairs.push({
        x: 80 + i * 120,
        y: 480,
        expectancy: p.random(0.5, 1.5)
      });
    }

    // Completion circles - the Ten arrangement
    for(let i = 0; i < 10; i++) {
      let angle = (i / 10) * p.TWO_PI;
      completionCircles.push({
        x: 200 + p.cos(angle) * 80,
        y: 300 + p.sin(angle) * 80,
        radius: 8,
        completed: false,
        delay: i * 30
      });
    }
  };

  p.draw = function() {
    // Blue-tinted background with depth
    p.background(15, 25, 45);

    timeFlow += 0.01;

    // Create atmosphere - suspended dust in light shafts
    for(let particle of dustParticles) {
      particle.x += particle.drift * p.sin(timeFlow + particle.y * 0.01);
      particle.y += particle.float * p.cos(timeFlow + particle.x * 0.01);

      // Wrap around
      if(particle.x > 400) particle.x = 0;
      if(particle.x < 0) particle.x = 400;
      if(particle.y > 600) particle.y = 0;
      if(particle.y < 0) particle.y = 600;

      p.fill(120, 140, 180, particle.alpha);
      p.noStroke();
      p.circle(particle.x, particle.y, particle.size);
    }

    // Light shafts from windows
    p.strokeWeight(0.5);
    for(let i = 0; i < 5; i++) {
      let x = 50 + i * 80;
      p.stroke(140, 160, 200, 15);
      p.line(x, 0, x + p.sin(timeFlow + i) * 20, 200);
    }

    // Central vigil point - responds to mouse proximity
    let mouseDistance = p.dist(p.mouseX, p.mouseY, vigil.x, vigil.y);
    vigil.intensity = p.map(mouseDistance, 0, 200, 1, 0.1);
    vigil.intensity = p.constrain(vigil.intensity, 0, 1);

    // Draw stopped clock
    p.stroke(80, 120, 160);
    p.strokeWeight(3);
    p.noFill();
    p.circle(clock.x, clock.y, clock.radius * 2);

    // Clock face details
    for(let h = 0; h < 12; h++) {
      let angle = (h / 12) * p.TWO_PI - p.PI/2;
      let x1 = clock.x + p.cos(angle) * (clock.radius - 5);
      let y1 = clock.y + p.sin(angle) * (clock.radius - 5);
      let x2 = clock.x + p.cos(angle) * (clock.radius - 10);
      let y2 = clock.y + p.sin(angle) * (clock.radius - 10);
      p.stroke(100, 140, 180);
      p.strokeWeight(2);
      p.line(x1, y1, x2, y2);
    }

    // No hands - time stopped
    p.fill(120, 140, 180, 100);
    p.noStroke();
    p.circle(clock.x, clock.y, 8);

    // Ten doorways in circular arrangement - the suit's completion
    for(let i = 0; i < doorways.length; i++) {
      let door = doorways[i];

      // Doorways gradually open based on time and mouse interaction
      let targetOpenness = p.sin(timeFlow * 0.5 + door.angle) * 0.5 + 0.5;
      targetOpenness *= vigil.intensity;
      door.openness = p.lerp(door.openness, targetOpenness, 0.02);

      // Light emanating from doorways
      door.light = door.openness * 100;

      p.push();
      p.translate(door.x, door.y);
      p.rotate(door.angle + p.PI/2);

      // Door frame
      p.stroke(60, 100, 140);
      p.strokeWeight(4);
      p.noFill();
      p.rect(-15, -25, 30, 50);

      // Door opening - light within
      p.fill(140 + door.light, 160 + door.light, 200 + door.light, door.openness * 80);
      p.noStroke();
      p.rect(-12 + (1-door.openness) * 24, -22, 24 * door.openness, 44);

      // Threshold
      p.stroke(80, 120, 160, 150);
      p.strokeWeight(2);
      p.line(-15, 25, 15, 25);

      p.pop();
    }

    // Ten completion circles - the full arrangement
    for(let i = 0; i < completionCircles.length; i++) {
      let circle = completionCircles[i];
      let progress = (p.frameCount - circle.delay) * 0.01;

      if(progress > 0) {
        circle.completed = p.sin(progress) > 0.7;

        let alpha = circle.completed ? 150 : 50;
        let size = circle.completed ? circle.radius * 1.5 : circle.radius;

        p.fill(100 + vigil.intensity * 40, 140 + vigil.intensity * 40, 180 + vigil.intensity * 40, alpha);
        p.stroke(140, 160, 200, 100);
        p.strokeWeight(1);
        p.circle(circle.x, circle.y, size);

        // Connection lines when complete
        if(circle.completed && i < completionCircles.length - 1) {
          let nextCircle = completionCircles[(i + 1) % completionCircles.length];
          if(nextCircle.completed) {
            p.stroke(120, 140, 180, 30);
            p.strokeWeight(0.5);
            p.line(circle.x, circle.y, nextCircle.x, nextCircle.y);
          }
        }
      }
    }

    // Empty chairs - spaces of expectation
    for(let i = 0; i < waitingChairs.length; i++) {
      let chair = waitingChairs[i];
      let bob = p.sin(timeFlow * chair.expectancy + i) * 2;

      p.push();
      p.translate(chair.x, chair.y + bob);

      // Chair back
      p.stroke(70, 110, 150);
      p.strokeWeight(3);
      p.noFill();
      p.rect(-20, -40, 40, 40);

      // Chair seat
      p.rect(-20, 0, 40, 20);

      // Chair legs
      p.line(-15, 20, -15, 40);
      p.line(15, 20, 15, 40);
      p.line(-15, -40, -15, -60);
      p.line(15, -40, 15, -60);

      // Aura of waiting
      p.noStroke();
      p.fill(100, 140, 180, 20);
      p.ellipse(0, -10, 60 + bob, 80 + bob);

      p.pop();
    }

    // Central completion mandala
    p.push();
    p.translate(200, 300);
    p.rotate(timeFlow * 0.2);

    // The circle complete - overflow and transformation
    for(let ring = 0; ring < 3; ring++) {
      let radius = 30 + ring * 20;
      let points = 10 - ring * 2;

      for(let i = 0; i < points; i++) {
        let angle = (i / points) * p.TWO_PI;
        let x = p.cos(angle) * radius;
        let y = p.sin(angle) * radius;

        let completion = p.sin(timeFlow + ring + i * 0.5) * 0.5 + 0.5;
        let size = 3 + completion * 5;
        let alpha = 50 + completion * 100;

        p.fill(120 + completion * 40, 140 + completion * 40, 180 + completion * 40, alpha * vigil.intensity);
        p.noStroke();
        p.circle(x, y, size);
      }
    }

    p.pop();

    // Overflow effect - when completion tips into transformation
    let overflow = p.sin(timeFlow * 0.3) * 0.5 + 0.5;
    if(overflow > 0.8) {
      p.stroke(140, 160, 200, (overflow - 0.8) * 500);
      p.strokeWeight(1);
      p.noFill();
      for(let r = 50; r < 150; r += 20) {
        p.circle(200, 300, r + p.sin(timeFlow * 2) * 10);
      }
    }
  };

  p.mousePressed = function() {
    // Click triggers completion wave
    for(let circle of completionCircles) {
      circle.completed = true;
      circle.delay = p.frameCount + p.random(0, 30);
    }

    // Doors respond to interaction
    for(let door of doorways) {
      door.openness = p.min(door.openness + 0.3, 1);
    }
  };
}

