    for(let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(45, 55, 85), p.color(25, 35, 55), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Mouse influence on atmosphere
    let mouseInfluence = p.map(p.mouseX, 0, p.width, 0.5, 1.5);
    lightShaftAlpha = 80 + p.sin(p.frameCount * 0.02) * 40 * mouseInfluence;

    // Window light shaft
    p.push();
    p.noStroke();
    let lightColor = p.color(220, 230, 255, lightShaftAlpha);
    p.fill(lightColor);
    p.quad(120, 80, 280, 80, 200, 400, 150, 400);
    p.pop();

    // Doorway threshold
    doorwayGlow = p.map(p.mouseY, 0, p.height, 20, 100);
    p.push();
    p.stroke(180, 200, 255, doorwayGlow);
    p.strokeWeight(8);
    p.noFill();
    p.rect(50, 50, 100, 200, 5);
    p.fill(60, 80, 120, 40);
    p.noStroke();
    p.rect(50, 50, 100, 200, 5);
    p.pop();

    // Clock without hands (suspended time)
    p.push();
    p.translate(300, 120);
    p.stroke(160, 180, 220, 150);
    p.strokeWeight(3);
    p.noFill();
    p.circle(0, 0, 60);

    // Clock numbers that drift
    p.textAlign(p.CENTER, p.CENTER);
    p.textSize(8);
    p.fill(140, 160, 200, 100);
    for(let i = 1; i <= 12; i++) {
      let angle = (i * p.TWO_PI / 12) - p.HALF_PI;
      let drift = p.sin(p.frameCount * 0.01 + i) * 2;
      let x = p.cos(angle) * (25 + drift);
      let y = p.sin(angle) * (25 + drift);
      p.text(i, x, y);
    }
    p.pop();

    // Floating time elements
    for(let t of timeFloating) {
      t.x += t.drift;
      t.bob += 0.02;
      let bobY = p.sin(t.bob) * 3;

      p.push();
      p.fill(120, 140, 180, 60);
      p.textAlign(p.CENTER);
      p.textSize(14);
      p.text(t.value, t.x, t.y + bobY);
      p.pop();

      if(t.x > p.width + 20) t.x = -20;
      if(t.x < -20) t.x = p.width + 20;
    }

    // Dust particles in light shaft
    for(let dust of dustParticles) {
      dust.y += dust.speed;
      if(dust.y > p.height) dust.y = 50;

      let inLight = dust.x > 120 && dust.x < 280 && dust.y > 80;
      let alpha = inLight ? dust.alpha * 1.5 : dust.alpha * 0.3;

      p.push();
      p.fill(200, 220, 255, alpha);
      p.noStroke();
      p.circle(dust.x + p.sin(dust.y * 0.01) * 2, dust.y, dust.size);
      p.pop();
    }

    // Empty chair (expectation)
    p.push();
    chairAlpha = 60 + p.sin(p.frameCount * 0.03) * 20;
    p.stroke(100, 120, 160, chairAlpha);
    p.strokeWeight(4);
    p.noFill();
    // Chair back
    p.line(320, 380, 320, 320);
    p.line(350, 380, 350, 320);
    p.line(320, 330, 350, 330);
    // Chair seat
    p.line(320, 380, 350, 380);
    p.line(315, 385, 345, 385);
    // Legs
    p.line(320, 380, 315, 420);
    p.line(350, 380, 355, 420);
    p.line(315, 385, 310, 425);
    p.line(345, 385, 350, 425);
    p.pop();

    // Young figure (wanderer)
    figureX = 200 + p.sin(p.frameCount * 0.01) * 5;

    p.push();
    p.translate(figureX, figureY);

    // Shadow
    p.fill(30, 40, 60, 40);
    p.noStroke();
    p.ellipse(0, 80, 60, 15);

    // Body
    p.stroke(120, 140, 180);
    p.strokeWeight(6);
    p.line(0, 0, 0, 60); // torso
    p.line(0, 60, -15, 85); // left leg
    p.line(0, 60, 15, 85); // right leg
    p.line(0, 20, -20, 45); // left arm reaching
    p.line(0, 20, 10, 40); // right arm

    // Head
    p.fill(140, 160, 200, 180);
    p.stroke(120, 140, 180);
    p.strokeWeight(2);
    p.circle(0, -15, 25);

    // Reaching toward something unseen
    let reachX = -30 + p.sin(p.frameCount * 0.02) * 3;
    let reachY = 35 + p.cos(p.frameCount * 0.02) * 2;

    // Gesture of uncertainty/curiosity
    p.stroke(160, 180, 220, 100);
    p.strokeWeight(1);
    p.noFill();
    p.arc(reachX, reachY, 15, 15, 0, p.PI);

    p.pop();

    // Question mark that appears on mouse interaction
    let dist = p.dist(p.mouseX, p.mouseY, figureX, figureY);
    if(dist < 100) {
      questionMarkAlpha = p.lerp(questionMarkAlpha, 150, 0.1);
    } else {
      questionMarkAlpha = p.lerp(questionMarkAlpha, 0, 0.1);
    }

    p.push();
    p.fill(180, 200, 240, questionMarkAlpha);
    p.textAlign(p.CENTER);
    p.textSize(24);
    p.text("?", figureX - 40, figureY - 20);
    p.pop();

    // Threshold glow responds to mouse
    if(p.mouseX < 160 && p.mouseY < 260) {
      p.push();
      p.stroke(200, 220, 255, 60);
      p.strokeWeight(12);
      p.noFill();
      p.rect(45, 45, 110, 210, 5);
      p.pop();
    }

    // Subtle frame
    p.push();
    p.stroke(80, 100, 140, 120);
    p.strokeWeight(2);
    p.noFill();
    p.rect(10, 10, p.width-20, p.height-20, 8);
    p.pop();
  };
}

function sketch(p) {
  let figure = {};
  let dustParticles = [];
  let clockAngle = 0;
  let breathPhase = 0;
  let windowLight = 0;
  let chairSway = 0;
  let eyeBlink = 0;
  let recognition = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    figure.x = 200;
    figure.y = 350;
    figure.eyeState = 1;

    // Create dust particles
    for (let i = 0; i < 40; i++) {
      dustParticles.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        driftX: p.random(-0.3, 0.3),
        driftY: p.random(-0.1, 0.1),
        size: p.random(1, 3),
        alpha: p.random(30, 80)
      });
    }
  };

  p.draw = function() {
    // Blue-tinted atmospheric background
    p.background(18, 25, 40);

    breathPhase += 0.02;
    windowLight = 0.3 + 0.2 * p.sin(breathPhase * 0.5);
    chairSway = p.sin(breathPhase * 0.8) * 2;
    eyeBlink = p.abs(p.sin(breathPhase * 3)) > 0.95 ? 0.2 : 1;

    // Mouse interaction affects recognition
    let mouseProximity = p.dist(p.mouseX, p.mouseY, figure.x, figure.y);
    recognition = p.map(mouseProximity, 0, 200, 1, 0.3);
    recognition = p.constrain(recognition, 0.3, 1);

    // Window with suspended light
    drawWindow();

    // Dust particles in light shaft
    drawDustParticles();

    // Empty chair waiting
    drawChair();

    // Clock without hands
    drawClock();

    // Threshold/doorway frame
    drawThreshold();

    // Central figure - the Observer
    drawObserver();

    // Subtle recognition aura
    drawRecognitionField();
  };

  function drawWindow() {
    // Window frame
    p.stroke(40, 60, 90);
    p.strokeWeight(4);
    p.fill(0, 0, 0, 0);
    p.rect(50, 80, 120, 160);

    // Cross frame
    p.line(110, 80, 110, 240);
    p.line(50, 160, 170, 160);

    // Light shaft from window
    p.noStroke();
    let lightAlpha = 25 * windowLight;
    p.fill(120, 150, 180, lightAlpha);
    p.beginShape();
    p.vertex(80, 160);
    p.vertex(140, 160);
    p.vertex(220, 400);
    p.vertex(160, 400);
    p.endShape(p.CLOSE);
  };

  function drawDustParticles() {
    p.noStroke();
    for (let particle of dustParticles) {
      // Drift motion
      particle.x += particle.driftX;
      particle.y += particle.driftY;

      // Wrap around edges
      if (particle.x < 0) particle.x = 400;
      if (particle.x > 400) particle.x = 0;
      if (particle.y < 0) particle.y = 600;
      if (particle.y > 600) particle.y = 0;

      // Only visible in light shaft area
      if (particle.x > 80 && particle.x < 220 && particle.y > 160 && particle.y < 500) {
        p.fill(200, 220, 240, particle.alpha * windowLight);
        p.ellipse(particle.x, particle.y, particle.size);
      }
    }
  };

  function drawChair() {
    p.push();
    p.translate(320 + chairSway, 450);

    // Chair back
    p.stroke(30, 45, 70);
    p.strokeWeight(6);
    p.fill(25, 35, 55);
    p.rect(-15, -80, 30, 80);

    // Chair seat
    p.ellipse(0, -20, 50, 30);

    // Chair legs
    p.strokeWeight(4);
    p.line(-20, -5, -20, 40);
    p.line(20, -5, 20, 40);
    p.line(-20, -50, -20, -20);
    p.line(20, -50, 20, -20);

    p.pop();
  };

  function drawClock() {
    p.push();
    p.translate(320, 120);

    // Clock face
    p.stroke(50, 70, 100);
    p.strokeWeight(2);
    p.fill(30, 40, 60);
    p.ellipse(0, 0, 60, 60);

    // Hour markers
    for (let i = 0; i < 12; i++) {
      let angle = i * p.TWO_PI / 12;
      let x1 = p.cos(angle) * 25;
      let y1 = p.sin(angle) * 25;
      let x2 = p.cos(angle) * 20;
      let y2 = p.sin(angle) * 20;
      p.line(x1, y1, x2, y2);
    }

    // No hands - time suspended

    p.pop();
  };

  function drawThreshold() {
    // Doorway frame
    p.stroke(45, 65, 95);
    p.strokeWeight(8);
    p.noFill();
    p.rect(30, 300, 140, 280);

    // Inner shadow
    p.stroke(15, 20, 35);
    p.strokeWeight(2);
    p.rect(35, 305, 130, 270);
  };

  function drawObserver() {
    p.push();
    p.translate(figure.x, figure.y + p.sin(breathPhase) * 3);

    // Body - simple, present form
    p.fill(60, 80, 120, 200);
    p.noStroke();
    p.ellipse(0, 20, 40, 60);

    // Arms - open, receptive
    p.stroke(60, 80, 120);
    p.strokeWeight(6);
    p.line(-15, 10, -25, 0);
    p.line(15, 10, 25, 0);

    // Head
    p.noStroke();
    p.fill(80, 100, 140, 220);
    p.ellipse(0, -10, 30, 35);

    // Eyes - alert, present, seeing
    p.fill(150, 170, 200, 255 * eyeBlink * recognition);
    p.ellipse(-6, -12, 4, 6);
    p.ellipse(6, -12, 4, 6);

    // Pupil intensity shows recognition
    p.fill(200, 220, 240, 255 * recognition);
    p.ellipse(-6, -12, 2, 3);
    p.ellipse(6, -12, 2, 3);

    p.pop();
  };

  function drawRecognitionField() {
    // Subtle field showing mutual recognition
    p.push();
    p.translate(figure.x, figure.y);

    p.noFill();
    p.stroke(120, 150, 180, 30 * recognition);
    p.strokeWeight(2);

    for (let i = 0; i < 3; i++) {
      let radius = 50 + i * 20 + p.sin(breathPhase + i) * 5;
      p.ellipse(0, 0, radius, radius);
    }

    p.pop();

    // Connection to mouse (the other being observed)
    if (recognition > 0.6) {
      p.stroke(100, 130, 160, 40);
      p.strokeWeight(1);
      p.line(figure.x, figure.y, p.mouseX, p.mouseY);
    }
  };
}

function sketch(p) {
  let keeper;
  let dustParticles = [];
  let clockAngle = 0;
  let doorOpening = 0;
  let lightShafts = [];
  let timeStops = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    keeper = {
      x: 200,
      y: 350,
      sway: 0,
      breathing: 0
    };

    // Create dust particles
    for (let i = 0; i < 80; i++) {
      dustParticles.push({
        x: p.random(100, 300),
        y: p.random(200, 500),
        size: p.random(1, 3),
        drift: p.random(-0.3, 0.3),
        fall: p.random(0.1, 0.5),
        alpha: p.random(30, 80)
      });
    }

    // Create light shaft points
    for (let i = 0; i < 5; i++) {
      lightShafts.push({
        x: 150 + i * 25,
        intensity: p.random(0.3, 0.8),
        pulse: p.random(0.01, 0.03)
      });
    }

    // Time stop moments
    for (let i = 0; i < 3; i++) {
      timeStops.push({
        x: p.random(50, 350),
        y: p.random(100, 200),
        size: 0,
        active: false,
        timer: p.random(200, 400)
      });
    }
  };

  p.draw = function() {
    // Blue-tinted background gradient
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 45), p.color(35, 45, 65), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Window with threshold
    p.push();
    p.stroke(60, 80, 120, 180);
    p.strokeWeight(8);
    p.noFill();
    p.rect(80, 80, 240, 180, 5);

    // Window panes
    p.strokeWeight(3);
    p.line(200, 80, 200, 260);
    p.line(80, 170, 320, 170);
    p.pop();

    // Light shafts through window
    p.push();
    p.blendMode(p.ADD);
    for (let shaft of lightShafts) {
      shaft.intensity += shaft.pulse * p.sin(p.frameCount * 0.02);
      if (shaft.intensity > 0.9 || shaft.intensity < 0.2) shaft.pulse *= -1;

      let alpha = shaft.intensity * 40;
      p.fill(100, 120, 160, alpha);
      p.noStroke();
      p.quad(shaft.x, 260, shaft.x + 20, 260, 
             shaft.x + 60, 500, shaft.x + 40, 500);
    }
    p.pop();

    // Dust particles in light
    for (let dust of dustParticles) {
      dust.x += dust.drift + p.sin(p.frameCount * 0.01) * 0.2;
      dust.y += dust.fall;

      if (dust.y > p.height + 10) {
        dust.y = -10;
        dust.x = p.random(100, 300);
      }
      if (dust.x > 350) dust.x = 50;
      if (dust.x < 50) dust.x = 350;

      let mouseInfluence = p.dist(p.mouseX, p.mouseY, dust.x, dust.y);
      if (mouseInfluence < 50) {
        dust.alpha = p.min(dust.alpha + 2, 120);
      } else {
        dust.alpha = p.max(dust.alpha - 1, 30);
      }

      p.push();
      p.fill(180, 200, 240, dust.alpha);
      p.noStroke();
      p.ellipse(dust.x, dust.y, dust.size);
      p.pop();
    }

    // Empty chair waiting
    p.push();
    p.stroke(80, 100, 140, 200);
    p.strokeWeight(6);
    p.noFill();
    // Chair back
    p.line(320, 400, 320, 480);
    p.line(300, 400, 340, 400);
    // Chair seat
    p.line(300, 480, 360, 480);
    // Chair legs
    p.line(300, 480, 300, 520);
    p.line(340, 480, 340, 520);
    p.line(320, 400, 320, 440);
    p.line(360, 480, 360, 520);
    p.pop();

    // Keeper figure
    keeper.sway = p.sin(p.frameCount * 0.015) * 3;
    keeper.breathing = p.sin(p.frameCount * 0.03) * 2;

    p.push();
    p.translate(keeper.x + keeper.sway, keeper.y);

    // Keeper's body - languid brush strokes
    p.stroke(120, 140, 180, 220);
    p.strokeWeight(8);
    p.noFill();
    p.beginShape();
    p.curveVertex(0, -80 + keeper.breathing);
    p.curveVertex(0, -60 + keeper.breathing);
    p.curveVertex(-5, -20);
    p.curveVertex(-10, 20);
    p.curveVertex(-5, 60);
    p.curveVertex(0, 80);
    p.endShape();

    // Arms holding vigil lamp
    p.strokeWeight(6);
    p.beginShape();
    p.curveVertex(-10, -20);
    p.curveVertex(-15, -10);
    p.curveVertex(-25, 10);
    p.curveVertex(-30, 30);
    p.endShape(p.OPEN);

    p.beginShape();
    p.curveVertex(-10, -20);
    p.curveVertex(15, -10);
    p.curveVertex(25, 10);
    p.curveVertex(30, 30);
    p.endShape(p.OPEN);

    // Vigil lamp/waiting symbol
    p.push();
    p.translate(0, -10);
    let lampGlow = 150 + p.sin(p.frameCount * 0.05) * 50;
    p.fill(lampGlow, lampGlow + 20, 200, 180);
    p.noStroke();
    p.ellipse(0, 0, 30 + keeper.breathing * 2, 30 + keeper.breathing * 2);

    // Lamp holder
    p.stroke(100, 120, 160, 200);
    p.strokeWeight(4);
    p.noFill();
    p.arc(0, 0, 40, 40, p.PI, p.TWO_PI);
    p.pop();

    p.pop();

    // Clock without hands
    p.push();
    p.translate(100, 150);
    p.stroke(80, 100, 140, 150);
    p.strokeWeight(4);
    p.noFill();
    p.ellipse(0, 0, 60, 60);

    // Clock face marks but no hands
    for (let i = 0; i < 12; i++) {
      let angle = (i * p.TWO_PI) / 12;
      let x1 = p.cos(angle) * 25;
      let y1 = p.sin(angle) * 25;
      let x2 = p.cos(angle) * 22;
      let y2 = p.sin(angle) * 22;
      p.line(x1, y1, x2, y2);
    }
    p.pop();

    // Time stop moments
    for (let stop of timeStops) {
      stop.timer--;
      if (stop.timer <= 0 && !stop.active) {
        stop.active = true;
        stop.size = 0;
      }

      if (stop.active) {
        stop.size += 0.5;
        p.push();
        p.stroke(150, 170, 220, 200 - stop.size * 4);
        p.strokeWeight(2);
        p.noFill();
        p.ellipse(stop.x, stop.y, stop.size, stop.size);
        p.pop();

        if (stop.size > 50) {
          stop.active = false;
          stop.timer = p.random(300, 600);
          stop.x = p.random(50, 350);
          stop.y = p.random(100, 200);
        }
      }
    }

    // Door threshold at bottom
    doorOpening = p.lerp(doorOpening, p.mouseIsPressed ? 20 : 0, 0.05);
    p.push();
    p.stroke(60, 80, 120, 200);
    p.strokeWeight(10);
    p.line(50, p.height - 50, 150 - doorOpening, p.height - 50);
    p.line(250 + doorOpening, p.height - 50, 350, p.height - 50);
    p.line(150 - doorOpening, p.height - 50, 150 - doorOpening, p.height);
    p.line(250 + doorOpening, p.height - 50, 250 + doorOpening, p.height);
    p.pop();
  };
}

