      let c = p.lerpColor(p.color(25, 35, 55), p.color(45, 60, 85), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    breathingOffset = p.sin(p.millis() * 0.001) * 3;
    lightShaftAngle = p.sin(p.millis() * 0.0005) * 0.1;

    // Window with light shaft
    p.push();
    p.translate(300, 120);
    p.rotate(lightShaftAngle);

    // Window frame
