    p.stroke(120, 140, 180, 180);
    p.strokeWeight(6);
    p.rect(-40, -25, 80, 50);
    p.line(-40, 0, 40, 0);
    p.line(0, -25, 0, 25);

    // Light shaft
    p.fill(180, 200, 255, 15);
    p.noStroke();
    p.triangle(-30, 25, 30, 25, 0, 300);
    p.pop();

    // Doorway threshold
    doorwayAlpha = p.map(p.mouseX, 0, p.width, 20, 80);
    p.stroke(100, 120, 160, doorwayAlpha);
    p.strokeWeight(8);
    p.fill(0, 0, 0, 10);
    p.rect(50, 100, 80, 180);
    p.noFill();
    p.arc(90, 100, 80, 80, p.PI, p.TWO_PI);

    // Clock without hands
    p.push();
    p.translate(120, 150);
    p.noFill();
    p.stroke(90, 110, 150, 120);
    p.strokeWeight(3);
    p.circle(0, 0, clockRadius);

    // Clock numbers that fade and shift
    p.textAlign(p.CENTER, p.CENTER);
    p.textSize(12);
    for (let i = 1; i <= 12; i++) {
      let angle = (i * p.TWO_PI / 12) - p.PI / 2;
      let x = p.cos(angle) * (clockRadius / 2 - 10);
      let y = p.sin(angle) * (clockRadius / 2 - 10);
      let alpha = p.map(p.sin(p.millis() * 0.002 + i), -1, 1, 30, 100);
      p.fill(130, 150, 190, alpha);
      p.text(i, x, y);
    }
    p.pop();

    // Empty chair with subtle glow
    chairGlow = p.map(p.mouseY, 0, p.height, 0, 40);
    p.push();
    p.translate(320, 400);

    // Chair glow
    p.fill(150, 170, 220, chairGlow);
    p.noStroke();
    p.ellipse(0, 0, 100, 100);

    // Chair structure
    p.stroke(80, 100, 140);
    p.strokeWeight(4);
    p.noFill();

    // Seat
    p.rect(-25, -5, 50, 30);
    // Back
    p.rect(-25, -35, 50, 30);
    // Legs
    p.line(-20, 25, -20, 50);
    p.line(20, 25, 20, 50);
    p.line(-20, -5, -20, -15);
    p.line(20, -5, 20, -15);
    p.pop();

    // Dust particles in light shaft
    p.noStroke();
    for (let particle of dustParticles) {
      particle.x += particle.driftX + p.sin(p.millis() * 0.001 + particle.y * 0.01) * 0.1;
      particle.y += particle.driftY;

      // Wrap around
      if (particle.x < 100) particle.x = 350;
      if (particle.x > 350) particle.x = 100;
      if (particle.y < 150) particle.y = 500;
      if (particle.y > 500) particle.y = 150;

      let distanceFromShaft = p.abs(particle.x - (250 + p.sin(p.millis() * 0.0005) * 50));
      let inShaft = distanceFromShaft < 40;
      let alpha = inShaft ? particle.alpha * 2 : particle.alpha * 0.3;

      p.fill(200, 220, 255, alpha);
      p.circle(particle.x, particle.y, particle.size);
    }

    // Central figure - the Dweller
    p.push();
    p.translate(figure.x, figure.y + breathingOffset);

    // Figure's aura of complete ease
    let auraSize = 120 + p.sin(p.millis() * 0.002) * 10;
    p.fill(120, 160, 220, 15);
    p.noStroke();
    p.ellipse(0, 0, auraSize, auraSize);

    // Figure silhouette
    p.fill(60, 80, 120, 180);
    p.noStroke();

    // Head
    p.ellipse(0, -30, 30, 35);

    // Body in meditation pose
    p.ellipse(0, 10, 45, 60);

    // Arms in restful position
    p.ellipse(-25, 0, 15, 40);
    p.ellipse(25, 0, 15, 40);

    // Legs crossed
    p.ellipse(-15, 40, 35, 20);
    p.ellipse(15, 40, 35, 20);

    // Integration symbol - infinity loop around figure
    p.noFill();
    p.stroke(140, 180, 240, 100 + p.sin(p.millis() * 0.003) * 50);
    p.strokeWeight(2);

    let loopSize = 60 + p.sin(p.millis() * 0.002) * 5;
    for (let t = 0; t < p.TWO_PI; t += 0.1) {
      let x = loopSize * p.cos(t) / (1 + p.sin(t) * p.sin(t));
      let y = loopSize * p.sin(t) * p.cos(t) / (1 + p.sin(t) * p.sin(t));
      if (t == 0) {
        p.beginShape();
        p.noFill();
      }
      p.curveVertex(x, y);
      if (t > p.TWO_PI - 0.2) {
        p.endShape();
      }
    }
    p.pop();

    // Subtle interaction - figure's ease responds to stillness
    let mouseStillness = p.constrain(5 - p.abs(p.mouseX - p.pmouseX) - p.abs(p.mouseY - p.pmouseY), 0, 5);
    figure.ease = p.lerp(figure.ease, mouseStillness, 0.05);

    // Glow increases with stillness
    p.push();
    p.translate(figure.x, figure.y + breathingOffset);
    p.fill(160, 200, 255, figure.ease * 8);
    p.noStroke();
    p.ellipse(0, 0, 100 + figure.ease * 10, 100 + figure.ease * 10);
    p.pop();

    // Threshold between states - subtle border
    p.noFill();
    p.stroke(100, 130, 170, 60);
    p.strokeWeight(2);
    p.rect(10, 10, p.width - 20, p.height - 20, 15);
  };
}

function sketch(p) {
  let particles = [];
  let eyeSymbol = {};
  let time = 0;
  let mouseInfluence = 0;
  let sparkles = [];

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Initialize the eye symbol
    eyeSymbol = {
      x: p.width / 2,
      y: p.height / 2,
      size: 80,
      alpha: 0,
      pulsePhase: 0
    };

    // Create background particles
    for (let i = 0; i < 50; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(1, 3),
        speed: p.random(0.2, 0.8),
        phase: p.random(p.TWO_PI),
        alpha: p.random(10, 40)
      });
    }

    // Create sparkles for recognition moments
    for (let i = 0; i < 20; i++) {
      sparkles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        life: p.random(100),
        maxLife: p.random(80, 120),
        twinkle: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    time += 0.02;

    // Create deep blue gradient background
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(220, 80, 15),  // Deep blue-purple
        p.color(240, 60, 8),   // Very dark blue
        inter
      );
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Mouse influence calculation
    let mouseDist = p.dist(p.mouseX, p.mouseY, eyeSymbol.x, eyeSymbol.y);
    mouseInfluence = p.map(mouseDist, 0, 200, 1, 0);
    mouseInfluence = p.constrain(mouseInfluence, 0, 1);

    // Draw floating particles
    p.noFill();
    for (let particle of particles) {
      particle.y -= particle.speed;
      if (particle.y < -10) particle.y = p.height + 10;

      let flickerAlpha = particle.alpha + p.sin(time * 3 + particle.phase) * 15;
      p.stroke(210, 40, 70, flickerAlpha);
      p.strokeWeight(particle.size);
      p.point(particle.x, particle.y);
    }

    // Draw sparkles that represent moments of recognition
    for (let sparkle of sparkles) {
      sparkle.life += 1;
      if (sparkle.life > sparkle.maxLife) {
        sparkle.life = 0;
        sparkle.x = p.random(p.width);
        sparkle.y = p.random(p.height);
      }

      let sparkleAlpha = p.map(p.sin(sparkle.life * 0.1 + sparkle.twinkle), -1, 1, 0, 60);
      sparkleAlpha *= (1 - sparkle.life / sparkle.maxLife);

      p.fill(200, 30, 90, sparkleAlpha);
      p.noStroke();
      p.circle(sparkle.x, sparkle.y, 2);
    }

    // Draw emerging hands from darkness
    p.push();
    p.translate(p.width / 2, p.height * 0.75);

    // Left hand emerging from shadow
    p.fill(220, 20, 25, 40 + mouseInfluence * 30);
    p.noStroke();
    p.ellipse(-60, 20, 25 + p.sin(time) * 3, 40 + p.cos(time) * 2);
    p.ellipse(-45, 10, 8, 15);
    p.ellipse(-40, 5, 6, 12);
    p.ellipse(-35, 8, 6, 10);
    p.ellipse(-32, 12, 5, 8);

    // Right hand reaching
    p.fill(220, 20, 25, 40 + mouseInfluence * 30);
    p.ellipse(60, 20, 25 + p.sin(time + p.PI) * 3, 40 + p.cos(time + p.PI) * 2);
    p.ellipse(45, 10, 8, 15);
    p.ellipse(40, 5, 6, 12);
    p.ellipse(35, 8, 6, 10);
    p.ellipse(32, 12, 5, 8);
    p.pop();

    // Draw the central eye symbol - emerging from darkness
    p.push();
    p.translate(eyeSymbol.x, eyeSymbol.y);

    // Eye alpha increases with mouse proximity and time
    eyeSymbol.alpha = 30 + mouseInfluence * 50 + p.sin(time * 2) * 20;
    eyeSymbol.pulsePhase += 0.03;

    let eyeSize = eyeSymbol.size + p.sin(eyeSymbol.pulsePhase) * 10;

    // Outer eye shape - languid brush stroke style
    p.strokeWeight(3);
    p.stroke(200, 60, 80, eyeSymbol.alpha);
    p.noFill();

    // Draw eye outline with imperfect curves for languid feeling
    p.beginShape();
    p.vertex(-eyeSize/2, 0);
    p.bezierVertex(-eyeSize/3, -eyeSize/4, -eyeSize/6, -eyeSize/4, 0, -eyeSize/6);
    p.bezierVertex(eyeSize/6, -eyeSize/4, eyeSize/3, -eyeSize/4, eyeSize/2, 0);
    p.bezierVertex(eyeSize/3, eyeSize/4, eyeSize/6, eyeSize/4, 0, eyeSize/6);
    p.bezierVertex(-eyeSize/6, eyeSize/4, -eyeSize/3, eyeSize/4, -eyeSize/2, 0);
    p.endShape();

    // Inner iris - the moment of recognition
    let irisAlpha = eyeSymbol.alpha * 0.8;
    p.fill(190, 80, 90, irisAlpha);
    p.noStroke();
    p.circle(0, 0, eyeSize * 0.4);

    // Pupil - the depth of seeing
    p.fill(240, 90, 20, eyeSymbol.alpha * 1.2);
    p.circle(0, 0, eyeSize * 0.15);

    // Reflection sparkle - the spark of recognition
    if (mouseInfluence > 0.3) {
      p.fill(60, 20, 95, 80);
      p.circle(-eyeSize * 0.05, -eyeSize * 0.05, 3);
    }

    p.pop();

    // Draw light rays emanating from the eye when mouse is close
    if (mouseInfluence > 0.5) {
      p.push();
      p.translate(eyeSymbol.x, eyeSymbol.y);
      p.strokeWeight(1);
      p.stroke(200, 40, 85, mouseInfluence * 40);

      for (let i = 0; i < 8; i++) {
        let angle = (p.TWO_PI / 8) * i + time;
        let rayLength = 60 + p.sin(time * 2 + i) * 20;
        p.line(0, 0, p.cos(angle) * rayLength, p.sin(angle) * rayLength);
      }
      p.pop();
    }

    // Draw subtle face outline - partially obscured
    p.push();
    p.translate(p.width / 2, p.height / 2 - 50);
    p.strokeWeight(2);
    p.stroke(220, 30, 60, 20 + mouseInfluence * 25);
    p.noFill();

    // Face outline - left side more visible
    p.arc(-20, 0, 120, 160, -p.HALF_PI, p.HALF_PI);

    // Right side fading into shadow
    p.stroke(220, 30, 60, 10 + mouseInfluence * 15);
    p.arc(20, 0, 120, 160, p.HALF_PI, p.PI + p.HALF_PI);
    p.pop();
  };

  p.mousePressed = function() {
    // Create burst of recognition sparkles
    for (let i = 0; i < 10; i++) {
      sparkles.push({
        x: p.mouseX + p.random(-50, 50),
        y: p.mouseY + p.random(-50, 50),
        life: 0,
        maxLife: p.random(60, 100),
        twinkle: p.random(p.TWO_PI)
      });
    }
  };
}

function sketch(p) {
  let face1, face2;
  let eyeOffset = 0;
  let breathe = 0;
  let mirrorOpacity = 0;
  let handGesture = 0;
  let recognitionMoment = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    face1 = { x: 120, y: 250, visible: 0.7 };
    face2 = { x: 280, y: 350, visible: 0.7 };
  };

  p.draw = function() {
    // Blue-tinted gradient background
    for(let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 45), p.color(35, 55, 85), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Animate breathing and recognition
    breathe += 0.02;
    eyeOffset = p.sin(p.millis() * 0.001) * 5;
    handGesture = p.sin(p.millis() * 0.0015) * 15;

    // Mouse interaction affects recognition moment
    let mouseInfluence = p.map(p.mouseX, 0, p.width, 0, 1);
    recognitionMoment = p.lerp(recognitionMoment, mouseInfluence, 0.02);

    // Mirror reflection effect
    mirrorOpacity = 40 + p.sin(breathe) * 20;
    p.push();
    p.translate(p.width/2, p.height/2);
    p.rotate(p.PI/6);
    p.stroke(120, 140, 180, mirrorOpacity);
    p.strokeWeight(2);
    p.noFill();
    p.ellipse(0, 0, 150, 300);
    p.pop();

    // Draw first figure - partially obscured
    p.push();
    p.translate(face1.x, face1.y);

    // Shadow that reveals and conceals
    p.fill(20, 30, 60, 100 - recognitionMoment * 50);
    p.noStroke();
    p.ellipse(10, 10, 80, 100);

    // Face partially visible
    p.fill(180, 190, 220, face1.visible * 255 * (0.5 + recognitionMoment * 0.5));
    p.ellipse(0, 0, 70, 90);

    // Eyes - one looking, one avoiding
    p.fill(60, 80, 120);
    p.ellipse(-15 + eyeOffset, -10, 8, 12);
    p.fill(60, 80, 120, 100 + recognitionMoment * 155);
    p.ellipse(15 - eyeOffset, -10, 8, 12);

    // Expressive hand gesture
    p.stroke(140, 160, 200, 180);
    p.strokeWeight(3);
    p.noFill();
    p.beginShape();
    p.curveVertex(30, 40 + handGesture);
    p.curveVertex(35, 35 + handGesture);
    p.curveVertex(45, 40 + handGesture);
    p.curveVertex(50, 50 + handGesture);
    p.endShape();

    p.pop();

    // Draw second figure - mirroring the first
    p.push();
    p.translate(face2.x, face2.y);

    // Shadow
    p.fill(20, 30, 60, 100 - recognitionMoment * 50);
    p.noStroke();
    p.ellipse(-10, -10, 80, 100);

    // Face
    p.fill(180, 190, 220, face2.visible * 255 * (0.5 + recognitionMoment * 0.5));
    p.ellipse(0, 0, 70, 90);

    // Eyes - mirroring the gaze
    p.fill(60, 80, 120, 100 + recognitionMoment * 155);
    p.ellipse(-15 - eyeOffset, -10, 8, 12);
    p.fill(60, 80, 120);
    p.ellipse(15 + eyeOffset, -10, 8, 12);

    // Responding hand gesture
    p.stroke(140, 160, 200, 180);
    p.strokeWeight(3);
    p.noFill();
    p.beginShape();
    p.curveVertex(-50, 40 - handGesture);
    p.curveVertex(-45, 35 - handGesture);
    p.curveVertex(-35, 40 - handGesture);
    p.curveVertex(-30, 50 - handGesture);
    p.endShape();

    p.pop();

    // Connection between the two - dialogue line
    p.stroke(100, 140, 180, 50 + recognitionMoment * 100);
    p.strokeWeight(2);
    p.line(face1.x + 30, face1.y, face2.x - 30, face2.y);

    // Light revealing/concealing
    for(let i = 0; i < 5; i++) {
      let lightX = p.map(p.noise(i * 0.1, p.millis() * 0.001), 0, 1, 50, 350);
      let lightY = p.map(p.noise(i * 0.2, p.millis() * 0.0008), 0, 1, 150, 450);
      let lightSize = p.map(p.noise(i * 0.15, p.millis() * 0.0012), 0, 1, 20, 60);

      p.fill(220, 230, 255, 30 + recognitionMoment * 40);
      p.noStroke();
      p.ellipse(lightX, lightY, lightSize, lightSize * 0.6);
    }

    // Moment of recognition particle
    if(recognitionMoment > 0.7) {
      let centerX = (face1.x + face2.x) / 2;
      let centerY = (face1.y + face2.y) / 2;

      for(let i = 0; i < 8; i++) {
        let angle = (p.millis() * 0.002 + i * p.PI/4);
        let radius = 30 * (recognitionMoment - 0.7) * 3;
        let px = centerX + p.cos(angle) * radius;
        let py = centerY + p.sin(angle) * radius;

        p.fill(150, 180, 255, 100);
        p.noStroke();
        p.ellipse(px, py, 4, 4);
      }
    }
  };

  p.mousePressed = function() {
    // Click creates ripple of recognition
    for(let i = 0; i < 3; i++) {
      setTimeout(() => {
        face1.visible = p.random(0.3, 1);
        face2.visible = p.random(0.3, 1);
      }, i * 200);
    }
  };
}

function sketch(p) {
  let faces = [];
  let reflections = [];
  let growthSpirals = [];
  let mouseInfluence = 0;
  let breathe = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create three faces in triangular arrangement
    faces.push({
      x: 200, y: 150,
      opacity: 0.8,
      eyeOffset: 0,
      isVisible: true
    });
    faces.push({
      x: 130, y: 320,
      opacity: 0.6,
      eyeOffset: p.PI/3,
      isVisible: false
    });
    faces.push({
      x: 270, y: 320,
      opacity: 0.7,
      eyeOffset: -p.PI/4,
      isVisible: true
    });

    // Create reflection points
    for(let i = 0; i < 5; i++) {
      reflections.push({
        x: p.random(50, 350),
        y: p.random(400, 550),
        size: p.random(30, 80),
        drift: p.random(0.01, 0.03)
      });
    }

    // Growth spirals emerging from triangle center
    for(let i = 0; i < 3; i++) {
      growthSpirals.push({
        angle: i * p.TWO_PI / 3,
        radius: 0,
        growth: 0.5 + i * 0.3
      });
    }
  };

  p.draw = function() {
    // Blue-tinted gradient background
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 55), p.color(45, 65, 95), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    breathe += 0.02;
    mouseInfluence = p.map(p.mouseX, 0, p.width, 0, 1);

    // Draw growth spirals from center
    p.push();
    p.translate(200, 250);
    p.noFill();
    for(let spiral of growthSpirals) {
      spiral.radius += spiral.growth;
      if(spiral.radius > 150) spiral.radius = 0;

      p.stroke(120, 150, 200, 100);
      p.strokeWeight(2);
      p.beginShape();
      p.noFill();
      for(let a = 0; a < p.TWO_PI * 3; a += 0.1) {
        let r = spiral.radius * (a / (p.TWO_PI * 3));
        let x = p.cos(a + spiral.angle) * r;
        let y = p.sin(a + spiral.angle) * r;
        p.vertex(x, y);
      }
      p.endShape();
    }
    p.pop();

    // Draw faces with partial visibility
    for(let i = 0; i < faces.length; i++) {
      let face = faces[i];
      let pulseSize = 40 + p.sin(breathe + i) * 8;

      p.push();
      p.translate(face.x, face.y);

      // Shadow/obscurement
      p.fill(20, 30, 60, 150 - mouseInfluence * 50);
      p.noStroke();
      p.ellipse(5, 5, pulseSize + 10, pulseSize + 10);

      // Face outline (partially visible)
      p.stroke(100, 130, 180, face.opacity * 255);
      p.strokeWeight(3);
      p.noFill();
      let visibilityMask = face.isVisible ? 1 : mouseInfluence;

      // Draw face arc (partially obscured)
      let startAngle = p.PI + face.eyeOffset;
      let endAngle = p.TWO_PI + p.PI * 0.3 + face.eyeOffset;
      p.arc(0, 0, pulseSize, pulseSize, startAngle, endAngle);

      // Eyes - meeting or avoiding based on mouse
      if(visibilityMask > 0.3) {
        p.fill(150, 170, 220, visibilityMask * 200);
        p.noStroke();

        let eyeGaze = mouseInfluence > 0.5 ? 0 : face.eyeOffset;
        p.ellipse(-8 + p.cos(eyeGaze) * 3, -5 + p.sin(eyeGaze) * 2, 4, 6);
        p.ellipse(8 + p.cos(eyeGaze) * 3, -5 + p.sin(eyeGaze) * 2, 4, 6);
      }

      // Expressive hand gesture
      p.stroke(80, 110, 160, face.opacity * 180);
      p.strokeWeight(4);
      p.beginShape();
      p.noFill();
      let handX = 25 + p.sin(breathe + i * 0.7) * 10;
      let handY = 15 + p.cos(breathe + i * 0.5) * 8;
      p.vertex(handX, handY);
      p.vertex(handX + 8, handY - 5);
      p.vertex(handX + 12, handY + 3);
      p.endShape();

      p.pop();
    }

    // Mirrors and reflections at bottom
    for(let reflection of reflections) {
      reflection.x += p.sin(breathe + reflection.drift * 100) * 0.5;

      p.push();
      p.translate(reflection.x, reflection.y);

      // Mirror surface
      p.fill(70, 100, 140, 80);
      p.stroke(100, 130, 170, 120);
      p.strokeWeight(2);
      p.ellipse(0, 0, reflection.size, reflection.size * 0.6);

      // Distorted reflection
      if(mouseInfluence > 0.2) {
        p.fill(120, 150, 200, 60);
        p.noStroke();
        let distortion = p.sin(breathe * 2 + reflection.drift * 50) * 5;
        p.ellipse(distortion, -reflection.size * 0.2, reflection.size * 0.6, reflection.size * 0.3);
      }

      p.pop();
    }

    // Light rays revealing/concealing
    p.stroke(150, 180, 220, 40 + mouseInfluence * 60);
    p.strokeWeight(1);
    for(let i = 0; i < 8; i++) {
      let angle = (breathe + i * 0.3) % p.TWO_PI;
      let x1 = 200 + p.cos(angle) * 50;
      let y1 = 250 + p.sin(angle) * 50;
      let x2 = 200 + p.cos(angle) * 200;
      let y2 = 250 + p.sin(angle) * 200;
      p.line(x1, y1, x2, y2);
    }

    // Triangular connection lines (showing the three)
    p.stroke(90, 120, 170, 100 + mouseInfluence * 100);
    p.strokeWeight(1);
    p.line(faces[0].x, faces[0].y, faces[1].x, faces[1].y);
    p.line(faces[1].x, faces[1].y, faces[2].x, faces[2].y);
    p.line(faces[2].x, faces[2].y, faces[0].x, faces[0].y);
  };

  p.mousePressed = function() {
    // Toggle visibility of middle face on click
    faces[1].isVisible = !faces[1].isVisible;

    // Ripple effect
    for(let i = 0; i < 3; i++) {
      growthSpirals[i].radius = 10;
    }
  };
}

function sketch(p) {
  let eyes = [];
  let mirrors = [];
  let hands = [];
  let shadows = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create four corners of seeing - eyes positioned in square formation
    eyes = [
      {x: 100, y: 150, blinkTimer: 0, isOpen: true, gaze: 0},
      {x: 300, y: 150, blinkTimer: 0, isOpen: true, gaze: 0},
      {x: 100, y: 450, blinkTimer: 0, isOpen: true, gaze: 0},
      {x: 300, y: 450, blinkTimer: 0, isOpen: true, gaze: 0}
    ];

    // Mirrors reflecting the seeing
    mirrors = [
      {x: 200, y: 100, angle: 0, opacity: 120},
      {x: 200, y: 500, angle: p.PI, opacity: 120},
      {x: 50, y: 300, angle: p.PI/2, opacity: 120},
      {x: 350, y: 300, angle: -p.PI/2, opacity: 120}
    ];

    // Hands reaching toward center
    hands = [
      {x: 150, y: 200, targetX: 200, targetY: 250},
      {x: 250, y: 200, targetX: 200, targetY: 250},
      {x: 150, y: 400, targetX: 200, targetY: 350},
      {x: 250, y: 400, targetX: 200, targetY: 350}
    ];

    // Shadows that reveal and conceal
    shadows = [];
    for(let i = 0; i < 8; i++) {
      shadows.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        size: p.random(30, 80),
        drift: p.random(-0.5, 0.5),
        alpha: p.random(20, 60)
      });
    }
  };

  p.draw = function() {
    // Blue-tinted background with subtle gradient
    for(let i = 0; i < p.height; i++) {
      let alpha = p.map(i, 0, p.height, 0.2, 0.8);
      p.stroke(60, 90, 140, alpha * 255);
      p.line(0, i, p.width, i);
    }

    // Draw drifting shadows first
    p.noStroke();
    for(let shadow of shadows) {
      shadow.x += shadow.drift;
      if(shadow.x < -50) shadow.x = 450;
      if(shadow.x > 450) shadow.x = -50;

      p.fill(20, 40, 80, shadow.alpha);
      p.ellipse(shadow.x, shadow.y, shadow.size);
    }

    // Draw connecting lines between corners (foundation structure)
    p.stroke(80, 120, 180, 80);
    p.strokeWeight(1);
    // Square formation
    p.line(eyes[0].x, eyes[0].y, eyes[1].x, eyes[1].y);
    p.line(eyes[1].x, eyes[1].y, eyes[3].x, eyes[3].y);
    p.line(eyes[3].x, eyes[3].y, eyes[2].x, eyes[2].y);
    p.line(eyes[2].x, eyes[2].y, eyes[0].x, eyes[0].y);
    // Diagonal connections
    p.stroke(80, 120, 180, 40);
    p.line(eyes[0].x, eyes[0].y, eyes[3].x, eyes[3].y);
    p.line(eyes[1].x, eyes[1].y, eyes[2].x, eyes[2].y);

    // Draw mirrors with reflective quality
    p.strokeWeight(3);
    for(let mirror of mirrors) {
      p.push();
      p.translate(mirror.x, mirror.y);
      p.rotate(mirror.angle + p.sin(p.millis() * 0.001) * 0.1);

      // Mirror surface
      p.fill(140, 180, 220, mirror.opacity);
      p.stroke(100, 140, 190);
      p.rect(-30, -5, 60, 10);

      // Reflection shimmer
      p.fill(180, 210, 255, 60 + p.sin(p.millis() * 0.003 + mirror.x) * 20);
      p.noStroke();
      p.ellipse(0, 0, 20, 8);
      p.pop();
    }

    // Draw hands reaching inward
    p.strokeWeight(2);
    for(let hand of hands) {
      let mouseInfluence = p.dist(p.mouseX, p.mouseY, hand.x, hand.y) < 100 ? 20 : 0;
      let currentX = p.lerp(hand.x, hand.targetX + mouseInfluence, 0.1);
      let currentY = p.lerp(hand.y, hand.targetY, 0.1);

      p.stroke(70, 100, 160);
      p.fill(90, 130, 180, 150);

      // Palm
      p.ellipse(currentX, currentY, 25, 35);

      // Fingers reaching toward center
      for(let i = 0; i < 4; i++) {
        let fingerAngle = p.atan2(200 - currentY, 200 - currentX) + (i - 1.5) * 0.3;
        let fingerX = currentX + p.cos(fingerAngle) * 15;
        let fingerY = currentY + p.sin(fingerAngle) * 15;
        p.ellipse(fingerX, fingerY, 8, 20);
      }
    }

    // Draw eyes in four corners
    for(let eye of eyes) {
      eye.blinkTimer++;
      if(eye.blinkTimer > 120) {
        eye.isOpen = !eye.isOpen;
        eye.blinkTimer = 0;
      }

      // Eye follows mouse when close
      let mouseDistance = p.dist(p.mouseX, p.mouseY, eye.x, eye.y);
      if(mouseDistance < 150) {
        eye.gaze = p.lerp(eye.gaze, p.atan2(p.mouseY - eye.y, p.mouseX - eye.x), 0.1);
      } else {
        eye.gaze = p.lerp(eye.gaze, p.atan2(300 - eye.y, 200 - eye.x), 0.05);
      }

      // Partially obscured face
      p.fill(100, 130, 170, 180);
      p.noStroke();
      p.ellipse(eye.x - 15, eye.y + 10, 60, 40); // Face shadow

      // Eye socket
      p.fill(120, 150, 190);
      p.ellipse(eye.x, eye.y, 30, 20);

      if(eye.isOpen) {
        // Iris
        p.fill(60, 90, 140);
        let irisX = eye.x + p.cos(eye.gaze) * 3;
        let irisY = eye.y + p.sin(eye.gaze) * 2;
        p.ellipse(irisX, irisY, 15, 15);

        // Pupil
        p.fill(20, 40, 80);
        p.ellipse(irisX, irisY, 8, 8);

        // Highlight
        p.fill(200, 220, 255, 180);
        p.ellipse(irisX + 2, irisY - 1, 3, 3);
      } else {
        // Closed eye
        p.stroke(80, 110, 150);
        p.strokeWeight(2);
        p.line(eye.x - 12, eye.y, eye.x + 12, eye.y);
      }

      // Light and shadow interplay
      let lightIntensity = p.map(p.sin(p.millis() * 0.002 + eye.x * 0.01), -1, 1, 50, 150);
      p.fill(160, 190, 230, lightIntensity);
      p.noStroke();
      p.ellipse(eye.x + 10, eye.y - 10, 20, 15);
    }

    // Central convergence point - the moment of recognition
    let centerPulse = p.sin(p.millis() * 0.004) * 10 + 40;
    p.fill(120, 160, 200, 100);
    p.noStroke();
    p.ellipse(200, 300, centerPulse, centerPulse);

    // Subtle particles representing the flow of seeing
    if(p.frameCount % 15 === 0) {
      for(let eye of eyes) {
        let particle = {
          x: eye.x,
          y: eye.y,
          targetX: 200 + p.random(-20, 20),
          targetY: 300 + p.random(-20, 20),
          life: 60,
          maxLife: 60
        };
        shadows.push({
          x: particle.x,
          y: particle.y,
          size: 3,
          drift: (particle.targetX - particle.x) / 60,
          alpha: 80,
          isParticle: true,
          life: particle.life
        });
      }
    }

    // Update and draw particles
    for(let i = shadows.length - 1; i >= 0; i--) {
      if(shadows[i].isParticle) {
        shadows[i].life--;
        shadows[i].alpha = p.map(shadows[i].life, 0, 60, 0, 80);
        if(shadows[i].life <= 0) {
          shadows.splice(i, 1);
        }
      }
    }
  };

  p.mousePressed = function() {
    // Create ripple effect when clicked
    for(let i = 0; i < 12; i++) {
      let angle = (p.TWO_PI / 12) * i;
      shadows.push({
        x: p.mouseX + p.cos(angle) * 20,
        y: p.mouseY + p.sin(angle) * 20,
        size: 5,
        drift: p.cos(angle) * 2,
        alpha: 120,
        isParticle: true,
        life: 30
      });
    }
  };
}

function sketch(p) {
  let eyes = [];
  let fragments = [];
  let time = 0;
  let disruption = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create five eyes in unstable arrangement
    eyes.push({x: 100, y: 150, angle: 0, offset: 0, visible: true});
    eyes.push({x: 300, y: 180, angle: p.PI/4, offset: p.PI/3, visible: true});
    eyes.push({x: 200, y: 280, angle: p.PI/2, offset: p.PI/2, visible: false}); // hidden/disrupted
    eyes.push({x: 80, y: 400, angle: p.PI, offset: p.PI, visible: true});
    eyes.push({x: 320, y: 450, angle: p.PI/6, offset: p.PI*1.5, visible: true});

    // Create mirror fragments
    for(let i = 0; i < 12; i++) {
      fragments.push({
        x: p.random(400),
        y: p.random(600),
        size: p.random(30, 80),
        angle: p.random(p.TWO_PI),
        speed: p.random(0.5, 2),
        opacity: p.random(100, 200)
      });
    }
  };

  p.draw = function() {
    // Blue-tinted background with languid movement
    let bgBlue = p.map(p.sin(time * 0.01), -1, 1, 20, 60);
    p.background(bgBlue, bgBlue + 20, bgBlue + 40);

    time++;
    disruption = p.map(p.sin(time * 0.02), -1, 1, 0, 1);

    // Draw floating mirror fragments
    p.push();
    p.noFill();
    for(let frag of fragments) {
      p.push();
      p.translate(frag.x, frag.y);
      p.rotate(frag.angle + time * 0.005);

      // Languid brush stroke style
      p.strokeWeight(p.random(1, 3));
      p.stroke(150, 180, 220, frag.opacity * disruption);

      p.beginShape();
      for(let i = 0; i < 6; i++) {
        let angle = i * p.PI / 3;
        let r = frag.size + p.sin(time * 0.03 + frag.speed) * 10;
        let x = p.cos(angle) * r;
        let y = p.sin(angle) * r;
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);
      p.pop();

      frag.angle += 0.002;
    }
    p.pop();

    // Draw the five eyes with instability
    for(let i = 0; i < eyes.length; i++) {
      let eye = eyes[i];

      if(!eye.visible && i === 2) continue; // The disrupted eye

      p.push();
      p.translate(eye.x, eye.y);

      // Add instability - eyes drift and shake
      let shake = disruption * 15;
      let offsetX = p.sin(time * 0.04 + eye.offset) * shake;
      let offsetY = p.cos(time * 0.03 + eye.offset) * shake;
      p.translate(offsetX, offsetY);

      p.rotate(eye.angle + p.sin(time * 0.01 + eye.offset) * 0.3);

      // Draw eye with languid strokes
      p.fill(80, 120, 180, 150);
      p.stroke(120, 150, 200, 200);
      p.strokeWeight(2);
      p.ellipse(0, 0, 60, 40);

      // Pupil that follows mouse with resistance
      let mouseInfluence = p.map(p.dist(p.mouseX, p.mouseY, eye.x, eye.y), 0, 200, 1, 0);
      let pupilX = p.lerp(0, (p.mouseX - eye.x) * 0.1, mouseInfluence);
      let pupilY = p.lerp(0, (p.mouseY - eye.y) * 0.1, mouseInfluence);

      p.fill(20, 40, 80);
      p.noStroke();
      p.ellipse(pupilX, pupilY, 20, 20);

      // Highlight
      p.fill(180, 200, 255, 150);
      p.ellipse(pupilX - 5, pupilY - 5, 8, 8);

      p.pop();
    }

    // Draw the disrupted/hidden eye as fragmented glimpses
    let hiddenEye = eyes[2];
    for(let i = 0; i < 5; i++) {
      if(p.random() < 0.3) {
        p.push();
        p.translate(hiddenEye.x + p.random(-30, 30), hiddenEye.y + p.random(-30, 30));
        p.rotate(p.random(p.TWO_PI));

        p.fill(80, 120, 180, p.random(50, 150));
        p.noStroke();
        p.arc(0, 0, 30, 20, p.random(p.TWO_PI), p.random(p.TWO_PI));
        p.pop();
      }
    }

    // Shadows and light that reveal and conceal
    p.push();
    p.fill(0, 0, 50, 100);
    p.noStroke();
    let shadowY = p.map(p.sin(time * 0.015), -1, 1, 100, 500);
    p.ellipse(200, shadowY, 300, 80);
    p.pop();

    // Interactive disruption on mouse press
    if(p.mouseIsPressed) {
      for(let i = 0; i < 3; i++) {
        p.push();
        p.translate(p.mouseX + p.random(-50, 50), p.mouseY + p.random(-50, 50));
        p.rotate(p.random(p.TWO_PI));
        p.stroke(200, 220, 255, 100);
        p.strokeWeight(p.random(1, 4));
        p.noFill();
        p.ellipse(0, 0, p.random(20, 60), p.random(10, 30));
        p.pop();
      }
    }
  };
}

function sketch(p) {
  let eyes = [];
  let reflections = [];
  let time = 0;
  let hexCenter;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    hexCenter = p.createVector(200, 300);

    // Create six eyes in hexagonal arrangement
    for (let i = 0; i < 6; i++) {
      let angle = (i * p.PI) / 3;
      let radius = 80;
      let x = hexCenter.x + p.cos(angle) * radius;
      let y = hexCenter.y + p.sin(angle) * radius;
      eyes.push({
        pos: p.createVector(x, y),
        basePos: p.createVector(x, y),
        pupilOffset: p.createVector(0, 0),
        blinkPhase: p.random(p.TWO_PI),
        opacity: 0.8,
        size: 40 + p.random(20),
        gazeTarget: p.createVector(200, 300)
      });
    }

    // Create reflection points
    for (let i = 0; i < 12; i++) {
      reflections.push({
        pos: p.createVector(p.random(400), p.random(600)),
        life: p.random(1),
        maxLife: p.random(0.5, 1.5),
        size: p.random(5, 15)
      });
    }
  };

  p.draw = function() {
    time += 0.02;

    // Blue-tinted background with subtle gradient
    for (let y = 0; y < p.height; y++) {
      let alpha = p.map(y, 0, p.height, 0.2, 0.8);
      p.stroke(20, 40, 80 + p.sin(time * 0.5) * 20, alpha * 255);
      p.line(0, y, p.width, y);
    }

    p.noStroke();

    // Mouse influence for harmony disruption/restoration
    let mouseDistance = p.dist(p.mouseX, p.mouseY, hexCenter.x, hexCenter.y);
    mouseInfluence = p.map(p.constrain(mouseDistance, 0, 150), 0, 150, 1, 0);

    // Draw connecting lines between eyes (harmony visualization)
    p.stroke(80, 120, 180, 150 * mouseInfluence);
    p.strokeWeight(1);
    for (let i = 0; i < eyes.length; i++) {
      let next = (i + 1) % eyes.length;
      let currentEye = eyes[i];
      let nextEye = eyes[next];

      // Flowing, organic lines
      let midX = (currentEye.pos.x + nextEye.pos.x) / 2;
      let midY = (currentEye.pos.y + nextEye.pos.y) / 2;
      let offset = p.sin(time + i) * 15 * mouseInfluence;

      p.beginShape();
      p.noFill();
      p.vertex(currentEye.pos.x, currentEye.pos.y);
      p.quadraticVertex(midX + offset, midY + offset, nextEye.pos.x, nextEye.pos.y);
      p.endShape();
    }

    // Update and draw reflections
    for (let i = reflections.length - 1; i >= 0; i--) {
      let r = reflections[i];
      r.life += 0.01;

      if (r.life > r.maxLife) {
        reflections[i] = {
          pos: p.createVector(p.random(400), p.random(600)),
          life: 0,
          maxLife: p.random(0.5, 1.5),
          size: p.random(5, 15)
        };
      }

      let alpha = p.sin(r.life * p.PI) * 100;
      p.fill(150, 200, 255, alpha);
      p.ellipse(r.pos.x, r.pos.y, r.size);
    }

    // Draw eyes with dynamic gazing
    for (let i = 0; i < eyes.length; i++) {
      let eye = eyes[i];

      // Subtle position drift for organic feel
      let drift = p.sin(time + i) * 3;
      eye.pos.x = eye.basePos.x + drift;
      eye.pos.y = eye.basePos.y + p.cos(time + i * 0.7) * 2;

      // Calculate gaze direction
      if (p.mouseIsPressed) {
        eye.gazeTarget.x = p.mouseX;
        eye.gazeTarget.y = p.mouseY;
      } else {
        // Look at center with slight variations
        eye.gazeTarget.x = hexCenter.x + p.sin(time + i * 0.5) * 20;
        eye.gazeTarget.y = hexCenter.y + p.cos(time + i * 0.3) * 15;
      }

      let gazeDir = p5.Vector.sub(eye.gazeTarget, eye.pos);
      gazeDir.normalize();
      gazeDir.mult(8);
      eye.pupilOffset = p5.Vector.lerp(eye.pupilOffset, gazeDir, 0.1);

      // Blinking
      let blinkAmount = p.max(0, p.sin(time * 2 + eye.blinkPhase));
      let eyeHeight = eye.size * (0.3 + 0.7 * blinkAmount);

      // Eye white with blue tint
      p.fill(200, 220, 255, eye.opacity * 255);
      p.ellipse(eye.pos.x, eye.pos.y, eye.size, eyeHeight);

      // Iris
      p.fill(60, 100, 160, eye.opacity * 255);
      p.ellipse(
        eye.pos.x + eye.pupilOffset.x * 0.5, 
        eye.pos.y + eye.pupilOffset.y * 0.5, 
        eye.size * 0.6, 
        eyeHeight * 0.6
      );

      // Pupil
      p.fill(20, 30, 50, eye.opacity * 255);
      p.ellipse(
        eye.pos.x + eye.pupilOffset.x, 
        eye.pos.y + eye.pupilOffset.y, 
        eye.size * 0.25, 
        eyeHeight * 0.25
      );

      // Highlight
      p.fill(255, 255, 255, eye.opacity * 180 * blinkAmount);
      p.ellipse(
        eye.pos.x + eye.pupilOffset.x - 3, 
        eye.pos.y + eye.pupilOffset.y - 3, 
        eye.size * 0.1, 
        eyeHeight * 0.1
      );
    }

    // Central harmony indicator - grows with mouse proximity
    let harmonySize = 20 + mouseInfluence * 30;
    p.fill(100, 150, 255, 100 + mouseInfluence * 100);
    p.ellipse(hexCenter.x, hexCenter.y, harmonySize);

    // Subtle shadow effects
    p.fill(0, 0, 0, 30);
    for (let eye of eyes) {
      p.ellipse(eye.pos.x + 2, eye.pos.y + 2, eye.size * 0.8);
    }
  };

  p.mousePressed = function() {
    // Ripple effect on click
    for (let i = 0; i < 6; i++) {
      reflections.push({
        pos: p.createVector(p.mouseX + p.random(-50, 50), p.mouseY + p.random(-50, 50)),
        life: 0,
        maxLife: 1.0,
        size: p.random(10, 25)
      });
    }
  };
}

function sketch(p) {
  let eyes = [];
  let mirrors = [];
  let mouseInfluence = 0;
  let timeOffset = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create seven eye/mirror pairs arranged in assessment pattern
    // Three at top, one central, three at bottom - suggesting choice/evaluation
    for(let i = 0; i < 7; i++) {
      let angle = (i * p.TWO_PI / 7) + p.PI/4;
      let radius = i === 3 ? 80 : 120; // Central eye closer
      let x = p.width/2 + p.cos(angle) * radius;
      let y = p.height/2 + p.sin(angle) * radius * 0.7;

      eyes.push({
        x: x,
        y: y,
        originalX: x,
        originalY: y,
        angle: angle,
        blinkPhase: p.random(p.TWO_PI),
        gazeX: 0,
        gazeY: 0,
        recognition: p.random(0.3, 1.0),
        isCentral: i === 3
      });

      // Corresponding mirror fragments
      mirrors.push({
        x: x + p.random(-30, 30),
        y: y + p.random(-30, 30),
        rotation: p.random(p.TWO_PI),
        size: p.random(15, 25),
        opacity: p.random(0.2, 0.7)
      });
    }
  };

  p.draw = function() {
    // Deep blue gradient background
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 45), p.color(35, 55, 85), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    timeOffset += 0.01;
    mouseInfluence = p.lerp(mouseInfluence, p.dist(p.mouseX, p.mouseY, p.width/2, p.height/2) / 200, 0.1);

    // Draw crossroads/assessment lines - faint paths between eyes
    p.stroke(80, 120, 160, 30);
    p.strokeWeight(1);
    for(let i = 0; i < eyes.length; i++) {
      for(let j = i + 1; j < eyes.length; j++) {
        let eye1 = eyes[i];
        let eye2 = eyes[j];
        let alpha = p.map(p.sin(timeOffset * 2 + i + j), -1, 1, 10, 40);
        p.stroke(120, 150, 190, alpha);

        // Languid, curved connection lines
        let midX = (eye1.x + eye2.x) / 2 + p.sin(timeOffset + i) * 20;
        let midY = (eye1.y + eye2.y) / 2 + p.cos(timeOffset + j) * 15;

        p.noFill();
        p.beginShape();
        p.curveVertex(eye1.x, eye1.y);
        p.curveVertex(eye1.x, eye1.y);
        p.curveVertex(midX, midY);
        p.curveVertex(eye2.x, eye2.y);
        p.curveVertex(eye2.x, eye2.y);
        p.endShape();
      }
    }

    // Draw mirror fragments first (behind eyes)
    for(let i = 0; i < mirrors.length; i++) {
      let mirror = mirrors[i];
      let shimmer = p.sin(timeOffset * 3 + i) * 0.3 + 0.7;

      p.push();
      p.translate(mirror.x, mirror.y);
      p.rotate(mirror.rotation + timeOffset * 0.5);

      // Reflective surface
      p.fill(150, 200, 255, mirror.opacity * shimmer * 255);
      p.stroke(200, 230, 255, 100);
      p.strokeWeight(1);
      p.ellipse(0, 0, mirror.size, mirror.size * 0.6);

      // Reflection gleam
      p.fill(255, 255, 255, shimmer * 100);
      p.noStroke();
      p.ellipse(-mirror.size/4, -mirror.size/4, mirror.size/3, mirror.size/6);
      p.pop();
    }

    // Draw the seven eyes - each partially obscured, in assessment
    for(let i = 0; i < eyes.length; i++) {
      let eye = eyes[i];
      let breathe = p.sin(timeOffset * 2 + eye.blinkPhase) * 5;
      let blink = p.map(p.sin(timeOffset * 0.7 + eye.blinkPhase), -1, 1, 0.8, 1.0);

      // Mouse interaction - eyes track mouse but with hesitation (assessment)
      let targetGazeX = p.map(p.mouseX, 0, p.width, -8, 8) * eye.recognition;
      let targetGazeY = p.map(p.mouseY, 0, p.height, -6, 6) * eye.recognition;
      eye.gazeX = p.lerp(eye.gazeX, targetGazeX, 0.03);
      eye.gazeY = p.lerp(eye.gazeY, targetGazeY, 0.03);

      // Position with subtle drift
      eye.x = eye.originalX + p.sin(timeOffset + i) * 8;
      eye.y = eye.originalY + breathe;

      p.push();
      p.translate(eye.x, eye.y);

      // Eye shadow/obscuring element
      let shadowAlpha = p.map(p.sin(timeOffset * 1.5 + i), -1, 1, 30, 80);
      p.fill(20, 40, 70, shadowAlpha);
      p.noStroke();
      p.ellipse(5, 8, 35, 25);

      // Eye white
      let eyeSize = eye.isCentral ? 32 : 28;
      p.fill(220, 235, 255, 200);
      p.stroke(100, 140, 180, 150);
      p.strokeWeight(1);
      p.ellipse(0, 0, eyeSize, eyeSize * 0.7 * blink);

      // Iris - blue tinted
      p.fill(60, 100, 140, 180);
      p.noStroke();
      let irisSize = eyeSize * 0.6;
      p.ellipse(eye.gazeX, eye.gazeY, irisSize, irisSize * 0.8 * blink);

      // Pupil
      p.fill(10, 20, 40);
      let pupilSize = irisSize * 0.4;
      p.ellipse(eye.gazeX, eye.gazeY, pupilSize, pupilSize * blink);

      // Highlight
      p.fill(200, 220, 255, 150);
      p.ellipse(eye.gazeX - 3, eye.gazeY - 2, pupilSize * 0.3, pupilSize * 0.3);

      // Partial obscuring - the "moment before/after recognition"
      let veilAlpha = p.map(p.sin(timeOffset * 0.8 + i * 0.7), -1, 1, 20, 100);
      p.fill(30, 50, 80, veilAlpha);
      p.noStroke();

      // Languid brush stroke effect - partial concealment
      for(let j = 0; j < 3; j++) {
        let brushX = p.random(-eyeSize/2, eyeSize/2);
        let brushY = p.random(-eyeSize/3, eyeSize/3);
        let brushSize = p.random(8, 20);
        p.ellipse(brushX, brushY, brushSize, brushSize * 0.3);
      }

      p.pop();
    }

    // Central assessment glow - the moment of choice
    let centralGlow = p.map(p.sin(timeOffset * 1.5), -1, 1, 20, 60);
    p.fill(100, 150, 200, centralGlow);
    p.noStroke();
    p.ellipse(p.width/2, p.height/2, 100, 100);

    // Crossroads indicator - subtle plus shape in center
    p.stroke(150, 180, 220, 80);
    p.strokeWeight(2);
    let crossSize = 25 + p.sin(timeOffset * 2) * 5;
    p.line(p.width/2 - crossSize, p.height/2, p.width/2 + crossSize, p.height/2);
    p.line(p.width/2, p.height/2 - crossSize, p.width/2, p.height/2 + crossSize);
  };

  p.mousePressed = function() {
    // Click creates ripple of recognition through the eyes
    for(let i = 0; i < eyes.length; i++) {
      let eye = eyes[i];
      let d = p.dist(p.mouseX, p.mouseY, eye.x, eye.y);
      if(d < 50) {
        eye.recognition = p.random(0.1, 1.0);
        eye.blinkPhase = p.random(p.TWO_PI);

        // Corresponding mirror responds
        mirrors[i].opacity = p.random(0.3, 0.9);
        mirrors[i].rotation = p.random(p.TWO_PI);
      }
    }
  };
}

function sketch(p) {
  let eyes = [];
  let mirrors = [];
  let particles = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create 8 eyes in dynamic spiral arrangement
    for(let i = 0; i < 8; i++) {
      let angle = (i / 8) * p.TWO_PI;
      let radius = 80 + i * 15;
      eyes.push({
        x: 200 + p.cos(angle) * radius,
        y: 300 + p.sin(angle) * radius * 0.7,
        angle: angle,
        radius: radius,
        openness: p.random(0.3, 1),
        blinkTimer: p.random(100, 300),
        originalAngle: angle,
        id: i
      });
    }

    // Create mirror fragments
    for(let i = 0; i < 12; i++) {
      mirrors.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        angle: p.random(p.TWO_PI),
        size: p.random(20, 60),
        opacity: p.random(0.3, 0.8),
        drift: p.random(-0.02, 0.02)
      });
    }

    // Create witness particles
    for(let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        life: p.random(50, 150)
      });
    }
  };

  p.draw = function() {
    // Blue-tinted gradient background
    for(let i = 0; i < p.height; i++) {
      let alpha = p.map(i, 0, p.height, 0.9, 0.3);
      p.stroke(20, 40, 80 + i * 0.1, alpha * 255);
      p.line(0, i, p.width, i);
    }

    time += 0.02;

    // Draw flowing connection lines between eyes
    p.stroke(70, 120, 180, 80);
    p.strokeWeight(2);
    p.noFill();
    p.beginShape();
    for(let i = 0; i < eyes.length; i++) {
      let eye = eyes[i];
      let nextEye = eyes[(i + 1) % eyes.length];
      let midX = (eye.x + nextEye.x) / 2 + p.sin(time + i) * 20;
      let midY = (eye.y + nextEye.y) / 2 + p.cos(time + i) * 15;

      if(i === 0) p.vertex(eye.x, eye.y);
      p.bezierVertex(
        eye.x + p.cos(eye.angle) * 30,
        eye.y + p.sin(eye.angle) * 20,
        midX, midY,
        nextEye.x, nextEye.y
      );
    }
    p.endShape(p.CLOSE);

    // Update and draw mirror fragments
    mirrors.forEach(mirror => {
      mirror.angle += mirror.drift;
      mirror.y += p.sin(time + mirror.x * 0.01) * 0.5;

      p.push();
      p.translate(mirror.x, mirror.y);
      p.rotate(mirror.angle);
      p.fill(150, 180, 220, mirror.opacity * 100);
      p.stroke(200, 220, 255, mirror.opacity * 200);
      p.strokeWeight(1);
      p.rect(-mirror.size/2, -mirror.size/4, mirror.size, mirror.size/2);

      // Reflection gleam
      p.stroke(255, 255, 255, mirror.opacity * 150);
      p.line(-mirror.size/3, -mirror.size/8, mirror.size/3, mirror.size/8);
      p.pop();
    });

    // Update and draw eyes in spiral motion
    eyes.forEach((eye, i) => {
      // Spiral motion
      eye.angle += 0.008;
      eye.x = 200 + p.cos(eye.angle) * eye.radius;
      eye.y = 300 + p.sin(eye.angle) * eye.radius * 0.7;

      // Mouse interaction - eyes look toward mouse when close
      let mouseDistance = p.dist(p.mouseX, p.mouseY, eye.x, eye.y);
      let lookAtMouse = mouseDistance < 100;

      // Blinking animation
      eye.blinkTimer--;
      if(eye.blinkTimer <= 0) {
        eye.openness = p.lerp(eye.openness, 0, 0.3);
        if(eye.openness < 0.1) {
          eye.blinkTimer = p.random(120, 400);
          eye.openness = 1;
        }
      }

      p.push();
      p.translate(eye.x, eye.y);

      // Eye shadow/depth
      p.fill(30, 50, 90, 100);
      p.noStroke();
      p.ellipse(2, 2, 35, 25 * eye.openness);

      // Eye white
      p.fill(220, 230, 255, 200);
      p.stroke(80, 110, 160);
      p.strokeWeight(1);
      p.ellipse(0, 0, 30, 20 * eye.openness);

      if(eye.openness > 0.3) {
        // Iris
        p.fill(60, 100, 160);
        p.noStroke();
        let irisX = lookAtMouse ? p.lerp(0, (p.mouseX - eye.x) * 0.1, 0.3) : p.sin(time + i * 0.5) * 3;
        let irisY = lookAtMouse ? p.lerp(0, (p.mouseY - eye.y) * 0.1, 0.3) : 0;
        p.ellipse(irisX, irisY, 12, 12 * eye.openness);

        // Pupil
        p.fill(20, 30, 60);
        p.ellipse(irisX, irisY, 6, 6 * eye.openness);

        // Eye highlight
        p.fill(255, 255, 255, 180);
        p.ellipse(irisX - 2, irisY - 1, 3, 3 * eye.openness);
      }

      p.pop();
    });

    // Update and draw witness particles
    particles.forEach((particle, index) => {
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life--;

      // Attraction to eyes
      let closestEye = eyes.reduce((closest, eye) => {
        let dist = p.dist(particle.x, particle.y, eye.x, eye.y);
        return dist < closest.dist ? {eye, dist} : closest;
      }, {eye: eyes[0], dist: Infinity});

      if(closestEye.dist < 80) {
        let force = 0.02;
        particle.vx += (closestEye.eye.x - particle.x) * force;
        particle.vy += (closestEye.eye.y - particle.y) * force;
      }

      // Draw particle
      let alpha = p.map(particle.life, 0, 150, 0, 100);
      p.fill(150, 180, 220, alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, 3, 3);

      // Reset particle when it dies
      if(particle.life <= 0) {
        particle.x = p.random(400);
        particle.y = p.random(600);
        particle.vx = p.random(-1, 1);
        particle.vy = p.random(-1, 1);
        particle.life = p.random(50, 150);
      }
    });

    // Draw transformative energy waves
    p.noFill();
    p.stroke(100, 140, 200, 60);
    p.strokeWeight(2);
    for(let wave = 0; wave < 3; wave++) {
      p.beginShape();
      for(let x = 0; x <= p.width; x += 10) {
        let y = 300 + p.sin(x * 0.02 + time * 2 + wave * 2) * (30 + wave * 10);
        p.vertex(x, y);
      }
      p.endShape();
    }
  };

  p.mousePressed = function() {
    // Create ripple effect of recognition
    for(let i = 0; i < 20; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-3, 3),
        vy: p.random(-3, 3),
        life: 100
      });
    }

    // Make nearby eyes blink in recognition
    eyes.forEach(eye => {
      if(p.dist(p.mouseX, p.mouseY, eye.x, eye.y) < 100) {
        eye.blinkTimer = 1;
      }
    });
  };
}

function sketch(p) {
  let eyes = [];
  let mirrors = [];
  let lightBeams = [];
  let shadows = [];
  let mouseInfluence = 0;
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create 9 eyes (symbols of seeing) in a nearly complete arrangement
    for(let i = 0; i < 9; i++) {
      let angle = (i / 9) * p.TWO_PI - p.PI/2;
      let radius = 80 + (i % 2) * 40;
      eyes.push({
        x: 200 + p.cos(angle) * radius,
        y: 300 + p.sin(angle) * radius,
        size: 15 + p.random(10),
        blink: p.random(p.TWO_PI),
        awareness: p.random(0.5, 1),
        lookX: 0,
        lookY: 0
      });
    }

    // Create mirror fragments
    for(let i = 0; i < 5; i++) {
      mirrors.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        w: p.random(30, 80),
        h: p.random(40, 100),
        angle: p.random(p.TWO_PI),
        opacity: p.random(0.3, 0.8)
      });
    }

    // Create light beams
    for(let i = 0; i < 12; i++) {
      lightBeams.push({
        x1: p.random(400),
        y1: p.random(600),
        x2: p.random(400),
        y2: p.random(600),
        intensity: p.random(0.2, 0.6),
        phase: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    time += 0.02;
    mouseInfluence = p.map(p.mouseX, 0, 400, 0, 1);

    // Deep blue gradient background
    for(let y = 0; y < 600; y++) {
      let inter = p.map(y, 0, 600, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 60), p.color(45, 65, 120), inter);
      p.stroke(c);
      p.line(0, y, 400, y);
    }

    // Draw light beams with languid movement
    p.strokeWeight(1);
    for(let beam of lightBeams) {
      let intensity = beam.intensity * (0.5 + 0.5 * p.sin(time + beam.phase));
      p.stroke(180, 200, 255, intensity * 100);

      let x1 = beam.x1 + 20 * p.sin(time * 0.5 + beam.phase);
      let y1 = beam.y1 + 15 * p.cos(time * 0.3 + beam.phase);
      let x2 = beam.x2 + 25 * p.cos(time * 0.4 + beam.phase);
      let y2 = beam.y2 + 20 * p.sin(time * 0.6 + beam.phase);

      p.line(x1, y1, x2, y2);
    }

    // Draw mirror fragments with reflective quality
    for(let mirror of mirrors) {
      p.push();
      p.translate(mirror.x, mirror.y);
      p.rotate(mirror.angle + time * 0.1);

      // Mirror surface with blue tint
      p.fill(120, 150, 200, mirror.opacity * 150);
      p.stroke(200, 220, 255, 100);
      p.strokeWeight(2);
      p.rect(-mirror.w/2, -mirror.h/2, mirror.w, mirror.h);

      // Reflection highlight
      p.fill(255, 255, 255, 60);
      p.noStroke();
      p.ellipse(-mirror.w/4, -mirror.h/4, mirror.w/3, mirror.h/6);
      p.pop();
    }

    // Draw the nine eyes in languid, expressive style
    for(let i = 0; i < eyes.length; i++) {
      let eye = eyes[i];

      // Update eye movement based on mouse and time
      let targetX = p.lerp(0, (p.mouseX - eye.x) * 0.1, mouseInfluence);
      let targetY = p.lerp(0, (p.mouseY - eye.y) * 0.1, mouseInfluence);
      eye.lookX = p.lerp(eye.lookX, targetX, 0.05);
      eye.lookY = p.lerp(eye.lookY, targetY, 0.05);

      // Blink animation
      eye.blink += 0.03;
      let blinkAmount = p.max(0, p.sin(eye.blink + i)) * 0.3;

      p.push();
      p.translate(eye.x, eye.y);

      // Eye socket shadow
      p.fill(20, 30, 70, 100);
      p.noStroke();
      p.ellipse(2, 2, eye.size * 1.4, eye.size * 1.2);

      // Eye white with blue tint
      p.fill(220, 230, 255, eye.awareness * 200);
      p.stroke(100, 120, 180, 150);
      p.strokeWeight(1);
      p.ellipse(0, 0, eye.size, eye.size * (1 - blinkAmount));

      if(blinkAmount < 0.8) {
        // Iris with depth
        p.fill(60, 80, 140, eye.awareness * 255);
        p.noStroke();
        let irisSize = eye.size * 0.6;
        p.ellipse(eye.lookX, eye.lookY, irisSize, irisSize * (1 - blinkAmount));

        // Pupil
        p.fill(10, 15, 30);
        let pupilSize = eye.size * 0.25;
        p.ellipse(eye.lookX, eye.lookY, pupilSize, pupilSize * (1 - blinkAmount));

        // Highlight
        p.fill(255, 255, 255, 180);
        p.ellipse(eye.lookX - pupilSize * 0.3, eye.lookY - pupilSize * 0.3, 
                 pupilSize * 0.4, pupilSize * 0.4);
      }

      p.pop();
    }

    // Draw partial face silhouettes emerging from shadows
    p.fill(80, 100, 160, 80);
    p.noStroke();

    // Left face fragment
    p.beginShape();
    p.vertex(50, 200);
    p.bezierVertex(80, 180, 120, 190, 140, 220);
    p.bezierVertex(135, 250, 130, 280, 120, 310);
    p.bezierVertex(100, 340, 70, 350, 40, 330);
    p.bezierVertex(30, 300, 35, 250, 50, 200);
    p.endShape(p.CLOSE);

    // Right face fragment
    p.beginShape();
    p.vertex(350, 180);
    p.bezierVertex(320, 160, 280, 170, 260, 200);
    p.bezierVertex(265, 230, 270, 260, 280, 290);
    p.bezierVertex(300, 320, 330, 330, 360, 310);
    p.bezierVertex(370, 280, 365, 230, 350, 180);
    p.endShape(p.CLOSE);

    // Hands reaching toward recognition
    p.strokeWeight(3);
    p.stroke(120, 140, 200, 120);
    p.fill(100, 120, 180, 60);

    // Left hand
    let leftHandX = 100 + 10 * p.sin(time * 0.5);
    let leftHandY = 450 + 5 * p.cos(time * 0.7);
    p.ellipse(leftHandX, leftHandY, 40, 60);

    // Right hand
    let rightHandX = 300 + 8 * p.sin(time * 0.6);
    let rightHandY = 440 + 6 * p.cos(time * 0.8);
    p.ellipse(rightHandX, rightHandY, 35, 55);

    // Connecting recognition energy between hands
    p.stroke(150, 170, 255, 100);
    p.strokeWeight(2);
    p.line(leftHandX, leftHandY, rightHandX, rightHandY);

    // Particles of almost-complete seeing
    for(let i = 0; i < 15; i++) {
      let x = 200 + 100 * p.cos(time + i * 0.4);
      let y = 300 + 60 * p.sin(time * 0.8 + i * 0.3);
      let size = 3 + 2 * p.sin(time * 2 + i);

      p.fill(180, 200, 255, 150);
      p.noStroke();
      p.ellipse(x, y, size, size);
    }
  };

  p.mousePressed = function() {
    // Intensify awareness on click
    for(let eye of eyes) {
      eye.awareness = p.min(1, eye.awareness + 0.2);
      eye.blink = 0; // Reset blink
    }
  };
}

function sketch(p) {
  let eyes = [];
  let reflections = [];
  let particles = [];
  let breathPhase = 0;
  let recognitionMoment = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Create ten eyes arranged in sacred geometry
    for (let i = 0; i < 10; i++) {
      let angle = (i / 10) * p.TWO_PI;
      let radius = 120 + p.sin(i * 0.7) * 40;
      let x = 200 + p.cos(angle) * radius;
      let y = 300 + p.sin(angle) * radius;

      eyes.push({
        x: x,
        y: y,
        originalX: x,
        originalY: y,
        size: p.random(20, 40),
        blinkPhase: p.random(p.TWO_PI),
        gazeAngle: angle,
        awareness: p.random(0.5, 1.0)
      });
    }

    // Create reflection points
    for (let i = 0; i < 20; i++) {
      reflections.push({
        x: p.random(p.width),
        y: p.random(p.height),
        opacity: p.random(10, 30),
        phase: p.random(p.TWO_PI),
        speed: p.random(0.01, 0.03)
      });
    }

    // Create witness particles
    for (let i = 0; i < 50; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.5, 0.5),
        life: p.random(50, 100),
        maxLife: 100
      });
    }
  };

  p.draw = function() {
    // Blue-tinted gradient background
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(220, 40, 15), // deep blue
        p.color(240, 60, 30), // lighter blue
        inter
      );
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    breathPhase += 0.02;
    recognitionMoment = p.sin(breathPhase * 0.3) * 0.5 + 0.5;
    mouseInfluence = p.dist(p.mouseX, p.mouseY, 200, 300) / 300;

    // Draw shadowy reflections first
    p.push();
    p.blendMode(p.OVERLAY);
    for (let reflection of reflections) {
      reflection.phase += reflection.speed;
      let alpha = reflection.opacity * p.sin(reflection.phase) * recognitionMoment;
      p.fill(200, 30, 80, p.abs(alpha));
      p.noStroke();
      let size = 30 + p.sin(reflection.phase) * 10;
      p.ellipse(reflection.x, reflection.y, size, size);
    }
    p.pop();

    // Draw witness particles
    p.blendMode(p.ADD);
    for (let particle of particles) {
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life--;

      if (particle.life <= 0) {
        particle.x = p.random(p.width);
        particle.y = p.random(p.height);
        particle.life = particle.maxLife;
      }

      let alpha = p.map(particle.life, 0, particle.maxLife, 0, 30);
      p.fill(200, 60, 90, alpha * recognitionMoment);
      p.noStroke();
      p.ellipse(particle.x, particle.y, 2, 2);
    }
    p.blendMode(p.BLEND);

    // Draw connecting lines between eyes (moments of recognition)
    p.stroke(210, 50, 70, 20 + recognitionMoment * 30);
    p.strokeWeight(1);
    for (let i = 0; i < eyes.length; i++) {
      for (let j = i + 1; j < eyes.length; j++) {
        let distance = p.dist(eyes[i].x, eyes[i].y, eyes[j].x, eyes[j].y);
        if (distance < 150) {
          let alpha = p.map(distance, 50, 150, 30, 0);
          p.stroke(210, 50, 70, alpha * recognitionMoment);
          p.line(eyes[i].x, eyes[i].y, eyes[j].x, eyes[j].y);
        }
      }
    }

    // Draw the ten eyes of witness
    for (let i = 0; i < eyes.length; i++) {
      let eye = eyes[i];

      // Subtle movement responding to recognition phase
      eye.x = eye.originalX + p.sin(breathPhase + i * 0.3) * 5;
      eye.y = eye.originalY + p.cos(breathPhase + i * 0.5) * 3;

      // Eye socket shadow
      p.fill(220, 60, 20, 40);
      p.noStroke();
      p.ellipse(eye.x, eye.y, eye.size * 1.4, eye.size * 1.2);

      // Outer eye
      p.fill(210, 40, 85, 80);
      p.stroke(200, 70, 60, 60);
      p.strokeWeight(1);
      p.ellipse(eye.x, eye.y, eye.size, eye.size * 0.7);

      // Iris that responds to mouse
      let irisSize = eye.size * 0.6;
      let pupilX = eye.x + (p.mouseX - eye.x) * 0.05;
      let pupilY = eye.y + (p.mouseY - eye.y) * 0.05;

      p.fill(220, 80, 50, 90);
      p.noStroke();
      p.ellipse(pupilX, pupilY, irisSize, irisSize);

      // Pupil
      let pupilSize = irisSize * (0.3 + mouseInfluence * 0.3);
      p.fill(240, 20, 10, 95);
      p.ellipse(pupilX, pupilY, pupilSize, pupilSize);

      // Reflection highlight
      let highlightX = pupilX - irisSize * 0.2;
      let highlightY = pupilY - irisSize * 0.2;
      p.fill(200, 20, 95, 70 + recognitionMoment * 30);
      p.ellipse(highlightX, highlightY, pupilSize * 0.3, pupilSize * 0.3);

      // Blinking
      eye.blinkPhase += 0.03;
      let blinkAmount = p.max(0, p.sin(eye.blinkPhase) * 2 - 1.5);
      if (blinkAmount > 0) {
        p.fill(220, 60, 20, blinkAmount * 100);
        p.noStroke();
        p.ellipse(eye.x, eye.y, eye.size, eye.size * 0.7);
      }
    }

    // Central recognition vortex
    p.push();
    p.translate(200, 300);
    p.rotate(breathPhase);
    p.noFill();
    for (let r = 10; r < 80; r += 10) {
      let alpha = 40 * recognitionMoment * (1 - r / 80);
      p.stroke(210, 70, 80, alpha);
      p.strokeWeight(2);
      p.ellipse(0, 0, r, r);
    }
    p.pop();

    // Overflow effect - additional eyes appearing and fading
    if (recognitionMoment > 0.7) {
      let overflowAlpha = (recognitionMoment - 0.7) * 100;
      for (let i = 0; i < 5; i++) {
        let angle = breathPhase * 2 + i * p.TWO_PI / 5;
        let x = 200 + p.cos(angle) * 180;
        let y = 300 + p.sin(angle) * 180;

        p.fill(210, 40, 85, overflowAlpha * 0.5);
        p.noStroke();
        p.ellipse(x, y, 25, 18);

        p.fill(220, 80, 50, overflowAlpha * 0.7);
        p.ellipse(x, y, 15, 15);

        p.fill(240, 20, 10, overflowAlpha);
        p.ellipse(x, y, 8, 8);
      }
    }
  };

  p.mousePressed = function() {
    // Pulse of recognition
    recognitionMoment = 1.0;

    // Add burst of particles
    for (let i = 0; i < 20; i++) {
      particles.push({
        x: p.mouseX,
        y: p.mouseY,
        vx: p.random(-3, 3),
        vy: p.random(-3, 3),
        life: 30,
        maxLife: 30
      });
    }
  };
}

