        rotSpeed: p.random(-0.02, 0.02)
      });
    }

    particleSystem = new ParticleSystem();
  };

  p.draw = function() {
    time += 0.02;

    // Deep blue gradient background
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 45), p.color(35, 55, 85), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Ambient light rays
    p.push();
    p.translate(p.width * 0.8, p.height * 0.2);
    for (let ray of lightRays) {
      ray.angle += ray.speed;
      p.stroke(120, 140, 200, ray.opacity);
      p.strokeWeight(2);
      let endX = p.cos(ray.angle) * ray.length;
      let endY = p.sin(ray.angle) * ray.length;
      p.line(0, 0, endX, endY);
    }
    p.pop();

    // Mirror fragments in background
    for (let fragment of mirrorFragments) {
      fragment.angle += fragment.rotSpeed;
      p.push();
      p.translate(fragment.x, fragment.y);
      p.rotate(fragment.angle);
      p.fill(80, 120, 180, 40);
      p.noStroke();
      p.ellipse(0, 0, fragment.size, fragment.size * 0.6);
      p.pop();
    }

    // Wanderer figure - partially obscured
    let wandererSway = p.sin(time * 0.8) * 8;
    wanderer.x = p.width * 0.3 + wandererSway;

    // Wanderer's shadow
    p.fill(20, 30, 50, 100);
    p.noStroke();
    p.ellipse(wanderer.x, p.height * 0.85, 80, 20);

    // Wanderer's body
    p.fill(60, 80, 120);
    p.noStroke();
    p.ellipse(wanderer.x, wanderer.y, 50, 100);

    // Wanderer's partially visible face
    p.fill(90, 110, 150);
    let faceY = wanderer.y - 60;
    p.ellipse(wanderer.x + 5, faceY, 35, 40);

    // Eye looking toward mirrors with uncertainty
    wanderer.eyeGaze = p.lerp(wanderer.eyeGaze, (p.mouseX - wanderer.x) * 0.01, 0.05);
    p.fill(40, 60, 100);
    p.ellipse(wanderer.x + 8 + wanderer.eyeGaze, faceY - 3, 8, 12);

    // Expressive hand reaching toward something unseen
    let handReach = p.sin(time * 1.2) * 15;
    wanderer.handX = p.width * 0.5 + handReach;
    wanderer.handY = p.height * 0.45 + p.sin(time * 0.9) * 10;

    p.stroke(90, 110, 150);
    p.strokeWeight(8);
    p.line(wanderer.x + 20, wanderer.y - 20, wanderer.handX, wanderer.handY);

    p.fill(90, 110, 150);
    p.noStroke();
    p.ellipse(wanderer.handX, wanderer.handY, 20, 25);

    // Ghostly reflections
    for (let reflection of reflections) {
      reflection.x += reflection.drift;
      if (reflection.x > p.width + 50) reflection.x = -50;
      if (reflection.x < -50) reflection.x = p.width + 50;

      let pulseOpacity = reflection.opacity + p.sin(time * 2 + reflection.y * 0.01) * 20;
      p.fill(100, 140, 200, pulseOpacity);
      p.noStroke();

      // Partial face in reflection
      p.ellipse(reflection.x, reflection.y, reflection.size * 0.6, reflection.size * 0.7);

      // Suggestion of features
      p.fill(70, 110, 180, pulseOpacity * 0.8);
      p.ellipse(reflection.x - 8, reflection.y - 5, 6, 8);
      p.ellipse(reflection.x + 8, reflection.y - 5, 6, 8);
    }

    // Interactive recognition moments
    let mouseDistance = p.dist(p.mouseX, p.mouseY, wanderer.handX, wanderer.handY);
    if (mouseDistance < 80) {
      // Moment of recognition - light emanates
      p.fill(150, 180, 220, 60);
      p.noStroke();
      let recognitionRadius = p.map(mouseDistance, 0, 80, 100, 20);
      p.ellipse(wanderer.handX, wanderer.handY, recognitionRadius, recognitionRadius);

      // Particles of understanding
      particleSystem.addParticle(wanderer.handX, wanderer.handY);
    }

    // Update and draw particles
    particleSystem.update();
    particleSystem.display();

    // Subtle vignette
    for (let i = 0; i < 50; i++) {
      let alpha = p.map(i, 0, 50, 0, 30);
      p.stroke(15, 25, 45, alpha);
      p.strokeWeight(1);
      p.noFill();
      p.rect(i, i, p.width - i * 2, p.height - i * 2);
    }
  };

  class ParticleSystem {
    constructor() {
      this.particles = [];
    }

    addParticle(x, y) {
      if (this.particles.length < 20) {
        this.particles.push(new Particle(x, y));
      }
    }

    update() {
      for (let i = this.particles.length - 1; i >= 0; i--) {
        this.particles[i].update();
        if (this.particles[i].isDead()) {
          this.particles.splice(i, 1);
        }
      }
    }

    display() {
      for (let particle of this.particles) {
        particle.display();
      }
    }
  }

  class Particle {
    constructor(x, y) {
      this.x = x;
      this.y = y;
      this.vx = p.random(-2, 2);
      this.vy = p.random(-3, -1);
      this.life = 255;
      this.decay = p.random(2, 5);
    }

    update() {
      this.x += this.vx;
      this.y += this.vy;
      this.vy += 0.05; // gravity
      this.life -= this.decay;
    }

    display() {
      p.fill(140, 180, 220, this.life);
      p.noStroke();
      p.ellipse(this.x, this.y, 4, 4);
    }

    isDead() {
      return this.life <= 0;
    }
  }

  p.mousePressed = function() {
    // Create ripple of recognition
    for (let i = 0; i < 5; i++) {
      particleSystem.addParticle(p.mouseX + p.random(-20, 20), p.mouseY + p.random(-20, 20));
    }
  };
}

function sketch(p) {
  let figure;
  let eyes = [];
  let reflections = [];
  let shadowParticles = [];
  let lightParticles = [];
  let mouseInfluence = 0;
  let recognitionMoment = 0;
  let handGesture = { x: 0, y: 0, angle: 0 };

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize figure position
    figure = {
      x: p.width * 0.5,
      y: p.height * 0.6,
      eyeOpenness: 0.8
    };

    // Create multiple eyes for observation theme
    for (let i = 0; i < 8; i++) {
      eyes.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        size: p.random(15, 35),
        blink: p.random(1000),
        watching: false,
        alpha: p.random(0.3, 0.8)
      });
    }

    // Create reflection points
    for (let i = 0; i < 12; i++) {
      reflections.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(20, 60),
        phase: p.random(p.TWO_PI),
        speed: p.random(0.01, 0.03)
      });
    }

    // Initialize particles
    for (let i = 0; i < 30; i++) {
      shadowParticles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.5, 0.5),
        size: p.random(3, 12),
        alpha: p.random(0.1, 0.4)
      });

      lightParticles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.3, 0.3),
        vy: p.random(-0.3, 0.3),
        size: p.random(2, 8),
        alpha: p.random(0.2, 0.6),
        pulse: p.random(1000)
      });
    }
  };

  p.draw = function() {
    // Blue-tinted gradient background
    for (let i = 0; i <= p.height; i++) {
      let alpha = p.map(i, 0, p.height, 0.2, 0.8);
      p.stroke(20 + i * 0.1, 40 + i * 0.15, 80 + i * 0.2, alpha * 255);
      p.line(0, i, p.width, i);
    }

    mouseInfluence = p.lerp(mouseInfluence, p.dist(p.mouseX, p.mouseY, figure.x, figure.y) / 200, 0.05);
    recognitionMoment = p.sin(p.millis() * 0.002) * 0.5 + 0.5;

    // Update and draw shadow particles (concealment)
    p.fill(10, 20, 40, 80);
    p.noStroke();
    for (let particle of shadowParticles) {
      particle.x += particle.vx * (1 + mouseInfluence * 0.5);
      particle.y += particle.vy * (1 + mouseInfluence * 0.5);

      if (particle.x < 0 || particle.x > p.width) particle.vx *= -1;
      if (particle.y < 0 || particle.y > p.height) particle.vy *= -1;

      let size = particle.size * (1 + p.sin(p.millis() * 0.003 + particle.x) * 0.3);
      p.fill(10, 20, 40, particle.alpha * 100 * (1 - recognitionMoment * 0.5));
      p.ellipse(particle.x, particle.y, size, size * 1.5);
    }

    // Draw reflections/mirrors
    p.strokeWeight(1);
    for (let reflection of reflections) {
      reflection.phase += reflection.speed;
      let brightness = p.sin(reflection.phase) * 0.5 + 0.5;
      let interactionScale = 1 + (1 - mouseInfluence) * 0.3;

      p.stroke(60 + brightness * 40, 80 + brightness * 60, 120 + brightness * 80, brightness * 100 * recognitionMoment);
      p.noFill();
      p.ellipse(reflection.x, reflection.y, reflection.size * interactionScale, reflection.size * interactionScale * 0.6);

      // Inner reflection shimmer
      p.fill(80 + brightness * 60, 100 + brightness * 80, 160 + brightness * 100, brightness * 60 * recognitionMoment);
      p.noStroke();
      p.ellipse(reflection.x + p.sin(reflection.phase * 2) * 5, reflection.y + p.cos(reflection.phase * 2) * 3, 
                reflection.size * 0.3 * interactionScale, reflection.size * 0.2 * interactionScale);
    }

    // Draw observing eyes
    for (let eye of eyes) {
      let distToMouse = p.dist(p.mouseX, p.mouseY, eye.x, eye.y);
      eye.watching = distToMouse < 100;

      // Eye socket shadow
      p.fill(15, 25, 45, eye.alpha * 150);
      p.noStroke();
      p.ellipse(eye.x, eye.y, eye.size * 1.4, eye.size * 0.8);

      // Eye base
      let eyeOpenness = p.sin(p.millis() * 0.005 + eye.blink) * 0.3 + 0.7;
      if (eye.watching) eyeOpenness = p.lerp(eyeOpenness, 1.0, 0.1);

      p.fill(220, 230, 240, eye.alpha * 200);
      p.ellipse(eye.x, eye.y, eye.size, eye.size * eyeOpenness);

      // Iris - looks toward mouse when watching
      let irisX = eye.x;
      let irisY = eye.y;
      if (eye.watching) {
        let angle = p.atan2(p.mouseY - eye.y, p.mouseX - eye.x);
        irisX += p.cos(angle) * eye.size * 0.15;
        irisY += p.sin(angle) * eye.size * 0.15;
      }

      p.fill(40, 60, 120, eye.alpha * 180);
      p.ellipse(irisX, irisY, eye.size * 0.6, eye.size * 0.6 * eyeOpenness);

      // Pupil
      p.fill(10, 15, 30, eye.alpha * 220);
      p.ellipse(irisX, irisY, eye.size * 0.25, eye.size * 0.25 * eyeOpenness);

      // Highlight
      p.fill(180, 200, 240, eye.alpha * 160 * recognitionMoment);
      p.ellipse(irisX - eye.size * 0.08, irisY - eye.size * 0.08, eye.size * 0.12, eye.size * 0.12);
    }

    // Central figure - partially obscured face
    p.push();
    p.translate(figure.x, figure.y);

    // Figure shadow/silhouette
    p.fill(20, 30, 60, 120 * (1 - recognitionMoment * 0.3));
    p.noStroke();
    p.ellipse(0, 0, 120, 160); // Head
    p.ellipse(0, 80, 100, 120); // Body

    // Partial face visibility - fragments
    let faceAlpha = recognitionMoment * 180 + 50;
    p.fill(150, 160, 180, faceAlpha);

    // Face fragments appearing/disappearing
    if (recognitionMoment > 0.3) {
      p.ellipse(-20, -20, 15, 25); // Left eye area
      p.ellipse(20, -20, 15, 25);  // Right eye area
    }
    if (recognitionMoment > 0.6) {
      p.ellipse(0, 10, 20, 15); // Nose/mouth area
    }

    // Central observing eyes
    figure.eyeOpenness = p.lerp(figure.eyeOpenness, 0.3 + recognitionMoment * 0.7, 0.03);

    // Left eye
    p.fill(40, 60, 120, faceAlpha);
    p.ellipse(-20, -20, 18, 18 * figure.eyeOpenness);
    p.fill(10, 15, 30, faceAlpha * 1.2);
    p.ellipse(-20, -20, 8, 8 * figure.eyeOpenness);

    // Right eye  
    p.fill(40, 60, 120, faceAlpha);
    p.ellipse(20, -20, 18, 18 * figure.eyeOpenness);
    p.fill(10, 15, 30, faceAlpha * 1.2);
    p.ellipse(20, -20, 8, 8 * figure.eyeOpenness);

    p.pop();

    // Expressive hand gesture
    handGesture.angle += 0.02;
    handGesture.x = figure.x + p.sin(handGesture.angle) * 60;
    handGesture.y = figure.y + 60 + p.cos(handGesture.angle * 1.3) * 20;

    p.strokeWeight(8);
    p.stroke(80, 100, 140, 160 * recognitionMoment);
    p.fill(120, 140, 180, 140 * recognitionMoment);

    // Hand reaching/gesturing
    p.push();
    p.translate(handGesture.x, handGesture.y);
    p.rotate(handGesture.angle * 0.5);

    // Palm
    p.ellipse(0, 0, 25, 35);

    // Fingers
    for (let i = 0; i < 5; i++) {
      let fingerAngle = p.map(i, 0, 4, -0.5, 0.5);
      let fingerLength = 20 + i * 2;
      p.strokeWeight(4);
      p.line(0, 0, p.sin(fingerAngle) * fingerLength, -p.cos(fingerAngle) * fingerLength);
    }

    p.pop();

    // Light particles (revelation)
    for (let particle of lightParticles) {
      particle.x += particle.vx * (2 - mouseInfluence);
      particle.y += particle.vy * (2 - mouseInfluence);

      if (particle.x < 0 || particle.x > p.width) particle.vx *= -1;
      if (particle.y < 0 || particle.y > p.height) particle.vy *= -1;

      let pulse = p.sin(p.millis() * 0.004 + particle.pulse) * 0.5 + 0.5;
      let size = particle.size * (1 + pulse * 0.5);

      p.fill(120 + pulse * 60, 140 + pulse * 80, 200 + pulse * 55, particle.alpha * 120 * recognitionMoment);
      p.noStroke();
      p.ellipse(particle.x, particle.y, size, size);
    }

    // Recognition connection lines
    if (recognitionMoment > 0.5) {
      p.strokeWeight(1);
      p.stroke(100, 120, 180, (recognitionMoment - 0.5) * 200);

      for (let i = 0; i < eyes.length; i++) {
        if (eyes[i].watching) {
          p.line(eyes[i].x, eyes[i].y, figure.x, figure.y - 20);
        }
      }
    }
  };

  p.mousePressed = function() {
    // Trigger recognition moment
    recognitionMoment = 1.0;

    // Add burst of light particles at mouse position
    for (let i = 0; i < 10; i++) {
      lightParticles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-2, 2),
        vy: p.random(-2, 2),
        size: p.random(3, 12),
        alpha: p.random(0.4, 0.8),
        pulse: p.random(1000)
      });
    }
  };
}

function sketch(p) {
  let figure;
  let mirrors = [];
  let particles = [];
  let eyeGlow = 0;
  let handY = 0;
  let shadowOpacity = 0;
  let recognitionMoment = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    figure = {
      x: 200,
      y: 300,
      faceVisible: 0.3
    };

    for (let i = 0; i < 3; i++) {
      mirrors.push({
        x: 80 + i * 120,
        y: 150 + i * 40,
        angle: i * 0.3,
        reflection: 0,
        size: 60 + i * 20
      });
    }

    for (let i = 0; i < 50; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.5, 0.5),
        opacity: p.random(0.1, 0.3),
        size: p.random(1, 3)
      });
    }
  };

  p.draw = function() {
    p.background(15, 25, 45);

    let mouseInfluence = p.dist(p.mouseX, p.mouseY, 200, 300) / 300;
    eyeGlow = p.lerp(eyeGlow, 1 - mouseInfluence, 0.05);
    handY = p.sin(p.millis() * 0.001) * 10;
    shadowOpacity = p.map(p.mouseY, 0, 600, 0.8, 0.1);
    recognitionMoment = p.map(p.mouseX, 0, 400, 0, 1);

    // Background particles - floating awareness
    for (let particle of particles) {
      particle.x += particle.vx;
      particle.y += particle.vy;

      if (particle.x < 0 || particle.x > 400) particle.vx *= -1;
      if (particle.y < 0 || particle.y > 600) particle.vy *= -1;

      p.fill(120, 150, 200, particle.opacity * 255);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);
    }

    // Shadows and light interplay
    p.push();
    p.translate(figure.x, figure.y);

    // Shadow figure
    p.fill(20, 30, 60, shadowOpacity * 100);
    p.noStroke();
    p.ellipse(-30, 50, 80, 120);
    p.ellipse(-20, -20, 60, 80);

    // Light emanating from hands
    let lightIntensity = eyeGlow * 150;
    for (let i = 0; i < 5; i++) {
      p.fill(150, 180, 220, lightIntensity - i * 20);
      p.ellipse(0, 30 + handY, 40 + i * 10, 40 + i * 10);
    }
    p.pop();

    // Mirrors reflecting different aspects
    for (let mirror of mirrors) {
      p.push();
      p.translate(mirror.x, mirror.y);
      p.rotate(mirror.angle + recognitionMoment * 0.2);

      // Mirror frame
      p.stroke(100, 130, 170);
      p.strokeWeight(3);
      p.fill(30, 50, 80, 150);
      p.ellipse(0, 0, mirror.size);

      // Reflection content
      let reflectionClear = p.map(p.dist(p.mouseX, p.mouseY, mirror.x, mirror.y), 0, 200, 1, 0);
      p.fill(80, 120, 160, reflectionClear * 100);
      p.noStroke();

      // Partial face reflection
      if (reflectionClear > 0.3) {
        p.ellipse(-5, -8, 15, 20); // eye
        p.fill(120, 150, 200, reflectionClear * 80);
        p.ellipse(-5, 0, 8, 4); // mouth suggestion
      }

      p.pop();
    }

    // Main figure - the Keeper
    p.push();
    p.translate(figure.x, figure.y);

    // Body suggestion
    p.fill(40, 70, 110, 180);
    p.noStroke();
    p.ellipse(0, 40, 60, 100);

    // Arms reaching to tend/protect
    p.stroke(60, 90, 130);
    p.strokeWeight(8);
    p.line(-20, 20, -40, 30 + handY);
    p.line(20, 20, 40, 30 + handY);

    // Hands in gesture of holding/protecting
    p.fill(80, 110, 150);
    p.noStroke();
    p.ellipse(-40, 30 + handY, 12, 16);
    p.ellipse(40, 30 + handY, 12, 16);

    // Face partially obscured
    p.fill(60, 90, 130, figure.faceVisible * 255);
    p.ellipse(0, -20, 40, 50);

    // Eyes that respond to mouse - the act of seeing
    if (eyeGlow > 0.4) {
      p.fill(150, 200, 255, eyeGlow * 200);
      p.ellipse(-8, -25, 6, 8);
      p.ellipse(8, -25, 6, 8);

      // Gaze following mouse
      let gazeX = p.map(p.mouseX, 0, 400, -2, 2);
      let gazeY = p.map(p.mouseY, 0, 600, -2, 2);
      p.fill(200, 220, 255);
      p.ellipse(-8 + gazeX, -25 + gazeY, 2, 3);
      p.ellipse(8 + gazeX, -25 + gazeY, 2, 3);
    }

    p.pop();

    // Central symbol being tended - an eye/lens of recognition
    p.push();
    p.translate(200, 400);
    p.rotate(p.sin(p.millis() * 0.0005) * 0.1);

    // Outer ring - the frame of seeing
    p.stroke(100, 140, 180);
    p.strokeWeight(4);
    p.noFill();
    p.ellipse(0, 0, 80, 80);

    // Inner lens - clarity of recognition
    p.fill(120, 160, 200, recognitionMoment * 100);
    p.noStroke();
    p.ellipse(0, 0, 50, 50);

    // Pupil - the depth of seeing
    p.fill(20, 40, 80);
    p.ellipse(0, 0, 20, 20);

    // Light rays extending when mouse approaches
    let proximity = p.map(p.dist(p.mouseX, p.mouseY, 200, 400), 0, 100, 1, 0);
    if (proximity > 0) {
      p.stroke(150, 190, 230, proximity * 100);
      p.strokeWeight(2);
      for (let i = 0; i < 8; i++) {
        let angle = i * p.PI / 4;
        p.line(0, 0, p.cos(angle) * 60 * proximity, p.sin(angle) * 60 * proximity);
      }
    }

    p.pop();

    // Protective energy field around the symbol
    p.stroke(80, 120, 160, 30);
    p.strokeWeight(1);
    p.noFill();
    for (let i = 0; i < 3; i++) {
      let pulse = p.sin(p.millis() * 0.001 + i) * 10;
      p.ellipse(200, 400, 120 + i * 20 + pulse, 120 + i * 20 + pulse);
    }

    // Light patterns revealing and concealing
    p.push();
    p.blendMode(p.SCREEN);
    p.fill(100, 140, 180, 30);
    p.noStroke();
    let waveOffset = p.millis() * 0.002;
    for (let y = 0; y < 600; y += 20) {
      let wave = p.sin(y * 0.01 + waveOffset) * 30;
      p.rect(0, y, 400, 10 + wave);
    }
    p.pop();
  };

  p.mousePressed = function() {
    // Moment of recognition - brief illumination
    for (let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-2, 2),
        vy: p.random(-2, 2),
        opacity: 0.8,
        size: p.random(2, 6)
      });
    }

    // Remove excess particles
    if (particles.length > 80) {
      particles.splice(0, particles.length - 80);
    }
  };
}

