        y: p.random(p.height),
        size: p.random(2, 8),
        speed: p.random(0.3, 1.2),
        opacity: p.random(0.2, 0.6),
        direction: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    time += 0.01;
    restPulse = p.sin(time * 2) * 0.1;

    // Deep blue gradient background
    for(let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(20, 30, 80), p.color(40, 60, 120), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Draw floating recognition particles
    p.noStroke();
    for(let particle of particles) {
      particle.x += p.cos(particle.direction) * particle.speed;
      particle.y += p.sin(particle.direction) * particle.speed;

      if(particle.x < 0) particle.x = p.width;
      if(particle.x > p.width) particle.x = 0;
      if(particle.y < 0) particle.y = p.height;
      if(particle.y > p.height) particle.y = 0;

      let pulse = p.sin(time * 3 + particle.x * 0.01) * 0.3 + 0.7;
      p.fill(150, 180, 255, particle.opacity * pulse * 255);
      p.ellipse(particle.x, particle.y, particle.size * pulse);
    }

    // Draw mirrors with reflections
    for(let mirror of mirrors) {
      mirror.angle += mirror.rotSpeed;
      mirror.y += p.sin(time * 1.5 + mirror.floatOffset) * 0.5;

      p.push();
      p.translate(mirror.x, mirror.y);
      p.rotate(mirror.angle);

      // Mirror surface
      p.fill(180, 200, 255, mirror.opacity * 100);
      p.stroke(200, 220, 255, mirror.opacity * 200);
      p.strokeWeight(2);
      p.ellipse(0, 0, mirror.size, mirror.size * 0.6);

      // Reflection shimmer
      p.fill(220, 240, 255, mirror.opacity * 150);
      p.noStroke();
      p.ellipse(mirror.size * -0.2, mirror.size * -0.2, mirror.size * 0.3);
      p.pop();
    }

    // Draw the dwelling figure at rest
    p.push();
    p.translate(figure.x, figure.y + restPulse * 10);

    // Shadow beneath figure
    p.fill(10, 20, 40, 100);
    p.noStroke();
    p.ellipse(0, 60, 120, 30);

    // Body in peaceful sitting position
    p.fill(80, 100, 160, 200);
    p.stroke(120, 140, 200);
    p.strokeWeight(2);
    p.ellipse(0, 20, 60, 80); // torso

    // Arms in gentle, open gesture
    p.strokeWeight(8);
    p.strokeCap(p.ROUND);
    p.stroke(100, 120, 180, 150);
    p.line(-25, 10, -45, 35); // left arm
    p.line(25, 10, 45, 35); // right arm

    // Hands in expressive, welcoming gesture
    p.fill(120, 140, 200, 180);
    p.noStroke();
    p.ellipse(-45, 35, 12, 16);
    p.ellipse(45, 35, 12, 16);

    // Head partially visible/obscured by gentle shadows
    p.fill(100, 120, 180, 160);
    p.stroke(140, 160, 220, 100);
    p.strokeWeight(1);
    p.ellipse(0, -20, 50, 55);

    // Eyes - responsive to mouse position for "seeing" interaction
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, figure.x, figure.y - 20) / 200;
    eyeOpenness = p.lerp(0.3, 1.0, 1 - p.constrain(mouseInfluence, 0, 1));

    // Eye shadows and light
    p.fill(60, 80, 140, 100);
    p.noStroke();
    p.ellipse(-8, -25, 8, 12 * eyeOpenness);
    p.ellipse(8, -25, 8, 12 * eyeOpenness);

    // Eyes meeting or avoiding based on mouse
    if(mouseInfluence < 0.5) {
      p.fill(180, 200, 255, 200);
      p.ellipse(-8, -25, 4, 6 * eyeOpenness);
      p.ellipse(8, -25, 4, 6 * eyeOpenness);
    }

    p.pop();

    // Suit symbol integration - eyes of recognition floating around figure
    let numEyes = 8;
    for(let i = 0; i < numEyes; i++) {
      let angle = (i / numEyes) * p.TWO_PI + time * 0.5;
      let radius = 100 + p.sin(time * 2 + i) * 20;
      let eyeX = figure.x + p.cos(angle) * radius;
      let eyeY = figure.y + p.sin(angle) * radius * 0.6;

      // Floating eyes of mutual seeing
      p.push();
      p.translate(eyeX, eyeY);
      p.rotate(angle + p.PI/2);

      let eyeAlpha = p.sin(time * 3 + i * 0.5) * 0.3 + 0.7;
      p.fill(150, 170, 255, eyeAlpha * 120);
      p.stroke(180, 200, 255, eyeAlpha * 150);
      p.strokeWeight(1);
      p.ellipse(0, 0, 20, 12);

      // Eye pupil
      p.fill(60, 80, 140, eyeAlpha * 200);
      p.noStroke();
      p.ellipse(0, 0, 8, 6);

      // Glint of recognition
      p.fill(220, 240, 255, eyeAlpha * 255);
      p.ellipse(-2, -1, 3, 2);

      p.pop();
    }

    // Interactive recognition ripples on click
    if(p.mouseIsPressed) {
      let rippleSize = (p.frameCount % 60) * 8;
      p.noFill();
      p.stroke(200, 220, 255, 255 - (rippleSize / 8) * 4);
      p.strokeWeight(3);
      for(let r = 0; r < rippleSize; r += 40) {
        p.ellipse(p.mouseX, p.mouseY, r);
      }
    }
  };
}

function sketch(p) {
  let particles = [];
  let keySymbol = {};
  let heartGlow = 0;
  let breathe = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Initialize the key symbol (representing finding/home)
    keySymbol = {
      x: p.width / 2,
      y: p.height / 2 + 20,
      rotation: 0,
      scale: 1,
      emergingProgress: 0
    };

    // Create gentle floating particles
    for (let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(2, 6),
        speed: p.random(0.3, 0.8),
        angle: p.random(p.TWO_PI),
        brightness: p.random(60, 90)
      });
    }
  };

  p.draw = function() {
    // Orange sky gradient background
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let skyColor = p.lerpColor(
        p.color(25, 80, 95), // warm orange
        p.color(220, 30, 30), // blue-tinted dusk
        inter
      );
      p.stroke(skyColor);
      p.line(0, y, p.width, y);
    }

    breathe += 0.02;
    heartGlow = p.sin(breathe) * 20 + 50;

    // Mouse interaction creates warmth
    let mouseDist = p.dist(p.mouseX, p.mouseY, p.width/2, p.height/2);
    mouseInfluence = p.map(mouseDist, 0, p.width/2, 1, 0.3);
    mouseInfluence = p.constrain(mouseInfluence, 0.3, 1);

    // Draw floating particles (like dust motes in warm light)
    p.noStroke();
    for (let particle of particles) {
      particle.x += p.cos(particle.angle) * particle.speed * mouseInfluence;
      particle.y += p.sin(particle.angle) * particle.speed * 0.5;
      particle.angle += 0.01;

      // Wrap around edges
      if (particle.x < 0) particle.x = p.width;
      if (particle.x > p.width) particle.x = 0;
      if (particle.y < 0) particle.y = p.height;
      if (particle.y > p.height) particle.y = 0;

      let alpha = p.map(p.sin(p.frameCount * 0.02 + particle.x * 0.01), -1, 1, 20, 60);
      p.fill(45, 40, particle.brightness, alpha);
      p.ellipse(particle.x, particle.y, particle.size);
    }

    // Draw hands emerging from darkness, cupping the key
    p.push();
    p.translate(p.width/2, p.height * 0.7);

    // Left hand
    p.push();
    p.rotate(-0.2);
    p.fill(30, 40, 40, 70);
    p.ellipse(-60, 0, 80, 120);
    p.pop();

    // Right hand
    p.push();
    p.rotate(0.2);
    p.fill(30, 40, 45, 70);
    p.ellipse(60, 0, 80, 120);
    p.pop();

    p.pop();

    // Central warm glow
    let glowSize = 150 + heartGlow * mouseInfluence;
    p.push();
    p.drawingContext.filter = 'blur(20px)';
    p.fill(35, 60, 90, 30);
    p.ellipse(p.width/2, p.height/2, glowSize);
    p.drawingContext.filter = 'blur(10px)';
    p.fill(35, 80, 95, 20);
    p.ellipse(p.width/2, p.height/2, glowSize * 0.7);
    p.drawingContext.filter = 'none';
    p.pop();

    // The Key - symbol of finding/home
    p.push();
    p.translate(keySymbol.x, keySymbol.y);
    p.rotate(p.sin(breathe * 0.5) * 0.1);
    p.scale(1 + p.sin(breathe) * 0.05);

    // Key body
    p.strokeWeight(8);
    p.stroke(45, 70, 95);
    p.fill(45, 80, 100, 80);
    p.rect(-40, -8, 80, 16, 8);

    // Key head (circle)
    p.ellipse(-50, 0, 30);

    // Key teeth
    p.strokeWeight(6);
    p.line(30, -8, 30, -20);
    p.line(30, 8, 30, 20);
    p.line(20, -8, 20, -15);

    // Inner glow of key
    p.noStroke();
    p.fill(50, 60, 100, 40);
    p.ellipse(0, 0, 120, 40);

    p.pop();

    // Gentle light rays emanating from key
    p.strokeWeight(2);
    for (let i = 0; i < 8; i++) {
      let angle = (i / 8) * p.TWO_PI + breathe * 0.3;
      let rayLength = 80 + p.sin(breathe + i) * 20;
      let x1 = p.width/2 + p.cos(angle) * 60;
      let y1 = p.height/2 + p.sin(angle) * 60;
      let x2 = p.width/2 + p.cos(angle) * rayLength;
      let y2 = p.height/2 + p.sin(angle) * rayLength;

      p.stroke(50, 50, 100, 30 * mouseInfluence);
      p.line(x1, y1, x2, y2);
    }

    // Circle of belonging - subtle ring around the scene
    p.noFill();
    p.strokeWeight(3);
    p.stroke(200, 60, 80, 40 * mouseInfluence);
    let ringSize = 200 + p.sin(breathe * 0.7) * 10;
    p.ellipse(p.width/2, p.height/2, ringSize);

    // Smaller inner circle
    p.strokeWeight(2);
    p.stroke(200, 40, 90, 60 * mouseInfluence);
    p.ellipse(p.width/2, p.height/2, ringSize * 0.6);
  };

  p.mousePressed = function() {
    // Create burst of particles when clicked
    for (let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        size: p.random(3, 8),
        speed: p.random(1, 2),
        angle: p.random(p.TWO_PI),
        brightness: p.random(80, 100)
      });
    }

    // Limit particle count
    if (particles.length > 60) {
      particles.splice(0, particles.length - 60);
    }
  };
}

function sketch(p) {
  let figures = [];
  let particles = [];
  let breathPhase = 0;
  let homeGlow = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create two figures facing each other
    figures.push({
      x: 120,
      y: 300,
      angle: 0.3,
      breathOffset: 0,
      armReach: 0
    });

    figures.push({
      x: 280,
      y: 300,
      angle: -0.3,
      breathOffset: p.PI,
      armReach: 0
    });

    // Initialize warmth particles
    for(let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(50, 350),
        y: p.random(400, 550),
        size: p.random(2, 6),
        drift: p.random(-0.5, 0.5),
        bob: p.random(0, p.TWO_PI),
        alpha: p.random(50, 150)
      });
    }
  };

  p.draw = function() {
    // Orange sky gradient to deeper blue
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let skyColor = p.lerpColor(
        p.color(255, 140, 70, 200),
        p.color(60, 90, 140, 255),
        inter
      );
      p.stroke(skyColor);
      p.line(0, y, p.width, y);
    }

    breathPhase += 0.02;
    homeGlow = p.sin(breathPhase * 0.5) * 30 + 50;

    // Draw circle of belonging behind figures
    p.push();
    p.translate(p.width/2, p.height/2 - 50);
    p.fill(255, 200, 100, homeGlow);
    p.noStroke();
    let circleSize = 180 + p.sin(breathPhase) * 20;
    p.ellipse(0, 0, circleSize, circleSize);
    p.pop();

    // Draw hearth particles
    for(let particle of particles) {
      particle.y -= 0.3;
      particle.x += particle.drift;
      particle.bob += 0.05;

      if(particle.y < 0) {
        particle.y = p.height;
        particle.x = p.random(50, 350);
      }

      p.fill(255, 180 + p.sin(particle.bob) * 30, 80, particle.alpha);
      p.noStroke();
      let wobble = p.sin(particle.bob) * 2;
      p.ellipse(particle.x + wobble, particle.y, particle.size);
    }

    // Mouse interaction - figures reach toward each other more when mouse is between them
    let mouseInfluence = 0;
    if(p.mouseX > 120 && p.mouseX < 280 && p.mouseY > 200 && p.mouseY < 400) {
      mouseInfluence = p.map(p.mouseX, 120, 280, 0, 1);
    }

    // Draw figures
    for(let i = 0; i < figures.length; i++) {
      let fig = figures[i];
      let breathing = p.sin(breathPhase + fig.breathOffset) * 3;

      p.push();
      p.translate(fig.x, fig.y + breathing);
      p.rotate(fig.angle);

      // Body
      p.stroke(80, 100, 160);
      p.strokeWeight(12);
      p.fill(120, 140, 200, 150);
      p.ellipse(0, 0, 40, 60);

      // Head - peaceful expression
      p.fill(200, 170, 140);
      p.stroke(160, 130, 110);
      p.strokeWeight(2);
      p.ellipse(0, -35, 25, 30);

      // Eyes - closed in peace
      p.stroke(100, 80, 70);
      p.strokeWeight(2);
      p.line(-6, -38, -2, -38);
      p.line(2, -38, 6, -38);

      // Arms reaching toward each other
      let reachAmount = 20 + mouseInfluence * 15;
      let armDirection = (i === 0) ? 1 : -1;

      p.stroke(200, 170, 140);
      p.strokeWeight(6);
      p.line(0, -5, armDirection * reachAmount, -10);
      p.line(armDirection * reachAmount, -10, armDirection * (reachAmount + 8), -5);

      p.pop();
    }

    // Draw connection between figures when mouse is present
    if(mouseInfluence > 0.3) {
      p.stroke(255, 220, 150, mouseInfluence * 100);
      p.strokeWeight(2);
      let breath1 = p.sin(breathPhase) * 3;
      let breath2 = p.sin(breathPhase + p.PI) * 3;
      p.line(figures[0].x + 15, figures[0].y + breath1 - 10, 
             figures[1].x - 15, figures[1].y + breath2 - 10);
    }

    // Draw ground/home foundation
    p.fill(100, 70, 50, 100);
    p.noStroke();
    p.rect(0, p.height - 80, p.width, 80);

    // Subtle home elements
    p.stroke(180, 150, 120, 150);
    p.strokeWeight(3);
    for(let x = 60; x < p.width - 60; x += 40) {
      let flicker = p.sin(breathPhase + x * 0.1) * 2;
      p.line(x, p.height - 60, x, p.height - 40 + flicker);
    }
  };

  p.mousePressed = function() {
    // Add burst of home particles on click
    for(let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY,
        size: p.random(3, 8),
        drift: p.random(-1, 1),
        bob: p.random(0, p.TWO_PI),
        alpha: p.random(80, 180)
      });
    }
  };
}

function sketch(p) {
  let symbols = [];
  let particles = [];
  let homeGlow = 0;
  let warmthPulse = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create three symbols in triangular arrangement
    symbols.push({
      x: 200, y: 180,
      size: 60,
      rotation: 0,
      targetRotation: 0
    });
    symbols.push({
      x: 140, y: 280,
      size: 50,
      rotation: 0,
      targetRotation: 0
    });
    symbols.push({
      x: 260, y: 280,
      size: 50,
      rotation: 0,
      targetRotation: 0
    });

    // Initialize warmth particles
    for (let i = 0; i < 40; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        size: p.random(2, 6),
        speed: p.random(0.3, 1.2),
        alpha: p.random(20, 80),
        drift: p.random(-0.5, 0.5)
      });
    }
  };

  p.draw = function() {
    // Orange sky gradient with blue tint
    for (let y = 0; y < 600; y++) {
      let inter = p.map(y, 0, 600, 0, 1);
      let c = p.lerpColor(
        p.color(255, 180, 120, 220), // warm orange
        p.color(120, 140, 180, 180), // blue tint
        inter
      );
      p.stroke(c);
      p.line(0, y, 400, y);
    }

    warmthPulse += 0.02;
    homeGlow += 0.015;

    // Hearth warmth background
    let centerX = 200;
    let centerY = 230;
    let glowSize = 180 + p.sin(homeGlow) * 20;

    for (let r = glowSize; r > 0; r -= 15) {
      let alpha = p.map(r, 0, glowSize, 80, 0);
      p.fill(255, 140, 80, alpha);
      p.noStroke();
      p.ellipse(centerX, centerY, r, r);
    }

    // Floating warmth particles
    p.blendMode(p.SCREEN);
    for (let particle of particles) {
      particle.y -= particle.speed;
      particle.x += particle.drift;

      if (particle.y < -10) {
        particle.y = 610;
        particle.x = p.random(400);
      }

      if (particle.x < 0) particle.x = 400;
      if (particle.x > 400) particle.x = 0;

      let distFromCenter = p.dist(particle.x, particle.y, centerX, centerY);
      let nearness = p.map(p.constrain(distFromCenter, 0, 150), 150, 0, 0.3, 1);

      p.fill(255, 200, 120, particle.alpha * nearness);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size, particle.size);
    }
    p.blendMode(p.BLEND);

    // Mouse interaction - symbols lean toward mouse
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, centerX, centerY) < 200;

    // Draw the three symbols - doorways/windows suggesting home
    for (let i = 0; i < symbols.length; i++) {
      let symbol = symbols[i];

      if (mouseInfluence) {
        let angle = p.atan2(p.mouseY - symbol.y, p.mouseX - symbol.x);
        symbol.targetRotation = angle * 0.1;
      } else {
        symbol.targetRotation = 0;
      }

      symbol.rotation = p.lerp(symbol.rotation, symbol.targetRotation, 0.05);

      p.pushMatrix();
      p.translate(symbol.x, symbol.y);
      p.rotate(symbol.rotation);

      // Draw doorway/window symbol
      let pulse = 1 + p.sin(warmthPulse + i * 0.5) * 0.1;
      let size = symbol.size * pulse;

      // Warm glow around symbol
      p.fill(255, 180, 100, 60);
      p.noStroke();
      p.ellipse(0, 0, size * 1.4, size * 1.4);

      // Symbol frame
      p.strokeWeight(3);
      p.stroke(180, 140, 220, 200);
      p.noFill();
      p.rect(-size/2, -size/2, size, size, 8);

      // Inner light
      p.fill(255, 220, 150, 120 + p.sin(warmthPulse + i) * 30);
      p.noStroke();
      p.rect(-size/2 + 6, -size/2 + 6, size - 12, size - 12, 4);

      // Cross pattern suggesting window panes
      p.strokeWeight(2);
      p.stroke(160, 120, 200, 180);
      p.line(0, -size/2 + 6, 0, size/2 - 6);
      p.line(-size/2 + 6, 0, size/2 - 6, 0);

      p.popMatrix();
    }

    // Connecting lines between symbols - bonds of belonging
    p.strokeWeight(2);
    p.stroke(200, 160, 220, 120 + p.sin(homeGlow * 1.5) * 40);

    // Triangle connections
    p.line(symbols[0].x, symbols[0].y, symbols[1].x, symbols[1].y);
    p.line(symbols[1].x, symbols[1].y, symbols[2].x, symbols[2].y);
    p.line(symbols[2].x, symbols[2].y, symbols[0].x, symbols[0].y);

    // Growth emanating from center
    let centerGrowth = 15 + p.sin(warmthPulse * 0.7) * 8;
    p.fill(180, 220, 255, 100);
    p.noStroke();
    p.ellipse(centerX, centerY, centerGrowth, centerGrowth);

    // Gentle domestic touches - small floating elements
    if (p.frameCount % 120 == 0) {
      particles.push({
        x: centerX + p.random(-50, 50),
        y: centerY + 100,
        size: p.random(3, 8),
        speed: p.random(0.5, 1.5),
        alpha: p.random(40, 120),
        drift: p.random(-0.3, 0.3)
      });
    }

    // Remove old particles
    particles = particles.filter(p => p.y > -20);
  };

  p.mousePressed = function() {
    // Create burst of warmth particles on click
    for (let i = 0; i < 15; i++) {
      particles.push({
        x: p.mouseX + p.random(-30, 30),
        y: p.mouseY + p.random(-30, 30),
        size: p.random(4, 10),
        speed: p.random(1, 3),
        alpha: p.random(60, 140),
        drift: p.random(-1, 1)
      });
    }
  };
}

