      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Breathing animation
    breathingOffset += 0.03;
    let breathScale = 1 + p.sin(breathingOffset) * 0.05;

    // Home light - warm central glow
    homeLight.pulsePhase += 0.02;
    let pulseSize = homeLight.radius + p.sin(homeLight.pulsePhase) * 15;

    // Respond to mouse proximity for warmth
    let mouseDistance = p.dist(p.mouseX, p.mouseY, homeLight.x, homeLight.y);
    let warmthFactor = p.map(p.constrain(mouseDistance, 0, 150), 0, 150, 1.5, 0.8);

    p.push();
    p.translate(homeLight.x, homeLight.y);
    p.noFill();
    for(let r = pulseSize * warmthFactor; r > 10; r -= 8) {
      let alpha = p.map(r, 10, pulseSize * warmthFactor, 0.8, 0.1);
      p.stroke(255, 200 + p.sin(breathingOffset) * 30, 150, alpha * 255);
      p.strokeWeight(3);
      p.circle(0, 0, r);
    }
    p.pop();

    // Four Finding symbols - circular emblems suggesting home/belonging
    p.push();
    p.translate(p.width/2, p.height/2);
    p.scale(breathScale);

    for(let i = 0; i < symbols.length; i++) {
      let sym = symbols[i];
      let localX = sym.x - p.width/2;
      let localY = sym.y - p.height/2;

      p.push();
      p.translate(localX, localY);

      // Blue-tinted finding symbol with orange warmth
      let hoverDistance = p.dist(p.mouseX, p.mouseY, sym.x, sym.y);
      let isHovered = hoverDistance < 40;

      // Outer ring - foundation
      p.strokeWeight(4);
      p.stroke(isHovered ? p.color(255, 150, 100) : p.color(100, 150, 200, 180));
      p.noFill();
      p.circle(0, 0, 35);

      // Inner glow
      p.fill(isHovered ? p.color(255, 200, 150, 100) : p.color(120, 180, 220, 80));
      p.noStroke();
      p.circle(0, 0, 25);

      // Central mark - home anchor
      p.fill(isHovered ? p.color(255, 180, 120) : p.color(80, 120, 180));
      p.noStroke();
      p.circle(0, 0, 8);

      // Connecting lines suggesting structure
      if(i < symbols.length - 1) {
        let nextSym = symbols[i + 1];
        let nextLocalX = nextSym.x - p.width/2;
        let nextLocalY = nextSym.y - p.height/2;
        p.stroke(120, 160, 200, 100);
        p.strokeWeight(2);
        p.line(localX, localY, nextLocalX, nextLocalY);
      }

      p.pop();
    }

    // Complete the square
    let firstSym = symbols[0];
    let lastSym = symbols[symbols.length - 1];
    p.stroke(120, 160, 200, 100);
    p.strokeWeight(2);
    p.line(firstSym.x - p.width/2, firstSym.y - p.height/2, 
           lastSym.x - p.width/2, lastSym.y - p.height/2);

    p.pop();

    // Floating warmth particles
    p.noStroke();
    for(let particle of particles) {
      particle.x += particle.vx;
      particle.y += particle.vy;

      // Wrap around
      if(particle.x < 0) particle.x = p.width;
      if(particle.x > p.width) particle.x = 0;
      if(particle.y < 0) particle.y = p.height;
      if(particle.y > p.height) particle.y = 0;

      // Draw particle with languid movement
      let floatOffset = p.sin(p.frameCount * 0.02 + particle.x * 0.01) * 2;
      p.fill(255, 220, 180, particle.alpha * 255);
      p.circle(particle.x, particle.y + floatOffset, particle.size);
    }

    // Gentle corner anchors suggesting boundaries/structure
    let cornerAlpha = 60;
    p.fill(100, 140, 180, cornerAlpha);
    p.noStroke();
    p.triangle(0, 0, 30, 0, 0, 30);
    p.triangle(p.width, 0, p.width - 30, 0, p.width, 30);
    p.triangle(0, p.height, 30, p.height, 0, p.height - 30);
    p.triangle(p.width, p.height, p.width - 30, p.height, p.width, p.height - 30);
  };

  p.mousePressed = function() {
    // Gentle interaction - pulse of home warmth
    homeLight.pulsePhase = 0;

    // Add temporary warmth particles at mouse
    for(let i = 0; i < 8; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-1, 1),
        vy: p.random(-1.5, -0.5),
        size: p.random(3, 12),
        alpha: p.random(0.5, 1.0)
      });
    }
  };
}

function sketch(p) {
  let symbols = [];
  let homeCircles = [];
  let particles = [];
  let time = 0;
  let disruption = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create five symbolic elements representing "finding" - like glowing orbs or hearth flames
    for (let i = 0; i < 5; i++) {
      symbols.push({
        x: 80 + (i % 3) * 120 + p.random(-20, 20),
        y: 200 + Math.floor(i / 3) * 150 + p.random(-30, 30),
        baseX: 80 + (i % 3) * 120,
        baseY: 200 + Math.floor(i / 3) * 150,
        size: p.random(25, 40),
        glow: p.random(0.5, 1),
        wobble: p.random(0.02, 0.05),
        instability: i === 2 ? 2.5 : 1, // middle symbol most unstable
        phase: p.random(p.TWO_PI)
      });
    }

    // Create circles of belonging that will be disrupted
    for (let i = 0; i < 3; i++) {
      homeCircles.push({
        x: 200 + p.cos(i * p.TWO_PI / 3) * 80,
        y: 300 + p.sin(i * p.TWO_PI / 3) * 80,
        radius: 60,
        alpha: 0.3,
        distortion: 0
      });
    }

    // Floating particles for atmosphere
    for (let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.3, 0.1),
        size: p.random(2, 6),
        alpha: p.random(0.3, 0.8)
      });
    }
  };

  p.draw = function() {
    time += 0.01;

    // Mouse influence creates disruption
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, 200, 300) / 200;
    disruption = p.lerp(disruption, 1 - mouseInfluence, 0.05);

    // Gradient sky - orange to deep blue
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(255, 140, 60, 180), // warm orange
        p.color(40, 60, 120, 200),  // blue-tinted night
        inter
      );
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Draw disrupted circles of belonging
    p.noFill();
    for (let circle of homeCircles) {
      circle.distortion = p.sin(time + circle.x * 0.01) * disruption * 15;

      p.strokeWeight(2);
      p.stroke(255, 200, 100, circle.alpha * 255 * (1 - disruption * 0.5));

      p.beginShape();
      for (let a = 0; a < p.TWO_PI + 0.1; a += 0.1) {
        let r = circle.radius + p.sin(a * 3 + time * 2) * circle.distortion;
        let x = circle.x + p.cos(a) * r;
        let y = circle.y + p.sin(a) * r;
        p.vertex(x, y);
      }
      p.endShape();
    }

    // Draw the five symbols with instability
    for (let i = 0; i < symbols.length; i++) {
      let sym = symbols[i];

      // Calculate instable position
      let shake = disruption * sym.instability * 8;
      sym.x = sym.baseX + p.sin(time * sym.wobble + sym.phase) * shake + p.random(-shake/2, shake/2);
      sym.y = sym.baseY + p.cos(time * sym.wobble * 1.3 + sym.phase) * shake + p.random(-shake/2, shake/2);

      // Draw symbol as glowing hearth-like element
      let glowIntensity = sym.glow * (1 + p.sin(time * 2 + i) * 0.3);

      // Outer glow
      for (let r = sym.size; r > 0; r -= 3) {
        let alpha = p.map(r, sym.size, 0, 0, glowIntensity * 100 * (1 - disruption * 0.4));
        p.fill(255, 150 + r, 80, alpha);
        p.noStroke();
        p.ellipse(sym.x, sym.y, r * 2);
      }

      // Core symbol
      p.fill(255, 220, 150, 200);
      p.stroke(255, 180, 100, 150);
      p.strokeWeight(1);
      p.ellipse(sym.x, sym.y, sym.size * 0.6);

      // Inner flame-like detail
      p.fill(255, 240, 200, 180);
      p.noStroke();
      let innerSize = sym.size * 0.3 + p.sin(time * 3 + i) * 3;
      p.ellipse(sym.x, sym.y - 2, innerSize, innerSize * 1.5);
    }

    // Draw connecting lines between symbols (broken/unstable)
    p.stroke(150, 180, 255, 100 * (1 - disruption));
    p.strokeWeight(1);
    for (let i = 0; i < symbols.length - 1; i++) {
      if (p.random() > disruption * 0.7) { // lines break under disruption
        let midX = (symbols[i].x + symbols[i+1].x) / 2;
        let midY = (symbols[i].y + symbols[i+1].y) / 2;
        midX += p.sin(time + i) * disruption * 10;
        midY += p.cos(time + i) * disruption * 10;

        p.line(symbols[i].x, symbols[i].y, midX, midY);
        p.line(midX, midY, symbols[i+1].x, symbols[i+1].y);
      }
    }

    // Floating atmospheric particles
    p.noStroke();
    for (let particle of particles) {
      particle.x += particle.vx;
      particle.y += particle.vy;

      if (particle.x > p.width) particle.x = 0;
      if (particle.x < 0) particle.x = p.width;
      if (particle.y > p.height) particle.y = 0;
      if (particle.y < 0) particle.y = p.height;

      p.fill(200, 220, 255, particle.alpha * 80);
      p.ellipse(particle.x, particle.y, particle.size);
    }

    // Subtle vignette effect
    p.fill(20, 40, 80, 50 + disruption * 30);
    p.noStroke();
    for (let i = 0; i < 50; i++) {
      let alpha = p.map(i, 0, 50, 50, 0);
      p.fill(20, 40, 80, alpha);
      p.rect(0, 0, p.width, i);
      p.rect(0, p.height - i, p.width, i);
      p.rect(0, 0, i, p.height);
      p.rect(p.width - i, 0, i, p.height);
    }
  };

  p.mousePressed = function() {
    // Create ripple of disruption on click
    for (let i = 0; i < symbols.length; i++) {
      let d = p.dist(p.mouseX, p.mouseY, symbols[i].x, symbols[i].y);
      if (d < 100) {
        symbols[i].instability *= 1.5;
        setTimeout(() => {
          symbols[i].instability /= 1.5;
        }, 1000);
      }
    }
  };
}

function sketch(p) {
  let symbols = [];
  let particles = [];
  let time = 0;
  let mouseInfluence = 0;
  let centerX, centerY;
  let orangeBase, blueBase, warmWhite;

  p.setup = function() {
    p.createCanvas(400, 600);
    centerX = p.width / 2;
    centerY = p.height / 2;

    // Color palette
    orangeBase = p.color(255, 140, 60);
    blueBase = p.color(120, 160, 200);
    warmWhite = p.color(255, 250, 240);

    // Create six symbols arranged in harmonious hexagon
    for (let i = 0; i < 6; i++) {
      let angle = (p.TWO_PI / 6) * i;
      let radius = 80;
      symbols.push({
        x: centerX + p.cos(angle) * radius,
        y: centerY + p.sin(angle) * radius + 20,
        baseX: centerX + p.cos(angle) * radius,
        baseY: centerY + p.sin(angle) * radius + 20,
        angle: angle,
        phase: i * 0.5,
        size: 25
      });
    }

    // Create flowing particles for atmosphere
    for (let i = 0; i < 40; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.3, 0.3),
        size: p.random(2, 8),
        alpha: p.random(30, 80)
      });
    }
  };

  p.draw = function() {
    time += 0.02;

    // Calculate mouse influence
    let mouseDistance = p.dist(p.mouseX, p.mouseY, centerX, centerY);
    mouseInfluence = p.map(p.constrain(mouseDistance, 0, 150), 0, 150, 1, 0);

    // Gradient sky background (orange to blue)
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let skyColor = p.lerpColor(orangeBase, blueBase, inter);
      skyColor = p.lerpColor(skyColor, warmWhite, 0.3);
      p.stroke(skyColor);
      p.line(0, y, p.width, y);
    }

    // Draw flowing particles
    p.noStroke();
    for (let particle of particles) {
      particle.x += particle.vx + p.sin(time + particle.y * 0.01) * 0.2;
      particle.y += particle.vy;

      // Wrap around edges
      if (particle.x < 0) particle.x = p.width;
      if (particle.x > p.width) particle.x = 0;
      if (particle.y < 0) particle.y = p.height;
      if (particle.y > p.height) particle.y = 0;

      let particleColor = p.lerpColor(orangeBase, warmWhite, 0.6);
      particleColor = p.color(p.red(particleColor), p.green(particleColor), p.blue(particleColor), particle.alpha);
      p.fill(particleColor);
      p.ellipse(particle.x, particle.y, particle.size);
    }

    // Draw connection lines between symbols (communication/flow)
    p.strokeWeight(1.5);
    let connectionColor = p.lerpColor(blueBase, warmWhite, 0.4);
    connectionColor = p.color(p.red(connectionColor), p.green(connectionColor), p.blue(connectionColor), 100 + mouseInfluence * 100);
    p.stroke(connectionColor);

    for (let i = 0; i < symbols.length; i++) {
      let next = (i + 1) % symbols.length;
      let pulse = p.sin(time * 2 + i) * 0.3 + 0.7;
      p.strokeWeight(1.5 * pulse);
      p.line(symbols[i].x, symbols[i].y, symbols[next].x, symbols[next].y);
    }

    // Draw central harmony circle
    p.noStroke();
    let centralGlow = p.lerpColor(orangeBase, warmWhite, 0.7);
    centralGlow = p.color(p.red(centralGlow), p.green(centralGlow), p.blue(centralGlow), 80);
    p.fill(centralGlow);
    let centralSize = 60 + p.sin(time * 1.5) * 8 + mouseInfluence * 20;
    p.ellipse(centerX, centerY + 20, centralSize);

    // Draw the six symbols (stylized home/belonging symbols)
    for (let i = 0; i < symbols.length; i++) {
      let symbol = symbols[i];

      // Gentle breathing motion
      let breathe = p.sin(time * 1.2 + symbol.phase) * 3;
      symbol.x = symbol.baseX + breathe + p.sin(time + i) * 2;
      symbol.y = symbol.baseY + breathe * 0.5;

      // Mouse interaction - symbols lean toward cursor
      if (mouseInfluence > 0.3) {
        let pullX = (p.mouseX - symbol.x) * 0.1 * mouseInfluence;
        let pullY = (p.mouseY - symbol.y) * 0.1 * mouseInfluence;
        symbol.x += pullX;
        symbol.y += pullY;
      }

      p.push();
      p.translate(symbol.x, symbol.y);

      // Draw stylized house/hearth symbol
      p.noStroke();
      let symbolColor = p.lerpColor(blueBase, warmWhite, 0.8);
      p.fill(symbolColor);

      // Simple house shape representing home/belonging
      p.beginShape();
      p.vertex(-8, 5);
      p.vertex(-8, -2);
      p.vertex(0, -8);
      p.vertex(8, -2);
      p.vertex(8, 5);
      p.endShape(p.CLOSE);

      // Warm glow inside (hearth)
      let hearthGlow = p.lerpColor(orangeBase, warmWhite, 0.3);
      hearthGlow = p.color(p.red(hearthGlow), p.green(hearthGlow), p.blue(hearthGlow), 150);
      p.fill(hearthGlow);
      p.ellipse(0, 0, 8, 8);

      p.pop();
    }

    // Draw flowing energy streams connecting all symbols
    p.noFill();
    for (let i = 0; i < 3; i++) {
      let streamColor = p.lerpColor(orangeBase, blueBase, i * 0.3);
      streamColor = p.color(p.red(streamColor), p.green(streamColor), p.blue(streamColor), 60 + mouseInfluence * 40);
      p.stroke(streamColor);
      p.strokeWeight(0.8);

      p.beginShape();
      p.noFill();
      for (let t = 0; t <= 1; t += 0.05) {
        let angle = t * p.TWO_PI * 2 + time * (1 + i * 0.3);
        let radius = 90 + p.sin(angle * 3 + time) * 15;
        let x = centerX + p.cos(angle) * radius;
        let y = centerY + 20 + p.sin(angle) * radius * 0.6;

        if (t === 0) {
          p.vertex(x, y);
        } else {
          p.vertex(x, y);
        }
      }
      p.endShape();
    }
  };

  p.mousePressed = function() {
    // Create ripple effect on click
    for (let i = 0; i < 8; i++) {
      particles.push({
        x: p.mouseX,
        y: p.mouseY,
        vx: p.cos(i * p.TWO_PI / 8) * 3,
        vy: p.sin(i * p.TWO_PI / 8) * 3,
        size: 6,
        alpha: 120
      });
    }
  };
}

function sketch(p) {
  let symbols = [];
  let homeSymbols = [];
  let mouseInfluence = 0;
  let time = 0;
  let crossroadsCenter;
  let evaluationRadius = 120;

  p.setup = function() {
    p.createCanvas(400, 600);
    crossroadsCenter = p.createVector(200, 300);

    // Create seven symbols arranged for evaluation
    for (let i = 0; i < 7; i++) {
      let angle = (i / 7) * p.TWO_PI - p.PI/2;
      let distance = evaluationRadius + p.random(-20, 20);
      let x = crossroadsCenter.x + p.cos(angle) * distance;
      let y = crossroadsCenter.y + p.sin(angle) * distance;

      symbols.push({
        x: x,
        y: y,
        originalX: x,
        originalY: y,
        size: 25 + p.random(10),
        angle: p.random(p.TWO_PI),
        rotSpeed: p.random(-0.02, 0.02),
        brightness: p.random(0.8, 1.2),
        pulsePhase: p.random(p.TWO_PI),
        evaluated: false,
        evaluationTime: i * 0.3
      });
    }

    // Create gentle home elements in background
    for (let i = 0; i < 15; i++) {
      homeSymbols.push({
        x: p.random(50, 350),
        y: p.random(50, 550),
        size: p.random(3, 8),
        drift: p.random(0.5, 1.5),
        phase: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    time += 0.016;

    // Orange-blue gradient sky suggesting home and assessment
    for (let y = 0; y < 600; y++) {
      let lerpAmount = y / 600;
      let skyColor = p.lerpColor(
        p.color(255, 180, 120, 200), // warm orange
        p.color(120, 150, 200, 150), // blue tint
        lerpAmount
      );
      p.stroke(skyColor);
      p.line(0, y, 400, y);
    }

    // Mouse influence for gentle interaction
    let mousePos = p.createVector(p.mouseX, p.mouseY);
    let distToCenter = p5.Vector.dist(mousePos, crossroadsCenter);
    mouseInfluence = p.map(distToCenter, 0, 200, 1, 0.3);
    mouseInfluence = p.constrain(mouseInfluence, 0, 1);

    // Draw soft home elements in background
    p.push();
    p.noStroke();
    homeSymbols.forEach((home, i) => {
      p.fill(255, 200, 150, 40 + 20 * p.sin(time + home.phase));
      let driftX = home.x + p.sin(time * home.drift + i) * 10;
      let driftY = home.y + p.cos(time * home.drift * 0.7 + i) * 5;
      p.ellipse(driftX, driftY, home.size);
    });
    p.pop();

    // Draw crossroads paths with languid strokes
    p.push();
    p.stroke(180, 160, 120, 100);
    p.strokeWeight(8);
    p.line(100, crossroadsCenter.y, 300, crossroadsCenter.y);
    p.line(crossroadsCenter.x, 150, crossroadsCenter.x, 450);

    // Diagonal assessment paths
    p.strokeWeight(4);
    p.stroke(200, 180, 140, 80);
    p.line(150, 200, 250, 400);
    p.line(250, 200, 150, 400);
    p.pop();

    // Draw central point of assessment
    p.push();
    p.noStroke();
    let centerPulse = 1 + 0.3 * p.sin(time * 2);
    p.fill(255, 200, 100, 150);
    p.ellipse(crossroadsCenter.x, crossroadsCenter.y, 30 * centerPulse);
    p.fill(255, 220, 150, 200);
    p.ellipse(crossroadsCenter.x, crossroadsCenter.y, 15 * centerPulse);
    p.pop();

    // Draw and animate the seven symbols
    symbols.forEach((symbol, i) => {
      // Evaluation animation - symbols pulse and shift as they're considered
      let evalProgress = p.sin(time - symbol.evaluationTime) * 0.5 + 0.5;
      let isBeingEvaluated = p.sin(time * 0.5 + i * 0.8) > 0.3;

      if (isBeingEvaluated && !symbol.evaluated) {
        symbol.evaluated = true;
      }

      // Gentle movement toward or away from center based on mouse
      let targetX = p.lerp(symbol.originalX, crossroadsCenter.x + (symbol.originalX - crossroadsCenter.x) * 0.7, mouseInfluence * 0.3);
      let targetY = p.lerp(symbol.originalY, crossroadsCenter.y + (symbol.originalY - crossroadsCenter.y) * 0.7, mouseInfluence * 0.3);

      symbol.x = p.lerp(symbol.x, targetX, 0.05);
      symbol.y = p.lerp(symbol.y, targetY, 0.05);

      // Rotation and pulsing
      symbol.angle += symbol.rotSpeed;
      let pulse = 1 + 0.2 * p.sin(time * 3 + symbol.pulsePhase);
      let brightness = symbol.brightness * (isBeingEvaluated ? 1.3 : 1.0);

      p.push();
      p.translate(symbol.x, symbol.y);
      p.rotate(symbol.angle);

      // Draw symbol as a gentle house/heart shape suggesting home and finding
      p.noStroke();
      p.fill(255, 180 * brightness, 120 * brightness, 180);

      // House shape with heart-like curves
      p.beginShape();
      p.vertex(0, -symbol.size * pulse);
      p.bezierVertex(-symbol.size * 0.7 * pulse, -symbol.size * 0.8 * pulse, -symbol.size * 0.8 * pulse, 0, 0, symbol.size * 0.3 * pulse);
      p.bezierVertex(symbol.size * 0.8 * pulse, 0, symbol.size * 0.7 * pulse, -symbol.size * 0.8 * pulse, 0, -symbol.size * pulse);
      p.endShape(p.CLOSE);

      // Inner glow
      p.fill(255, 220, 180, 100);
      p.ellipse(0, 0, symbol.size * 0.6 * pulse);

      p.pop();

      // Draw subtle connection lines during evaluation
      if (isBeingEvaluated) {
        p.push();
        p.stroke(255, 200, 150, 60);
        p.strokeWeight(2);
        p.line(symbol.x, symbol.y, crossroadsCenter.x, crossroadsCenter.y);
        p.pop();
      }
    });

    // Draw evaluation waves emanating from center when mouse is near
    if (mouseInfluence > 0.5) {
      p.push();
      p.noFill();
      p.stroke(255, 200, 120, 100 * (mouseInfluence - 0.5) * 2);
      p.strokeWeight(2);
      let waveRadius = (time * 50) % 150;
      p.ellipse(crossroadsCenter.x, crossroadsCenter.y, waveRadius * 2);
      p.ellipse(crossroadsCenter.x, crossroadsCenter.y, (waveRadius - 50) * 2);
      p.pop();
    }

    // Gentle particles suggesting the warmth of assessment and choice
    p.push();
    p.noStroke();
    for (let i = 0; i < 8; i++) {
      let particleX = crossroadsCenter.x + p.sin(time + i) * 80;
      let particleY = crossroadsCenter.y + p.cos(time * 0.7 + i) * 60;
      p.fill(255, 220, 180, 30 + 20 * p.sin(time * 2 + i));
      p.ellipse(particleX, particleY, 4 + 2 * p.sin(time + i * 2));
    }
    p.pop();
  };
}

function sketch(p) {
  let symbols = [];
  let time = 0;
  let hearth;
  let homeLight;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create eight symbols representing finding/home elements
    for (let i = 0; i < 8; i++) {
      symbols.push({
        x: p.width/2,
        y: p.height/2,
        angle: (i * p.TWO_PI) / 8,
        baseAngle: (i * p.TWO_PI) / 8,
        radius: 80 + i * 15,
        baseRadius: 80 + i * 15,
        size: 15 + i * 2,
        type: i % 3, // different symbol types
        phase: i * 0.5,
        settled: false,
        targetX: 0,
        targetY: 0
      });
    }

    // Calculate final positions for symbols
    for (let i = 0; i < 8; i++) {
      let angle = symbols[i].baseAngle;
      symbols[i].targetX = p.width/2 + p.cos(angle) * symbols[i].baseRadius;
      symbols[i].targetY = p.height/2 + p.sin(angle) * symbols[i].baseRadius;
    }

    hearth = {
      x: p.width/2,
      y: p.height/2 + 50,
      warmth: 0
    };

    homeLight = {
      intensity: 0,
      pulsePhase: 0
    };
  };

  p.draw = function() {
    time += 0.02;

    // Create orange sky gradient with blue tinting
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let orangeTop = p.color(255, 180, 120, 200);
      let blueBottom = p.color(120, 150, 255, 100);
      let skyColor = p.lerpColor(orangeTop, blueBottom, inter);
      p.stroke(skyColor);
      p.line(0, i, p.width, i);
    }

    // Home light effect - warm glow from center
    homeLight.pulsePhase += 0.03;
    homeLight.intensity = 0.7 + 0.3 * p.sin(homeLight.pulsePhase);

    p.push();
    p.translate(p.width/2, p.height/2);
    for (let r = 200; r > 0; r -= 20) {
      let alpha = (1 - r/200) * homeLight.intensity * 30;
      let warmColor = p.color(255, 200, 150, alpha);
      p.fill(warmColor);
      p.noStroke();
      p.ellipse(0, 0, r, r);
    }
    p.pop();

    // Interactive mouse influence
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, p.width/2, p.height/2) / 200;
    mouseInfluence = p.constrain(1 - mouseInfluence, 0, 1);

    // Update and draw symbols in spiral motion toward home
    for (let i = 0; i < symbols.length; i++) {
      let symbol = symbols[i];

      if (!symbol.settled) {
        // Spiraling motion toward final positions
        let spiralProgress = (time + symbol.phase) * 0.3;
        let currentRadius = symbol.baseRadius * (1 - spiralProgress * 0.1);
        currentRadius = p.max(currentRadius, 20);

        symbol.angle = symbol.baseAngle + spiralProgress;
        symbol.x = p.width/2 + p.cos(symbol.angle) * currentRadius;
        symbol.y = p.height/2 + p.sin(symbol.angle) * currentRadius;

        // Gradually settle into final positions
        if (spiralProgress > 3) {
          symbol.x = p.lerp(symbol.x, symbol.targetX, 0.02);
          symbol.y = p.lerp(symbol.y, symbol.targetY, 0.02);

          if (p.dist(symbol.x, symbol.y, symbol.targetX, symbol.targetY) < 2) {
            symbol.settled = true;
          }
        }
      } else {
        // Gentle breathing motion when settled
        let breathe = p.sin(time + symbol.phase) * 3;
        symbol.x = symbol.targetX + breathe;
        symbol.y = symbol.targetY + breathe;
      }

      // Draw symbols with blue tinting and warm highlights
      p.push();
      p.translate(symbol.x, symbol.y);
      p.rotate(symbol.angle + time);

      let symbolAlpha = symbol.settled ? 255 : 150;
      let baseColor = p.color(150, 180, 255, symbolAlpha);
      let warmHighlight = p.color(255, 220, 180, symbolAlpha * 0.7);

      // Different symbol types
      if (symbol.type === 0) {
        // Home/heart symbol
        p.fill(p.lerpColor(baseColor, warmHighlight, mouseInfluence));
        p.noStroke();
        p.beginShape();
        for (let a = 0; a < p.TWO_PI; a += 0.2) {
          let r = symbol.size * (1 + 0.3 * p.sin(a * 4));
          let x = r * p.cos(a);
          let y = r * p.sin(a);
          p.vertex(x, y);
        }
        p.endShape(p.CLOSE);
      } else if (symbol.type === 1) {
        // Door/threshold symbol
        p.strokeWeight(3);
        p.stroke(p.lerpColor(baseColor, warmHighlight, mouseInfluence));
        p.noFill();
        p.rect(-symbol.size/2, -symbol.size/2, symbol.size, symbol.size);
        p.circle(0, 0, symbol.size/3);
      } else {
        // Light/window symbol
        p.fill(p.lerpColor(baseColor, warmHighlight, mouseInfluence));
        p.noStroke();
        for (let rays = 0; rays < 8; rays++) {
          p.push();
          p.rotate(rays * p.PI/4);
          p.ellipse(0, -symbol.size/2, 3, symbol.size);
          p.pop();
        }
        p.circle(0, 0, symbol.size/2);
      }
      p.pop();
    }

    // Central hearth - representing the heart of home
    hearth.warmth = p.lerp(hearth.warmth, mouseInfluence, 0.05);

    p.push();
    p.translate(hearth.x, hearth.y);

    // Hearth base
    let hearthColor = p.lerpColor(
      p.color(100, 130, 200, 200),
      p.color(255, 180, 100, 255),
      hearth.warmth
    );

    p.fill(hearthColor);
    p.noStroke();
    p.ellipse(0, 0, 40 + hearth.warmth * 20, 30 + hearth.warmth * 15);

    // Warm flame effect when mouse is near
    if (hearth.warmth > 0.3) {
      for (let flames = 0; flames < 5; flames++) {
        let flameHeight = 20 + hearth.warmth * 30;
        let flameX = (flames - 2) * 8;
        let flameWave = p.sin(time * 3 + flames) * 5;

        p.fill(255, 200 + hearth.warmth * 55, 100, 180);
        p.ellipse(flameX + flameWave, -flameHeight/2, 8, flameHeight);
      }
    }
    p.pop();

    // Circles of belonging - expanding rings when interactive
    if (mouseInfluence > 0.2) {
      p.stroke(255, 220, 180, 100 * mouseInfluence);
      p.strokeWeight(2);
      p.noFill();

      for (let rings = 1; rings <= 3; rings++) {
        let ringSize = rings * 100 + time * 20;
        ringSize = ringSize % 300;
        let alpha = (300 - ringSize) / 300 * mouseInfluence * 100;

        p.stroke(255, 220, 180, alpha);
        p.circle(p.width/2, p.height/2, ringSize);
      }
    }
  };

  p.mousePressed = function() {
    // Reset symbols to create new spiral dance
    for (let symbol of symbols) {
      symbol.settled = false;
    }
    time = 0;
  };
}

function sketch(p) {
  let symbols = [];
  let particles = [];
