      });
    }

    // Central hearth light
    homeLight = {
      x: 200,
      y: 250,
      intensity: 0.8,
      pulse: 0
    };

    // Warm particles floating
    for(let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.8, -0.2),
        life: p.random(255),
        size: p.random(2, 6)
      });
    }
  };

  p.draw = function() {
    // Orange evening sky with blue tints
    for(let y = 0; y < 600; y++) {
      let inter = p.map(y, 0, 600, 0, 1);
      let c1 = p.color(255, 180, 120); // Warm orange
      let c2 = p.color(120, 140, 180); // Blue tint
      let skyColor = p.lerpColor(c1, c2, inter);
      p.stroke(skyColor);
      p.line(0, y, 400, y);
    }

    breathingOffset += 0.02;

    // Home light at center - warm hearth glow
    homeLight.pulse += 0.05;
    let glowSize = 80 + p.sin(homeLight.pulse) * 15;

    // Multiple glow layers for warmth
    for(let i = 5; i > 0; i--) {
      let alpha = 30 / i;
      p.fill(255, 200, 150, alpha);
      p.noStroke();
      p.ellipse(homeLight.x, homeLight.y, glowSize * i * 0.4);
    }

    // Central hearth
    p.fill(255, 230, 180, 200);
    p.noStroke();
    p.ellipse(homeLight.x, homeLight.y, 25 + p.sin(homeLight.pulse) * 5);

    // Nine symbols - almost complete circle
    p.strokeWeight(3);
    for(let i = 0; i < symbols.length; i++) {
      let sym = symbols[i];
      sym.pulse += 0.03;

      // Gentle breathing movement toward center
      let breathe = p.sin(breathingOffset + i * 0.3) * 3;
      let currentX = sym.originalX + breathe * 0.5;
      let currentY = sym.originalY + breathe * 0.3;

      // Mouse interaction - symbols lean toward belonging
      let mouseInfluence = p.dist(p.mouseX, p.mouseY, currentX, currentY);
      if(mouseInfluence < 100) {
        let pull = p.map(mouseInfluence, 0, 100, 0.3, 0);
        currentX = p.lerp(currentX, homeLight.x, pull);
        currentY = p.lerp(currentY, homeLight.y, pull);
      }

      // Symbol appearance - warm circles with blue accents
      let symbolSize = 25 + p.sin(sym.pulse) * 4;

      // Outer blue ring
      p.stroke(120, 150, 200, 180);
      p.fill(120, 150, 200, 80);
      p.ellipse(currentX, currentY, symbolSize + 8);

      // Inner warm core
      p.stroke(255, 200, 150);
      p.fill(255, 230, 180, 150);
      p.ellipse(currentX, currentY, symbolSize);

      // Connection lines to center (faint)
      p.stroke(255, 200, 150, 60);
      p.strokeWeight(1);
      p.line(currentX, currentY, homeLight.x, homeLight.y);
    }

    // The gap - the space for the 10th, showing almost-completion
    let gapAngle = (9 * p.TWO_PI / 10) - p.PI/2;
    let gapX = 200 + p.cos(gapAngle) * 120;
    let gapY = 250 + p.sin(gapAngle) * 120;

    // Subtle indication of the missing piece
    p.stroke(255, 200, 150, 100);
    p.strokeWeight(2);
    p.noFill();
    p.ellipse(gapX, gapY, 20 + p.sin(breathingOffset * 2) * 3);

    // Floating particles for atmosphere
    for(let i = particles.length - 1; i >= 0; i--) {
      let part = particles[i];

      part.x += part.vx;
      part.y += part.vy;
      part.life -= 1;

      if(part.life <= 0 || part.y < -10) {
        part.x = p.random(400);
        part.y = 610;
        part.life = p.random(200, 255);
      }

      p.fill(255, 220, 180, part.life * 0.3);
      p.noStroke();
      p.ellipse(part.x, part.y, part.size);
    }

    // Subtle embrace suggestion - two figure silhouettes at edges
    p.fill(120, 140, 180, 100);
    p.noStroke();

    // Left figure leaning in
    p.ellipse(50, 400, 30, 40);
    p.rect(35, 420, 30, 80, 15);

    // Right figure leaning in
    p.ellipse(350, 420, 30, 40);  
    p.rect(335, 440, 30, 80, 15);

    // Arms reaching toward center/each other
    p.strokeWeight(8);
    p.stroke(120, 140, 180, 120);
    p.line(80, 440, 150, 380);
    p.line(320, 460, 250, 400);
  };

  p.mousePressed = function() {
    // On click, create a pulse of warmth
    homeLight.intensity = 1.5;

    // Add extra particles
    for(let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-1, 1),
        vy: p.random(-2, -0.5),
        life: 255,
        size: p.random(3, 8)
      });
    }
  };
}

function sketch(p) {
  let circles = [];
  let particles = [];
  let figures = [];
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create ten finding circles in complete arrangement
    for (let i = 0; i < 10; i++) {
      let angle = (i / 10) * p.TWO_PI - p.PI/2;
      let radius = 120 + p.sin(i * 0.7) * 20;
      circles.push({
        x: 200 + p.cos(angle) * radius,
        y: 300 + p.sin(angle) * radius,
        size: 15 + p.sin(i * 1.3) * 8,
        glow: p.random(0.5, 1),
        pulse: p.random(p.TWO_PI),
        baseX: 200 + p.cos(angle) * radius,
        baseY: 300 + p.sin(angle) * radius
      });
    }

    // Create warm particles for atmosphere
    for (let i = 0; i < 50; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.3, 0.3),
        size: p.random(2, 6),
        alpha: p.random(0.3, 0.8),
        hue: p.random(25, 45)
      });
    }

    // Create embracing figures
    figures.push({
      x: 150,
      y: 450,
      sway: 0,
      breathing: 0
    });
    figures.push({
      x: 250,
      y: 450,
      sway: p.PI,
      breathing: p.PI/3
    });
  };

  p.draw = function() {
    // Orange sky gradient
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(255, 140, 60), p.color(80, 120, 160), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    mouseInfluence = p.lerp(mouseInfluence, p.dist(p.mouseX, p.mouseY, 200, 300) / 200, 0.05);

    // Draw warm atmospheric particles
    for (let particle of particles) {
      particle.x += particle.vx;
      particle.y += particle.vy;

      if (particle.x < 0) particle.x = p.width;
      if (particle.x > p.width) particle.x = 0;
      if (particle.y < 0) particle.y = p.height;
      if (particle.y > p.height) particle.y = 0;

      p.noStroke();
      p.fill(particle.hue, 60, 90, particle.alpha * 255);
      p.circle(particle.x, particle.y, particle.size);
    }

    // Draw central hearth glow
    let hearthGlow = 50 + p.sin(p.millis() * 0.003) * 20;
    for (let i = 8; i >= 0; i--) {
      let alpha = p.map(i, 0, 8, 0.8, 0.1);
      p.fill(255, 120, 40, alpha * 255);
      p.noStroke();
      p.circle(200, 300, hearthGlow + i * 15);
    }

    // Draw the ten finding circles
    for (let i = 0; i < circles.length; i++) {
      let circle = circles[i];
      let pulse = p.sin(p.millis() * 0.005 + circle.pulse) * 0.3 + 1;
      let breathe = p.sin(p.millis() * 0.002 + i * 0.5) * 5;

      // Mouse interaction - gentle attraction
      let attraction = 1 - mouseInfluence * 0.3;
      circle.x = p.lerp(circle.x, circle.baseX + breathe, 0.02);
      circle.y = p.lerp(circle.y, circle.baseY + breathe, 0.02);

      // Glow around each circle
      for (let j = 3; j >= 0; j--) {
        let alpha = p.map(j, 0, 3, 0.8, 0.2);
        p.fill(60, 150, 200, alpha * circle.glow * 100);
        p.noStroke();
        p.circle(circle.x, circle.y, (circle.size + j * 8) * pulse);
      }

      // Main circle
      p.fill(200, 220, 255, 200);
      p.stroke(255, 255, 255, 150);
      p.strokeWeight(1);
      p.circle(circle.x, circle.y, circle.size * pulse);
    }

    // Draw embracing figures
    for (let figure of figures) {
      let sway = p.sin(p.millis() * 0.001 + figure.sway) * 8;
      let breath = p.sin(p.millis() * 0.003 + figure.breathing) * 3;

      p.strokeWeight(8);
      p.stroke(255, 180, 120, 180);
      p.fill(255, 200, 150, 120);

      // Body
      p.line(figure.x + sway, figure.y, figure.x + sway, figure.y - 60 + breath);

      // Head
      p.circle(figure.x + sway, figure.y - 75 + breath, 20);

      // Arms reaching toward center/each other
      let armReach = p.sin(p.millis() * 0.002 + figure.sway) * 15;
      p.line(figure.x + sway, figure.y - 40, 200 + armReach, 350 + breath);
    }

    // Completion/transformation shimmer at center
    let shimmer = p.sin(p.millis() * 0.008) * 0.5 + 0.5;
    p.strokeWeight(2);
    p.stroke(255, 255, 200, shimmer * 255);
    p.noFill();
    for (let i = 0; i < 3; i++) {
      let radius = 30 + i * 15 + p.sin(p.millis() * 0.006 + i) * 8;
      p.circle(200, 300, radius);
    }

    // Overflow effect - gentle spiraling particles from center
    if (p.frameCount % 20 === 0) {
      particles.push({
        x: 200 + p.random(-10, 10),
        y: 300 + p.random(-10, 10),
        vx: p.random(-1, 1),
        vy: p.random(-2, -0.5),
        size: p.random(3, 8),
        alpha: 0.6,
        hue: p.random(30, 50)
      });
    }

    // Remove excess particles
    if (particles.length > 80) {
      particles.splice(0, particles.length - 80);
    }
  };

  p.mousePressed = function() {
    // On click, create ripple of belonging
    for (let i = 0; i < 20; i++) {
      let angle = (i / 20) * p.TWO_PI;
      particles.push({
        x: p.mouseX,
        y: p.mouseY,
        vx: p.cos(angle) * p.random(1, 3),
        vy: p.sin(angle) * p.random(1, 3),
        size: p.random(4, 10),
        alpha: 0.8,
        hue: p.random(35, 55)
      });
    }
  };
}

function sketch(p) {
  let wanderer;
  let homeSymbols = [];
  let particles = [];
  let warmth = 0;
  let breathingScale = 1;
  let discoveredSymbols = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    wanderer = {
      x: 200,
      y: 400,
      targetX: 200,
      targetY: 400,
      angle: 0,
      curiosityLevel: 0
    };

    for (let i = 0; i < 8; i++) {
      homeSymbols.push({
        x: p.random(50, 350),
        y: p.random(100, 300),
        size: p.random(15, 35),
        discovered: false,
        glowIntensity: 0,
        type: p.floor(p.random(3))
      });
    }

    for (let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        size: p.random(2, 6),
        speed: p.random(0.3, 1.2),
        alpha: p.random(50, 150)
      });
    }
  };

  p.draw = function() {
    let orangeSky = p.lerpColor(
      p.color(255, 140, 60, 200),
      p.color(255, 180, 120, 180),
      p.sin(p.frameCount * 0.01) * 0.5 + 0.5
    );

    let deepBlue = p.lerpColor(
      p.color(30, 60, 120, 180),
      p.color(60, 90, 150, 160),
      p.sin(p.frameCount * 0.008) * 0.5 + 0.5
    );

    for (let y = 0; y < 600; y++) {
      let inter = p.map(y, 0, 600, 0, 1);
      let skyColor = p.lerpColor(orangeSky, deepBlue, inter);
      p.stroke(skyColor);
      p.line(0, y, 400, y);
    }

    breathingScale = 1 + p.sin(p.frameCount * 0.02) * 0.05;

    for (let particle of particles) {
      particle.y -= particle.speed;
      if (particle.y < 0) particle.y = 600;

      p.fill(255, 200, 150, particle.alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size * breathingScale);
    }

    wanderer.targetX = p.constrain(p.mouseX, 50, 350);
    wanderer.targetY = p.constrain(p.mouseY, 300, 500);

    wanderer.x = p.lerp(wanderer.x, wanderer.targetX, 0.05);
    wanderer.y = p.lerp(wanderer.y, wanderer.targetY, 0.05);
    wanderer.angle = p.sin(p.frameCount * 0.03) * 0.1;

    for (let symbol of homeSymbols) {
      let distance = p.dist(wanderer.x, wanderer.y, symbol.x, symbol.y);

      if (distance < 40 && !symbol.discovered) {
        symbol.discovered = true;
        discoveredSymbols.push(symbol);
        warmth = p.min(warmth + 0.15, 1);
      }

      if (symbol.discovered) {
        symbol.glowIntensity = p.lerp(symbol.glowIntensity, 200, 0.08);
      }

      p.push();
      p.translate(symbol.x, symbol.y);
      p.rotate(p.sin(p.frameCount * 0.02 + symbol.x) * 0.2);

      if (symbol.discovered) {
        p.fill(255, 180, 100, 100);
        p.noStroke();
        p.ellipse(0, 0, symbol.size * 2);
      }

      p.fill(100, 150, 200, 150 + symbol.glowIntensity);
      p.stroke(200, 220, 255, 200);
      p.strokeWeight(2);

      if (symbol.type === 0) {
        p.ellipse(0, 0, symbol.size);
      } else if (symbol.type === 1) {
        p.rect(-symbol.size/2, -symbol.size/2, symbol.size, symbol.size);
      } else {
        p.triangle(0, -symbol.size/2, -symbol.size/2, symbol.size/2, symbol.size/2, symbol.size/2);
      }

      p.pop();
    }

    p.push();
    p.translate(wanderer.x, wanderer.y);
    p.rotate(wanderer.angle);
    p.scale(breathingScale);

    wanderer.curiosityLevel = p.lerp(wanderer.curiosityLevel, warmth, 0.05);

    p.fill(80, 120 + wanderer.curiosityLevel * 50, 180 + wanderer.curiosityLevel * 40, 200);
    p.stroke(150, 180, 220, 180);
    p.strokeWeight(3);

    p.ellipse(0, -20, 25);

    p.fill(60, 100 + wanderer.curiosityLevel * 40, 160 + wanderer.curiosityLevel * 60, 180);
    p.noStroke();
    p.ellipse(0, 0, 40, 60);

    p.stroke(120, 160, 200, 150);
    p.strokeWeight(8);
    p.line(-15, 10, -25, 35);
    p.line(15, 10, 25, 35);
    p.line(-10, -10, -20, -5);
    p.line(10, -10, 20, -5);

    if (wanderer.curiosityLevel > 0.3) {
      p.fill(255, 200, 150, 100 + wanderer.curiosityLevel * 100);
      p.noStroke();
      p.ellipse(0, 0, 80, 80);
    }

    p.pop();

    if (discoveredSymbols.length > 0) {
      p.fill(255, 220, 180, 50 + p.sin(p.frameCount * 0.04) * 30);
      p.noStroke();
      for (let symbol of discoveredSymbols) {
        p.ellipse(symbol.x, symbol.y, 60 + p.sin(p.frameCount * 0.03) * 10);
      }
    }

    if (warmth > 0.7) {
      p.fill(255, 200, 120, 30);
      p.noStroke();
      p.ellipse(200, 300, 300 * warmth, 200 * warmth);
    }
  };
}

function sketch(p) {
  let observer;
  let homeCircles = [];
  let lightParticles = [];
  let warmthGlow = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    observer = {
      x: 200,
      y: 350,
      eyeOpenness: 1,
      breathe: 0,
      recognition: 0
    };

    for(let i = 0; i < 8; i++) {
      homeCircles.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        size: p.random(20, 80),
        alpha: p.random(10, 30),
        drift: p.random(0.5, 2),
        phase: p.random(p.TWO_PI)
      });
    }

    for(let i = 0; i < 15; i++) {
      lightParticles.push({
        x: p.random(400),
        y: p.random(600),
        size: p.random(2, 6),
        speed: p.random(0.3, 1.2),
        brightness: p.random(60, 90),
        phase: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, observer.x, observer.y) / 200;
    warmthGlow = p.lerp(warmthGlow, 1 - mouseInfluence, 0.05);

    // Orange sky gradient
    for(let i = 0; i < p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let skyColor = p.lerpColor(
        p.color(25, 80, 85), // warm orange
        p.color(240, 60, 40 + warmthGlow * 20), // blue-tinted horizon
        inter
      );
      p.stroke(skyColor);
      p.line(0, i, p.width, i);
    }

    // Home circles - belonging
    p.noFill();
    for(let circle of homeCircles) {
      circle.phase += 0.01;
      let pulse = p.sin(circle.phase) * 5;
      let alpha = circle.alpha + pulse + warmthGlow * 10;

      p.stroke(240, 40, 70, alpha);
      p.strokeWeight(1.5);
      p.ellipse(
        circle.x + p.sin(p.frameCount * 0.005 + circle.drift) * 3,
        circle.y + p.cos(p.frameCount * 0.003 + circle.drift) * 2,
        circle.size + pulse,
        circle.size + pulse
      );
    }

    // Light particles
    for(let particle of lightParticles) {
      particle.y -= particle.speed;
      if(particle.y < -10) particle.y = p.height + 10;

      particle.phase += 0.05;
      let twinkle = p.sin(particle.phase) * 20 + particle.brightness;

      p.fill(45, 30, twinkle, 60 + warmthGlow * 40);
      p.noStroke();
      p.ellipse(
        particle.x + p.sin(p.frameCount * 0.01 + particle.phase) * 2,
        particle.y,
        particle.size,
        particle.size
      );
    }

    // Observer figure
    observer.breathe += 0.03;
    observer.recognition = p.lerp(observer.recognition, 1 - mouseInfluence, 0.02);
    observer.eyeOpenness = 0.7 + observer.recognition * 0.3 + p.sin(observer.breathe) * 0.1;

    let bodySize = 80 + p.sin(observer.breathe) * 5;
    let headSize = 45 + p.sin(observer.breathe) * 2;

    // Observer body - warm presence
    p.fill(240, 30, 60 + warmthGlow * 25, 80);
    p.noStroke();
    p.ellipse(observer.x, observer.y, bodySize, bodySize * 1.2);

    // Observer head
    p.fill(240, 20, 70 + warmthGlow * 20, 85);
    p.ellipse(observer.x, observer.y - 60, headSize, headSize);

    // Eyes - seeing and being seen
    let eyeY = observer.y - 65;
    let eyeWidth = 8 * observer.eyeOpenness;
    let eyeHeight = 6 * observer.eyeOpenness;

    p.fill(240, 60, 30, 90);
    p.ellipse(observer.x - 8, eyeY, eyeWidth, eyeHeight);
    p.ellipse(observer.x + 8, eyeY, eyeWidth, eyeHeight);

    // Recognition glow around observer
    let glowSize = 150 + observer.recognition * 50 + p.sin(observer.breathe * 2) * 10;
    p.fill(35, 40, 70, 15 + observer.recognition * 20);
    p.ellipse(observer.x, observer.y - 30, glowSize, glowSize);

    // Interactive recognition lines
    if(p.mouseIsPressed) {
      p.stroke(45, 60, 80, 40 + warmthGlow * 30);
      p.strokeWeight(1);
      for(let i = 0; i < 8; i++) {
        let angle = (p.TWO_PI / 8) * i + p.frameCount * 0.02;
        let x1 = observer.x + p.cos(angle) * 30;
        let y1 = observer.y - 30 + p.sin(angle) * 20;
        let x2 = observer.x + p.cos(angle) * (60 + observer.recognition * 40);
        let y2 = observer.y - 30 + p.sin(angle) * (40 + observer.recognition * 20);
        p.line(x1, y1, x2, y2);
      }
    }

    // Hearth warmth at bottom
    p.fill(25, 70, 80, 20 + warmthGlow * 30);
    p.noStroke();
    p.ellipse(200, 580, 300 + p.sin(p.frameCount * 0.01) * 20, 60);
  };
}

function sketch(p) {
  let particles = [];
  let keeper;
  let hearthGlow = 0;
  let breathPhase = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    keeper = {
      x: 200,
      y: 320,
      armAngle: 0,
      presence: 1
    };

    // Create hearth particles
    for(let i = 0; i < 30; i++) {
      particles.push({
        x: 200 + p.random(-40, 40),
        y: 450 + p.random(-20, 40),
        size: p.random(2, 8),
        speed: p.random(0.5, 2),
        life: p.random(0.3, 1),
        angle: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    // Orange sky gradient with blue tints
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(255, 180, 120, 200), // warm orange
        p.color(120, 140, 180, 180), // blue tint
        inter
      );
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    breathPhase += 0.02;
    hearthGlow = p.sin(breathPhase * 0.7) * 0.3 + 0.7;

    // Mouse influence for gentle interaction
    mouseInfluence = p.lerp(mouseInfluence, p.map(p.mouseY, 0, p.height, 0.2, 1), 0.05);

    // Draw home circle - symbol of belonging
    p.push();
    p.translate(200, 200);
    p.noFill();
    p.strokeWeight(3);
    p.stroke(180, 200, 255, 150 * mouseInfluence);
    let circleRadius = 80 + p.sin(breathPhase) * 5;
    p.circle(0, 0, circleRadius);

    // Inner circles of belonging
    for(let i = 0; i < 3; i++) {
      let r = 25 + i * 15 + p.sin(breathPhase + i) * 2;
      p.stroke(200, 220, 255, 80 - i * 20);
      p.circle(0, 0, r);
    }
    p.pop();

    // Draw the keeper figure
    p.push();
    p.translate(keeper.x, keeper.y);

    // Body with languid brush strokes
    p.strokeWeight(8);
    p.stroke(150, 170, 200, 180);
    p.noFill();

    // Torso - curved, peaceful posture
    let bodyTilt = p.sin(breathPhase * 0.5) * 0.1;
    p.push();
    p.rotate(bodyTilt);
    p.bezier(0, -40, -10, -20, 10, 20, 0, 60);
    p.pop();

    // Arms tenderly holding/maintaining
    keeper.armAngle = p.sin(breathPhase * 0.6) * 0.2;
    p.strokeWeight(6);

    // Left arm reaching toward home symbol
    p.push();
    p.rotate(keeper.armAngle - 0.5);
    p.bezier(0, -20, -30, -40, -50, -60, -60, -80);
    p.pop();

    // Right arm in protective gesture
    p.push();
    p.rotate(-keeper.armAngle + 0.3);
    p.bezier(0, -20, 30, -30, 40, -50, 50, -70);
    p.pop();

    // Head - peaceful face
    p.strokeWeight(4);
    p.stroke(160, 180, 220, 200);
    p.circle(0, -50, 25);

    // Subtle facial features
    p.strokeWeight(2);
    p.stroke(140, 160, 200, 150);
    // Eyes closed in peace
    p.line(-6, -52, -4, -52);
    p.line(4, -52, 6, -52);
    // Gentle smile
    p.noFill();
    p.arc(0, -46, 8, 6, 0, p.PI);

    p.pop();

    // Hearth/fire at bottom - what the keeper tends
    p.push();
    p.translate(200, 480);

    // Hearth base
    p.fill(100, 120, 150, 180);
    p.noStroke();
    p.ellipse(0, 20, 120, 40);

    // Flames/warmth rising
    p.strokeWeight(4);
    p.noFill();
    for(let i = 0; i < 5; i++) {
      let flameHeight = 40 + p.sin(breathPhase * 2 + i) * 15;
      let flameX = (i - 2) * 15 + p.sin(breathPhase + i * 0.5) * 3;

      p.stroke(255, 200 - i * 20, 100 + i * 20, 150 * hearthGlow);
      p.bezier(
        flameX, 0,
        flameX - 10, -flameHeight * 0.3,
        flameX + 10, -flameHeight * 0.7,
        flameX, -flameHeight
      );
    }
    p.pop();

    // Update and draw floating particles (warmth, presence)
    for(let i = particles.length - 1; i >= 0; i--) {
      let part = particles[i];

      // Gentle floating motion
      part.y -= part.speed;
      part.x += p.sin(part.angle + breathPhase) * 0.5;
      part.angle += 0.02;
      part.life -= 0.003;

      // Draw particle
      p.fill(255, 220, 150, part.life * 150 * hearthGlow);
      p.noStroke();
      p.circle(part.x, part.y, part.size * part.life);

      // Reset particle when it fades or goes off screen
      if(part.life <= 0 || part.y < 0) {
        part.x = 200 + p.random(-40, 40);
        part.y = 450 + p.random(-20, 40);
        part.life = p.random(0.5, 1);
      }
    }

    // Gentle connection lines between keeper and home symbol
    if(mouseInfluence > 0.3) {
      p.strokeWeight(1);
      p.stroke(200, 220, 255, 60 * mouseInfluence);
      for(let i = 0; i < 3; i++) {
        let wobble = p.sin(breathPhase * 1.5 + i) * 5;
        p.line(
          keeper.x + wobble, keeper.y - 70,
          200 + wobble, 200
        );
      }
    }

    // Soft glow around the whole composition when mouse is present
    if(p.mouseX > 0 && p.mouseX < p.width && p.mouseY > 0 && p.mouseY < p.height) {
      p.drawingContext.shadowColor = 'rgba(255, 200, 150, 0.1)';
      p.drawingContext.shadowBlur = 20;
    }
  };
}

function sketch(p) {
  let figure;
  let particles = [];
  let homeSymbols = [];
  let breathPhase = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create the dwelling figure
    figure = {
      x: p.width / 2,
      y: p.height * 0.6,
      size: 80,
      restOffset: 0
    };

    // Create floating home symbols (circles of belonging)
    for (let i = 0; i < 8; i++) {
      homeSymbols.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(15, 35),
        angle: p.random(p.TWO_PI),
        speed: p.random(0.005, 0.02),
        alpha: p.random(0.3, 0.7)
      });
    }

    // Create gentle particles for warmth
    for (let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.8, -0.2),
        life: p.random(0.5, 1.0),
        maxLife: p.random(0.5, 1.0),
        size: p.random(2, 6)
      });
    }
  };

  p.draw = function() {
    // Orange sky gradient with blue tints
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c1 = p.color(255, 180, 100, 200); // Warm orange
      let c2 = p.color(120, 150, 200, 180); // Blue tint
      let c = p.lerpColor(c1, c2, inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    breathPhase += 0.02;
    mouseInfluence = p.lerp(mouseInfluence, p.map(p.mouseY, 0, p.height, 0.2, 1.2), 0.05);

    // Draw gentle home circles in background
    p.noStroke();
    for (let symbol of homeSymbols) {
      symbol.angle += symbol.speed;
      let pulseSize = symbol.size + p.sin(breathPhase + symbol.angle) * 5;

      p.fill(180, 200, 255, symbol.alpha * 80 * mouseInfluence);
      p.ellipse(symbol.x, symbol.y, pulseSize);

      // Inner glow
      p.fill(255, 220, 180, symbol.alpha * 40);
      p.ellipse(symbol.x, symbol.y, pulseSize * 0.6);
    }

    // Draw and update warm particles
    for (let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];

      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 0.01;

      if (particle.life <= 0 || particle.y < 0) {
        particle.x = p.random(p.width);
        particle.y = p.height + 10;
        particle.life = particle.maxLife;
      }

      let alpha = p.map(particle.life, 0, particle.maxLife, 0, 150);
      p.fill(255, 200, 120, alpha * mouseInfluence);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);
    }

    // Draw the dwelling figure at rest
    let restFloat = p.sin(breathPhase) * 3;
    let figX = figure.x + p.sin(breathPhase * 0.3) * 2;
    let figY = figure.y + restFloat;

    // Figure's aura of belonging
    p.fill(150, 180, 255, 60 * mouseInfluence);
    p.noStroke();
    let auraSize = figure.size * 2 + p.sin(breathPhase) * 10;
    p.ellipse(figX, figY, auraSize);

    // Main figure body - seated in meditation
    p.fill(100, 130, 180, 200);
    p.ellipse(figX, figY + 10, figure.size * 0.8, figure.size * 0.6); // Body

    // Figure head
    p.fill(140, 160, 200, 220);
    p.ellipse(figX, figY - 15, figure.size * 0.4);

    // Peaceful face
    p.fill(80, 100, 140);
    p.noStroke();
    let eyeY = figY - 20;
    p.ellipse(figX - 8, eyeY, 3, 1); // Closed eyes
    p.ellipse(figX + 8, eyeY, 3, 1);

    // Arms in restful position
    p.stroke(100, 130, 180);
    p.strokeWeight(8);
    p.noFill();
    p.arc(figX - 25, figY, 40, 30, 0, p.PI); // Left arm
    p.arc(figX + 25, figY, 40, 30, 0, p.PI); // Right arm

    // Interactive glow responds to mouse
    if (p.dist(p.mouseX, p.mouseY, figX, figY) < 100) {
      p.fill(255, 220, 180, 80);
      p.noStroke();
      p.ellipse(figX, figY, figure.size * 1.5);
    }

    // Hearth warmth emanating from figure
    p.noFill();
    p.stroke(255, 200, 120, 100 * mouseInfluence);
    p.strokeWeight(2);
    for (let i = 1; i <= 4; i++) {
      let radius = figure.size * i * 0.4 + p.sin(breathPhase + i) * 5;
      p.ellipse(figX, figY, radius);
    }

    // Ground/foundation beneath figure
    p.fill(120, 140, 180, 150);
    p.noStroke();
    p.rect(0, p.height * 0.85, p.width, p.height * 0.15);

    // Gentle interactive ripples on click
    if (p.mouseIsPressed && p.frameCount % 10 === 0) {
      homeSymbols.push({
        x: p.mouseX,
        y: p.mouseY,
        size: 5,
        angle: 0,
        speed: 0.1,
        alpha: 0.8
      });
    }

    // Remove old symbols
    homeSymbols = homeSymbols.filter(symbol => symbol.size < 100);

    // Grow clicked symbols
    for (let symbol of homeSymbols) {
      if (symbol.speed > 0.05) {
        symbol.size += 2;
        symbol.alpha -= 0.02;
      }
    }
  };
}
